		["thunder ridge"] = {
			name = "Thunder Ridge",
			short = "Thunder Ridge is a gorge in northwestern Durotar, southwest of Orgrimmar. It holds a forest of ancient trees that grew in harmony with the thunder lizards denning among them.",
			full = "Thunder Ridge is a gorge in northwestern Durotar, southwest of Orgrimmar. It holds a forest of ancient trees that grew in harmony with the thunder lizards denning among them.\n\nThe harmony broke when a human lumber operation began stripping the ridge of its trees, driving the lizards mad. Rexxar, sent to gather shimmerweed for Drek'Thar, noticed the change in the beasts and carried word back to Orgrimmar. He and Drek'Thar returned together, found the logging operation, and were forced to put down the maddened lizards to avert disaster, though Rexxar gathered their eggs afterward for Drek'Thar to study.\n\nJaina Proudmoore, sent by Thrall to learn what had further troubled the ridge, found that its trees had been cut down by demonic magic, the work of the Burning Blade seeking to destabilize the region. A small band of its cultists, led by Fizzle Darkclaw, made camp there to spread further chaos, and Orgnil Soulscar called for Fizzle's death and his claw as proof of it.",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Ridge",
