		["tiragarde keep"] = {
			name = "Tiragarde Keep",
			short = "Tiragarde Keep rises white against the red rock of the Scuttle Coast, a stronghold that should never have stood in Durotar at all.",
			full = "Tiragarde Keep rises white against the red rock of the Scuttle Coast, a stronghold that should never have stood in Durotar at all.\n\nIt was raised in haste, on the orders of Grand Admiral Daelin Proudmoore of Kul Tiras. The Third War had ended in an uneasy peace between Thrall and Lady Jaina Proudmoore, the Admiral's own daughter, but Daelin trusted no orc and honored no truce signed in his name. He brought his fleet from Kul Tiras to the shores of Durotar and threw it against the Horde, building Tiragarde Keep as a foothold for the war he meant to finish. The offensive broke against the orcs, and the keep fell into ruin with it.\n\nDaelin himself did not live to see it rebuilt; he was slain when the Horde, led by Rexxar, stormed Theramore. But before sailing from Kul Tiras, he had left behind sealed orders against the day his fleet fell silent. When no word came back, those orders surfaced, and Lieutenant Benedict was sent to reclaim the ruin and carry on his commander's crusade.\n\nSo the keep stands again, battered but held, a gleaming wrong-colored scar on the crimson stone.",
			source = "https://warcraft.wiki.gg/wiki/Tiragarde_Keep",
		},
		["torkren farm"] = {
			name = "Tor'kren Farm",
			short = "Tor'kren Farm lies between Thunder Ridge and the Southfury Watershed, a modest holding that has never yielded the profit of its neighbors.",
			full = "Tor'kren Farm lies between Thunder Ridge and the Southfury Watershed, a modest holding that has never yielded the profit of its neighbors. It was once worked by Misha Tor'kren and her son Kron, until Kron went down to the Southfury River to hunt crocolisks and did not come home. Misha keeps the farm alone now, and asks for a necklace strung from crocolisk teeth, to remember him by.",
			source = "https://warcraft.wiki.gg/wiki/Tor'kren_Farm",
		},
		["valley of trials"] = {
			name = "Valley of Trials",
			short = "The Valley of Trials lies walled in southern Durotar, a bowl of scorched earth where every young orc begins the life the Horde has set before them.",
			full = "The Valley of Trials lies walled in southern Durotar, a bowl of scorched earth where every young orc begins the life the Horde has set before them. Those who fail are not carried out. They are left where they fall, to bake in the sun until the desert has finished what the trial started.\n\nAt the heart of the valley stands the Den, a cave cut into the cliffside and fitted out with the plain comforts of a life lived in service. Elders keep it, teaching the young their callings and setting them to their trials.\n\nTo the north, a modest run of natural caves once sat empty in the cliffs. Something has since crept into them. Demons of the Burning Blade now nest there, spilling out into the valley proper, and their presence has given weight to old whispers that the Shadow Council has found some purchase in the region. The demons are weak, but they do not stay in their caves, and the taint they carry has begun to spread beyond the stone that once held it.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Trials",
		},
	},
