		["red cloud mesa"] = {
			name = "Red Cloud Mesa",
			short = "Red Cloud Mesa is a stretch of rolling plains atop the high cliffs of southern Mulgore, known for its quiet, open beauty.",
			full = "Red Cloud Mesa is a stretch of rolling plains atop the high cliffs of southern Mulgore, known for its quiet, open beauty. It is here that young tauren prove themselves, taking up arms against the Bristleback quilboar, who hold Brambleblade Ravine to the northeast.\n\nCamp Narache, set in the northwest of the mesa, stands as the last safe ground on the mesa. From the graveyard west of the camp, a path climbs up to the top of Fargaze Mesa.",
			source = "https://warcraft.wiki.gg/wiki/Red_Cloud_Mesa",
