		["red rocks"] = {
			name = "Red Rocks",
			short = "The red sandstone of Red Rocks rises in the northeast of Mulgore, a place where the world of Thunder Bluff falls away and something quieter takes its place.",
			full = "The red sandstone of Red Rocks rises in the northeast of Mulgore, a place where the world of Thunder Bluff falls away and something quieter takes its place. Here the tauren send their honored dead to the Earth Mother and Sky Father by cleansing flame. Not every fallen tauren is brought here; only the most valiant are given this rest, the warriors who founded and defended Thunder Bluff, those who gave their lives for their tribes and chieftains. It is also where young braves come to complete their passage into adulthood, standing among the stones to listen for the voices of their ancestors on the wind.\n\nThe sacredness of the place has not kept it safe. A band of Bristleback quilboar forced their way into Red Rocks and fouled the holy ground with their presence, an act that stirred deep anger among the tauren of Thunder Bluff who hold this place dear.",
			source = "https://warcraft.wiki.gg/wiki/Red_Rocks",
		},
		["rolling plains"] = {
			name = "Rolling Plains",
			short = "The Rolling Plains open out south of Bloodhoof Village, running toward the border of the Barrens. Wolves and cougars move through the grass alongside kodo and tallstriders.",
			full = "The Rolling Plains open out south of Bloodhoof Village, running toward the border of the Barrens. Wolves and cougars move through the grass alongside kodo and tallstriders.\n\nUnlike the rest of Mulgore, the plains are not sealed off: centaur outriders have found a way through here, ranging where no other centaur tread. In the eastern reaches, a nest of Windfury harpies has taken hold.",
			source = "https://warcraft.wiki.gg/wiki/Rolling_Plains",
		},
		["skywatcher plateau"] = {
			pending = true,
			name = "Skywatcher Plateau",
			short = "",
			full = "",
			source = "",
		},
		["stonebull lake"] = {
			name = "Stonebull Lake",
			short = "Stonebull Lake curls around Bloodhoof Village on three sides, a long horseshoe of cool water. Its waters run thick with fish, and lines are cast into it through many quiet hours.",
			full = "Stonebull Lake curls around Bloodhoof Village on three sides, a long horseshoe of cool water. Its waters run thick with fish, and lines are cast into it through many quiet hours. Where the lake narrows, a bridge spans the gap, carrying the road that links Bloodhoof Village to Thunder Bluff.",
			source = "https://warcraft.wiki.gg/wiki/Stonebull_Lake",
		},
		["thunderhorn water well"] = {
			name = "Thunderhorn Water Well",
			short = "The well sits in the open grass of Mulgore, along the north road between Thunder Bluff and Bloodhoof Village.",
			full = "The well sits in the open grass of Mulgore, along the north road between Thunder Bluff and Bloodhoof Village. The Venture Company once seized it, hoping to choke off the tauren's water, but the tauren drove them out and reclaimed it.",
			source = "https://warcraft.wiki.gg/wiki/Thunderhorn_Water_Well",
		},
		["venture co mine"] = {
			name = "Venture Co. Mine",
			short = "The mine cuts deep into the eastern cliffs of Mulgore, three ways in: the main gate on foot, a cliff face, and a small lumber camp beyond it.",
			full = "The mine cuts deep into the eastern cliffs of Mulgore, three ways in: the main gate on foot, a cliff face, and a small lumber camp beyond it. It does not belong there. The tauren refused the Venture Company mining rights in their homeland, and the company simply began digging anyway, with Supervisor Fizsprocket set over the operation and Mogul Razdunk's advisory board pressing him to expand further still, into lumber, sending new shredders and raw materials for a mill to feed on Mulgore's timber.\n\nThe tauren did not let the intrusion pass. A caravan of mining supplies moving under guard along the northern shore of Stonebull Lake was found by the Outrunners, who fell on it and burned what they could, leaving the wreckage behind on the assumption that fire had ruined anything worth taking. It had not. Venture Co. salvagers were later seen picking through the ashes, gathering up what the flames had spared.\n\nThat discovery marked the mine for retaliation, a warning struck at Fizsprocket's operation for the company's refusal to leave tauren land alone.",
			source = "https://warcraft.wiki.gg/wiki/Venture_Co._Mine",
		},
		["wildmane water well"] = {
			name = "Wildmane Water Well",
			short = "The Wildmane Water Well rises north of Thunder Bluff, northernmost of the tauren's sacred wells. Windfury harpies have taken the ground around it, and the well lies fouled, awaiting cleansing.",
			full = "The Wildmane Water Well rises north of Thunder Bluff, northernmost of the tauren's sacred wells. Windfury harpies have taken the ground around it, and the well lies fouled, awaiting cleansing.",
			source = "https://warcraft.wiki.gg/wiki/Wildmane_Water_Well",
		},
		["windfury ridge"] = {
			name = "Windfury Ridge",
			short = "Windfury Ridge takes its name from the harpies nesting in its heights, fierce creatures that swoop upon any who stray too close, killing or carrying off the unwary.",
			full = "Windfury Ridge takes its name from the harpies nesting in its heights, fierce creatures that swoop upon any who stray too close, killing or carrying off the unwary. Cougars and wolves prowl the surrounding hills as well.\n\nYet the harpies' brilliant feathers are prized by the tauren of Thunder Bluff, who take them for weddings and feasts.",
			source = "https://warcraft.wiki.gg/wiki/Windfury_Ridge",
		},
		["winterhoof water well"] = {
			name = "Winterhoof Water Well",
			short = "The Winterhoof Water Well lies at the edge of the Rolling Plains in southern Mulgore. Years after the Third War, the Venture Company seized it and poisoned its waters to choke off the tauren's supply.",
			full = "The Winterhoof Water Well lies at the edge of the Rolling Plains in southern Mulgore. Years after the Third War, the Venture Company seized it and poisoned its waters to choke off the tauren's supply. Mull Thunderhorn crafts totems to cleanse the taint, but the well is not yet pure.",
			source = "https://warcraft.wiki.gg/wiki/Winterhoof_Water_Well",
		},
	},
	-- The Barrens: 31 subzones
	[1413] = {
		["agamagor"] = {
			name = "Agama'gor",
			short = "Agama'gor lies north of the road running west from Camp Taurajo, a warren of thornwood claimed by the Bristleback quilboar.",
			full = "Agama'gor lies north of the road running west from Camp Taurajo, a warren of thornwood claimed by the Bristleback quilboar. Their dead leave behind shards of dried blood, tokens the exile Mangletooth prizes and trades his own strange favors for.",
			source = "https://warcraft.wiki.gg/wiki/Agama'gor",
		},
		["bael modan"] = {
			name = "Bael Modan",
			short = "The stone fortress of Bael'dun Keep rises where a Stonespire tauren village once stood.",
			full = "The stone fortress of Bael'dun Keep rises where a Stonespire tauren village once stood. Beneath it, dwarven excavators dig toward an ancient titan complex, a research facility buried since before the tauren themselves walked this ground, its relics still mostly unclaimed in the dark.\n\nThe dwarves came with explosives, blasting into land the Stonespire tribe held holy. The digging tore the earth apart, and it tore the tauren apart with it, most of the tribe killed or scattered from lands they had kept for generations. Their old village now lies torn open by the dwarves' digging machines. Gann Stonespire, who still walks the roads nearby, tried to settle it as one chieftain to another, speaking rather than fighting. The dwarves would not yield the dig. He turned from diplomacy to war, seeking any strength he could find to drive them out.",
			source = "https://warcraft.wiki.gg/wiki/Bael_Modan",
		},
		["baeldun keep"] = {
			name = "Bael'dun Keep",
			short = "Bael'dun Keep stands above the digsite at Bael Modan in the southern Barrens. General Twinbraid commands it, holding the keep and its dwarves against the tauren and orcs of the plains around it.",
			full = "Bael'dun Keep stands above the digsite at Bael Modan in the southern Barrens. General Twinbraid commands it, holding the keep and its dwarves against the tauren and orcs of the plains around it.",
			source = "https://warcraft.wiki.gg/wiki/Bael'dun_Keep",
		},
		["blackthorn ridge"] = {
			name = "Blackthorn Ridge",
			short = "Thorns crowd the valley north of Razorfen Kraul, held by Razormane quilboar. On the ridge dwells Brine, a shaman. Below her camp lies a pool of water, clear and pure amid the thorns.",
			full = "Thorns crowd the valley north of Razorfen Kraul, held by Razormane quilboar. On the ridge dwells Brine, a shaman. Below her camp lies a pool of water, clear and pure amid the thorns.",
			source = "https://warcraft.wiki.gg/wiki/Blackthorn_Ridge",
		},
		["boulder lode mine"] = {
			name = "Boulder Lode Mine",
			short = "The Boulder Lode Mine lies in the Barrens, its tunnels shored with orcish timber and hung with Horde banners, faded relics of whoever first drove these shafts into the rock.",
			full = "The Boulder Lode Mine lies in the Barrens, its tunnels shored with orcish timber and hung with Horde banners, faded relics of whoever first drove these shafts into the rock. That claim is gone now. The Venture Company holds the mine, goblins swarming the galleries where orcs once worked.\n\nWord reached Wharfmaster Dizzywig that one of the miners there had broken into a seam and pulled free a giant emerald. The wharfmaster wanted it badly enough to promise a share of the profit to anyone willing to go in and take it from the Venture Company's hands.",
			source = "https://warcraft.wiki.gg/wiki/Boulder_Lode_Mine",
		},
		["bramblescar"] = {
			name = "Bramblescar",
			short = "The Razormane quilboar hold Bramblescar. Across the road at Agama'gor sit the Bristleback, and between the two tribes there is only war.",
			full = "The Razormane quilboar hold Bramblescar. Across the road at Agama'gor sit the Bristleback, and between the two tribes there is only war. Wander too close to the Razormane lair and the quilboar will not wait to be provoked.",
			source = "https://warcraft.wiki.gg/wiki/Bramblescar",
		},
		["camp taurajo"] = {
			name = "Camp Taurajo",
			short = "Camp Taurajo stands in the Barrens, near the mountain pass leading into Mulgore. It offers rest and provisions to those traveling from Bloodhoof Village before they press on toward the tauren homeland.",
			full = "Camp Taurajo stands in the Barrens, near the mountain pass leading into Mulgore. It offers rest and provisions to those traveling from Bloodhoof Village before they press on toward the tauren homeland.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Taurajo",
		},
		["crossroads"] = {
			name = "Crossroads",
			short = "The Crossroads sits where the roads meet: the north-south track down from the Gold Road, and the long east-west way that runs from Ratchet out to the Stonetalon Mountains.",
			full = "The Crossroads sits where the roads meet: the north-south track down from the Gold Road, and the long east-west way that runs from Ratchet out to the Stonetalon Mountains. It is a place made by its crossing rather than by anything built there -- few lodgings, no great walls, just tents and stalls and traders shouting over one another to sell what they have.\n\nPast the edge of the settlement lies a burial ground, plain and quiet against the noise of the trade square behind it. It is here that the Horde comes to pay respects to its dead, much as Sentinel Hill serves the same purpose for the Alliance.",
			source = "https://warcraft.wiki.gg/wiki/Crossroads",
		},
		["dreadmist den"] = {
			name = "Dreadmist Den",
			short = "A dark red mist hangs forever over Dreadmist Peak, cloaking it in twilight. Within, Burning Blade cultists hold Dreadmist Den, guarding the Demon Seed, an artifact they prize above all else.",
			full = "A dark red mist hangs forever over Dreadmist Peak, cloaking it in twilight. Within, Burning Blade cultists hold Dreadmist Den, guarding the Demon Seed, an artifact they prize above all else. The mist itself seems to shield their demon-worship from outside eyes.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmist_Den",
		},
		["dreadmist peak"] = {
			name = "Dreadmist Peak",
			short = "Northwest of the Crossroads, Dreadmist Peak rises in the Barrens, its summit choked in red fog - residuum of an ancient demonic curse.",
			full = "Northwest of the Crossroads, Dreadmist Peak rises in the Barrens, its summit choked in red fog - residuum of an ancient demonic curse. Burning Blade cultists have made their home atop it, guarding the Demon Seed within the Dreadmist Den below.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmist_Peak",
		},
		["dry hills"] = {
			name = "Dry Hills",
			short = "The Dry Hills rise green against the dust of the Barrens, foothills climbing toward Stonetalon.",
			full = "The Dry Hills rise green against the dust of the Barrens, foothills climbing toward Stonetalon. The Witchwing harpies hold this ground, and they have grown bold, falling on caravans along the northern Gold Road before vanishing back into the green.",
			source = "https://warcraft.wiki.gg/wiki/Dry_Hills",
		},
		["far watch post"] = {
			name = "Far Watch Post",
			short = "Far Watch Post sits just west of the bridge linking Durotar to the Barrens, little more than a watch tower, an orc burrow, and a line of catapults, with a wolf pen and its two peons a short way south.",
			full = "Far Watch Post sits just west of the bridge linking Durotar to the Barrens, little more than a watch tower, an orc burrow, and a line of catapults, with a wolf pen and its two peons a short way south. It is not a comfortable posting, but a necessary one, guarding the caravans bound for Durotar and holding the line against Alliance and quilboar alike.",
			source = "https://warcraft.wiki.gg/wiki/Far_Watch_Post",
		},
		["field of giants"] = {
			name = "Field of Giants",
			short = "The Field of Giants sprawls across the southern Barrens, wide and open, where herds of thunder lizards and kodo move together in numbers few other lands can match.",
			full = "The Field of Giants sprawls across the southern Barrens, wide and open, where herds of thunder lizards and kodo move together in numbers few other lands can match.\n\nThe Gold Road runs its southern leg through these plains, less safe here than in the north. Watchtowers once stood along it to guard passing caravans; they stand empty now, abandoned to the wind and the grass.\n\nThe Horde has not given up this ground, though its hold on it is thin. On a ridge along the Field's southern edge lives the shaman Brine, apart from any camp or crossroads. Not far off walks Gann Stonespire, nursing an old grievance -- his tribe was driven from its village when dwarves came digging into the earth for titan ruins on land beside their home. That dig became Bael Modan, and Gann has not forgotten what it cost his people.",
			source = "https://warcraft.wiki.gg/wiki/Field_of_Giants",
		},
		["forgotten pools"] = {
			name = "Forgotten Pools",
			short = "The Forgotten Pools lie north of the western road out of the Crossroads, the northernmost of the oases scattered through the Northern Barrens.",
			full = "The Forgotten Pools lie north of the western road out of the Crossroads, the northernmost of the oases scattered through the Northern Barrens. Their shores stay green, ringed with Laden Mushrooms found nowhere else, and their waters hold deviate fish unlike any caught elsewhere in the Barrens.\n\nKolkar centaurs range the water's edge alongside the turtles and wildlife that shelter there.",
			source = "https://warcraft.wiki.gg/wiki/Forgotten_Pools",
		},
		["fray island"] = {
			name = "Fray Island",
			short = "Fray Island lies small and dry off the eastern shore of the Barrens.",
			full = "Fray Island lies small and dry off the eastern shore of the Barrens.\n\nThe island serves as a training ground for warriors of every race and creed, gathered there under Klannoc Macleod.",
			source = "https://warcraft.wiki.gg/wiki/Fray_Island",
		},
		["gold road"] = {
			name = "Gold Road",
			short = "The Gold Road stretches between Mor'shan Rampart and the Great Divide, its southern stretch known separately as the Southern Gold Road beyond the bridge that marks the crossing.",
			full = "The Gold Road stretches between Mor'shan Rampart and the Great Divide, its southern stretch known separately as the Southern Gold Road beyond the bridge that marks the crossing.",
			source = "https://warcraft.wiki.gg/wiki/Gold_Road",
		},
		["groldom farm"] = {
			name = "Grol'dom Farm",
			short = "Grol'dom Farm is one of the pig farms that took root in the years after Orgrimmar was founded, its pens standing under constant raids from the Razormane Pillagers.",
			full = "Grol'dom Farm is one of the pig farms that took root in the years after Orgrimmar was founded, its pens standing under constant raids from the Razormane Pillagers.",
			source = "https://warcraft.wiki.gg/wiki/Grol'dom_Farm",
		},
		["lushwater oasis"] = {
			name = "Lushwater Oasis",
			short = "Water gathers where the Great Divide falls away, and wild beasts come down through the trees to drink it. Kolkar centaur wait among the roots for them, hunting the animals drawn to the pools.",
			full = "Water gathers where the Great Divide falls away, and wild beasts come down through the trees to drink it. Kolkar centaur wait among the roots for them, hunting the animals drawn to the pools.\n\nBeneath the oasis lies the entrance to the Wailing Caverns, a place spoken of as accursed. What stirs below does not surface, but its name hangs over the water still.\n\nThe fish here are unlike any found elsewhere in the Barrens.",
			source = "https://warcraft.wiki.gg/wiki/Lushwater_Oasis",
		},
		["merchant coast"] = {
			name = "Merchant Coast",
			short = "The Merchant Coast takes its name from the trade that runs through it, thrifty and constant, in the hands of the goblins of Ratchet.",
			full = "The Merchant Coast takes its name from the trade that runs through it, thrifty and constant, in the hands of the goblins of Ratchet.\n\nThe southern coast belongs to the Southsea Freebooters. Among them is Baron Longshore, who once stole valuable cargo of Gazlowe's and buried it before he could be caught, leaving the fortune lost somewhere along the shore.",
			source = "https://warcraft.wiki.gg/wiki/Merchant_Coast",
		},
		["morshan base camp"] = {
			name = "Mor'shan Base Camp",
			short = "Mor'shan Base Camp stands south of the border with Ashenvale, near the Mor'shan Rampart, one of the larger Horde holdings in the Barrens.",
			full = "Mor'shan Base Camp stands south of the border with Ashenvale, near the Mor'shan Rampart, one of the larger Horde holdings in the Barrens. The Warsong Outriders make their base here, watching the road that leads north into the contested forest beyond.",
			source = "https://warcraft.wiki.gg/wiki/Mor'shan_Base_Camp",
		},
		["morshan rampart"] = {
			name = "Mor'shan Rampart",
			short = "The Mor'shan Rampart stands where the Gold Road runs north out of the Barrens, raised as a wall against the Alliance push out of Ashenvale.",
			full = "The Mor'shan Rampart stands where the Gold Road runs north out of the Barrens, raised as a wall against the Alliance push out of Ashenvale. It is a rough thing, built for war: earthworks and watch towers meant to hold a line against forces pressing down from the north.",
			source = "https://warcraft.wiki.gg/wiki/Mor'shan_Rampart",
		},
		["raptor grounds"] = {
			name = "Raptor Grounds",
			short = "The Sunscale raptors that fill this small valley are unlike any others in the Barrens. They show an unnatural cunning, building crude huts and fashioning tools with claws that should know nothing of craft.",
			full = "The Sunscale raptors that fill this small valley are unlike any others in the Barrens. They show an unnatural cunning, building crude huts and fashioning tools with claws that should know nothing of craft.\n\nStranger still is their hunger for anything bright or unfamiliar, which has driven them to raid nearby Horde settlements, dragging off whatever catches their eye.",
			source = "https://warcraft.wiki.gg/wiki/Raptor_Grounds",
		},
		["ratchet"] = {
			name = "Ratchet",
			short = "Ratchet sits on the eastern shore of the Barrens, a goblin harbor town doing brisk trade with Booty Bay and Baron Revilgaz across the sea.",
			full = "Ratchet sits on the eastern shore of the Barrens, a goblin harbor town doing brisk trade with Booty Bay and Baron Revilgaz across the sea. Gazlowe founded it with the coin Thrall paid him for raising Orgrimmar, and it filled out with smugglers and everyone else respectable places had turned away.\n\nThat indifference nearly cost it dearly. The Burning Blade cult worked quietly to set Orgrimmar and Theramore against one another, arranging shipping incidents near Ratchet's harbor that neither side understood as anything but provocation. Orc and human sailors who had shared its docks in peace began brawling in its streets, and when the bruiser Muzzlecrank arrested the captains Klatt and Joq, Northwatch Hold took it as proof the orcs were massing for war. Ratchet became the staging ground for a Horde army readying to march against them. Only when the Burning Blade's hand in the affair came to light did Thrall call the fight off before it began.",
			source = "https://warcraft.wiki.gg/wiki/Ratchet",
		},
		["shrine of the fallen warrior"] = {
			name = "Shrine of the Fallen Warrior",
			short = "A worn trail climbs a hill west of the Crossroads, ending at a shrine to a fallen warrior. No name is carved there, no banner marks it.",
			full = "A worn trail climbs a hill west of the Crossroads, ending at a shrine to a fallen warrior. No name is carved there, no banner marks it. The hill keeps its silence, and the path up it is the only sign anyone still remembers.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_the_Fallen_Warrior",
		},
		["sludge fen"] = {
			name = "Sludge Fen",
			short = "Sludge Fen was not always a wound on the land. Once it held a pool of crystal-blue water, before the Venture Company came and raised an oil rig over it.",
			full = "Sludge Fen was not always a wound on the land. Once it held a pool of crystal-blue water, before the Venture Company came and raised an oil rig over it. What is left now is a mire of industrial waste, worked under the eye of a goblin supervisor who answers for the operation to the Company.\n\nThe rig has drawn rivals as much as it has fouled the water. The Tinkers' Union in Ratchet, pressed by Director Riddlevox to match the Venture Company's newer shredders, gave up trying to out-build them and chose instead to steal the design outright. The goblin Sputtervalve sent Wizzlecrank to seize one of the machines from the fen and haul it back to Ratchet. Wizzlecrank managed only to climb into the shredder before he found he had no key to move it, and sat trapped in enemy ground until rescue came and the machine could be walked out under the noses of the Company's workers.",
			source = "https://warcraft.wiki.gg/wiki/Sludge_Fen",
		},
		["southern gold road"] = {
			name = "Southern Gold Road",
			short = "The Southern Gold Road takes its name from the caravans that travel it.",
			full = "The Southern Gold Road takes its name from the caravans that travel it. It runs from the Great Lift at the southern edge of the Barrens north to the bridge joining the Barrens' two halves, where it becomes simply the Gold Road.\n\nTraders come this way from far off: from Gadgetzan in Tanaris, from Auberdine in Darkshore, from Nighthaven to the north. All follow the same road, drawn by the same trade that gave it its name.",
			source = "https://warcraft.wiki.gg/wiki/Southern_Gold_Road",
		},
		["southfury river"] = {
			name = "Southfury River",
			short = "The Southfury rises high on Mount Hyjal, spilling from a mountain lake in a fall that drops thunderously into the lowlands.",
			full = "The Southfury rises high on Mount Hyjal, spilling from a mountain lake in a fall that drops thunderously into the lowlands. From there it runs wide and swift, cutting the land in two: it marks where Ashenvale gives way to Azshara, and further south where the Barrens ends and Durotar begins. At its mouth the river throws itself over a last cascade into the Great Sea, just northeast of the goblin port of Ratchet.\n\nThree bridges cross its length, one linking Azshara to Ashenvale, one carrying travelers into Orgrimmar, and one joining Durotar to the Barrens. Just north of the westernmost of these, a single stretch of water touches all four lands at once, the only place where Ashenvale, Azshara, Durotar, and the Barrens meet.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["stagnant oasis"] = {
			name = "Stagnant Oasis",
			short = "The Stagnant Oasis is a patch of still, green water between the Merchant Coast and the Gold Road. Kolkar centaur camp along its fringes, their presence and vitality said to come from the stagnant waters themselves.",
			full = "The Stagnant Oasis is a patch of still, green water between the Merchant Coast and the Gold Road. Kolkar centaur camp along its fringes, their presence and vitality said to come from the stagnant waters themselves. The kodo that wander here are weakened and solitary, unlike the great herds of the Field of Giants to the south, and far easier prey. Deviate fish swim beneath the surface, prized when cooked, while oasis snapjaws lurk in the murk alongside them.",
			source = "https://warcraft.wiki.gg/wiki/Stagnant_Oasis",
		},
		["thorn hill"] = {
			name = "Thorn Hill",
			short = "Thorn Hill sits on the north face of a mountain top between the Crossroads and Durotar, its slopes thick with quilboar of the Razormane tribe.",
			full = "Thorn Hill sits on the north face of a mountain top between the Crossroads and Durotar, its slopes thick with quilboar of the Razormane tribe. From this height they have struck at Horde caravans passing through the region, drawing the anger of those who guard the roads below.",
			source = "https://warcraft.wiki.gg/wiki/Thorn_Hill",
		},
		["tidus stair"] = {
			name = "Tidus Stair",
			short = "The Tidus Stair rises above the Merchant Coast as a series of broad stone terraces, stacked like a giant's staircase looking out over the water.",
			full = "The Tidus Stair rises above the Merchant Coast as a series of broad stone terraces, stacked like a giant's staircase looking out over the water. Islen Waterseer and Mahren Skyseer, two tauren, keep to these ledges, casting their lines into the surf and speaking with the spirits that dwell in the water below.",
			source = "https://warcraft.wiki.gg/wiki/Tidus_Stair",
		},
		["wailing caverns"] = {
			name = "Wailing Caverns",
			short = "The Wailing Caverns take their name from the sound of the place itself: steam bursting through fissures in the rock, carried through the dark in long, mournful cries.",
			full = "The Wailing Caverns take their name from the sound of the place itself: steam bursting through fissures in the rock, carried through the dark in long, mournful cries.\n\nIt was the night elf druid Naralex who found them, and who gave them their purpose. Beneath the savannah ran waterways that surfaced elsewhere as the scattered oases of the Barrens, and Naralex believed that if he joined those waters to the Emerald Dream itself, he could pour that green vitality back into the parched land above. He led his disciples down into the caverns and settled into meditation, opening himself as a channel between the Dream and the waking world.\n\nThe Emerald Nightmare took him instead. Naralex could not wake. Through his open, sleeping body the Nightmare's corruption poured into the caverns, tainting the waters, twisting the wildlife into strange deviate forms, and driving most of his disciples to madness -- those who remained became the Druids of the Fang.\n\nNaralex sleeps there still, and the Druids of the Fang hold the caverns against any who would wake him.",
			source = "https://warcraft.wiki.gg/wiki/Wailing_Caverns",
		},
	},
	-- Alterac Mountains: 7 subzones
	[1416] = {
		["dalaran"] = {
			name = "Dalaran",
			short = "Dalaran rose as a city of magi, founded after the Troll Wars by wizards of the Arathorian Empire, and became a nation unto itself.",
			full = "Dalaran rose as a city of magi, founded after the Troll Wars by wizards of the Arathorian Empire, and became a nation unto itself. Its people answered to no crown but the Kirin Tor, that elite circle of the world's mightiest spellcasters, governed by the Council of Six. At its heart stood the Violet Citadel, sanctum and haven to those who studied the arcane, and no city outside the elven lands of Quel'Thalas held so great a concentration of magical power. Even the high elven mages of Quel'Thalas, in their pride, bowed to the sovereignty of the Kirin Tor.\n\nThat sovereignty was broken in fire. When the Scourge came against Dalaran, its people were driven from their own kingdom, and Archimonde himself brought the city to ruin, scattering the Kirin Tor's surviving members across Azeroth.\n\nThe survivors did not let their city stay dead. They returned to the wreckage and set about rebuilding it, raising a vast dome of magic to shelter its broken heart from further harm.",
			source = "https://warcraft.wiki.gg/wiki/Dalaran",
		},
		["dandreds fold"] = {
			name = "Dandred's Fold",
			short = "A small farm and manor stands at the western edge of the Uplands, where the ground meets the Misty Shore and a harbor opens onto Lordamere Lake.",
			full = "A small farm and manor stands at the western edge of the Uplands, where the ground meets the Misty Shore and a harbor opens onto Lordamere Lake.\n\nHere lives Aliden, and with him his mistress Elysa. She wears a necklace that once belonged to Taretha Foxton.",
			source = "https://warcraft.wiki.gg/wiki/Dandred's_Fold",
		},
		["eventide"] = {
			pending = true,
			name = "The Eventide",
			short = "",
			full = "",
			source = "",
		},
		["lordamere internment camp"] = {
			name = "Lordamere Internment Camp",
			short = "Lordamere Internment Camp sits on a hill above the Dalaran Crater, the only internment camp raised in the Alterac Mountains, held under the watch of Dalaranian forces.",
			full = "Lordamere Internment Camp sits on a hill above the Dalaran Crater, the only internment camp raised in the Alterac Mountains, held under the watch of Dalaranian forces.\n\nHere, on their way to Dalaran, Prince Arthas Menethil and Lady Jaina Proudmoore once slipped past the guard patrols and watchtowers under cover of night to look upon the orcs held within. What they saw split them. Jaina looked on the orc females and their infants and felt her certainty falter into doubt and remorse. Arthas felt none of it, and held that the camps were necessary regardless. Neither was seen. They left the way they came, and the disagreement between them went with them.\n\nWarden Belamoore commands the garrison now, studying the Bloodstone Artifacts brought to her by Kegan Darkmar and his comrades.",
			source = "https://warcraft.wiki.gg/wiki/Lordamere_Internment_Camp",
		},
		["old dalaran ruins"] = {
			pending = true,
			name = "Old Dalaran Ruins",
			short = "",
			full = "",
			source = "",
		},
		["ruins of alterac"] = {
			name = "Ruins of Alterac",
			short = "Broken walls climb the slopes of the Alterac Mountains where a city once stood, its palace half-standing, its church and town hall fallen in on themselves, its gate built in the fashion of Stormwind's own.",
			full = "Broken walls climb the slopes of the Alterac Mountains where a city once stood, its palace half-standing, its church and town hall fallen in on themselves, its gate built in the fashion of Stormwind's own.\n\nIts ruin came from its own king. During the Second War, King Aiden Perenolde turned traitor, casting his lot with the Orcish Horde against his fellow humans. Alteraci soldiers were found fighting alongside the orcs, and a prison camp near the city held captive citizens of Dalaran. When the truth came out, the other human kingdoms marched on Alterac in retaliation. The people fled or were driven from their homes, and King Terenas Menethil II of Lordaeron declared the city under martial law, casting Perenolde down and throwing him into chains.\n\nThe city never rose again. Crushridge ogres, led by Mug'thol, settled into the empty streets and palace, while the scattered remnants of the old Alteraci people held the outlying villages beyond. Wrecked meat wagons still lie near the northern rampart and the gate, and the graveyards within and beyond the walls, the snow-buried farm, and shattered ballistae among the rubble remain as they were left.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Alterac",
		},
		["uplands"] = {
			name = "Uplands",
			short = "The Uplands once fed a kingdom. Its hills were the bread basket of Alterac, grain and pasture for the old nation.",
			full = "The Uplands once fed a kingdom. Its hills were the bread basket of Alterac, grain and pasture for the old nation.\n\nThat nation broke. The Uplands passed to no crown, but to the Syndicate, who hold nowhere in the mountains more firmly. Baron Vardus commands among their camps here, lord of a broken kingdom's leftover land.\n\nIn the westernmost reaches stands Dandred's Fold, a name that has outlasted whatever it once meant.",
			source = "https://warcraft.wiki.gg/wiki/Uplands",
		},
	},
	-- Arathi Highlands: 19 subzones
	[1417] = {
		["boulderfist hall"] = {
			name = "Boulderfist Hall",
			short = "Boulderfist Hall stands in southern Arathi Highlands, near Thandol Span and Witherbark Village, a mound of stone fortified by ogre hands.",
			full = "Boulderfist Hall stands in southern Arathi Highlands, near Thandol Span and Witherbark Village, a mound of stone fortified by ogre hands. Within the larger cave at its heart rules Kor'gresh Coldrage, chief of the Boulderfist clan.\n\nThe ogres have since pushed outward into the surrounding hills, strengthening their defenses further.",
			source = "https://warcraft.wiki.gg/wiki/Boulderfist_Hall",
		},
		["bouldergor"] = {
			name = "Boulder'gor",
			short = "North of Stromgarde Keep, the hill of Boulder'gor rises broken and rough. Boulderfist ogres hold their mound here, and Witherbark forest trolls linger on its slopes alongside them.",
			full = "North of Stromgarde Keep, the hill of Boulder'gor rises broken and rough. Boulderfist ogres hold their mound here, and Witherbark forest trolls linger on its slopes alongside them. On the eastern face stands the Circle of Elements, and just south of the hill lie a pair of farms.",
			source = "https://warcraft.wiki.gg/wiki/Boulder'gor",
		},
		["circle of east binding"] = {
			name = "Circle of East Binding",
			short = "The Stone of East Binding stands watch over the eastern reaches of Arathi Highlands, near Hammerfall, marking one of the Circles of Binding scattered across the region.",
			full = "The Stone of East Binding stands watch over the eastern reaches of Arathi Highlands, near Hammerfall, marking one of the Circles of Binding scattered across the region. Water elementals guard the stone still, bound to the place as though holding some old task unfinished.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_East_Binding",
		},
		["circle of inner binding"] = {
			name = "Circle of Inner Binding",
			short = "The Circle of Inner Binding stands in southern Arathi Highlands near Stromgarde Keep, guarded by earth elementals. Here rests the Stone of Inner Binding, strongest of the stones.",
			full = "The Circle of Inner Binding stands in southern Arathi Highlands near Stromgarde Keep, guarded by earth elementals. Here rests the Stone of Inner Binding, strongest of the stones.\n\nThrough its shard, Myzrael found a way to speak with mortals.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_Inner_Binding",
		},
		["circle of outer binding"] = {
			name = "Circle of Outer Binding",
			short = "The Circle of Outer Binding lies near Refuge Pointe in the Arathi Highlands. At its center stands the Stone of Outer Binding, guarded always by elementals of air.",
			full = "The Circle of Outer Binding lies near Refuge Pointe in the Arathi Highlands. At its center stands the Stone of Outer Binding, guarded always by elementals of air.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_Outer_Binding",
		},
		["circle of west binding"] = {
			name = "Circle of West Binding",
			short = "The Circle of West Binding stands in western Arathi Highlands, near Thoradin's Wall. There the Stone of West Binding rests, guarded by fire elementals that never leave it unwatched.",
			full = "The Circle of West Binding stands in western Arathi Highlands, near Thoradin's Wall. There the Stone of West Binding rests, guarded by fire elementals that never leave it unwatched.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_West_Binding",
		},
		["dabyries farmstead"] = {
			name = "Dabyrie's Farmstead",
			short = "In the northern reaches of the Arathi Highlands stands Dabyrie's Farmstead, held by Kenata Dabyrie and her children Fardel and Marcel, citizens of Stromgarde and loyal to the Alliance.",
			full = "In the northern reaches of the Arathi Highlands stands Dabyrie's Farmstead, held by Kenata Dabyrie and her children Fardel and Marcel, citizens of Stromgarde and loyal to the Alliance. A militia keeps watch over the fields, for the family has enemies.",
			source = "https://warcraft.wiki.gg/wiki/Dabyrie's_Farmstead",
		},
		["drowned reef"] = {
			name = "Drowned Reef",
			short = "Beneath the bay off the southern shore of Arathi Highlands lies a sunken elven city, ancient and ruined. It is no longer empty: the Daggerspine naga have claimed it, ruled by Prince Nazjak.",
			full = "Beneath the bay off the southern shore of Arathi Highlands lies a sunken elven city, ancient and ruined. It is no longer empty: the Daggerspine naga have claimed it, ruled by Prince Nazjak.\n\nThe reef above has taken many ships, among them the Maiden's Folly and the Spirit of Silverpine. It is said the Daggerspine can turn the very tides of the bay, luring crews who think they have found safe harbor in Faldir's Cove onto the stones instead.",
			source = "https://warcraft.wiki.gg/wiki/Drowned_Reef",
		},
		["drywhisker gorge"] = {
			name = "Drywhisker Gorge",
			short = "Drywhisker Gorge cuts through the mountains of eastern Arathi Highlands, northeast of Hammerfall. At its end lies a cave, home to the kobolds of Drywhisker, allied to the giants that share these highlands.",
			full = "Drywhisker Gorge cuts through the mountains of eastern Arathi Highlands, northeast of Hammerfall. At its end lies a cave, home to the kobolds of Drywhisker, allied to the giants that share these highlands.\n\nDeep within, past the warrens, rests a stone shard in which a piece of the essence of Princess Myzrael lies trapped. The kobolds guard it fiercely, along with the motes gathered in the cave's depths, though none among them seem to know what the shard truly holds.",
			source = "https://warcraft.wiki.gg/wiki/Drywhisker_Gorge",
		},
		["faldirs cove"] = {
			name = "Faldir's Cove",
			short = "Faldir's Cove takes its name from Faldir, who is said to have marked this spot when he and his followers set out.",
			full = "Faldir's Cove takes its name from Faldir, who is said to have marked this spot when he and his followers set out.\n\nLong after, the Blackwater Raiders came seeking an elven treasure said to lie in the waters nearby. Captains Steelgut and O'Breen led three ships into the cove, but a strange tide rose against them, stirred by naga guarding sunken ruins beneath the reef, and two of the three ships went down. Only the Harbinger reached the shore, and her crew found themselves trapped in the bay, unable to leave until the naga were driven off and the navigation logs recovered from the wrecks below.\n\nLater, two gnomish engineers, Doctor Draxlegauge and Professor Phizzlethorpe, built a device to hunt for elven gems said to be calcified within the stones of the Drowned Reef.\n\nThe cove still bears the scars of that flooded history: reef, wreck, and ruin, all telling of ships that never should have sunk, and a treasure the sea has not given up.",
			source = "https://warcraft.wiki.gg/wiki/Faldir's_Cove",
		},
		["goshek farm"] = {
			name = "Go'Shek Farm",
			short = "Go'Shek Farm lies in the eastern Arathi Highlands, near Witherbark Village.",
			full = "Go'Shek Farm lies in the eastern Arathi Highlands, near Witherbark Village. After the Third War, Forsaken and orcs out of Hammerfall took the farm for their own purposes, the orcs drawing supplies from it, the Forsaken turning its fields and outbuildings into a testing ground for alchemy of a darker sort.\n\nThe Alliance agents Quae and Kinelory came to look into what was happening here. With help, they cut down a Forsaken courier bound for Tarren Mill before he could deliver his message, and searched the farmstead itself, where they turned up the notes of an Apothecary Jorell. His research pointed to something new and terrible taking shape: another plague in the making.\n\nHammerfall Grunts hold the farm now.",
			source = "https://warcraft.wiki.gg/wiki/Go'Shek_Farm",
		},
		["hammerfall"] = {
			name = "Hammerfall",
			short = "The ground at Hammerfall remembers what it once was. After the Second War the Alliance of Lordaeron built one of its largest internment camps here, penning captured orcs behind its walls.",
			full = "The ground at Hammerfall remembers what it once was. After the Second War the Alliance of Lordaeron built one of its largest internment camps here, penning captured orcs behind its walls. It did not stay a prison. Warchief Thrall and Orgrim Doomhammer led the Horde against the camp to free their people, and in the chaos of that liberation, as Thrall covered the retreat, a charging knight drove a lance into Orgrim's back with such force that it pierced his armor front and back. Doomhammer died there, on the ground he had come to free.\n\nAfter the Third War the Horde returned to the ruins and raised a forward base among them, naming it Hammerfall in honor of the Warchief who had fallen taking it. It became more than an outpost -- a refuge for those who felt they had no place left in the world, its spirit lodges, stables, forge, and great hall standing where the internment camp's walls once stood.",
			source = "https://warcraft.wiki.gg/wiki/Hammerfall",
		},
		["northfold manor"] = {
			name = "Northfold Manor",
			short = "After the fall of Stromgarde, Northfold Manor passed into the hands of the Syndicate, who made it an outpost in Arathi Highlands.",
			full = "After the fall of Stromgarde, Northfold Manor passed into the hands of the Syndicate, who made it an outpost in Arathi Highlands.\n\nHere the troll shaman Tor'gan came, drawn by a wrongness in the air. Tracing it to the manor, he found the residual traces of demonic summoning still clinging to the place, and as he drew close his own blood began to boil with a rage not fully his own. On the ground he found an amulet of bloodstone, used to call up demons, though this one was spent of its power. Suspecting the Syndicate's dealings ran deeper than banditry, he sought out other such amulets to learn the truth of their intentions.",
			source = "https://warcraft.wiki.gg/wiki/Northfold_Manor",
		},
		["refuge pointe"] = {
			name = "Refuge Pointe",
			short = "When Stromgarde's capital fell in ruins during the Third War, most of its people fled south into the Arathi Highlands. But the remnants of the Stromgarde army would not go with them.",
			full = "When Stromgarde's capital fell in ruins during the Third War, most of its people fled south into the Arathi Highlands. But the remnants of the Stromgarde army would not go with them. They stayed, determined to reclaim what had been lost, and it was here, at Refuge Pointe, that they made their stand.\n\nThe outpost became the seat of the Alliance's war in the Highlands, its soldiers bent on retaking Stromgarde Keep and securing what resources they could for the Alliance's cause. That singleness of purpose left little room for anything else. When Thandol Span was struck hard by a Dark Iron assault and its dwarves sent word asking for aid to reclaim Dun Modr and the span itself, Captain Nials could not spare a soul. Stromgarde had fallen, she said, and until it was retaken every sword and every hand at Refuge Pointe belonged to that cause alone. Honor and duty bound them to the Highlands, she told the messenger, and Longbraid the Grim would have to manage without them.",
			source = "https://warcraft.wiki.gg/wiki/Refuge_Pointe",
		},
		["stromgarde keep"] = {
			name = "Stromgarde Keep",
			short = "Stromgarde was once Strom, cradle of the first human kingdom, capital of the Arathorian Empire.",
			full = "Stromgarde was once Strom, cradle of the first human kingdom, capital of the Arathorian Empire. When the Orcish Horde came to the Eastern Kingdoms, it still stood as a power among the Alliance of Lordaeron, its name unbowed even after the Second War.\n\nThe city was sacked after the Third War and left broken. It now lies split into three: the inner keep held by the Syndicate, the ruined mage district overrun by Boulderfist ogres aided by Witherbark trolls, and the last quarter still held by the Stromgarde military, from which Prince Galen Trollbane commands what remains of his people.",
			source = "https://warcraft.wiki.gg/wiki/Stromgarde_Keep",
		},
		["thandol span"] = {
			name = "Thandol Span",
			short = "Two great stone arches span the gap between the Wetlands and the Arathi Highlands, raised by dwarven hands and guarded for three generations by the Anvilmar line.",
			full = "Two great stone arches span the gap between the Wetlands and the Arathi Highlands, raised by dwarven hands and guarded for three generations by the Anvilmar line. They were built after the War of the Three Hammers, when Ironforge sought to keep faith with its Wildhammer kin in Aerie Peak, and the bridges became both road and symbol between the two dwarven kingdoms, carrying trade that enriched them both.\n\nThe bridges were capable of bearing the weight of whole armies, and once served as the main road of trade between dwarves and humans. It was here that Anduin Lothar drove the last of the Old Horde out of Lordaeron and back into Khaz Modan, forcing them across the Span in defeat.\n\nNow the Span stands scarred. A Dark Iron plot, laid by Kam Deepfury and Balgaras the Foul, has done heavy damage to the bridges, and dwarven forces fight to hold what remains and retake the nearby town of Dun Modr. Many dwarves have died in the fighting, among them Sully Balloo, Ebenezer Rustlocke, and the brother of Longbraid the Grim.",
			source = "https://warcraft.wiki.gg/wiki/Thandol_Span",
		},
		["thoradins wall"] = {
			name = "Thoradin's Wall",
			short = "King Thoradin raised this wall to hold back the Amani trolls, in the days when Strom stood young and Arathor had only just claimed the land for humanity.",
			full = "King Thoradin raised this wall to hold back the Amani trolls, in the days when Strom stood young and Arathor had only just claimed the land for humanity. For generations it stood a stalwart sentinel, a line meant to shield mankind from the trolls' incursions.\n\nCenturies on, the wall still stands, but heavily damaged, its stones broken and its long watch reduced to ruin.",
			source = "https://warcraft.wiki.gg/wiki/Thoradin's_Wall",
		},
		["tower of arathor"] = {
			name = "Tower of Arathor",
			short = "The Tower of Arathor stands in the mage district of Stromgarde Keep, named for the old Empire of Arathor from which the kingdom took its lineage.",
			full = "The Tower of Arathor stands in the mage district of Stromgarde Keep, named for the old Empire of Arathor from which the kingdom took its lineage.\n\nArchmage Trelane once studied within its walls, and there he built a defense woven into the tower itself, dormant until woken by an enchanted gem. When the Syndicate and the Boulderfist ogres closed in on Stromgarde, Trelane tried to hold the tower with his creation, but it was not enough. He fled the city, and the tower fell with it. The Boulderfist ogres took the district for their own, and the ogre mage Ruul Onestone came to dwell within its halls.\n\nTrelane never stopped thinking of what he had left behind there -- his phylactery, his orb, an ember agate worked with his own hand. He turned to his former apprentice, Archmage Malin, to see them recovered from the ogres who now held the tower. Word came back to Malin that the old master's possessions had been found again, hidden away in chests within the halls he once called his own.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Arathor",
		},
		["witherbark village"] = {
			name = "Witherbark Village",
			short = "Witherbark Village sits around a small lake in the southeast of the Arathi Highlands, home to the trolls of the Witherbark tribe. Behind the village lies a large cavern where the tribe's leaders are most often found.",
			full = "Witherbark Village sits around a small lake in the southeast of the Arathi Highlands, home to the trolls of the Witherbark tribe. Behind the village lies a large cavern where the tribe's leaders are most often found.\n\nThe Witherbark have made common cause with the Boulderfist ogres nearby, an alliance turned against Stromgarde and Hammerfall. Together, troll and ogre hold a section of Stromgarde itself, wrested from its former masters.\n\nThat strength has made the Witherbark a marked people, hunted by both the Alliance and the Horde, who wished to see them ended. Among those who stood against that reckoning, Nimar the Slayer was named the most dangerous, a fighter who in death took many of his enemies with him.",
			source = "https://warcraft.wiki.gg/wiki/Witherbark_Village",
		},
	},
	-- Badlands: 17 subzones
	[1418] = {
		["agmonds end"] = {
			name = "Agmond's End",
			short = "The dig site in the southern central Badlands bears the name of the dwarf who died there.",
			full = "The dig site in the southern central Badlands bears the name of the dwarf who died there. Agmond came to break stone and found the troggs that had already claimed the ground; they finished him where he stood, and the site was abandoned to them.",
			source = "https://warcraft.wiki.gg/wiki/Agmond's_End",
		},
		["angor fortress"] = {
			name = "Angor Fortress",
			short = "The Dark Iron dwarves hold Angor Fortress as their seat in the Badlands, directing their digging toward Uldaman.",
			full = "The Dark Iron dwarves hold Angor Fortress as their seat in the Badlands, directing their digging toward Uldaman.",
			source = "https://warcraft.wiki.gg/wiki/Angor_Fortress",
		},
		["apocryphans rest"] = {
			name = "Apocryphan's Rest",
			short = "The bones of Apocryphan's Rest sprawl across the Badlands south of Kargath, a dragon's skeleton fallen and left to bleach in the dry heat.",
			full = "The bones of Apocryphan's Rest sprawl across the Badlands south of Kargath, a dragon's skeleton fallen and left to bleach in the dry heat. Buzzards nest and hunt among the ribs now, the only ones who claim the great carcass as home.",
			source = "https://warcraft.wiki.gg/wiki/Apocryphan's_Rest",
		},
		["camp boff"] = {
			name = "Camp Boff",
			short = "Camp Boff is the southeastern camp of the Dustbelcher ogres, one of four alongside Camp Cagg, Kosh, and Wurg. Few ogres guard it.",
			full = "Camp Boff is the southeastern camp of the Dustbelcher ogres, one of four alongside Camp Cagg, Kosh, and Wurg. Few ogres guard it.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Boff",
		},
		["camp cagg"] = {
			name = "Camp Cagg",
			short = "Camp Cagg is one of the homes of the Dustbelcher ogres, sharing that name with three other camps scattered nearby.",
			full = "Camp Cagg is one of the homes of the Dustbelcher ogres, sharing that name with three other camps scattered nearby.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Cagg",
		},
		["camp kosh"] = {
			name = "Camp Kosh",
			short = "Camp Kosh sits at the northern edge of Dustbelcher territory, watching the barren roads that wind toward Kargath and down into the Searing Gorge.",
			full = "Camp Kosh sits at the northern edge of Dustbelcher territory, watching the barren roads that wind toward Kargath and down into the Searing Gorge. Caravans crossing the Badlands dread this stretch, for the ogres of Kosh fall upon them for whatever they carry.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Kosh",
		},
		["camp wurg"] = {
			name = "Camp Wurg",
			short = "Camp Wurg is one of the homes of the Dustbelcher ogres, kin to the ogres of Camp Cagg, Camp Boff, and Camp Kosh.",
			full = "Camp Wurg is one of the homes of the Dustbelcher ogres, kin to the ogres of Camp Cagg, Camp Boff, and Camp Kosh.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Wurg",
		},
		["dustbelch grotto"] = {
			name = "Dustbelch Grotto",
			short = "In the southwestern Badlands rises a great mound of earth and stone, hollowed out and claimed by the Dustbelcher ogres.",
			full = "In the southwestern Badlands rises a great mound of earth and stone, hollowed out and claimed by the Dustbelcher ogres. Dustbelch Grotto is their home, a warren of tunnels and chambers where the clan has made its den amid the cracked, sun-scorched land around it.",
			source = "https://warcraft.wiki.gg/wiki/Dustbelch_Grotto",
		},
		["dustbowl"] = {
			name = "Dustbowl",
			short = "The Dustbowl lies between Kargath and the valley of fangs, a stretch of cracked, arid ground in the northwest Badlands. Coyotes and buzzards range across it, and rock elementals stir among the stones.",
			full = "The Dustbowl lies between Kargath and the valley of fangs, a stretch of cracked, arid ground in the northwest Badlands. Coyotes and buzzards range across it, and rock elementals stir among the stones. Little grows here but cactus and a few stubborn trees. Camp Wurg stands within this waste.",
			source = "https://warcraft.wiki.gg/wiki/Dustbowl",
		},
		["dustwind gulch"] = {
			name = "Dustwind Gulch",
			short = "The winds scour Dustwind Gulch until nothing soft is left standing, only stone and the ravine's dry bones. It lies west of Lethlor Ravine, a cut of barren ground in the Badlands where the dust never settles for long.",
			full = "The winds scour Dustwind Gulch until nothing soft is left standing, only stone and the ravine's dry bones. It lies west of Lethlor Ravine, a cut of barren ground in the Badlands where the dust never settles for long.",
			source = "https://warcraft.wiki.gg/wiki/Dustwind_Gulch",
		},
		["hammertoes digsite"] = {
			name = "Hammertoe's Digsite",
			short = "Hammertoe's Digsite sits in the northern Badlands, its excavation trenches now silent of the miners who once worked them.",
			full = "Hammertoe's Digsite sits in the northern Badlands, its excavation trenches now silent of the miners who once worked them. Hammertoe himself has abandoned the site, and in his place a gang of Dark Irons has moved in, likely the same force that has pushed into Uldaman.",
			source = "https://warcraft.wiki.gg/wiki/Hammertoe's_Digsite",
		},
		["kargath"] = {
			name = "Kargath",
			short = "Kargath stands alone in Khaz Modan, the only outpost the Horde holds in that land, named for Kargath Bladefist, chieftain of the Shattered Hand clan.",
			full = "Kargath stands alone in Khaz Modan, the only outpost the Horde holds in that land, named for Kargath Bladefist, chieftain of the Shattered Hand clan.\n\nOn the order of Warchief Thrall himself, the Kargath Expeditionary Force rides out again and again into the harsh Badlands. Its true purpose is to cut a route through the Searing Gorge to Blackrock Mountain, so the Horde might strike at Rend Blackhand, Warchief of the Dark Horde, in his own stronghold. That road runs through ground the Dark Iron dwarves call theirs, and so the Horde has found itself at war with them again, not by plan but by the simple fact of the land it needed to cross.\n\nKargath's other worth is plainer to see: it is the hinge between north and south, the point where the road from Hammerfall and the Undercity meets the road down to Grom'Gol, Booty Bay, and Stonard.",
			source = "https://warcraft.wiki.gg/wiki/Kargath",
		},
		["lethlor ravine"] = {
			name = "Lethlor Ravine",
			short = "Lethlor Ravine cuts wide and craggy through the eastern Badlands, its floor haunted by whelps and drakes of the black dragonflight.",
			full = "Lethlor Ravine cuts wide and craggy through the eastern Badlands, its floor haunted by whelps and drakes of the black dragonflight. Scattered through the ravine stand crystalline obelisks, strange and deliberate amid the rock and dragon-fire.",
			source = "https://warcraft.wiki.gg/wiki/Lethlor_Ravine",
		},
		["makers terrace"] = {
			name = "Maker's Terrace",
			short = "Outside the entrance to Uldaman, the earth has been peeled back in wide, deliberate cuts, a scar of excavation left open to the sky.",
			full = "Outside the entrance to Uldaman, the earth has been peeled back in wide, deliberate cuts, a scar of excavation left open to the sky. Dark Iron dwarves hold the Terrace now, watching the diggings and the road that leads down into the buried places below.",
			source = "https://warcraft.wiki.gg/wiki/Maker's_Terrace",
		},
		["mirage flats"] = {
			name = "Mirage Flats",
			short = "The Mirage Flats lies east of Dustbelch Grotto in the Badlands. Little remains of it but a stretch of no-man's land, claimed only by giant buzzards, ridge stalker patriarchs, and rabid crag coyotes.",
			full = "The Mirage Flats lies east of Dustbelch Grotto in the Badlands. Little remains of it but a stretch of no-man's land, claimed only by giant buzzards, ridge stalker patriarchs, and rabid crag coyotes.",
			source = "https://warcraft.wiki.gg/wiki/Mirage_Flats",
		},
		["uldaman"] = {
			name = "Uldaman",
			short = "Deep within the mountains of Khaz Modan lies Uldaman, a vast and ancient vault raised by the titan keepers in ages long past.",
			full = "Deep within the mountains of Khaz Modan lies Uldaman, a vast and ancient vault raised by the titan keepers in ages long past. Dwarves out of Ironforge once delved into it, cutting away at its buried chambers before the Third War, but the vault has since fallen to troggs and Dark Irons, who now dig through its stone for whatever earthly riches it still holds.\n\nUldaman remains rich with the leavings of that titan-forged age, and those willing to brave its depths still find artifacts buried within it, slowly uncovered by archaeologists and adventurers of the Explorers' League who continue to pick through the ruin.",
			source = "https://warcraft.wiki.gg/wiki/Uldaman",
		},
		["valley of fangs"] = {
			name = "Valley of Fangs",
			short = "The Valley of Fangs cuts narrow between two walls of stone in the Badlands, claimed by wolves and cougars whose teeth give the place its name.",
			full = "The Valley of Fangs cuts narrow between two walls of stone in the Badlands, claimed by wolves and cougars whose teeth give the place its name.\n\nWithin it camps Martek the Exiled, cast out from wherever he once belonged, alongside Rigglefuzz and Jazzrik.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Fangs",
		},
	},
	-- Blasted Lands: 7 subzones
	[1419] = {
		["dark portal"] = {
			name = "Dark Portal",
			short = "The portal's making was a betrayal from the first stroke. Gul'dan and the human mage Medivh, the latter possessed by the Dark Titan Sargeras, tore the rift together.",
			full = "The portal's making was a betrayal from the first stroke. Gul'dan and the human mage Medivh, the latter possessed by the Dark Titan Sargeras, tore the rift together. On Draenor, the orc stonemasons who built its stone frame were murdered by warlocks to prime the final seal, and nearly every draenei prisoner still held by the Horde was brought to its base and drained of life in a single instant to give Gul'dan the power to bridge the two worlds. Through that gateway the Horde poured into Stormwind and began the First War, and in the war that followed it fed endless orcs and ogres into Azeroth, the swamps around it curdling into the blood-red waste later called the Blasted Lands.\n\nAt the war's end the archmage Khadgar and his fellow magi shattered the structure on Azeroth's side to bar the Horde's retreat, an explosion so violent it destroyed the frame on Draenor too. Khadgar raised Nethergarde Keep afterward to stand watch over the ruin, though the tear between the worlds was never truly sealed, and demons would come through it again in the years after.",
			source = "https://warcraft.wiki.gg/wiki/Dark_Portal",
		},
		["dreadmaul post"] = {
			name = "Dreadmaul Post",
			short = "Dreadmaul Post is a mound raised by the Dreadmaul ogre clan, who crossed into Azeroth from Draenor and never wandered far from the Dark Portal.",
			full = "Dreadmaul Post is a mound raised by the Dreadmaul ogre clan, who crossed into Azeroth from Draenor and never wandered far from the Dark Portal. They hold the ground still.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmaul_Post",
		},
		["garrison armory"] = {
			name = "Garrison Armory",
			short = "In the scarred ground of the Blasted Lands, Alliance miners work the Garrison Armory, wresting minerals from the earth for Nethergarde Keep.",
			full = "In the scarred ground of the Blasted Lands, Alliance miners work the Garrison Armory, wresting minerals from the earth for Nethergarde Keep. What they gather is shipped on to Stormwind, and in return the keep receives the other supplies it needs to endure in that blighted place.",
			source = "https://warcraft.wiki.gg/wiki/Garrison_Armory",
		},
		["nethergarde keep"] = {
			name = "Nethergarde Keep",
			short = "Nethergarde Keep stands on a high bluff above the only road into the Blasted Lands, its walls raised to watch a scar in the world that no one wanted opened again.",
			full = "Nethergarde Keep stands on a high bluff above the only road into the Blasted Lands, its walls raised to watch a scar in the world that no one wanted opened again.\n\nArchmage Khadgar called for its building, in the years after the Second War, when the first Dark Portal lay broken and the orcish homelands beyond it had withered into ruin. The Alliance of Lordaeron paid for it, some kingdoms more gladly than others, and the Stonemasons Guild raised it under Edwin VanCleef's hand. The Kirin Tor manned it afterward, laboring to hold back the taint that crept from the portal's wound and threatened to spread across the land beyond.\n\nKhadgar remained its master until Ner'zhul's clans reforged the Dark Portal from the Draenor side and besieged the keep. Khadgar and his companions Turalyon, Danath Trollbane, Alleria Windrunner, and Kurdran Wildhammer led the Alliance through the portal to break the Horde there, then stayed behind on the other side to seal it, so that Draenor's ruin would not follow them home. For twenty years after, the portal stood silent.",
			source = "https://warcraft.wiki.gg/wiki/Nethergarde_Keep",
		},
		["rise of the defiler"] = {
			name = "Rise of the Defiler",
			short = "The Rise of the Defiler rears up from the middle of the Blasted Lands, a craggy stretch of broken mountain. Here dwells the great demon Razelikh, its presence enough to give the place its name.",
			full = "The Rise of the Defiler rears up from the middle of the Blasted Lands, a craggy stretch of broken mountain. Here dwells the great demon Razelikh, its presence enough to give the place its name.",
			source = "https://warcraft.wiki.gg/wiki/Rise_of_the_Defiler",
		},
		["serpents coil"] = {
			name = "Serpent's Coil",
			short = "The Serpent's Coil is a winding cave system in the eastern Blasted Lands, its mouth marked by burnt-out orcish structures left over from the Second War.",
			full = "The Serpent's Coil is a winding cave system in the eastern Blasted Lands, its mouth marked by burnt-out orcish structures left over from the Second War. Long after that war ended, the caves became a hollow for something darker: cultists given over to the worship of Kirith the Damned.\n\nInto that labyrinth came Archmage Allistarj, who set his Shadowsworn to work from within it. Near the entrance a chest holds an amulet bearing his name.",
			source = "https://warcraft.wiki.gg/wiki/Serpent's_Coil",
		},
		["tainted scar"] = {
			name = "Tainted Scar",
			short = "The Tainted Scar was once part of the Black Morass, before the Dark Portal's corruption bled into it and left the ground dry, treeless, and red as blood.",
			full = "The Tainted Scar was once part of the Black Morass, before the Dark Portal's corruption bled into it and left the ground dry, treeless, and red as blood. No water runs there now. Demonic beasts prowl soil that no longer remembers what grew on it.\n\nAfter the battle at Mount Hyjal, the ered'ruin lord Kazzak withdrew what remained of the Burning Legion's forces on Azeroth into the Scar, making it his ground. He set his lieutenant Razelikh the Defiler over it, charging the Defiler to hold the land secure. Kazzak himself remained there afterward, his presence alone enough to mark the Scar as Legion territory still, years after Hyjal was fought and won elsewhere.\n\nAn old human warlock, Daio the Decrepit, came to the Scar long after and made his home at its altar. There, among the demons the land already bred, he practiced his rituals undisturbed and took on young recruits, teaching them the infernal arts in a place already given over to the fel.",
			source = "https://warcraft.wiki.gg/wiki/Tainted_Scar",
		},
	},
	-- Tirisfal Glades: 31 subzones
	[1420] = {
		["agamand family crypt"] = {
			name = "Agamand Family Crypt",
			short = "North of Agamand Mills, the Agamand family's dead once rested in this crypt. Captain Dargol, a minion of the Scourge, took the place for his own and woke every corpse and spirit within it.",
			full = "North of Agamand Mills, the Agamand family's dead once rested in this crypt. Captain Dargol, a minion of the Scourge, took the place for his own and woke every corpse and spirit within it. Now dust hangs thick in the dark passages, and the vengeful dead strike at anyone who enters unbidden.",
			source = "https://warcraft.wiki.gg/wiki/Agamand_Family_Crypt",
		},
		["agamand mills"] = {
			name = "Agamand Mills",
			short = "The windmills of Agamand once turned for one of the wealthiest families in Tirisfal. When the Scourge came north, Gregor Agamand refused to flee.",
			full = "The windmills of Agamand once turned for one of the wealthiest families in Tirisfal. When the Scourge came north, Gregor Agamand refused to flee. He fortified the mills, stocked them against siege, and convinced the family's own workers to stand and fight beside them.\n\nIt should have held. It did not, because the betrayal came from inside the walls. Devlin, the youngest Agamand son, turned on his own blood and aided the Scourge, and the garrison could not hold the line against the assaults that followed. In time the plague took the rest of the family anyway, and the Agamands who had died defending their home rose again as mindless dead within it.\n\nThe windmills still stand in the highlands of northern Tirisfal, and the family that built them now serves the very host that broke them.",
			source = "https://warcraft.wiki.gg/wiki/Agamand_Mills",
		},
		["balnir farmstead"] = {
			name = "Balnir Farmstead",
			short = "The Balnir Farmstead lies northeast of the ruined capital, its fences broken and its stables empty but for wandering Scourge.",
			full = "The Balnir Farmstead lies northeast of the ruined capital, its fences broken and its stables empty but for wandering Scourge.\n\nThe Balnir family once ran this land, breeding the great white horses that the royal house of Lordaeron rode as mounts. On the day Capital City fell, the Scourge came for the farmstead and killed the whole family, leaving only their haunted ground behind.\n\nThe snapdragons once tended in the farm's garden still grow wild there, and word has reached the living that the corruption of the Plaguelands may have crept into them. Scourge that slip past the Bulwark gather in numbers around the ruined farm.",
			source = "https://warcraft.wiki.gg/wiki/Balnir_Farmstead",
		},
		["bandarion keep"] = {
			pending = true,
			name = "Bandarion Keep",
			short = "",
			full = "",
			source = "",
		},
		["brightwater lake"] = {
			name = "Brightwater Lake",
			short = "Brightwater Lake lies northeast of Brill, its waters holding a large island at their center where Gunther's Retreat now stands.",
			full = "Brightwater Lake lies northeast of Brill, its waters holding a large island at their center where Gunther's Retreat now stands.",
			source = "https://warcraft.wiki.gg/wiki/Brightwater_Lake",
		},
		["brill"] = {
			name = "Brill",
			short = "Brill was once an ordinary town in the kingdom of Lordaeron, held by the Barov family, with the Agamands keeping a manor of their own within its bounds.",
			full = "Brill was once an ordinary town in the kingdom of Lordaeron, held by the Barov family, with the Agamands keeping a manor of their own within its bounds. Its ordinariness ended the day Kel'Thuzad came to it. Still a living man then, the necromancer chose Brill as the place to first test the plague of undeath, and the success of that infestation was so complete that it emboldened him to press the Lich King into launching the invasion of Lordaeron before its time. The dead of Tirisfal Glades were more than the land could bury properly; the great graveyard outside Brill's walls stands as the answer to that surplus. The town's own defenders could not hold it, and what survivors remained fled to join Prince Arthas Menethil as he hunted the source of the corruption sweeping the north.\n\nBrill did not stay silent. Years later the Forsaken claimed it, and Magistrate Sevren now governs what the plague once took. Old grudges linger here too: Coleman Farthing, once in service to the Agamand family, still seeks their remains, bones given not in mercy but in vengeance for a death he blames on them.",
			source = "https://warcraft.wiki.gg/wiki/Brill",
		},
		["brill town hall"] = {
			name = "Brill Town Hall",
			short = "The Town Hall stands as the most prominent structure in Brill. From its podium, Magistrate Sevren speaks for the town, setting the dead of Tirisfal to their tasks.",
			full = "The Town Hall stands as the most prominent structure in Brill. From its podium, Magistrate Sevren speaks for the town, setting the dead of Tirisfal to their tasks. Few such halls anywhere stand in Forsaken hands as this one does, a mark of how firmly Brill belongs to them.",
			source = "https://warcraft.wiki.gg/wiki/Brill_Town_Hall",
		},
		["bulwark"] = {
			name = "Bulwark",
			short = "The Bulwark stands where Tirisfal Glades meets the Western Plaguelands, the line the Forsaken hold against the Scourge that still masses to the east.",
			full = "The Bulwark stands where Tirisfal Glades meets the Western Plaguelands, the line the Forsaken hold against the Scourge that still masses to the east. Here Forsaken defenders and the Argent Dawn have set aside their differences against that common enemy, watching the border together and sending fighters east to strike at the Lich King's minions.\n\nUnlike the rest of Tirisfal, this stretch does not look like the Glades at all: a plaguemist hangs over it, tinting the sky the same sickly yellow-gray as the Western Plaguelands beyond.",
			source = "https://warcraft.wiki.gg/wiki/Bulwark",
		},
		["cold hearth manor"] = {
			name = "Cold Hearth Manor",
			short = "Cold Hearth Manor once earned its name for the warmth of its hearth and the richness of its fields. The Plague of Undeath ended that.",
			full = "Cold Hearth Manor once earned its name for the warmth of its hearth and the richness of its fields. The Plague of Undeath ended that. Everyone who lived or worked here died in the sickness, and the bountiful ground turned barren, its rows overtaken by mindless Scourge dead who still shamble there.\n\nThe Forsaken took the farmhouse for their own, dealing with travelers on the road nearby.",
			source = "https://warcraft.wiki.gg/wiki/Cold_Hearth_Manor",
		},
		["crusader outpost"] = {
			name = "Crusader Outpost",
			short = "A scout tower rises in the eastern hills of Tirisfal Glades, held by the Scarlet Crusade.",
			full = "A scout tower rises in the eastern hills of Tirisfal Glades, held by the Scarlet Crusade. From its height they watch the road south through the glades, ready to flank any force that dares march on the Scarlet Monastery beyond. Captain Vachon commands here.",
			source = "https://warcraft.wiki.gg/wiki/Crusader_Outpost",
		},
		["deathknell"] = {
			name = "Deathknell",
			short = "Deathknell lies in a narrow, well-guarded valley, and it is here that the newly risen Forsaken first open their eyes to the world they have been given.",
			full = "Deathknell lies in a narrow, well-guarded valley, and it is here that the newly risen Forsaken first open their eyes to the world they have been given.\n\nUnlike the other holdings of the Banshee Queen's rebel undead, which kept the names they bore as living towns, Deathknell was given a new name entirely, one fitted to what happens there rather than to what once stood there. No one now recalls why.\n\nSurvival here is a daily struggle, and gold is the scarcest thing of all. Northwest of the village lies a mine rich in metal, but it has been overrun by spiders, and the dead of Deathknell go out again and again to try to clear it, so the ore beneath might finally be worked. Deathguard Elites stand watch along the valley's edges, the only thing between the fragile new dead and the Scourge and Scarlet Crusade that would end them a second time.",
			source = "https://warcraft.wiki.gg/wiki/Deathknell",
		},
		["faols rest"] = {
			name = "Faol's Rest",
			short = "Southwest of the Scarlet Monastery, in eastern Tirisfal Glades, lies a plot of ground once tended by mourners: Faol's Rest, the grave of Archbishop Alonsus Faol.",
			full = "Southwest of the Scarlet Monastery, in eastern Tirisfal Glades, lies a plot of ground once tended by mourners: Faol's Rest, the grave of Archbishop Alonsus Faol.\n\nFaol was revered in life, and his death, some time before the coming of the Scourge, drew mourners to this ground.\n\nThe grave he left behind is no longer visited. The mourners who once came are gone, and the plot lies untended, mostly forgotten.",
			source = "https://warcraft.wiki.gg/wiki/Faol's_Rest",
		},
		["gallows end tavern"] = {
			name = "Gallows' End Tavern",
			short = "Gallows' End Tavern stands in Brill, its name a grim echo of the town it serves.",
			full = "Gallows' End Tavern stands in Brill, its name a grim echo of the town it serves. Beneath its floor, the cellars hold no casks worth mentioning: a captured Scarlet Zealot and a Dwarven Mountaineer are kept there, prisoners of the Forsaken.",
			source = "https://warcraft.wiki.gg/wiki/Gallows'_End_Tavern",
		},
		["garrens haunt"] = {
			name = "Garren's Haunt",
			short = "Garren's Haunt was once a bountiful farmstead in the northern Tirisfal Glades, its fields wide and its silos full. The Plague of Undeath ended that.",
			full = "Garren's Haunt was once a bountiful farmstead in the northern Tirisfal Glades, its fields wide and its silos full. The Plague of Undeath ended that. When the Scourge swept through in the Scourging of Lordaeron, Garren and his family were slaughtered where they lived, and the land itself turned gray and lifeless around their ruined home.\n\nWhat remains standing was claimed by the Rot Hide gnolls, led by Maggot Eye, who took the farmhouse and barn for their own and attacked without hesitation anyone who strayed too close.\n\nThe farmstead never recovered. It stands abandoned, its fields empty, its family gone, and only the gnolls remain to answer for who holds it now.",
			source = "https://warcraft.wiki.gg/wiki/Garren's_Haunt",
		},
		["gunthers retreat"] = {
			name = "Gunther's Retreat",
			short = "On an island in Brightwater Lake stands Gunther's Retreat, claimed by the Forsaken lich Gunther Arcanus and his zombie minions.",
			full = "On an island in Brightwater Lake stands Gunther's Retreat, claimed by the Forsaken lich Gunther Arcanus and his zombie minions. Off its southwestern shore, on a bare unnamed islet, sits a strange marker known only as Lillith's Dinner Table.",
			source = "https://warcraft.wiki.gg/wiki/Gunther's_Retreat",
		},
		["night webs hollow"] = {
			name = "Night Web's Hollow",
			short = "Night Web's Hollow is a small valley cut through with an old gold mine, both claimed by spiders. Young ones wander the open hollow while grown Night Web Spiders hold the mine's darker tunnels.",
			full = "Night Web's Hollow is a small valley cut through with an old gold mine, both claimed by spiders. Young ones wander the open hollow while grown Night Web Spiders hold the mine's darker tunnels.\n\nNewly risen Forsaken come here to test what their bodies can still do, cutting down the young spiders outside before daring the mine itself.\n\nIn its deepest recess sits the Night Web Matriarch, mother to the swarm above her.",
			source = "https://warcraft.wiki.gg/wiki/Night_Web's_Hollow",
		},
		["nightmare vale"] = {
			name = "Nightmare Vale",
			short = "West of the Scarlet Watchtower in Tirisfal Glades lies a valley gone to ruin. Its trees have withered, and the wildlife that once lived among them has been eaten out by darkhounds and huge vampire bats.",
			full = "West of the Scarlet Watchtower in Tirisfal Glades lies a valley gone to ruin. Its trees have withered, and the wildlife that once lived among them has been eaten out by darkhounds and huge vampire bats. Among these hunters flies Ressan the Needler, a rare white bat unlike the rest.",
			source = "https://warcraft.wiki.gg/wiki/Nightmare_Vale",
		},
		["north coast"] = {
			name = "North Coast",
			short = "The North Coast runs where the Tirisfal Glades meet the Great Sea, given over now to murlocs and creatures of the water.",
			full = "The North Coast runs where the Tirisfal Glades meet the Great Sea, given over now to murlocs and creatures of the water. Since the Plague of Undeath, the shore has turned dark and cold, and the tide leaves dead sea creatures rotting at the water's edge.",
			source = "https://warcraft.wiki.gg/wiki/North_Coast",
		},
		["ruins of lordaeron"] = {
			name = "Ruins of Lordaeron",
			short = "Above the buried city, the palace of Lordaeron still stands, its halls open to the sky, its gardens gone to ruin. Here the great kingdom of the Alliance died, and here its ghosts have never quite left.",
			full = "Above the buried city, the palace of Lordaeron still stands, its halls open to the sky, its gardens gone to ruin. Here the great kingdom of the Alliance died, and here its ghosts have never quite left.\n\nIt was Arthas Menethil who ended it. The prince returned home at the head of an army raised against his own people, welcomed through these gates by bells and cheering before anyone understood what he had become. He found his father, King Terenas, waiting in the throne room, and killed him there. Standing over the body, he spoke words that still echo in that room to any who linger: that the kingdom would fall, and from its ashes a new order would rise to shake the world. It was no idle boast. Within days the city and its people were slaughtered, and Lordaeron belonged to the Scourge.\n\nWalk the courtyard still and, it is said, one can hear what the stone remembers: hushed voices, the clang of welcoming bells, a murmur from the throne room that never quite fades. Those who can see beyond the veil say the citizens of Lordaeron still walk there, unaware that their kingdom is gone.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Lordaeron",
		},
		["scarlet monastery"] = {
			name = "Scarlet Monastery",
			short = "Under the Crusade, the Old Monastery became barracks and prison. Inquisitor Whitemane and Renault Mograine made it their seat, and its chapel became a place of judgment as well as prayer.",
			full = "Under the Crusade, the Old Monastery became barracks and prison. Inquisitor Whitemane and Renault Mograine made it their seat, and its chapel became a place of judgment as well as prayer.\n\nBefore it was a fortress, the Old Monastery was a cathedral of the Church of the Holy Light, filled with libraries where paladins trained. Alexandros Mograine himself spent months there in his youth, praying and studying before he ever bore a blade.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Monastery",
		},
		["scarlet watch post"] = {
			name = "Scarlet Watch Post",
			short = "The Scarlet Watch Post stands watch to guard the approach the Scarlet Monastery cannot defend on its own. Captain Melrache commands here, holding the post against any who would strike the monastery's exposed side unseen.",
			full = "The Scarlet Watch Post stands watch to guard the approach the Scarlet Monastery cannot defend on its own. Captain Melrache commands here, holding the post against any who would strike the monastery's exposed side unseen.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Watch_Post",
		},
		["shadow grave"] = {
			name = "Shadow Grave",
			short = "The Shadow Grave stands at the top of the slope within the Deathknell Graves, high among the mountains of Tirisfal. A worn path winds down from its entrance to Deathknell below.",
			full = "The Shadow Grave stands at the top of the slope within the Deathknell Graves, high among the mountains of Tirisfal. A worn path winds down from its entrance to Deathknell below.",
			source = "https://warcraft.wiki.gg/wiki/Shadow_Grave",
		},
		["shadowvale"] = {
			pending = true,
			name = "Shadowvale",
			short = "",
			full = "",
			source = "",
		},
		["solliden farmstead"] = {
			name = "Solliden Farmstead",
			short = "The pumpkin fields of Solliden are one of the few patches of ground in Tirisfal where the old life has not been swallowed by plague or undeath.",
			full = "The pumpkin fields of Solliden are one of the few patches of ground in Tirisfal where the old life has not been swallowed by plague or undeath. While the country around has fallen to the Scourge and then to the Forsaken who rose from it, the farmers here still work their rows, held safe under the watch of the Scarlet Crusade at the nearby Scarlet Palisade.\n\nThat protection has made Solliden an oddity. The farmers trust no one who is not Scarlet, turning away the Forsaken as abominations of the plague that nearly took them, and wary too of the Alliance, whose banners might drag them into a war they have so far escaped by staying small and forgotten.\n\nIt is that quiet the Forsaken cannot leave alone. Deathguard Simmer watches Solliden not for what it is now, but for what it might become: peaceful farmers today, armed tenants of the Alliance tomorrow, a foothold in land the Forsaken mean to hold.",
			source = "https://warcraft.wiki.gg/wiki/Solliden_Farmstead",
		},
		["stillwater pond"] = {
			name = "Stillwater Pond",
			short = "Before the plague, Stillwater Pond was a place for the living to be young.",
			full = "Before the plague, Stillwater Pond was a place for the living to be young. Families from the glades came to picnic on its banks, and children too small to brave the deeper waters of Brightwater Lake learned to swim here instead.\n\nThat water is gray now. The fish beneath the surface are only bones still swimming, as if no one told them to stop. Wandering undead and wild beasts pass along the shore, and the darkhound Bayne prowls the water's edge, feeding on whatever is unwary enough to linger.\n\nBy the time the Forsaken had begun raising Brill from its ruin, Scarlet warriors had taken to patrolling Stillwater's shore.",
			source = "https://warcraft.wiki.gg/wiki/Stillwater_Pond",
		},
		["terrace of repose"] = {
			name = "Terrace of Repose",
			short = "Just north of the Scarlet Monastery lies ground the plague has never touched. Green hedges grow here, and a fountain runs clear rather than stagnant, unlike the rest of Tirisfal Glades.",
			full = "Just north of the Scarlet Monastery lies ground the plague has never touched. Green hedges grow here, and a fountain runs clear rather than stagnant, unlike the rest of Tirisfal Glades. The Scarlet Crusade tends it, keeping this small terrace alive as proof that something clean can still endure amid the blight.",
			source = "https://warcraft.wiki.gg/wiki/Terrace_of_Repose",
		},
		["venomweb vale"] = {
			name = "Venomweb Vale",
			short = "Venomweb Vale was once green, thick with deer and rabbit, before it became what it is now: a valley overrun with poisonous spiders, led by the rare and deadly Sri'skulk, whose webs have replaced the grass and given the vale its name.",
			full = "Venomweb Vale was once green, thick with deer and rabbit, before it became what it is now: a valley overrun with poisonous spiders, led by the rare and deadly Sri'skulk, whose webs have replaced the grass and given the vale its name. Darkhounds prowl the north near the Scarlet Encampment, held by Lieutenant Sanders.",
			source = "https://warcraft.wiki.gg/wiki/Venomweb_Vale",
		},
		["whispering forest"] = {
			pending = true,
			name = "Whispering Forest",
			short = "",
			full = "",
			source = "",
		},
		["whispering gardens"] = {
			name = "Whispering Gardens",
			short = "On the hill south of the Scarlet Monastery, a battle was once fought here between the men who would become the Scarlet Crusade and a host of the Scourge.",
			full = "On the hill south of the Scarlet Monastery, a battle was once fought here between the men who would become the Scarlet Crusade and a host of the Scourge. Many fell on both sides. In the twilight, their spirits still linger, murmuring as faint whispers among the garden's quiet stones.",
			source = "https://warcraft.wiki.gg/wiki/Whispering_Gardens",
		},
		["whispering shore"] = {
			name = "Whispering Shore",
			short = "The Whispering Shore lies in western Tirisfal Glades, north of the Solliden Farmstead. Fishermen once favored its calm water and steady catch.",
			full = "The Whispering Shore lies in western Tirisfal Glades, north of the Solliden Farmstead. Fishermen once favored its calm water and steady catch.\n\nThat bounty is gone. Murlocs have overrun the shore, falling on anyone who comes near, and the water has turned cold and dark.",
			source = "https://warcraft.wiki.gg/wiki/Whispering_Shore",
		},
	},
	-- Silverpine Forest: 22 subzones
	[1421] = {
		["ambermill"] = {
			name = "Ambermill",
			short = "Ambermill was once a mill town of no importance, cutting timber southwest of Lordamere Lake in Silverpine Forest.",
			full = "Ambermill was once a mill town of no importance, cutting timber southwest of Lordamere Lake in Silverpine Forest.\n\nThe Scourge and the Burning Legion changed what the town was worth. The Kirin Tor of Dalaran, rebuilding after their own ruin, occupied the town, and for a time Ambermill became something it had never been: a source of real human resistance in Silverpine Forest, propped up by Dalaran's wizardry.\n\nThe Forsaken have not let that stand unwatched. Their Deathstalkers have learned, through a prisoner, that the wizards keep documents there bearing on the state of Dalaran itself. The mills, the stables, and the town hall remain in Kirin Tor hands, while spies move against them from the shadows of the forest.",
			source = "https://warcraft.wiki.gg/wiki/Ambermill",
		},
		["berens peril"] = {
			name = "Beren's Peril",
			short = "In the hills southwest of Ambermill lies Beren's Peril.",
			full = "In the hills southwest of Ambermill lies Beren's Peril. Years after the Third War, Forsaken scouts brought word to Shadow Priest Allister that undead had gathered there in secret, massing for a strike against the Sepulcher. The undead served the necromancer Thule Ravenclaw, who had chosen the place to gather his servants unseen, close enough to threaten the Sepulcher, far enough from the road to escape notice.",
			source = "https://warcraft.wiki.gg/wiki/Beren's_Peril",
		},
		["dawning isles"] = {
			name = "Dawning Isles",
			short = "The Dawning Isles once rose gentle and low from the crystalline waters of Lordamere Lake, quiet keys untouched by trouble. The Plague of Undeath changed that.",
			full = "The Dawning Isles once rose gentle and low from the crystalline waters of Lordamere Lake, quiet keys untouched by trouble. The Plague of Undeath changed that. Their trees sickened, and murlocs and bog beasts overran the islets. The bog beasts are gone now, but the Vile Fin murlocs bred unchecked and now hold the isles entirely.",
			source = "https://warcraft.wiki.gg/wiki/Dawning_Isles",
		},
		["dead field"] = {
			name = "Dead Field",
			short = "The Dead Field lies abandoned in northern Silverpine Forest, its fields gone to rot and its original tenants forgotten.",
			full = "The Dead Field lies abandoned in northern Silverpine Forest, its fields gone to rot and its original tenants forgotten. What is known is what has claimed it since: the Rot Hide gnolls, bound in service to the Scourge, who have made the ruined farm their base, their numbers swelling in a buildup that suggests some assault still being readied here.\n\nThe Forsaken have struck at the farm more than once, hoping to break the gnolls before they can move. Every attempt has failed. Whenever the Rot Hides come under threat, a banshee answers their call, a spirit named Nightlash who commands the gnolls as her own, appearing out of nothing to defend them.",
			source = "https://warcraft.wiki.gg/wiki/Dead_Field",
		},
		["decrepit ferry"] = {
			name = "Decrepit Ferry",
			short = "The Decrepit Ferry once carried trade out to Fenris Isle, where a lord and his family kept their manor, paying the ferryman a few coins a trip.",
			full = "The Decrepit Ferry once carried trade out to Fenris Isle, where a lord and his family kept their manor, paying the ferryman a few coins a trip.\n\nThen the Scourge came down over Lordaeron. The ferryman was slain where he worked, and his ferry broken apart.\n\nNow ghouls, skeletal warriors, and Rot Hide gnolls haunt the ruined docks, and the crossing stands abandoned, dangerous to any but the strong.",
			source = "https://warcraft.wiki.gg/wiki/Decrepit_Ferry",
		},
		["deep elem mine"] = {
			name = "Deep Elem Mine",
			short = "Deep Elem Mine lies in Silverpine Forest. Arugal let his magic spread into it, and worgen made the mine their den, led by Grimson the Pale, once foreman there.",
			full = "Deep Elem Mine lies in Silverpine Forest. Arugal let his magic spread into it, and worgen made the mine their den, led by Grimson the Pale, once foreman there.\n\nDalar Dawnweaver sought Grimson's death, so that the Forsaken might claim the mine as their own resource, in Varimathras's name.",
			source = "https://warcraft.wiki.gg/wiki/Deep_Elem_Mine",
		},
		["fenris isle"] = {
			name = "Fenris Isle",
			short = "Fenris Isle sits in the middle of Lordamere Lake, one piece of a broken ring of dry land it shares with the Dawning Isles, and it is counted, loosely, as part of Silverpine Forest.",
			full = "Fenris Isle sits in the middle of Lordamere Lake, one piece of a broken ring of dry land it shares with the Dawning Isles, and it is counted, loosely, as part of Silverpine Forest.\n\nBefore the Third War, the island held Fenris Keep, a military outpost of Lordaeron. When the Scourge swept over the land, the keep fell. Its people either fled or were killed where they stood, and the isle was left empty.\n\nInto that emptiness came the Rot Hide gnolls, who took the abandoned keep as their den. Their master was Thule Ravenclaw, remembered as treacherous even among gnolls, who rules the Rot Hides and, through them, all of Fenris Isle, holding the keep he claimed and the nearby Decrepit Ferry besides.",
			source = "https://warcraft.wiki.gg/wiki/Fenris_Isle",
		},
		["fenris keep"] = {
			name = "Fenris Keep",
			short = "Fenris Keep stands at the center of Lordamere Lake, upon Fenris Isle in Silverpine Forest, once home to a sizable portion of Lordaeron's military.",
			full = "Fenris Keep stands at the center of Lordamere Lake, upon Fenris Isle in Silverpine Forest, once home to a sizable portion of Lordaeron's military.\n\nWhen the Scourge swept over the land, the keep fell with it. Into the ruin came Thule Ravenclaw, a young mage once of the Kirin Tor, who threw in with the Scourge and bent the isle's gnolls to his will, forging them into the Rot Hide. With that tribe at his back, he made himself master of Fenris Keep, and the Rot Hide fall on anyone who nears their master.",
			source = "https://warcraft.wiki.gg/wiki/Fenris_Keep",
		},
		["greymane wall"] = {
			name = "Greymane Wall",
			short = "King Genn Greymane raised his wall before the Third War, weary of Gilnean coin spent on the orc internment camps and worn down by the quarrels dividing the kings of the Alliance of Lordaeron.",
			full = "King Genn Greymane raised his wall before the Third War, weary of Gilnean coin spent on the orc internment camps and worn down by the quarrels dividing the kings of the Alliance of Lordaeron. He turned his kingdom inward, cutting Gilneas off from Lordaeron and from the world beyond the mountains.\n\nThe wall held against the Plague of Undeath, but at a cost. As the Scourge swept over Lordaeron, refugees fled south and camped outside the gates, and for years the gates did not open. The refugees perished there, unanswered.",
			source = "https://warcraft.wiki.gg/wiki/Greymane_Wall",
		},
		["ivar patch"] = {
			name = "Ivar Patch",
			short = "Ivar's Patch was once a farm worth having, its rows heavy with pumpkins, its house full of hired hands who worked the fields for a man named Ivar.",
			full = "Ivar's Patch was once a farm worth having, its rows heavy with pumpkins, its house full of hired hands who worked the fields for a man named Ivar. It was a good living, until the Plague of Undeath came down over Lordaeron and took it from him.\n\nIvar did not simply die. He rose, and so did his family, and so did every farmhand who had worked his land, all turned to rotting ghouls that now fall on anyone who comes near. Ivar himself rose as something worse, remembered now as Ivar the Foul.\n\nThree deathstalkers sent north to judge the danger were caught here by the ghouls, and Ivar the Foul wounded one of them, Quinn Yorick, before Quinn and his kinswoman Rane barricaded themselves inside Ivar's old house.",
			source = "https://warcraft.wiki.gg/wiki/Ivar_Patch",
		},
		["lordamere lake"] = {
			name = "Lordamere Lake",
			short = "Lordamere Lake spreads beneath the shadow of kingdoms that once called its shores home.",
			full = "Lordamere Lake spreads beneath the shadow of kingdoms that once called its shores home. Lordaeron rose on its northern edge, and it is very likely from that great city, itself named for old Lordain, that the lake took its name. Dalaran and Alterac, too, stood prosperous around its waters in the days when the Alliance of Lordaeron bound the human kingdoms together.\n\nThat age is gone, and what remains is a border. The lake now lies between the Forsaken holdings of Tirisfal Glades and Silverpine Forest and the contested Alterac Mountains, separating the dead from the living.\n\nAt its heart sits Fenris Isle, its keep held by the Rot Hide gnolls under Thule Ravenclaw.\n\nEast of Fenris Isle, among the small Dawning Isles, the Vile Fin murlocs have made their claim, overrunning them entirely.",
			source = "https://warcraft.wiki.gg/wiki/Lordamere_Lake",
		},
		["maldens orchard"] = {
			name = "Malden's Orchard",
			short = "The trees in Malden's Orchard have gone dark and evergreen, their fruit hanging unpicked season after season. Malden himself is long gone, driven from his home when the Scourge came down over Lordaeron.",
			full = "The trees in Malden's Orchard have gone dark and evergreen, their fruit hanging unpicked season after season. Malden himself is long gone, driven from his home when the Scourge came down over Lordaeron.\n\nNow the orchard belongs to the worgs, denning in numbers among the trees and around the single small cottage that still stands there. It was into this that the Deathstalker Erland McKree walked, sent to scout the orchard during a reconnaissance of the northern forest. The worgs drove him to ground before he had gone far, and he barricaded himself inside the abandoned cottage, pinned there for days, until other Forsaken agents helped him escape back to his waiting partners.",
			source = "https://warcraft.wiki.gg/wiki/Malden's_Orchard",
		},
		["north tides hollow"] = {
			name = "North Tide's Hollow",
			short = "North Tide's Hollow lies just north of the Sepulcher in Silverpine Forest. It is one of the many haunts of the Moonrage worgen, servants of the Archmage Arugal.",
			full = "North Tide's Hollow lies just north of the Sepulcher in Silverpine Forest. It is one of the many haunts of the Moonrage worgen, servants of the Archmage Arugal. Here they raise crude encampments, holding nothing but the meanest necessities needed for survival, shelter enough for creatures who live by tooth and strength.",
			source = "https://warcraft.wiki.gg/wiki/North_Tide's_Hollow",
		},
		["north tides run"] = {
			name = "North Tide's Run",
			short = "The northwestern shoreline of Silverpine Forest, where the beach meets the cold Great Sea, bears the name North Tide's Run.",
			full = "The northwestern shoreline of Silverpine Forest, where the beach meets the cold Great Sea, bears the name North Tide's Run. Half-sunk in the shallows lies a broken Horde ship, its hull settled into the surf, the most prominent mark upon this stretch of coast.",
			source = "https://warcraft.wiki.gg/wiki/North_Tide's_Run",
		},
		["olsens farthing"] = {
			name = "Olsen's Farthing",
			short = "Olsen's Farthing once stood at the edge of the trade roads running through Silverpine Forest, a working farmstead whose fields fed the traffic passing by.",
			full = "Olsen's Farthing once stood at the edge of the trade roads running through Silverpine Forest, a working farmstead whose fields fed the traffic passing by.\n\nThe Third War ended that. Within a few years the farm lay in ruins.",
			source = "https://warcraft.wiki.gg/wiki/Olsen's_Farthing",
		},
		["pyrewood village"] = {
			name = "Pyrewood Village",
			short = "Pyrewood Village stands on the edge of Silverpine Forest, a huddle of humans who lived through the Scourge's first coming during the Third War.",
			full = "Pyrewood Village stands on the edge of Silverpine Forest, a huddle of humans who lived through the Scourge's first coming during the Third War. To the north stands a keep once held by Baron Silverlaine, guarded by the paladin Commander Springvale and the Silver Hand. Silverlaine and his men were slaughtered by the worgen of Archmage Arugal, who took the keep for his own and renamed it Shadowfang Keep. From there Arugal turned his madness on Pyrewood itself, cursing its people so that every night they become slavering Moonrage worgen, tearing at anyone who crosses their path, only to wake human again come dawn.\n\nDespite this, the village still opens its doors to travelers by day, its people bound to the curse Arugal laid upon them, with no end to it in sight.",
			source = "https://warcraft.wiki.gg/wiki/Pyrewood_Village",
		},
		["sepulcher"] = {
			name = "Sepulcher",
			short = "The Sepulcher sits above the Lordaeronian coastline in the western hills of Silverpine Forest, where a road once crossed a simple graveyard, its crypts marking nothing more than a resting place for the dead.",
			full = "The Sepulcher sits above the Lordaeronian coastline in the western hills of Silverpine Forest, where a road once crossed a simple graveyard, its crypts marking nothing more than a resting place for the dead.\n\nAfter the Third War, the Forsaken took the old graveyard and converted it into a base of operations, turning a place built for the dead into one that served the undying.\n\nThe choice came from necessity. Worgen prowled to the south, the Scourge still held ground to the east, and the Kirin Tor watched from the southeast. Surrounded on nearly every side, the Forsaken found in the Sepulcher one of the few places in Silverpine where the Horde could stand in safety.",
			source = "https://warcraft.wiki.gg/wiki/Sepulcher",
		},
		["shadowfang keep"] = {
			name = "Shadowfang Keep",
			short = "Shadowfang Keep stands on a high bluff above Pyrewood Village. It belonged once to Baron Silverlaine, a lord of Gilneas, until the Scourge came down upon Lordaeron and the Royal Archmage Arugal sought a way to stop them.",
			full = "Shadowfang Keep stands on a high bluff above Pyrewood Village. It belonged once to Baron Silverlaine, a lord of Gilneas, until the Scourge came down upon Lordaeron and the Royal Archmage Arugal sought a way to stop them. Drawing on the research of the mage Ur, and with King Genn Greymane's blessing but against the counsel of the Kirin Tor, Arugal summoned the worgen. They turned back the undead tide, then turned on Gilneas itself, savaging the Greymane Wall before running loose through Silverpine. They fell upon the keep and killed Baron Silverlaine and his household.\n\nArugal, broken by what he had unleashed, did not flee it. He named the worgen his children, took the keep for his own, and renamed it Shadowfang. Communing with a master he served in the Wolf Cult, he spread the curse through the forest, until Pyrewood Village itself was turned, its people human by day and beasts by night, ruled over by a council that answered to him alone.",
			source = "https://warcraft.wiki.gg/wiki/Shadowfang_Keep",
		},
		["shining strand"] = {
			name = "Shining Strand",
			short = "The Shining Strand runs along Lordamere Lake, from the capital of Lordaeron in the north down to the rough hills dividing Silverpine Forest from the Alterac Mountains.",
			full = "The Shining Strand runs along Lordamere Lake, from the capital of Lordaeron in the north down to the rough hills dividing Silverpine Forest from the Alterac Mountains.\n\nThe Vile Fin tribe of murlocs holds the strand thick with their settlements, and travelers who do not know the shoreline have learned to fear it. The late Apothecary Berard, in his journal, wrote of a rare item to be had from the Vile Fins, a Hardened Tumor, and speculated that it might be worked into a new plague.",
			source = "https://warcraft.wiki.gg/wiki/Shining_Strand",
		},
		["skittering dark"] = {
			name = "Skittering Dark",
			short = "The mine known as the Skittering Dark has been claimed by Skitterweb spiders, their webs draped over broken timbers and rusted tools.",
			full = "The mine known as the Skittering Dark has been claimed by Skitterweb spiders, their webs draped over broken timbers and rusted tools. Deep within hides the Skitterweb Matriarch, a spider grown monstrous, ruling the swarm from a dark she never leaves. Outside, the rare Krethis the Shadowspinner sometimes stalks the rocks alone.\n\nCocoons litter the ground, binding worgen, worgs, and bears, along with orcs dragged in from a wreck along the shore to the west.",
			source = "https://warcraft.wiki.gg/wiki/Skittering_Dark",
		},
		["south tides run"] = {
			name = "South Tide's Run",
			short = "South Tide's Run runs along the southwestern coast of Silverpine Forest, where the land meets the Great Sea.",
			full = "South Tide's Run runs along the southwestern coast of Silverpine Forest, where the land meets the Great Sea.",
			source = "https://warcraft.wiki.gg/wiki/South_Tide's_Run",
		},
		["valgans field"] = {
			name = "Valgan's Field",
			short = "Valgan's Field lies among the desolate farms of northern Silverpine Forest, west of the Shining Strand and north of a small river.",
			full = "Valgan's Field lies among the desolate farms of northern Silverpine Forest, west of the Shining Strand and north of a small river. It takes its name from a farmer who was killed or driven from the land when the Scourge swept through Silverpine. In its better days the farm looked out over Lordamere Lake, a view worth the name it once had.\n\nThe farm stands empty now, a ruin of what it once was, though Nightlash can occasionally be spotted about the place.",
			source = "https://warcraft.wiki.gg/wiki/Valgan's_Field",
		},
	},
	-- Western Plaguelands: 18 subzones
	[1422] = {
		["bulwark"] = {
			name = "Bulwark",
			short = "The Bulwark stands where Tirisfal Glades meets the Western Plaguelands, the line the Forsaken hold against the Scourge that still masses to the east.",
			full = "The Bulwark stands where Tirisfal Glades meets the Western Plaguelands, the line the Forsaken hold against the Scourge that still masses to the east. Here Forsaken defenders and the Argent Dawn have set aside their differences against that common enemy, watching the border together and sending fighters east to strike at the Lich King's minions.\n\nUnlike the rest of Tirisfal, this stretch does not look like the Glades at all. A plaguemist hangs over it, tinting the sky the same sickly yellow-gray as the Western Plaguelands beyond.",
			source = "https://warcraft.wiki.gg/wiki/Bulwark",
		},
		["caer darrow"] = {
			name = "Caer Darrow",
			short = "On the island in Darrowmere Lake stood a fortress raised by human hands long ago, holding an ancient high elven runestone.",
			full = "On the island in Darrowmere Lake stood a fortress raised by human hands long ago, holding an ancient high elven runestone. During the Second War the Horde overran the island and sacked the keep, tearing the runestone apart to forge the Altars of Storms, through which Gul'dan bound magic into the ogres of his Horde.\n\nThe keep was rebuilt and became the seat of House Barov. As the years turned toward war, the Barovs grew fearful of losing what decades had built them, and struck a bargain with Kel'Thuzad, master of the Cult of the Damned. Beneath the manor the catacombs became Scholomance, a school of necromancy, and the family's own servants were given over as subjects for a plague of undeath. Within half a year the sickness broke loose and killed everyone on the island. Its victims did not simply die: they rose as ghosts, bound to relive their final moments, and still walk the ruined halls of Caer Darrow today.",
			source = "https://warcraft.wiki.gg/wiki/Caer_Darrow",
		},
		["chillwind camp"] = {
			name = "Chillwind Camp",
			short = "Chillwind Camp sits at the southern gate of the Western Plaguelands, where the mountains of Alterac give way to poisoned ground. It is the last place an Alliance traveler can stand and still call the earth clean.",
			full = "Chillwind Camp sits at the southern gate of the Western Plaguelands, where the mountains of Alterac give way to poisoned ground. It is the last place an Alliance traveler can stand and still call the earth clean.\n\nA small contingent of the Argent Dawn holds it, with only a handful of troops and specialists to their name. What the camp lacks in numbers it makes up for in daring: its people wage a guerrilla war against the Scourge stronghold at Andorhal and the plague cauldrons seeding the land with death, relying on mercenaries willing to strike and vanish rather than hold ground they cannot keep.\n\nPromising young Knights of the Silver Hand were sent here by Lord Grayson Shadowbreaker to stand with Commander Ashlam Valorfist against the Scourge in the region.",
			source = "https://warcraft.wiki.gg/wiki/Chillwind_Camp",
		},
		["dalsons tears"] = {
			name = "Dalson's Tears",
			short = "Dalson's Orchard once bore fruit for a family that gave it their name. Now the trees stand in the Western Plaguelands under a name that remembers grief instead of harvest: Dalson's Tears.",
			full = "Dalson's Orchard once bore fruit for a family that gave it their name. Now the trees stand in the Western Plaguelands under a name that remembers grief instead of harvest: Dalson's Tears.\n\nThe Scourge took the farm and turned it into a wound in the earth. At its center they set a great cauldron that has not stopped since, spewing disease into the air, watched over by Cauldron Lord Malvinious and the blighted dead that serve him.\n\nThe Dalsons never left. Mrs. Dalson walks the property still, a wandering skeleton picking over ground she once tended as a woman. Her husband did not die beside her. He was shut into the outhouse and left there, and what he became in that locked dark was not a man anymore but a ghoul.",
			source = "https://warcraft.wiki.gg/wiki/Dalson's_Tears",
		},
		["darrowmere lake"] = {
			name = "Darrowmere Lake",
			short = "The waters of Darrowmere still hold the memory of the Second War, when the lake was crowded with sail.",
			full = "The waters of Darrowmere still hold the memory of the Second War, when the lake was crowded with sail. Most of the ships that anchored here flew the colors of the Proudmoore fleet, and before the burning of Quel'Thalas the Grand Admiral sent a number of them across these waters to carry Turalyon, Alleria Windrunner, and their army toward Stratholme. Turalyon weighed sailing on into Quel'Thalas itself, but Alleria warned him that the elves would never let human ships pass up their river, and so the fleet turned toward Stratholme instead. It was in this same war that Zul'jin and his band were pressed back to the lake's shores and the troll warlord was taken captive.\n\nAt the center of the lake stands the island town of Caer Darrow, empty now, once held by the House of Barov. Beneath the town's stones lies Scholomance, where the Cult of the Damned works among its undead, a darkness resting under the drowned quiet of the island.",
			source = "https://warcraft.wiki.gg/wiki/Darrowmere_Lake",
		},
		["felstone field"] = {
			name = "Felstone Field",
			short = "Felstone Field once fed the living. That ended when the Scourge came over it and would not let it be a farm again.",
			full = "Felstone Field once fed the living. That ended when the Scourge came over it and would not let it be a farm again.\n\nAt the heart of the field the Scourge set a great cauldron, and it has not stopped its work since. Vapor pours from it without pause, thick with disease. Cauldron Lord Bilemaw stands guard over it, with skeletal sorcerers, skeletal flayers, and slavering ghouls beside him, so nothing living can come near it and walk away clean.\n\nIn the northeastern corner the old house still stands, and Janice Felstone still keeps to it, lingering in ground that used to bear her family's crops.",
			source = "https://warcraft.wiki.gg/wiki/Felstone_Field",
		},
		["gahrrons withering"] = {
			name = "Gahrron's Withering",
			short = "The farm at the eastern edge of the Western Plaguelands once belonged to Del Gahrron, and in its better days it was known as Gahrron's Quickening, a place of planting and growth.",
			full = "The farm at the eastern edge of the Western Plaguelands once belonged to Del Gahrron, and in its better days it was known as Gahrron's Quickening, a place of planting and growth. Nothing grows there now. The Scourge took the fields and set a great cauldron at their center, and the cauldron never stops its work, spewing disease-filled vapor into the air until the ground itself seems to sicken. Cauldron Lord Soulwrath stands guard over it with other officers of the Scourge, and the vapors have called up things that should not walk: Haunting Visions drifting through the ruined rows, Wailing Deaths and Hungering Wraiths answering to no master but their hunger.",
			source = "https://warcraft.wiki.gg/wiki/Gahrron's_Withering",
		},
		["hearthglen"] = {
			name = "Hearthglen",
			short = "Hearthglen stands north of Andorhal, its walls closed around a keep, a mage tower, a mill, and a mine, the picture of order in a region gone to ruin.",
			full = "Hearthglen stands north of Andorhal, its walls closed around a keep, a mage tower, a mill, and a mine, the picture of order in a region gone to ruin. For years it held that order under Tirion Fordring, Lord of Mardenholde, until he gave aid to the orc Eitrigg and was cast out for treason. In time his son Taelan took his place as Lord of Mardenholde.\n\nHearthglen later sheltered the remnants of the Order of the Silver Hand, who answered Taelan's offer of refuge after the fall of Capital City. From its walls the paladins won victories in the years that followed, until the order was twisted into the Scarlet Crusade and took the town for its own.",
			source = "https://warcraft.wiki.gg/wiki/Hearthglen",
		},
		["mardenholde keep"] = {
			name = "Mardenholde Keep",
			short = "Mardenholde Keep has stood at the heart of Hearthglen since before the memory of most who walk its halls, its walls unbroken even in the darkest days of the orcish invasion of Lordaeron.",
			full = "Mardenholde Keep has stood at the heart of Hearthglen since before the memory of most who walk its halls, its walls unbroken even in the darkest days of the orcish invasion of Lordaeron. For years it was Tirion Fordring's seat, and there, in a council room dominated by a great oak table and a map that rendered Hearthglen down to its smallest road, the paladin met with his advisors on matters of the realm. Charged with treason for aiding the orc Eitrigg, Tirion was excommunicated and cast out, and Mardenholde passed in time to his own son, Taelan.\n\nAfter the Scourging of Lordaeron, Taelan granted the surviving Knights of the Silver Hand a home in Hearthglen. Word came within these walls that Alexandros Mograine was dead, and suspicion of betrayal split the order: Maxwell Tyrosus led his followers away to found the Argent Dawn, while those who remained took the name Scarlet Crusade, and Mardenholde became their stronghold, with Taelan raised to Highlord.",
			source = "https://warcraft.wiki.gg/wiki/Mardenholde_Keep",
		},
		["northridge lumber camp"] = {
			name = "Northridge Lumber Camp",
			short = "Northridge Lumber Camp lies in the northern Western Plaguelands near Hearthglen, its hillsides stripped bare by the Scarlet Crusade's timber cutting.",
			full = "Northridge Lumber Camp lies in the northern Western Plaguelands near Hearthglen, its hillsides stripped bare by the Scarlet Crusade's timber cutting. The Crusade works the mill for its lumber, a supply both Alliance and Horde have reason to see spoiled.\n\nBefore the Third War, the mill belonged to the family of Nathaniel Dumah, who worked the land until war and plague drove them out. Mickey Levine's family also labored here once.",
			source = "https://warcraft.wiki.gg/wiki/Northridge_Lumber_Camp",
		},
		["ruins of andorhal"] = {
			name = "Ruins of Andorhal",
			short = "Andorhal lies in ruin at the heart of the Western Plaguelands, its houses broken and spread across open ground.",
			full = "Andorhal lies in ruin at the heart of the Western Plaguelands, its houses broken and spread across open ground. What remains is held by Araj the Summoner, a lich of considerable power, and the dead that serve him -- ghouls dragging themselves between the fallen stones, skeletons standing sentinel where guards once did, banshees whose cries carry over the ruins, and abominations lumbering through the wreckage of homes.\n\nAraj remains at the center of it all, presiding over a city that never rose again.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Andorhal",
		},
		["scholomance"] = {
			name = "Scholomance",
			short = "On a rise above the abandoned city of Caer Darrow stands the manor that was once the seat of House Barov, a family whose reach ran from Caer Darrow to Brill, to Southshore, to Tarren Mill.",
			full = "On a rise above the abandoned city of Caer Darrow stands the manor that was once the seat of House Barov, a family whose reach ran from Caer Darrow to Brill, to Southshore, to Tarren Mill. For decades they ruled in comfort, but as the years drew toward war the Barovs grew bitter and grasping, unwilling to let death end what they had built. So they struck a bargain with Kel'Thuzad, master of the Cult of the Damned, to hold their fortune and their land beyond the span of mortal life.\n\nWithin six months the keep had rotted into something else entirely. Acolytes of the Cult studied the necromancer's art while the family's own servants were given over as living experiments for a plague of undeath. Before Uther the Lightbringer could pay a scheduled visit to the manor, a sickness bred in its halls was loosed upon Caer Darrow itself. It left no one alive, and bound its victims to wander afterward as ghosts.\n\nThe Barovs themselves rose again as undead, still bound to the halls they had sold away. Now the mortal necromancer Darkmaster Gandling serves as headmaster, having succeeded Araj the Summoner, who himself followed Kel'Thuzad.",
			source = "https://warcraft.wiki.gg/wiki/Scholomance",
		},
		["sorrow hill"] = {
			name = "Sorrow Hill",
			short = "Sorrow Hill served Andorhal in gentler days, a place for the town's dead, rich and poor alike, laid beneath crypts and simple stones.",
			full = "Sorrow Hill served Andorhal in gentler days, a place for the town's dead, rich and poor alike, laid beneath crypts and simple stones. That peace ended when the Plague of Undeath came. As the Scourge threw themselves against Andorhal again and again, the hill filled faster than it could hold -- hasty, unmarked graves still scar the ground where the defenders fell. In time the survivors stopped burying their dead altogether, too afraid the plague would raise their loved ones against them, and dug a mass grave south of the cemetery to burn the bodies instead.\n\nThe town's last act was its saddest. When Arthas struck down Lord Uther, the remaining people of Andorhal raised a great tomb atop the hill and laid the paladin's ruined body within it before abandoning their home for good. Some say the hill takes its name from that grave alone.\n\nThe Plague Cauldrons nearby did not spare the hill's own dead. Soldiers and townsfolk rose from their plots, standing guard over the graves they once filled.",
			source = "https://warcraft.wiki.gg/wiki/Sorrow_Hill",
		},
		["thondroril river"] = {
			name = "Thondroril River",
			short = "The Thondroril River divides the Western and Eastern Plaguelands. It rises far north near the Terrorweb Tunnel and runs south until it empties into Darrowmere Lake, continuing beyond as the Darrowmere River.",
			full = "The Thondroril River divides the Western and Eastern Plaguelands. It rises far north near the Terrorweb Tunnel and runs south until it empties into Darrowmere Lake, continuing beyond as the Darrowmere River.\n\nIts banks belong to the blight. Maggots and vampire bats crowd the wet ground, plaguebears and spiders stalk the shallows, and snapjaws lurk where the current slows.",
			source = "https://warcraft.wiki.gg/wiki/Thondroril_River",
		},
		["uthers tomb"] = {
			name = "Uther's Tomb",
			short = "Uther's Tomb stands at Sorrow Hill, the one place in the Western Plaguelands where the Light still holds against the dying of the land.",
			full = "Uther's Tomb stands at Sorrow Hill, the one place in the Western Plaguelands where the Light still holds against the dying of the land.\n\nUther the Lightbringer once held Andorhal against the Scourge, standing beside Sage Truthbearer and Ballador the Bright with the Knights of the Silver Hand at his back. It was Arthas Menethil who ended that stand, bringing his undead army against the city and cutting down Truthbearer, Ballador, and Uther himself.\n\nWhat Arthas left behind, Uther's own soldiers gathered up. They carried his body south of Andorhal's ruins and raised a tomb over it. His headstone shows him as he was in life, a tome of the Light in one hand and his warhammer in the other, with words cut into the marker stone before it in the common tongue.\n\nHigh Priest Thel'danis keeps the tomb still, its caretaker and guardian. The grave is sacred to those who follow the Light, one of the few places in the Plaguelands where such devotion still means something.",
			source = "https://warcraft.wiki.gg/wiki/Uther's_Tomb",
		},
		["weeping cave"] = {
			name = "Weeping Cave",
			short = "The Weeping Cave lies west of the Thondroril River, its hollows thick with bog beasts and oozes bred of the plagued land. Rotting behemoths and decaying horrors shamble through the dark.",
			full = "The Weeping Cave lies west of the Thondroril River, its hollows thick with bog beasts and oozes bred of the plagued land. Rotting behemoths and decaying horrors shamble through the dark. Deeper still, an elemental called the Husk is said to rarely surface, a strange and unsettling thing to glimpse.",
			source = "https://warcraft.wiki.gg/wiki/Weeping_Cave",
		},
		["writhing haunt"] = {
			name = "Writhing Haunt",
			short = "The Writhing Haunt was once farmland, tended for the sustenance of the living. That purpose is gone.",
			full = "The Writhing Haunt was once farmland, tended for the sustenance of the living. That purpose is gone. The Scourge took the fields and set at their center a great cauldron, which has not stopped its work since: a constant spew of disease-filled vapor rolling out across the furrows where crops once grew.\n\nThe cauldron is not left unguarded. Cauldron Lord Razarch stands watch over it, with Rotting Ghouls, Freezing Ghouls, and Fetid Zombies moving around him, bound to the place as its wardens.",
			source = "https://warcraft.wiki.gg/wiki/Writhing_Haunt",
		},
	},
	-- Eastern Plaguelands: 28 subzones
	[1423] = {
		["blackwood lake"] = {
			name = "Blackwood Lake",
			short = "The waters of Blackwood Lake run foul, infested by corrupted water elementals coiling through the murk. Old annals of Darrowshire claim the lake bed holds the head of Horgus the Ravager, sunk somewhere in that dark.",
			full = "The waters of Blackwood Lake run foul, infested by corrupted water elementals coiling through the murk. Old annals of Darrowshire claim the lake bed holds the head of Horgus the Ravager, sunk somewhere in that dark.\n\nBefore the plague, a town called Blackwood stood here, home to Grand Marshal Othmar Garithos. Nothing remains of it now but the lake bearing its name.",
			source = "https://warcraft.wiki.gg/wiki/Blackwood_Lake",
		},
		["browman mill"] = {
			name = "Browman Mill",
			short = "Stephen Browman once cut timber at the mill north of Light's Hope Chapel. The Scourge killed him like everyone else the plague touched, then raised him as a ghoul bound to its service.",
			full = "Stephen Browman once cut timber at the mill north of Light's Hope Chapel. The Scourge killed him like everyone else the plague touched, then raised him as a ghoul bound to its service. He never left. He stands guard now inside the walls he once owned.\n\nThe mill is thick with skeletons, banshees, and Abominations, more garrison than ruin, and nothing about it invites anyone to linger.",
			source = "https://warcraft.wiki.gg/wiki/Browman_Mill",
		},
		["corins crossing"] = {
			name = "Corin's Crossing",
			short = "Corin's Crossing sits where the roads to Andorhal, Darrowshire, Stratholme, and Tyr's Hand meet, between the Infectis Scar and Lake Mereldar.",
			full = "Corin's Crossing sits where the roads to Andorhal, Darrowshire, Stratholme, and Tyr's Hand meet, between the Infectis Scar and Lake Mereldar. Once an ordinary crossroads town, it kept a town hall and a blacksmith's forge.\n\nNow the Scourge fills its streets entirely, and among the dead move things that cannot be seen at all -- Unseen Servants, which see through stealth as if it were nothing. No quiet path exists through Corin's Crossing.",
			source = "https://warcraft.wiki.gg/wiki/Corin's_Crossing",
		},
		["crown guard tower"] = {
			name = "Crown Guard Tower",
			short = "Crown Guard Tower stands watch over the Eastern Plaguelands as one of its scout towers. The Scourge invasion of Lordaeron tore through the region, and the tower wears its scars still, a silent marker of the dead lands.",
			full = "Crown Guard Tower stands watch over the Eastern Plaguelands as one of its scout towers. The Scourge invasion of Lordaeron tore through the region, and the tower wears its scars still, a silent marker of the dead lands.",
			source = "https://warcraft.wiki.gg/wiki/Crown_Guard_Tower",
		},
		["darrowshire"] = {
			name = "Darrowshire",
			short = "Darrowshire once stood as a village in its own right, until the Third War brought the Scourge to its gates. A ghoul lord named Horgus the Ravager led the assault, alongside the death knight Marduk Blackpool.",
			full = "Darrowshire once stood as a village in its own right, until the Third War brought the Scourge to its gates. A ghoul lord named Horgus the Ravager led the assault, alongside the death knight Marduk Blackpool. The village's defenders fought back with some success at first, but the tide turned, and in the end every one of them was slaughtered.\n\nTheir deaths did not end them. The fallen rose again as ghouls, bound into the service of the very Scourge that killed them, their spirits trapped inside the rotting flesh that once was theirs.\n\nDarrowshire itself now stands silent and broken, empty but for ghosts and memory.",
			source = "https://warcraft.wiki.gg/wiki/Darrowshire",
		},
		["eastwall gate"] = {
			name = "Eastwall Gate",
			short = "The Eastwall Gate stands as the side way into Stratholme, opening directly onto Elder's Square, near the Alonsus Chapel where Aurius keeps his place.",
			full = "The Eastwall Gate stands as the side way into Stratholme, opening directly onto Elder's Square, near the Alonsus Chapel where Aurius keeps his place.",
			source = "https://warcraft.wiki.gg/wiki/Eastwall_Gate",
		},
		["eastwall tower"] = {
			name = "Eastwall Tower",
			short = "Eastwall Tower stands in the Eastern Plaguelands, a scout tower that once watched over the land for Lordaeron. The Scourge swept through the kingdom, and the tower wears its scars still, watching over dead lands.",
			full = "Eastwall Tower stands in the Eastern Plaguelands, a scout tower that once watched over the land for Lordaeron. The Scourge swept through the kingdom, and the tower wears its scars still, watching over dead lands.",
			source = "https://warcraft.wiki.gg/wiki/Eastwall_Tower",
		},
		["fungal vale"] = {
			name = "Fungal Vale",
			short = "North of the Marris Stead and the Crown Guard Tower lies the Fungal Vale, ground gone dark purple beneath a murky haze.",
			full = "North of the Marris Stead and the Crown Guard Tower lies the Fungal Vale, ground gone dark purple beneath a murky haze. Here the Plague of Undeath has taken its deepest hold, and the Scourge and the Cult of the Damned move freely through the corruption, holding the hollow as entirely their own.",
			source = "https://warcraft.wiki.gg/wiki/Fungal_Vale",
		},
		["infectis scar"] = {
			name = "Infectis Scar",
			short = "Near Corin's Crossing, the death knight Marduk Blackpool's runesword shattered against a dwarf captain's shield. He kept the hilt and cast the ruined blade aside as worthless.",
			full = "Near Corin's Crossing, the death knight Marduk Blackpool's runesword shattered against a dwarf captain's shield. He kept the hilt and cast the ruined blade aside as worthless. But it sank into the earth, and the ground opened beneath it, filling with dark water.\n\nWhat remains is unnatural through and through, unlike the nearby Pestilent Scar, a mere natural gorge.",
			source = "https://warcraft.wiki.gg/wiki/Infectis_Scar",
		},
		["lake mereldar"] = {
			name = "Lake Mereldar",
			short = "Lake Mereldar's waters lie thick with plague south of Corin's Crossing, corrupted water elementals moving beneath the surface.",
			full = "Lake Mereldar's waters lie thick with plague south of Corin's Crossing, corrupted water elementals moving beneath the surface. On its shore stand the ruins of an old house, and a shack and ferry that once served a farm now abandoned.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Mereldar",
		},
		["lights hope chapel"] = {
			name = "Light's Hope Chapel",
			short = "Beneath the mountains east of the Plaguelands stands a chapel far older than the ruin around it, among the oldest and most revered holy places the Church of the Holy Light ever raised.",
			full = "Beneath the mountains east of the Plaguelands stands a chapel far older than the ruin around it, among the oldest and most revered holy places the Church of the Holy Light ever raised.\n\nPaladins who would not follow the path the Scarlet Crusade was taking withdrew instead into the Eastern Plaguelands and made this chapel their base, calling themselves the Argent Dawn. Lord Raymond George led them first; when he died, Lord Maxwell Tyrosus took his place. Unlike the Scarlet Crusade, they turned no one away for their race.\n\nThough the Argent Dawn stands apart from the Scarlet Crusade, the chapel remains neutral ground where the two still meet to speak with one another.",
			source = "https://warcraft.wiki.gg/wiki/Light's_Hope_Chapel",
		},
		["marris stead"] = {
			name = "Marris Stead",
			short = "The Marris Stead sits on a low ridge above the region's main road, a farmstead that once belonged to Nathanos Marris.",
			full = "The Marris Stead sits on a low ridge above the region's main road, a farmstead that once belonged to Nathanos Marris. His cousin Stephon lived here for a time, and Sylvanas Windrunner was known to visit Nathanos beneath its roof.\n\nFreed by the Banshee Queen after she raised the Forsaken in the Undercity, Nathanos returned to the home he had lost and made it his own again on her order. From here he drew Horde soldiers into the fight against the Scourge and the Scarlet Crusade still infesting the Plaguelands, and he gathered relics from the battle of Darrowshire, keeping them within the stead for reasons he told no one.",
			source = "https://warcraft.wiki.gg/wiki/Marris_Stead",
		},
		["mazraalor"] = {
			name = "Mazra'Alor",
			short = "At the heart of Zul'Mashar rises Mazra'Alor, a ziggurat of stacked stone standing over the ruined lands around it.",
			full = "At the heart of Zul'Mashar rises Mazra'Alor, a ziggurat of stacked stone standing over the ruined lands around it. The Mossflayer tribe holds it still, their shadow hunters keeping watch from its heights over the troll settlement below.",
			source = "https://warcraft.wiki.gg/wiki/Mazra'Alor",
		},
		["northdale"] = {
			name = "Northdale",
			short = "Northdale is a ruined town north of Light's Hope Chapel, on the edge of Quel'Thalas. Here Taelan Fordring renounced the Order of the Silver Hand for the Scarlet Crusade.",
			full = "Northdale is a ruined town north of Light's Hope Chapel, on the edge of Quel'Thalas. Here Taelan Fordring renounced the Order of the Silver Hand for the Scarlet Crusade.\n\nBanshees and unseen watchers haunt the wreckage now. The nearby lake holds corrupted water elementals. Nothing living remains.",
			source = "https://warcraft.wiki.gg/wiki/Northdale",
		},
		["northpass tower"] = {
			name = "Northpass Tower",
			short = "Northpass Tower stands farthest north of the watchtowers in the Eastern Plaguelands, marking the road toward the Ghostlands of Quel'Thalas.",
			full = "Northpass Tower stands farthest north of the watchtowers in the Eastern Plaguelands, marking the road toward the Ghostlands of Quel'Thalas. The Scourge swept through Lordaeron, and the tower wears its scars still.",
			source = "https://warcraft.wiki.gg/wiki/Northpass_Tower",
		},
		["noxious glade"] = {
			name = "Noxious Glade",
			short = "The Noxious Glade sits up a hill north of Light's Hope Chapel, more tainted by the blight than the rest of the Plaguelands around it.",
			full = "The Noxious Glade sits up a hill north of Light's Hope Chapel, more tainted by the blight than the rest of the Plaguelands around it. The air hangs thick and sickly green, and the ground has been stained a dark purple where nothing green can grow.\n\nThe Scourge has made the glade its own: a plague cauldron, a slaughterhouse, and a few ziggurats stand among the poisoned ground, and Scourge creatures move through it in numbers.",
			source = "https://warcraft.wiki.gg/wiki/Noxious_Glade",
		},
		["pestilent scar"] = {
			name = "Pestilent Scar",
			short = "The Pestilent Scar is a deep gorge in the blighted Eastern Plaguelands, likely a lake that dried when the Plague of Undeath struck.",
			full = "The Pestilent Scar is a deep gorge in the blighted Eastern Plaguelands, likely a lake that dried when the Plague of Undeath struck. It lies mostly dry now, a wound in the earth, its depths home to oozes born of the old corruption.",
			source = "https://warcraft.wiki.gg/wiki/Pestilent_Scar",
		},
		["plaguewood"] = {
			name = "Plaguewood",
			short = "The trees south of Stratholme once stood green and untroubled, a woodland not unlike Elwynn Forest, with a small village nestled near the stone arch at its edge.",
			full = "The trees south of Stratholme once stood green and untroubled, a woodland not unlike Elwynn Forest, with a small village nestled near the stone arch at its edge. It was here that Sergeant Morigan, a Lordaeronian soldier born to that village, first noticed the poisoned grain out of Andorhal working its wrongness on the land, when Kel'Thuzad began his work. His warning came too late for the kingdom, and the same road he watched over was the one Prince Arthas later rode down on his way to Stratholme.\n\nWhat was left afterward was not a forest anymore. The soil itself went spongy underfoot, and mushrooms and toadstools swelled to the size of trees, towering over what remained of the old woodland. They breathe out a dark brown gas not unlike the fumes that rise from the Scourge's plague cauldrons, though no one can say for certain whether the fungus simply grows in poisoned ground or whether the Scourge cultivates it to spread its sickness further. It was for this transformation that the wood took its new name.",
			source = "https://warcraft.wiki.gg/wiki/Plaguewood",
		},
		["quellithien lodge"] = {
			name = "Quel'Lithien Lodge",
			short = "Quel'Lithien Lodge stood as a Farstrider camp near Quel'Thalas, a place of warmth and welcome. Lor'themar Theron remembered it that way from his own visits, greeted warmly by compatriots who called it home.",
			full = "Quel'Lithien Lodge stood as a Farstrider camp near Quel'Thalas, a place of warmth and welcome. Lor'themar Theron remembered it that way from his own visits, greeted warmly by compatriots who called it home. The lodge once housed a number of elven documents, some pertaining to the royal family and the Ranger-General of Silvermoon. By the time of the Second War, Renthar Hawkspear led the hunters there.",
			source = "https://warcraft.wiki.gg/wiki/Quel'Lithien_Lodge",
		},
		["scarlet base camp"] = {
			name = "Scarlet Base Camp",
			short = "On the eastern shore of Lake Mereldar, not far from the religious bastion of Tyr's Hand, the Scarlet Base Camp stands behind its barricades, its defenses reinforced against whatever might come.",
			full = "On the eastern shore of Lake Mereldar, not far from the religious bastion of Tyr's Hand, the Scarlet Base Camp stands behind its barricades, its defenses reinforced against whatever might come.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Base_Camp",
		},
		["scarlet basilica"] = {
			name = "Scarlet Basilica",
			short = "The Scarlet Basilica stands within Tyr's Hand, the high seat of the Scarlet Crusade's faith, bound to the abbey nearby and to the distant Scarlet Monastery in Tirisfal Glades.",
			full = "The Scarlet Basilica stands within Tyr's Hand, the high seat of the Scarlet Crusade's faith, bound to the abbey nearby and to the distant Scarlet Monastery in Tirisfal Glades. Crusader Lord Valdelmar holds it, his devotion to the Crusade's cause absolute.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Basilica",
		},
		["stratholme"] = {
			name = "Stratholme",
			short = "Stratholme's ruin began with grain. Shipments from Andorhal, secretly infected by the Cult of the Damned, were baked into bread and eaten by a populace who never knew they were dying.",
			full = "Stratholme's ruin began with grain. Shipments from Andorhal, secretly infected by the Cult of the Damned, were baked into bread and eaten by a populace who never knew they were dying. Prince Arthas Menethil arrived with Uther the Lightbringer and Jaina Proudmoore to find the plague already taking hold. Believing the only mercy left was a clean death rather than a slow turning into the walking dead, Arthas ordered the city put to the torch. Uther and Jaina refused and withdrew their men. Arthas did not. Fire swept the streets, and almost every soul in Stratholme was killed before the dreadlord Mal'Ganis, whom Arthas had come to kill, slipped away laughing, leaving the prince to burn what remained.\n\nIt was not enough. The dead rose anyway, and the city became the Scourge's capital in Lordaeron, ruled in turn by the lich Kel'Thuzad and later the death knight Baron Rivendare.\n\nStratholme still burns.",
			source = "https://warcraft.wiki.gg/wiki/Stratholme",
		},
		["terrordale"] = {
			name = "Terrordale",
			short = "Terrordale sits at the edge of the Plaguewood, its streets emptied and given over to the Scourge and plagued animals. Only the merchant Augustus the Touched and the ghost hunter Egan still linger among the ruin.",
			full = "Terrordale sits at the edge of the Plaguewood, its streets emptied and given over to the Scourge and plagued animals. Only the merchant Augustus the Touched and the ghost hunter Egan still linger among the ruin.\n\nThe town is haunted. Spirits walk its lanes, and in certain places Terrordale itself seems to falter, the physical world buckling under the weight of the realm beyond it, as though the ground remembers some old torment it cannot release.\n\nIt was this unrest that drew Lord Grayson Shadowbreaker, who saw in the spirits a fitting trial for paladins seeking to prove themselves worthy of judgment and sacrifice, a step toward earning the chargers reserved for the truly deserving. What the spirits had been in life goes unrecorded, only that their torment was real enough to warp the town around them.",
			source = "https://warcraft.wiki.gg/wiki/Terrordale",
		},
		["terrorweb tunnel"] = {
			name = "Terrorweb Tunnel",
			short = "The tunnel bores through the mountain northwest of Terrordale, running south to where it meets the Thondroril River.",
			full = "The tunnel bores through the mountain northwest of Terrordale, running south to where it meets the Thondroril River. Nerubian crypt fiends choke the passage entire, and among them stalks something worse: a Nerubian Overseer, far deadlier than its kin.\n\nAt the tunnel's mouth by the river, Tirion Fordring keeps watch, facing the dark of the passage from the light outside it.",
			source = "https://warcraft.wiki.gg/wiki/Terrorweb_Tunnel",
		},
		["thondroril river"] = {
			name = "Thondroril River",
			short = "The Thondroril River divides the Western and Eastern Plaguelands. It rises far north near the Terrorweb Tunnel and runs south until it empties into Darrowmere Lake, continuing beyond as the Darrowmere River.",
			full = "The Thondroril River divides the Western and Eastern Plaguelands. It rises far north near the Terrorweb Tunnel and runs south until it empties into Darrowmere Lake, continuing beyond as the Darrowmere River.\n\nIts banks belong to the blight. Maggots and vampire bats crowd the wet ground, plaguebears and spiders stalk the shallows, and snapjaws lurk where the current slows.",
			source = "https://warcraft.wiki.gg/wiki/Thondroril_River",
		},
		["tyrs hand"] = {
			name = "Tyr's Hand",
			short = "Tyr's Hand is a fortified human city, one of the last holdouts of the living against the Scourge in the region.",
			full = "Tyr's Hand is a fortified human city, one of the last holdouts of the living against the Scourge in the region. Its surroundings are in far better condition than the rest of the Plaguelands, though the trees and flora still decay.\n\nThe city is among the oldest and most revered holy sites of the Church of the Light, built almost entirely of churches, crowned by the Scarlet Basilica and the fortified abbey.\n\nWhen the Scourge came and the Eastweald became the Plaguelands, Tyr's Hand did not fall. Under Lord Valdelmar it withstood daily assault, sheltered first by the Knights of the Silver Hand and later by the Scarlet Crusade, sending supplies and reinforcements onward to other Scarlet holdings, with daily reports carried in from Stratholme by couriers who had to fight their way through the plague-thick roads.",
			source = "https://warcraft.wiki.gg/wiki/Tyr's_Hand",
		},
		["undercroft"] = {
			name = "Undercroft",
			short = "The Undercroft is a crypt in the southwestern Eastern Plaguelands, home to undead trolls led by Zaeldarr the Outcast, a risen dire troll.",
			full = "The Undercroft is a crypt in the southwestern Eastern Plaguelands, home to undead trolls led by Zaeldarr the Outcast, a risen dire troll. From here he raids the Argent Dawn's grave pit at Light's Hope Chapel, stealing bodies for his own.",
			source = "https://warcraft.wiki.gg/wiki/Undercroft",
		},
		["zulmashar"] = {
			name = "Zul'Mashar",
			short = "Zul'Mashar was once the capital of the Mossflayer tribe, forest trolls of the northeastern Eastern Plaguelands.",
			full = "Zul'Mashar was once the capital of the Mossflayer tribe, forest trolls of the northeastern Eastern Plaguelands. Long wars against the humans of Lordaeron left the tribe's lands in disarray, and the plague of undeath that followed brought ruin deeper still. The city that once ruled here stands now as a shadow of its former glory.\n\nIts ziggurat, Mazra'Alor, still stands at the heart of the city, held now by Warlord Thresh'jin and Zul'Brin Warpbranch. But the Mossflayers' own people are being covertly transformed by the plague, and Zul'Mashar is in danger of becoming nothing more than a bastion for the undead.",
			source = "https://warcraft.wiki.gg/wiki/Zul'Mashar",
		},
	},
	-- Hillsbrad Foothills: 29 subzones
	[1424] = {
		["azurelode mine"] = {
			name = "Azurelode Mine",
			short = "Azurelode Mine lies in the southwestern reach of Hillsbrad Foothills, its hill once counted part of Gilneas before the Greymane Wall rose and cut the kingdom off from the world.",
			full = "Azurelode Mine lies in the southwestern reach of Hillsbrad Foothills, its hill once counted part of Gilneas before the Greymane Wall rose and cut the kingdom off from the world.\n\nThe mine belongs to the Alliance, worked by miners under watch of guards, its iron feeding the Alliance's armories.",
			source = "https://warcraft.wiki.gg/wiki/Azurelode_Mine",
		},
		["chillwind point"] = {
			name = "Chillwind Point",
			short = "Chillwind Point takes its name from the chill wind pouring down from the Western Plaguelands, funneling through the ravine below. The rise is crowned by an ancient troll ruin, all that remains of those who raised it.",
			full = "Chillwind Point takes its name from the chill wind pouring down from the Western Plaguelands, funneling through the ravine below. The rise is crowned by an ancient troll ruin, all that remains of those who raised it. The pass once belonged to the kingdom of Lordaeron. The jungle troll Bath'rah the Windwatcher keeps to the ruin now.",
			source = "https://warcraft.wiki.gg/wiki/Chillwind_Point",
		},
		["corrahns dagger"] = {
			name = "Corrahn's Dagger",
			short = "Corrahn's Dagger is the second of the four fingers of Hillsbrad. The Syndicate holds this hill.",
			full = "Corrahn's Dagger is the second of the four fingers of Hillsbrad. The Syndicate holds this hill.",
			source = "https://warcraft.wiki.gg/wiki/Corrahn's_Dagger",
		},
		["crushridge hold"] = {
			name = "Crushridge Hold",
			short = "Crushridge Hold rises near the Ruins of Alterac, a cave hollowed into an earthen mound.",
			full = "Crushridge Hold rises near the Ruins of Alterac, a cave hollowed into an earthen mound. Around it the Crushridge ogres have raised their encampments, thick in number and brutish in temper, holding the slopes above the ruined city below.",
			source = "https://warcraft.wiki.gg/wiki/Crushridge_Hold",
		},
		["darrow hill"] = {
			name = "Darrow Hill",
			short = "Darrow Hill lies in the northern Hillsbrad Foothills, beneath the Headland.",
			full = "Darrow Hill lies in the northern Hillsbrad Foothills, beneath the Headland. Mountain lions and stags range its open fields, and within the Foothill Caverns yetis have made their den, among veins of Alterac granite that run through the rock.",
			source = "https://warcraft.wiki.gg/wiki/Darrow_Hill",
		},
		["dun garok"] = {
			name = "Dun Garok",
			short = "Dun Garok stands in the hills of the Hillsbrad Foothills, a dwarven keep under the command of Captain Ironhill.",
			full = "Dun Garok stands in the hills of the Hillsbrad Foothills, a dwarven keep under the command of Captain Ironhill. His garrison guards the humans of Hillsbrad and watches over the Azurelode Mine, a presence the Forsaken cannot abide, who have offered gold to any who would slip into the keep and put its dwarves to the sword.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Garok",
		},
		["durnholde keep"] = {
			name = "Durnholde Keep",
			short = "Durnholde Keep stands broken east of Tarren Mill, its barracks and mage tower fallen in on themselves, its arena silent.",
			full = "Durnholde Keep stands broken east of Tarren Mill, its barracks and mage tower fallen in on themselves, its arena silent. Once it was the seat of the orc internment system raised after the Second War, ruled by Lieutenant General Aedelas Blackmoore, a self-absorbed drunkard who used the camp for his own advancement.\n\nIt was Blackmoore who found an orc infant among the bodies of murdered parents and brought him back to the keep, naming him Thrall. The boy was raised and taught there, wet-nursed by a human woman whose daughter, Taretha Foxton, grew close to him. Blackmoore beat and fought the boy in the ring for years, trading on his strength to climb in rank. Taretha wrote to him in secret, and he wrote back, until at last he told her he meant to escape. She created the diversion that let him slip free, met him beyond the walls, and gave him provisions before he left.\n\nHe did return, years later, at the head of the free orcs he had gathered. Thrall laid siege to Durnholde, killed Blackmoore in single combat, and called upon the Spirit of the Earth to level the fortress entirely. What is left has since drawn the Syndicate, who claim these ruins as their own.",
			source = "https://warcraft.wiki.gg/wiki/Durnholde_Keep",
		},
		["eastern strand"] = {
			name = "Eastern Strand",
			short = "The Eastern Strand runs along the southeastern coast of the Hillsbrad Foothills, its counterpart lying further west along the same shore.",
			full = "The Eastern Strand runs along the southeastern coast of the Hillsbrad Foothills, its counterpart lying further west along the same shore. This stretch of sand belongs to the Daggerspine naga, who hold the beaches and the shallow water beyond them.",
			source = "https://warcraft.wiki.gg/wiki/Eastern_Strand",
		},
		["gallows corner"] = {
			name = "Gallows' Corner",
			short = "At Gallows' Corner, where the roads meet in the Alterac Mountains near the ruined halls of Alterac, a scout tower stands broken and empty.",
			full = "At Gallows' Corner, where the roads meet in the Alterac Mountains near the ruined halls of Alterac, a scout tower stands broken and empty. Crushridge ogres now hold the crossing, prowling the stones around the tower's remains, and nothing else stirs there.",
			source = "https://warcraft.wiki.gg/wiki/Gallows'_Corner",
		},
		["gavins naze"] = {
			name = "Gavin's Naze",
			short = "Gavin's Naze is the last of Hillsbrad's four hills, and the most guarded.",
			full = "Gavin's Naze is the last of Hillsbrad's four hills, and the most guarded.\n\nMountain lions range this hill, among them Araga, marked by her uncommon coloring.",
			source = "https://warcraft.wiki.gg/wiki/Gavin's_Naze",
		},
		["growless cave"] = {
			name = "Growless Cave",
			short = "In the Alterac Mountains, a cave shelters mountain yeti, with Skhowl often found just outside its mouth.",
			full = "In the Alterac Mountains, a cave shelters mountain yeti, with Skhowl often found just outside its mouth. Deep within stands the Flame of Uzel, a pyre raised by the human Helcular for the ritual that would make him a lich. Meat burned upon it draws the mighty yeti Frostmaw to the entrance.",
			source = "https://warcraft.wiki.gg/wiki/Growless_Cave",
		},
		["headland"] = {
			name = "Headland",
			short = "The Headland is one of the fingers of land reaching out across Hillsbrad.",
			full = "The Headland is one of the fingers of land reaching out across Hillsbrad.\n\nOn the cliffside here, Araga rests among her cubs.",
			source = "https://warcraft.wiki.gg/wiki/Headland",
		},
		["hillsbrad fields"] = {
			name = "Hillsbrad Fields",
			short = "Hillsbrad Fields lie fertile and cultivated across the western Hillsbrad Foothills, feeding Southshore and the town of Hillsbrad besides.",
			full = "Hillsbrad Fields lie fertile and cultivated across the western Hillsbrad Foothills, feeding Southshore and the town of Hillsbrad besides. Apple orchards, pumpkin patches, and grazing cattle cover the land, and the Azurelode Mine still sees work from the people of the town.\n\nEarly in the Second War, Doomhammer turned his armies against Hillsbrad and had it destroyed in a gruesome display meant to serve as a warning to the human kingdoms. It was rebuilt after the war, and stands populated still, one of the few corners of former Lordaeron that was not left in ruin nor swallowed by the Scarlet Crusade; its guards yet wear the tabard of their kingdom, and Magistrate Burnside governs from the town hall with the Council of Hillsbrad and the clerk Horrace Whitesteed at his side.\n\nNow the fields lie under threat again, from High Executor Darthalia's forces at Tarren Mill. Peasants and farmers bear the raids, but many strike back at the undead in ambushes of their own, armed by the blacksmith Verringtan and his apprentices.",
			source = "https://warcraft.wiki.gg/wiki/Hillsbrad_Fields",
		},
		["misty shore"] = {
			name = "Misty Shore",
			short = "The Misty Shore runs along Lordamere Lake, between Dandred's Fold and Dalaran. Turtles move slowly through its shallows.",
			full = "The Misty Shore runs along Lordamere Lake, between Dandred's Fold and Dalaran. Turtles move slowly through its shallows.\n\nTwo of the Scarlet Crusade hold this shore, falling on any who come too near, as though the ground itself needed guarding.\n\nAcross the water, the Dawning Isles can be seen, with Fenris Keep brooding faintly through the mist.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Shore",
		},
		["nethander stead"] = {
			name = "Nethander Stead",
			short = "Nethander Stead lies just east of Southshore, its fields long abandoned and overrun by Mudsnout gnolls, the only place their tribe is found.",
			full = "Nethander Stead lies just east of Southshore, its fields long abandoned and overrun by Mudsnout gnolls, the only place their tribe is found. Giant white mushrooms called Mudsnout Blossoms grow wild there, once sought by Apothecary Lydon for his deadly Elixir of Agony.",
			source = "https://warcraft.wiki.gg/wiki/Nethander_Stead",
		},
		["purgation isle"] = {
			name = "Purgation Isle",
			short = "A spiral of stone rises south of the Hillsbrad shore, crowned with a cemetery and the broken remains of a scout tower. Before the First War, Purgation Isle belonged to Kul Tiras.",
			full = "A spiral of stone rises south of the Hillsbrad shore, crowned with a cemetery and the broken remains of a scout tower. Before the First War, Purgation Isle belonged to Kul Tiras.\n\nWhat came after is uncertain, but the dead do not rest. Dozens of spirits walk the isle, human and dwarf, paladins and priests, monks and mages, condemned souls bound to its stones.",
			source = "https://warcraft.wiki.gg/wiki/Purgation_Isle",
		},
		["ravenholdt manor"] = {
			name = "Ravenholdt Manor",
			short = "Ravenholdt Manor sits apart from the world by design.",
			full = "Ravenholdt Manor sits apart from the world by design. Reached only by a narrow, twisting path that climbs from a plateau northwest of Durnholde Keep, winding through the mountains and a small cave before it opens onto the grounds, the manor is not a place one stumbles upon. Outsiders are not welcome here, and those who serve Lord Jorach Ravenholdt keep it that way.\n\nThe manor is his property, orange-roofed in the old fashion of Alterac, whose kingdom once held this land before the First War.\n\nIn the years since, the Syndicate has wandered this part of the highlands, and Ravenholdt has stood against that affliction from behind its hidden path and guarded gates.",
			source = "https://warcraft.wiki.gg/wiki/Ravenholdt_Manor",
		},
		["slaughter hollow"] = {
			name = "Slaughter Hollow",
			short = "Deep in the Alterac Mountains, the Crushridge ogres have made their home in Slaughter Hollow, a mound sunk into the hills.",
			full = "Deep in the Alterac Mountains, the Crushridge ogres have made their home in Slaughter Hollow, a mound sunk into the hills. Little more is known of the place than the ogres who hold it, but the name alone tells what waits for anyone who wanders too close.",
			source = "https://warcraft.wiki.gg/wiki/Slaughter_Hollow",
		},
		["soferas naze"] = {
			name = "Sofera's Naze",
			short = "Sofera's Naze rises as one of the four fingers of Hillsbrad. The Syndicate holds the hill, watching over the ground below.",
			full = "Sofera's Naze rises as one of the four fingers of Hillsbrad. The Syndicate holds the hill, watching over the ground below.",
			source = "https://warcraft.wiki.gg/wiki/Sofera's_Naze",
		},
		["southpoint tower"] = {
			name = "Southpoint Tower",
			short = "Southpoint Tower stands at the far western edge of Hillsbrad Foothills, just south of the road that runs on toward Silverpine Forest.",
			full = "Southpoint Tower stands at the far western edge of Hillsbrad Foothills, just south of the road that runs on toward Silverpine Forest. The stonework is old and cracked, a scout post left to ruin, though the tower itself was never brought down in the fighting that passed through here. Nearby, unmarked, another tower stands between Tarren Mill and Southshore, also spared the destruction that swept the rest of the foothills.",
			source = "https://warcraft.wiki.gg/wiki/Southpoint_Tower",
		},
		["strahnbrad"] = {
			name = "Strahnbrad",
			short = "Strahnbrad sits on the northeastern foothills of the Alterac Mountains, its town hall and blacksmith standing empty now.",
			full = "Strahnbrad sits on the northeastern foothills of the Alterac Mountains, its town hall and blacksmith standing empty now. Once it belonged to the Kingdom of Alterac, and after the Second War it passed into the hands of Lordaeron.\n\nThe town's ruin began shortly before the Third War, when Blackrock orcs descended on it to take slaves for sacrifice to the Burning Legion. Strahnbrad had only a handful of footmen to defend it, but word reached the Knights of the Silver Hand in time. Uther the Lightbringer rode ahead to try to head off the attack, while Prince Arthas Menethil was sent to hold the town itself. Arthas did not arrive in time. Dean, Joe, Mike, Scott, and many others were killed before he reached Strahnbrad, and what defenders remained joined him in routing the orcs and killing the Slave Master who had led the raid. The Alliance carried the field, but Strahnbrad's people were already gone.\n\nThe Syndicate later took the ruined town for their own, using it as a stronghold to claim the Alterac Mountains, and held the orc Gol'dir prisoner in one of its cells, working him as a slave to haul and dig.",
			source = "https://warcraft.wiki.gg/wiki/Strahnbrad",
		},
		["tarren mill"] = {
			name = "Tarren Mill",
			short = "Tarren Mill was once a simple Lordaeronian town among the grasslands below the Alterac Mountains.",
			full = "Tarren Mill was once a simple Lordaeronian town among the grasslands below the Alterac Mountains. In the early days of the Second War, high elven archers from Silvermoon, sent south to see the orcish threat for themselves, were ambushed near the town and dragged off to a nearby prison camp. King Terenas sent Alliance soldiers to free them, and the rescue succeeded. It was that success which led the Council of Silvermoon to join the armies of Quel'Thalas to the Alliance of Lordaeron.\n\nTarren Mill did not remain in human hands. The Forsaken took it in time, and left it as they left their other holdings: a church, a scatter of houses, orchards gone to rot, everything standing but nothing whole. From here the Forsaken stage their war against the Alliance forces of Southshore and Dun Garok, and the ground between Tarren Mill and Southshore has grown infamous for skirmish after skirmish between the two towns, neither able to break the other.",
			source = "https://warcraft.wiki.gg/wiki/Tarren_Mill",
		},
		["thoradins wall"] = {
			name = "Thoradin's Wall",
			short = "King Thoradin raised this wall to hold back the Amani trolls, in the days when Strom stood young and Arathor had only just claimed the land for humanity.",
			full = "King Thoradin raised this wall to hold back the Amani trolls, in the days when Strom stood young and Arathor had only just claimed the land for humanity. For generations it stood a stalwart sentinel, a line no troll horde could cross.\n\nCenturies on, it still stands, but heavily damaged, its stones broken and its long watch reduced to ruin.",
			source = "https://warcraft.wiki.gg/wiki/Thoradin's_Wall",
		},
		["western strand"] = {
			name = "Western Strand",
			short = "The Western Strand lies on the southwest coast of Hillsbrad Foothills. Torn Fin murlocs have raised small camps along its shore, and Andy Murgole patrols these waters, keeping watch over the coastline where they dwell.",
			full = "The Western Strand lies on the southwest coast of Hillsbrad Foothills. Torn Fin murlocs have raised small camps along its shore, and Andy Murgole patrols these waters, keeping watch over the coastline where they dwell.",
			source = "https://warcraft.wiki.gg/wiki/Western_Strand",
		},
	},
	-- The Hinterlands: 21 subzones
	[1425] = {
		["aerie peak"] = {
			name = "Aerie Peak",
			short = "The Wildhammer dwarves did not choose the Hinterlands first.",
			full = "The Wildhammer dwarves did not choose the Hinterlands first. Their home was Grim Batol, deep in the mountain, until the War of the Three Hammers ended and the dwarves returned to find their fortress poisoned by the death of Modgud. Grim Batol could not be lived in again. So the Wildhammers built anew here, atop the mountainside rather than within it, unwilling after the horrors of tunnel-fighting against the Dark Iron dwarves to bury themselves in stone again. The Aerie stands open to the sky because of that war.\n\nIt was from here that Kurdran Wildhammer led his gryphon riders against orc forces sent to strike the Hinterlands as a feint while the true Horde army moved on Quel'Thalas. Anduin Lothar's forces came to his aid and helped drive the orcs and forest trolls from Wildhammer land, and for that Kurdran pledged his clan to the Alliance.\n\nFalstad Wildhammer, left as High Thane when Kurdran did not return, rules the Aerie still. The forest trolls of the Hinterlands, who call the Wildhammers squatters on ancestral ground, still raid the gryphon aeries, while the high elves of Quel'Danil remain the dwarves' allies against that same enemy.",
			source = "https://warcraft.wiki.gg/wiki/Aerie_Peak",
		},
		["agolwatha"] = {
			name = "Agol'watha",
			short = "Agol'watha's stones are older than the trolls who last held them sacred, raised as a temple of the Amani Empire before that empire fell.",
			full = "Agol'watha's stones are older than the trolls who last held them sacred, raised as a temple of the Amani Empire before that empire fell. The Vilebranch trolls who came after claimed the ruin for their own. Now the temple has been overrun by animated sludges that fill its shattered courts.",
			source = "https://warcraft.wiki.gg/wiki/Agol'watha",
		},
		["altar of zul"] = {
			name = "Altar of Zul",
			short = "The Altar of Zul rises in the Hinterlands, raised by the Vilebranch forest trolls to their old rites. Qiaga the Keeper stands watch atop the stones, guardian of whatever power the altar still holds.",
			full = "The Altar of Zul rises in the Hinterlands, raised by the Vilebranch forest trolls to their old rites. Qiaga the Keeper stands watch atop the stones, guardian of whatever power the altar still holds.",
			source = "https://warcraft.wiki.gg/wiki/Altar_of_Zul",
		},
		["bogens ledge"] = {
			name = "Bogen's Ledge",
			short = "Bogen's Ledge is a cave in the southwestern Hinterlands.",
			full = "Bogen's Ledge is a cave in the southwestern Hinterlands.",
			source = "https://warcraft.wiki.gg/wiki/Bogen's_Ledge",
		},
		["creeping ruin"] = {
			name = "Creeping Ruin",
			short = "The Creeping Ruin lies broken in the Hinterlands, stone once shaped by forest troll hands. Slimes creep through its fallen halls now, oozing through the old troll stones where the trolls once walked.",
			full = "The Creeping Ruin lies broken in the Hinterlands, stone once shaped by forest troll hands. Slimes creep through its fallen halls now, oozing through the old troll stones where the trolls once walked.",
			source = "https://warcraft.wiki.gg/wiki/Creeping_Ruin",
		},
		["featherbeards hovel"] = {
			name = "Featherbeard's Hovel",
			short = "Beside Aerie Peak stands a small house that once belonged to someone called Featherbeard. It holds no garrison, no treasure.",
			full = "Beside Aerie Peak stands a small house that once belonged to someone called Featherbeard. It holds no garrison, no treasure. It serves no purpose now but to stand where it always stood, empty of whatever life once filled it.",
			source = "https://warcraft.wiki.gg/wiki/Featherbeard's_Hovel",
		},
		["hiriwatha"] = {
			name = "Hiri'watha",
			short = "The Witherbark trolls hold Hiri'watha, a village set south of Quel'Danil Lodge in the Hinterlands, deep in the forest they claim as their own.",
			full = "The Witherbark trolls hold Hiri'watha, a village set south of Quel'Danil Lodge in the Hinterlands, deep in the forest they claim as their own.",
			source = "https://warcraft.wiki.gg/wiki/Hiri'watha",
		},
		["jinthaalor"] = {
			name = "Jintha'Alor",
			short = "Jintha'Alor rises in terraces above the Hinterlands, second in size among the forest troll cities only to Zul'Aman.",
			full = "Jintha'Alor rises in terraces above the Hinterlands, second in size among the forest troll cities only to Zul'Aman. It was raised in the days of the Amani Empire and takes its name from Jintha, one of the Amani's ancient leaders.\n\nThe city belongs to the Vilebranch tribe, who have turned its heights into a fortress of sacrifice. Vile Priestess Hexx rules there in service to Hakkar the Soulflayer, and the Vilebranch prey without mercy on the weaker Revantusk tribe to feed their god's hunger. Elder Torntusk of the Revantusk was taken in one such raid and is held captive within the city still; his guard captain, Huntsman Malkhor, was captured in the same attack and executed, his remains thrown to the wolves and oozes kept within the walls.\n\nThe Wildhammer clan and the Revantusk tribe, bound by shared grievance against the Vilebranch, have laid siege to the city together, seeking to end its raids and win vengeance for their dead.",
			source = "https://warcraft.wiki.gg/wiki/Jintha'Alor",
		},
		["martsirt"] = {
			pending = true,
			name = "Martsirt",
			short = "",
			full = "",
			source = "",
		},
		["overlook cliffs"] = {
			name = "Overlook Cliffs",
			short = "The Overlook Cliffs mark the place where the Hinterlands stop being mountains and become sky.",
			full = "The Overlook Cliffs mark the place where the Hinterlands stop being mountains and become sky. The great river that winds through the region gathers itself here and pours over the edge in a single massive waterfall, falling to the shoreline below.\n\nThe cliffs are steep and deceptively high. Many who walked to their edge misjudged the drop and fell to their deaths.",
			source = "https://warcraft.wiki.gg/wiki/Overlook_Cliffs",
		},
		["plaguemist ravine"] = {
			name = "Plaguemist Ravine",
			short = "A mist hangs where the mountain wall breaks open west of Quel'Danil Lodge, marking the ravine that cuts north toward Caer Darrow. Nothing lives in the passage.",
			full = "A mist hangs where the mountain wall breaks open west of Quel'Danil Lodge, marking the ravine that cuts north toward Caer Darrow. Nothing lives in the passage. No birds cross it, no beasts den in its rock.\n\nThe Hinterlands around it stay green and clean, but the ravine breathes something else, a haze that does not belong to the forest. It is why the place carries the name it does now: Plaguemist, given for the sickly fog that fouls this one path while the rest of the land remains untouched.",
			source = "https://warcraft.wiki.gg/wiki/Plaguemist_Ravine",
		},
		["queldanil lodge"] = {
			name = "Quel'Danil Lodge",
			short = "Quel'Danil Lodge is one of the last true gatherings of the high elves, the larger of only two such settlements remaining in Lordaeron.",
			full = "Quel'Danil Lodge is one of the last true gatherings of the high elves, the larger of only two such settlements remaining in Lordaeron. After the Third War it became a place of correspondence, its ambassadors reaching out to the other peoples of the Alliance. That outreach won the Highvale elves an alliance with the Wildhammer dwarves, and it earned them the hatred of the Revantusk trolls, who sought to see the elves slaughtered and their records burned. The documents survived, records of deaths, births, seasons, and every treaty the elves had made.",
			source = "https://warcraft.wiki.gg/wiki/Quel'Danil_Lodge",
		},
		["revantusk village"] = {
			name = "Revantusk Village",
			short = "Revantusk Village stands on the coast of the Hinterlands, the last home of a forest troll tribe that chose loyalty over survival.",
			full = "Revantusk Village stands on the coast of the Hinterlands, the last home of a forest troll tribe that chose loyalty over survival.\n\nWhen the Old Horde broke in the Second War, the orcs' captors turned on their former allies, and forest troll tribes across the land abandoned the Horde without hesitation. The Revantusk did not. They lacked the numbers to free the captive orcs, who in any case showed little will to be freed, but their continued loyalty marked them for attack by other trolls who wanted nothing more to do with orcs. Driven from their lands, the Revantusk fled to the Hinterlands coast, hoping isolation would keep them safe, and built their village there.\n\nWord eventually reached them that Thrall had remade the Horde and led his people back to the shamanistic ways of their ancestors. The Revantusk sent their fastest runners to find him, and out of that meeting came a pact of friendship between the tribe and the new Horde. Other forest trolls have never forgiven it, calling the Revantusk weak and treacherous, while the Revantusk name all who deserted the Horde as the true traitors.",
			source = "https://warcraft.wiki.gg/wiki/Revantusk_Village",
		},
		["seradane"] = {
			name = "Seradane",
			short = "In the northeastern Hinterlands lies Seradane, where a great circular portal stands open to the Emerald Dream. The forest belongs to the green dragonflight, drawn to guard the threshold their kind holds sacred.",
			full = "In the northeastern Hinterlands lies Seradane, where a great circular portal stands open to the Emerald Dream. The forest belongs to the green dragonflight, drawn to guard the threshold their kind holds sacred. The drakes Rothos and Dreamtracker made their home among these trees.\n\nMost who keep the woods are dragonspawn, born of the flight's power. They move in groups of three, a Verdantine Oracle flanked by Boughguards and Tree Warders, patrolling the tangled paths in a standing watch over the way to the Dream.",
			source = "https://warcraft.wiki.gg/wiki/Seradane",
		},
		["shadraalor"] = {
			name = "Shadra'Alor",
			short = "In the Hinterlands stands Shadra'Alor, a settlement raised by the forest trolls of the Amani Empire. Here the loa Shadra could be called down and summoned, a place set apart for that purpose alone.",
			full = "In the Hinterlands stands Shadra'Alor, a settlement raised by the forest trolls of the Amani Empire. Here the loa Shadra could be called down and summoned, a place set apart for that purpose alone.",
			source = "https://warcraft.wiki.gg/wiki/Shadra'Alor",
		},
		["shaolwatha"] = {
			name = "Shaol'watha",
			short = "Shaol'watha is a ruin of the Vilebranch forest trolls in the northeastern Hinterlands. It was once a temple.",
			full = "Shaol'watha is a ruin of the Vilebranch forest trolls in the northeastern Hinterlands. It was once a temple.",
			source = "https://warcraft.wiki.gg/wiki/Shaol'watha",
		},
		["shindiggers camp"] = {
			name = "Shindigger's Camp",
			short = "Rhapsody Shindigger, a dwarf fond of drink, keeps his small camp in the Hinterlands alongside the high elf Gilveradin Sunchaser, an odd pairing that holds this quiet stretch of ground.",
			full = "Rhapsody Shindigger, a dwarf fond of drink, keeps his small camp in the Hinterlands alongside the high elf Gilveradin Sunchaser, an odd pairing that holds this quiet stretch of ground.",
			source = "https://warcraft.wiki.gg/wiki/Shindigger's_Camp",
		},
		["skulk rock"] = {
			name = "Skulk Rock",
			short = "Skulk Rock is a forest troll ruin overrun with slimes. A cave beneath it is one of the few places where Ghost Mushrooms still grow.",
			full = "Skulk Rock is a forest troll ruin overrun with slimes. A cave beneath it is one of the few places where Ghost Mushrooms still grow.\n\nDuring the Second War the Old Horde held the rock as a base, until the Alliance of Lordaeron drove them out.",
			source = "https://warcraft.wiki.gg/wiki/Skulk_Rock",
		},
		["valorwind lake"] = {
			name = "Valorwind Lake",
			short = "Valorwind Lake lies quiet northeast of Shadra'Alor, its waters seemingly unremarkable.",
			full = "Valorwind Lake lies quiet northeast of Shadra'Alor, its waters seemingly unremarkable. Yet along its edges grows something found nowhere else known in the world: the Violet Tragan, a mysterious mushroom whose secrets remain its own.",
			source = "https://warcraft.wiki.gg/wiki/Valorwind_Lake",
		},
		["wildhammer keep"] = {
			name = "Wildhammer Keep",
			short = "Wildhammer Keep rises at the heart of Aerie Peak, the seat of the Wildhammer dwarves who hold it. Its halls are open to travelers who reach the peak.",
			full = "Wildhammer Keep rises at the heart of Aerie Peak, the seat of the Wildhammer dwarves who hold it. Its halls are open to travelers who reach the peak.",
			source = "https://warcraft.wiki.gg/wiki/Wildhammer_Keep",
		},
		["zunwatha"] = {
			name = "Zun'watha",
			short = "The stones of Zun'watha once sheltered, and still shelter, the Witherbark trolls of the Hinterlands.",
			full = "The stones of Zun'watha once sheltered, and still shelter, the Witherbark trolls of the Hinterlands. Among the ruins they left standing, a Zul'arek hatefowler is seen from time to time, walking where the Witherbark still dwell.",
			source = "https://warcraft.wiki.gg/wiki/Zun'watha",
		},
	},
	-- Dun Morogh: 26 subzones
	[1426] = {
		["amberstill ranch"] = {
			name = "Amberstill Ranch",
			short = "Amberstill Ranch sits off the road to Loch Modan, north of Gol'Bolar Quarry, where the dwarves of the Amberstill family raise their herds against the cold of Dun Morogh.",
			full = "Amberstill Ranch sits off the road to Loch Modan, north of Gol'Bolar Quarry, where the dwarves of the Amberstill family raise their herds against the cold of Dun Morogh. Rudra Amberstill breeds prized rams here, while young Yarlyn keeps her snowshoe rabbits underfoot.\n\nThe herds have not gone untroubled. A wendigo named Vagash has taken to stalking the ranch's animals, and the Amberstills have had to defend what they raise against its hunger.",
			source = "https://warcraft.wiki.gg/wiki/Amberstill_Ranch",
		},
		["anvilmar"] = {
			name = "Anvilmar",
			short = "In Coldridge Valley stands Anvilmar, a hall built around a great forge. It was the first true settlement the dwarves raised in these northern reaches, a gathering place before any others took shape.",
			full = "In Coldridge Valley stands Anvilmar, a hall built around a great forge. It was the first true settlement the dwarves raised in these northern reaches, a gathering place before any others took shape. The forge at its heart burns still, though no smiths teach their craft there now.",
			source = "https://warcraft.wiki.gg/wiki/Anvilmar",
		},
		["brewnall village"] = {
			name = "Brewnall Village",
			short = "Brewnall Village sits in Chill Breeze Valley, near Gnomeregan, home to the Barleybrew family. The Barleybrews have given themselves to one pursuit: perfecting the dwarven art of brewing.",
			full = "Brewnall Village sits in Chill Breeze Valley, near Gnomeregan, home to the Barleybrew family. The Barleybrews have given themselves to one pursuit: perfecting the dwarven art of brewing. They send their young out from the village to guard it from wild animals and to seek rare ingredients for the ultimate ale.",
			source = "https://warcraft.wiki.gg/wiki/Brewnall_Village",
		},
		["chill breeze valley"] = {
			name = "Chill Breeze Valley",
			short = "Chill Breeze Valley runs east to west between Gnomeregan and Kharanos, its path worn familiar by young dwarves and gnomes passing through.",
			full = "Chill Breeze Valley runs east to west between Gnomeregan and Kharanos, its path worn familiar by young dwarves and gnomes passing through. But the valley bends north and south as well, and there the snow tells a different story: bloodstains spread wide across the white, and torn animal carcasses lie abandoned. Few travel this branch willingly. Those who do go hunting the beasts responsible, hoping to end their threat to the dwarven lands, and many do not return. Deep in one of the caves lairs a wendigo, the creature most responsible for the blood in the snow.",
			source = "https://warcraft.wiki.gg/wiki/Chill_Breeze_Valley",
		},
		["coldridge pass"] = {
			name = "Coldridge Pass",
			short = "Coldridge Pass is the narrow way out of Coldridge Valley, the last stretch a dwarf must cross before reaching Kharanos and the wider roads of Dun Morogh.",
			full = "Coldridge Pass is the narrow way out of Coldridge Valley, the last stretch a dwarf must cross before reaching Kharanos and the wider roads of Dun Morogh. Troggs have overrun the pass, and travelers are left with only two choices: run through as fast as their legs allow, or cut a bloody path through the invaders.\n\nFendrig Redbeard once led twelve other miners into the pass to investigate the infestation. Deep inside, he was pinned beneath a fall of stone. The others turned back to dig him free, but the effort brought the pass down around them. Twelve miners died. Only Fendrig, pulled from the rubble, survived.",
			source = "https://warcraft.wiki.gg/wiki/Coldridge_Pass",
		},
		["coldridge valley"] = {
			name = "Coldridge Valley",
			short = "Snow lies thick over Coldridge Valley, walled in on every side, its only way out the narrow tunnel of Coldridge Pass to the northeast.",
			full = "Snow lies thick over Coldridge Valley, walled in on every side, its only way out the narrow tunnel of Coldridge Pass to the northeast. That passage is infested with trogg raiders, brutish things that have long made the crossing to Kharanos and Ironforge dangerous for anyone travelling it alone.\n\nBeyond the pass the road climbs east, then north through Kharanos, before winding up through the mountains to the gates of Ironforge itself.",
			source = "https://warcraft.wiki.gg/wiki/Coldridge_Valley",
		},
		["frostmane hold"] = {
			name = "Frostmane Hold",
			short = "Frostmane Hold stands on the western edge of Dun Morogh's cold mountains, south of Gnomeregan, a scatter of buildings knit to a cave system driven into the mountainside.",
			full = "Frostmane Hold stands on the western edge of Dun Morogh's cold mountains, south of Gnomeregan, a scatter of buildings knit to a cave system driven into the mountainside. It is the base camp of the Frostmane ice trolls, who hold the ground with headhunters and hideskinners guarding every approach.",
			source = "https://warcraft.wiki.gg/wiki/Frostmane_Hold",
		},
		["gates of ironforge"] = {
			name = "Gates of Ironforge",
			short = "The Gates of Ironforge rise where the great ramp of Dun Morogh climbs to meet the mountain, visible for miles across the snows before a traveler ever reaches them.",
			full = "The Gates of Ironforge rise where the great ramp of Dun Morogh climbs to meet the mountain, visible for miles across the snows before a traveler ever reaches them. They stand as the threshold between the open dwarven lands and Ironforge proper.\n\nPassing through, one comes under the gaze of a huge statue raised to High King Modimus Anvilmar, set to keep watch just inside the entrance, so that none enter the city without passing beneath his eyes first.",
			source = "https://warcraft.wiki.gg/wiki/Gates_of_Ironforge",
		},
		["gnomeregan"] = {
			name = "Gnomeregan",
			short = "Gnomeregan is the subterranean capital of the gnomish kingdom of the same name, wrought-iron evidence of gnomish brilliance, ambition, and ingenuity.",
			full = "Gnomeregan is the subterranean capital of the gnomish kingdom of the same name, wrought-iron evidence of gnomish brilliance, ambition, and ingenuity.\n\nDuring the Third War, a trogg invasion brought about its downfall. The troggs had been pulled from their sleep by the upheaval of titan sites, and swarmed up into the city from below. In a desperate attempt to kill the invaders, High Tinker Gelbin Mekkatorque, on the advice of his advisor Sicco Thermaplugg, ordered his people to open the pressure valves of their giant, grinding machines and release toxic radiation throughout Gnomeregan. Though the gas killed some of the troggs, it only empowered others, and nearly eighty percent of gnomekind died within days. The survivors fled to the protection of Ironforge. Others were twisted into horrific, mindless, evil-doing leper gnomes, who still haunt the ruined tunnels.\n\nDriven mad by the radiation himself, Thermaplugg declared himself \"King of Gnomeregan\" and seized control of the poisoned city, leading an army of troggs and leper gnomes through its wrecked halls and workshops.",
			source = "https://warcraft.wiki.gg/wiki/Gnomeregan",
		},
		["golbolar quarry"] = {
			name = "Gol'Bolar Quarry",
			short = "Gol'Bolar Quarry lies dug into southeastern Dun Morogh, a mining camp cut short by what came crawling up from beneath it.",
			full = "Gol'Bolar Quarry lies dug into southeastern Dun Morogh, a mining camp cut short by what came crawling up from beneath it. The dwarves opened the excavation seeking what the mountain held, but the digging woke troggs, who swarmed up from the depths of the mine and overran the pits and tunnels the miners had carved.\n\nThe camp that remains is a foothold, not a victory: dwarves hold the surface while the mine below stays lost to the troggs.",
			source = "https://warcraft.wiki.gg/wiki/Gol'Bolar_Quarry",
		},
		["grizzled den"] = {
			name = "Grizzled Den",
			short = "A large cave system opens southwest of Kharanos, cutting deep into the ice of Dun Morogh. Wendigos have made their den here, shaggy frost-breathing beasts that flock together against any who trespass.",
			full = "A large cave system opens southwest of Kharanos, cutting deep into the ice of Dun Morogh. Wendigos have made their den here, shaggy frost-breathing beasts that flock together against any who trespass. Their manes are prized for seat covers, though few who go in after them come out without a fight, for the wendigos do not scatter but close ranks and drive intruders back out with claw and frozen breath.",
			source = "https://warcraft.wiki.gg/wiki/Grizzled_Den",
		},
		["helms bed lake"] = {
			name = "Helm's Bed Lake",
			short = "Helm's Bed Lake lies frozen for most of the year, its surface locked in ice thick enough to walk across in safety. Only a single hole is kept open, cut so that fresh water can still be drawn from beneath the frost.",
			full = "Helm's Bed Lake lies frozen for most of the year, its surface locked in ice thick enough to walk across in safety. Only a single hole is kept open, cut so that fresh water can still be drawn from beneath the frost.\n\nThe safety ends at the shore. Wolves and other wild creatures range the banks, and stray troggs haunt the surrounding rock. South of the lake stands an abandoned building claimed by Dark Iron dwarves, who strike at anyone who strays too near it.",
			source = "https://warcraft.wiki.gg/wiki/Helm's_Bed_Lake",
		},
		["iceflow lake"] = {
			name = "Iceflow Lake",
			short = "Iceflow Lake freezes hard in the cold of Dun Morogh, but the dwarves of Brewnall Village keep one hole cut through the ice, drawing fresh water and fish from beneath the frozen surface.",
			full = "Iceflow Lake freezes hard in the cold of Dun Morogh, but the dwarves of Brewnall Village keep one hole cut through the ice, drawing fresh water and fish from beneath the frozen surface.\n\nOut toward the lake's center rise a pair of islands, best left alone. A pack of ravenous wolves has claimed them, running under a worg named Timber, and their presence keeps the islands empty of all but the beasts that hold them.",
			source = "https://warcraft.wiki.gg/wiki/Iceflow_Lake",
		},
		["ironbands compound"] = {
			name = "Ironband's Compound",
			short = "South of Helm's Bed Lake, Ironband's Compound stands as a foothold for Dark Iron dwarves, who strike at anyone who strays too near. The place once belonged to Sturgy Ironband, before it fell into Dark Iron hands.",
			full = "South of Helm's Bed Lake, Ironband's Compound stands as a foothold for Dark Iron dwarves, who strike at anyone who strays too near. The place once belonged to Sturgy Ironband, before it fell into Dark Iron hands.",
			source = "https://warcraft.wiki.gg/wiki/Ironband's_Compound",
		},
		["ironforge submarine facility"] = {
			pending = true,
			name = "Ironforge Submarine Facility",
			short = "",
			full = "",
			source = "",
		},
		["kharanos"] = {
			name = "Kharanos",
			short = "Kharanos sits among the mountain peaks of Dun Morogh, its streets ringed by wintry wilds that never let its folk grow soft.",
			full = "Kharanos sits among the mountain peaks of Dun Morogh, its streets ringed by wintry wilds that never let its folk grow soft. A forge burns at its heart, a gnomish workshop clatters away, and the Thunderbrew Distillery pours some of the finest ale to be found anywhere, but the town has never been able to rest easy in its charm. To the west lies a cavern thick with wendigo, and to the northwest the Frostmane trolls hold Shimmer Ridge, watching the town below.\n\nThat watching once turned to war, when a giant Frostmane troll fell upon Kharanos and very nearly wiped out every dwarf living there. Where the town's defenders faltered, one dwarf did not. Lazlo Grindwidget stood against the troll and brought it down alone, and for that the town named him a hero, a title that has followed him ever since through streets that remember how close they came to silence.",
			source = "https://warcraft.wiki.gg/wiki/Kharanos",
		},
		["misty pine refuge"] = {
			name = "Misty Pine Refuge",
			short = "Misty Pine Refuge lies quiet in central Dun Morogh, a sheltered clearing among the snow-heavy pines.",
			full = "Misty Pine Refuge lies quiet in central Dun Morogh, a sheltered clearing among the snow-heavy pines.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Pine_Refuge",
		},
		["north gate outpost"] = {
			name = "North Gate Outpost",
			short = "North Gate Outpost sits astride North Gate Pass, the narrow way through the mountains that joins Dun Morogh to Loch Modan, the northeasternmost of the dwarven holds in these highlands.",
			full = "North Gate Outpost sits astride North Gate Pass, the narrow way through the mountains that joins Dun Morogh to Loch Modan, the northeasternmost of the dwarven holds in these highlands.\n\nThe mountaineers garrisoned here spend their days pushing back the wildlife pressing in from the surrounding peaks. Some who went hunting the more dangerous beasts have not come back, and search has been made of the mountains for word of them, with little enough to show for it.",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Outpost",
		},
		["north gate pass"] = {
			name = "North Gate Pass",
			short = "The pass cuts through the high mountains, dropping from Dun Morogh down toward Loch Modan.",
			full = "The pass cuts through the high mountains, dropping from Dun Morogh down toward Loch Modan. It is the shortest road between the two, and travelers bound for the lands beyond the Loch pass through here more than any other way.\n\nThe North Gate Outpost stands guard here, holding the passage.",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Pass",
		},
		["shimmer ridge"] = {
			name = "Shimmer Ridge",
			short = "Shimmer Ridge rises in northern Dun Morogh, held by Frostmane trolls who keep two camps joined by a bridge, tending shimmerweed and taming boars among the rocks.",
			full = "Shimmer Ridge rises in northern Dun Morogh, held by Frostmane trolls who keep two camps joined by a bridge, tending shimmerweed and taming boars among the rocks.",
			source = "https://warcraft.wiki.gg/wiki/Shimmer_Ridge",
		},
		["south gate outpost"] = {
			name = "South Gate Outpost",
			short = "South Gate Outpost sits where the pass narrows between Dun Morogh and Loch Modan, a chokepoint of stone held by dwarven mountaineers.",
			full = "South Gate Outpost sits where the pass narrows between Dun Morogh and Loch Modan, a chokepoint of stone held by dwarven mountaineers. Theirs is quieter work than that of their kin at North Gate: they have driven back the wildlife that once pressed on the pass, and the road through it stays open and safe for those making their way to or from Thelsamar.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Outpost",
		},
		["south gate pass"] = {
			name = "South Gate Pass",
			short = "South Gate Pass cuts through the mountains, joining the high snows of Dun Morogh to the lower valleys of Loch Modan. It is the shortest way down to Thelsamar, worn by travelers between the two lands.",
			full = "South Gate Pass cuts through the mountains, joining the high snows of Dun Morogh to the lower valleys of Loch Modan. It is the shortest way down to Thelsamar, worn by travelers between the two lands.\n\nHere stands South Gate Outpost, a guard station set to watch the pass.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Pass",
		},
		["steelgrills depot"] = {
			name = "Steelgrill's Depot",
			short = "Steelgrill's Depot sits east of Kharanos, a small camp of miners and engineers working the frozen ground of Dun Morogh.",
			full = "Steelgrill's Depot sits east of Kharanos, a small camp of miners and engineers working the frozen ground of Dun Morogh.",
			source = "https://warcraft.wiki.gg/wiki/Steelgrill's_Depot",
		},
		["thunderbrew distillery"] = {
			name = "Thunderbrew Distillery",
			short = "The Thunderbrew Distillery stands in Kharanos, its name known far beyond the dwarven town for the quality of its ale. Innkeeper Belm keeps the place, offering rest and drink to those who pass through.",
			full = "The Thunderbrew Distillery stands in Kharanos, its name known far beyond the dwarven town for the quality of its ale. Innkeeper Belm keeps the place, offering rest and drink to those who pass through.",
			source = "https://warcraft.wiki.gg/wiki/Thunderbrew_Distillery",
		},
		["tundrid hills"] = {
			name = "Tundrid Hills",
			short = "The Tundrid Hills lie south of Gol'Bolar Quarry, a stretch of wind-scoured ground where few travel without a blade in hand.",
			full = "The Tundrid Hills lie south of Gol'Bolar Quarry, a stretch of wind-scoured ground where few travel without a blade in hand. Wolves and other wild things prowl the slopes, and those who cross the hills to cut between Coldridge Valley and eastern Dun Morogh do so knowing the road through Kharanos would have been safer.\n\nThe Frostmane trolls have raised a camp in the valley here, holding this ground within sight of the dwarves' quarry.",
			source = "https://warcraft.wiki.gg/wiki/Tundrid_Hills",
		},
	},
	-- Searing Gorge: 11 subzones
	[1427] = {
		["blackchar cave"] = {
			name = "Blackchar Cave",
			short = "Blackchar Cave lies sealed near Blackrock Mountain, its dark stone quiet and closed off from the world outside.",
			full = "Blackchar Cave lies sealed near Blackrock Mountain, its dark stone quiet and closed off from the world outside.",
			source = "https://warcraft.wiki.gg/wiki/Blackchar_Cave",
		},
		["blackrock mountain"] = {
			name = "Blackrock Mountain",
			short = "Blackrock Mountain was not born of ordinary fire.",
			full = "Blackrock Mountain was not born of ordinary fire. When the Bronzebeard and Wildhammer armies marched to purge the Dark Iron clan during the War of the Three Hammers, Sorcerer-Thane Thaurissan reached into the world's molten heart and dragged its power up as a weapon. What answered him was Ragnaros. The Firelord's rebirth tore the mountains apart, drowned the surrounding land in fire, and sent both kings turning their armies back rather than face him. Where the Dark Iron kingdom had stood, a volcano now smoldered, with the Burning Steppes to its south and the Searing Gorge to its north. Ragnaros withdrew into the mountain's core and enslaved the surviving Dark Iron dwarves to carve Shadowforge City beneath their own ruined home.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Mountain",
		},
		["cauldron"] = {
			name = "Cauldron",
			short = "The Cauldron is a vast excavation gouged into the center of the Searing Gorge, fortified by the Dark Iron dwarves some time after they summoned Ragnaros.",
			full = "The Cauldron is a vast excavation gouged into the center of the Searing Gorge, fortified by the Dark Iron dwarves some time after they summoned Ragnaros. The great machines they used to tear it open still ring its edges. Below, fire and magma elementals move through the cracked, glowing crevices.\n\nSlave workers taken by the Dark Irons labor endlessly down there, broken by the work and the oppressive heat. They no longer know friend from captor, and meet anyone who enters with the same mindless violence as any overseer.",
			source = "https://warcraft.wiki.gg/wiki/Cauldron",
		},
		["dustfire valley"] = {
			name = "Dustfire Valley",
			short = "Dustfire Valley cuts through the Searing Gorge, windswept ground leading north to the gates of Stonewrought Pass and the Valley of Kings beyond in Loch Modan.",
			full = "Dustfire Valley cuts through the Searing Gorge, windswept ground leading north to the gates of Stonewrought Pass and the Valley of Kings beyond in Loch Modan.",
			source = "https://warcraft.wiki.gg/wiki/Dustfire_Valley",
		},
		["firewatch ridge"] = {
			name = "Firewatch Ridge",
			short = "Firewatch Ridge is the main camp of the Dark Iron dwarves in Searing Gorge, overlooking the great excavation of the Cauldron.",
			full = "Firewatch Ridge is the main camp of the Dark Iron dwarves in Searing Gorge, overlooking the great excavation of the Cauldron. Dark Iron dwarves hold the slopes with mechanical golems and giant flame spiders, making the ridge a dangerous place to tread.",
			source = "https://warcraft.wiki.gg/wiki/Firewatch_Ridge",
		},
		["grimesilt dig site"] = {
			name = "Grimesilt Dig Site",
			short = "Ironforge dwarves once dug here, until the Dark Iron dwarves came and seized the site for themselves. It remains in Dark Iron hands.",
			full = "Ironforge dwarves once dug here, until the Dark Iron dwarves came and seized the site for themselves. It remains in Dark Iron hands.",
			source = "https://warcraft.wiki.gg/wiki/Grimesilt_Dig_Site",
		},
		["sea of cinders"] = {
			name = "Sea of Cinders",
			short = "The Sea of Cinders lies flat and open in the southern reaches of Searing Gorge, just north of Blackrock Mountain. Nothing grows there.",
			full = "The Sea of Cinders lies flat and open in the southern reaches of Searing Gorge, just north of Blackrock Mountain. Nothing grows there. The ground still smolders, and ash rises constantly on the wind, drifting across the barren flats. Fire and wind left nothing behind but waste, and the burning has never stopped.",
			source = "https://warcraft.wiki.gg/wiki/Sea_of_Cinders",
		},
		["slag pit"] = {
			name = "Slag Pit",
			short = "The Slag Pit sinks deep into the Cauldron excavation in Searing Gorge, worked by slaves under the cruelty of Dark Iron dwarves.",
			full = "The Slag Pit sinks deep into the Cauldron excavation in Searing Gorge, worked by slaves under the cruelty of Dark Iron dwarves. Slavers and taskmasters drive the labor on, and even the cowed workers will turn on anyone who strikes at their overseers. The Dark Irons answer any interference with their mining with open hostility, and in the pit's deeper dark, ravenous Incendosaurs nest among the diggings.",
			source = "https://warcraft.wiki.gg/wiki/Slag_Pit",
		},
		["stonewrought pass"] = {
			name = "Stonewrought Pass",
			short = "The tunnel known as Stonewrought Pass cuts through the mountains, joining Searing Gorge to the Valley of Kings in Loch Modan, at the northern end of Dustfire Valley.",
			full = "The tunnel known as Stonewrought Pass cuts through the mountains, joining Searing Gorge to the Valley of Kings in Loch Modan, at the northern end of Dustfire Valley. It is the work of Franclorn Forgewright, who also raised the Stonewrought Dam and much else of dwarven stonework across the Eastern Kingdoms.\n\nThe Loch Modan gate is held shut by Mountaineer Pebblebitty, barring the way to all but those who have proven themselves against Margol the Rager.",
			source = "https://warcraft.wiki.gg/wiki/Stonewrought_Pass",
		},
		["tanner camp"] = {
			name = "Tanner Camp",
			short = "Sarah Tanner, master of elemental leatherworking, keeps a lone tent in Searing Gorge. Behind it a long passage winds into the mountain, ending where the thunder lizard Margol the Rager waits.",
			full = "Sarah Tanner, master of elemental leatherworking, keeps a lone tent in Searing Gorge. Behind it a long passage winds into the mountain, ending where the thunder lizard Margol the Rager waits.",
			source = "https://warcraft.wiki.gg/wiki/Tanner_Camp",
		},
		["thorium point"] = {
			name = "Thorium Point",
			short = "In the scorched north of Searing Gorge stands Thorium Point, a small neutral town held by the Thorium Brotherhood, populated mostly by Dark Iron dwarves who hold to the Brotherhood rather than the dark powers beneath the mountains.",
			full = "In the scorched north of Searing Gorge stands Thorium Point, a small neutral town held by the Thorium Brotherhood, populated mostly by Dark Iron dwarves who hold to the Brotherhood rather than the dark powers beneath the mountains. A forge and anvil stand ready here, kept lit amid the ash and heat, where metal is still shaped despite what the Gorge has become.",
			source = "https://warcraft.wiki.gg/wiki/Thorium_Point",
		},
	},
	-- Burning Steppes: 12 subzones
	[1428] = {
		["blackrock mountain"] = {
			name = "Blackrock Mountain",
			short = "Blackrock Mountain was not born of ordinary fire.",
			full = "Blackrock Mountain was not born of ordinary fire. When the Bronzebeard and Wildhammer armies marched to purge the Dark Iron clan during the War of the Three Hammers, Sorcerer-Thane Thaurissan reached into the world's molten heart and dragged its power up as a weapon. What answered him was Ragnaros. The Firelord's rebirth tore the mountains apart, drowned the surrounding land in fire, and sent both kings turning their armies back rather than face him. Where the Dark Iron kingdom had stood, a volcano now smoldered, with the Burning Steppes to its south and the Searing Gorge to its north. Ragnaros withdrew into the mountain's core and enslaved the surviving Dark Iron dwarves to carve Shadowforge City beneath their own ruined home.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Mountain",
		},
		["blackrock pass"] = {
			name = "Blackrock Pass",
			short = "Blackrock Pass is the threshold between two worlds. On one side lies Redridge, green and quiet. On the other, the Burning Steppes wait, scorched and twisted beyond recognition.",
			full = "Blackrock Pass is the threshold between two worlds. On one side lies Redridge, green and quiet. On the other, the Burning Steppes wait, scorched and twisted beyond recognition. A gate stands at the border, marking the line plainly.\n\nTo pass through is to leave safety behind in a single step. Those who wander through unprepared find the change brutal: the creatures beyond are far crueler than anything stirring in the mountains behind them.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Pass",
		},
		["blackrock stronghold"] = {
			name = "Blackrock Stronghold",
			short = "The stronghold rises at the edge of the Burning Steppes, hard against the shadow of Blackrock Spire, a fortress of black stone held by the Blackrock clan.",
			full = "The stronghold rises at the edge of the Burning Steppes, hard against the shadow of Blackrock Spire, a fortress of black stone held by the Blackrock clan. Outside its walls, in the Fields of Honor, the clan's warriors and their allies muster and drill, kept in line by the lash and voice of the Blackrock Sergeants.\n\nCommand of the stronghold falls to General Thorg'izog, who disciplines the troops gathered in the fields and sees that his orders are carried through without question.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Stronghold",
		},
		["dracodar"] = {
			name = "Draco'dar",
			short = "Draco'dar's hills lie blackened and scorched, given over entirely to the black dragonflight. Their kind moves freely across the ground here, thick enough that none should walk into it without caution and without company.",
			full = "Draco'dar's hills lie blackened and scorched, given over entirely to the black dragonflight. Their kind moves freely across the ground here, thick enough that none should walk into it without caution and without company.",
			source = "https://warcraft.wiki.gg/wiki/Draco'dar",
		},
		["dreadmaul rock"] = {
			name = "Dreadmaul Rock",
			short = "Dreadmaul Rock is a stronghold of stone paths and hollowed ogre mounds, seat of the Firegut clan.",
			full = "Dreadmaul Rock is a stronghold of stone paths and hollowed ogre mounds, seat of the Firegut clan. From its heights and tunnels the Fireguts stage their raids southward into the Redridge Mountains, using the rock as their base before falling back into its depths.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmaul_Rock",
		},
		["flame crest"] = {
			name = "Flame Crest",
			short = "Flame Crest sits on a bare outcropping in the Burning Steppes, reachable only by a crude bridge. In the small cave at its back lives Kibler, who keeps a talkative parrot.",
			full = "Flame Crest sits on a bare outcropping in the Burning Steppes, reachable only by a crude bridge. In the small cave at its back lives Kibler, who keeps a talkative parrot.",
			source = "https://warcraft.wiki.gg/wiki/Flame_Crest",
		},
		["morgans vigil"] = {
			name = "Morgan's Vigil",
			short = "Morgan's Vigil lies in ruin in the southeastern Burning Steppes, its houses burned to the ground and its mage tower crumbled to rubble.",
			full = "Morgan's Vigil lies in ruin in the southeastern Burning Steppes, its houses burned to the ground and its mage tower crumbled to rubble. Tents stand among the wreckage, sheltering those who remain.\n\nFrom these tents the Alliance keeps its watch on Blackrock Mountain, striking at the danger closer to its source.",
			source = "https://warcraft.wiki.gg/wiki/Morgan's_Vigil",
		},
		["pillar of ash"] = {
			name = "Pillar of Ash",
			short = "A tall tower of scorched stone rises at the eastern end of Black Tooth Hovel, its surface blackened as though fire itself had climbed it and stopped.",
			full = "A tall tower of scorched stone rises at the eastern end of Black Tooth Hovel, its surface blackened as though fire itself had climbed it and stopped. Nothing grows near it, and nothing else here stands so high.",
			source = "https://warcraft.wiki.gg/wiki/Pillar_of_Ash",
		},
		["poachers den"] = {
			pending = true,
			name = "Poacher's Den",
			short = "",
			full = "",
			source = "",
		},
		["ruins of thaurissan"] = {
			name = "Ruins of Thaurissan",
			short = "Once these ashen flats in the Burning Steppes were green, and the city here bore the name of its founder: Thaurissan City, capital of the Dark Iron clan, exiled from Ironforge and led south by Sorcerer-Thane Thaurissan during the War of the Three Hammers.",
			full = "Once these ashen flats in the Burning Steppes were green, and the city here bore the name of its founder: Thaurissan City, capital of the Dark Iron clan, exiled from Ironforge and led south by Sorcerer-Thane Thaurissan during the War of the Three Hammers.\n\nThe Dark Irons were losing that war. Their army had just been broken against the other two clans' strongholds when Thaurissan, desperate to turn the tide, gathered seven of his most trusted dwarves and called down into the powers sleeping beneath the earth for a servant to win the war back. What answered was no servant, but Ragnaros, Elemental Lord of Fire, and his coming split the mountains with a volcano that burned the valley to ash. The city was annihilated, and the surviving Dark Irons were enslaved to the Firelord. Abandoning the ruins, they built a new home beneath Blackrock Mountain, and from the ashes of Thaurissan rose Blackrock Spire and a new Dark Iron nation.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Thaurissan",
		},
		["slither rock"] = {
			name = "Slither Rock",
			short = "Slither Rock is a small cave hidden beyond the Terror Wing Path in the far northeastern Burning Steppes.",
			full = "Slither Rock is a small cave hidden beyond the Terror Wing Path in the far northeastern Burning Steppes. It shelters the black dragonspawn Cyrus Therepentous, who will aid others against a common foe, though never without rude, derisive comments.",
			source = "https://warcraft.wiki.gg/wiki/Slither_Rock",
		},
		["terror wing path"] = {
			name = "Terror Wing Path",
			short = "Terror Wing Path is a valley in the eastern Burning Steppes, given over entirely to the black dragonflight. Whelps and dragonkin nest among its rocks and ash.",
			full = "Terror Wing Path is a valley in the eastern Burning Steppes, given over entirely to the black dragonflight. Whelps and dragonkin nest among its rocks and ash.",
			source = "https://warcraft.wiki.gg/wiki/Terror_Wing_Path",
		},
	},
	-- Elwynn Forest: 24 subzones
	[1429] = {
		["brackwell pumpkin patch"] = {
			name = "Brackwell Pumpkin Patch",
			short = "In southeast Elwynn Forest stands a farmstead that once belonged to the Brackwell family. What became of them, no one can say.",
			full = "In southeast Elwynn Forest stands a farmstead that once belonged to the Brackwell family. What became of them, no one can say. The Defias Brotherhood took the place for their own, and the Brackwells simply vanished from its fields and fences.\n\nOf them, only one memory lingers: a prize sow named Princess, grown enormous on vegetables she stole by creeping over to the neighboring Stonefield Farm night after night, long before the bandits ever came.",
			source = "https://warcraft.wiki.gg/wiki/Brackwell_Pumpkin_Patch",
		},
		["crystal lake"] = {
			name = "Crystal Lake",
			short = "Crystal Lake lies east of Goldshire, its waters thick with murlocs that make the shore a poor place for the unwary. A human homestead watches over the water from the southern shore.",
			full = "Crystal Lake lies east of Goldshire, its waters thick with murlocs that make the shore a poor place for the unwary. A human homestead watches over the water from the southern shore.",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Lake",
		},
		["eastvale logging camp"] = {
			name = "Eastvale Logging Camp",
			short = "The mill camps of Eastvale stand scattered through eastern Elwynn, their living quarters strung between the sawpits, and the work never truly stops.",
			full = "The mill camps of Eastvale stand scattered through eastern Elwynn, their living quarters strung between the sawpits, and the work never truly stops. Orders for lumber come in faster than the deadlines allow, and the lumberjacks labor under a constant press of buyers waiting on Stormwind's timber.\n\nMarshal Haggard, who once led the Stormwind Guard, retired from that command a few years back and chose to spend his remaining years in a manor within the camp rather than in the city he once defended. Ceya Northbrooke was raised here as well.\n\nThe forest presses close on every side, and the wildness of it is no small thing. Wolves and bears have harried the loggers, scattering work crews and threatening to bury the camp's deadlines entirely. The trouble grew severe enough that the Stormwind Guard was forced to call for outside help in culling the beasts.",
			source = "https://warcraft.wiki.gg/wiki/Eastvale_Logging_Camp",
		},
		["echo ridge mine"] = {
			name = "Echo Ridge Mine",
			short = "Echo Ridge Mine's tunnels lie in northwestern Northshire Valley.",
			full = "Echo Ridge Mine's tunnels lie in northwestern Northshire Valley. Kobolds swarmed the shafts and made them their own, much to the frustration of the humans living nearby, and Marshal McBride could do no more than send men to cull their numbers again and again.",
			source = "https://warcraft.wiki.gg/wiki/Echo_Ridge_Mine",
		},
		["fargodeep mine"] = {
			name = "Fargodeep Mine",
			short = "Fargodeep Mine was once worked for Stormwind gold, its shafts sunk deep into the earth of Elwynn Forest. It stands abandoned now, its tunnels claimed by a clan of kobolds.",
			full = "Fargodeep Mine was once worked for Stormwind gold, its shafts sunk deep into the earth of Elwynn Forest. It stands abandoned now, its tunnels claimed by a clan of kobolds. Lower Mines, the deeper reaches beneath the main works, run further still into the dark.\n\nMarshal Dughan, watching over Elwynn's safety, saw the surrounding patrols increased once the kobold presence within was confirmed. Among the kobolds skulks Goldtooth, who holds a necklace stolen from Auntie Bernice Stonefield, a keepsake she has not given up hope of seeing again.",
			source = "https://warcraft.wiki.gg/wiki/Fargodeep_Mine",
		},
		["forests edge"] = {
			name = "Forest's Edge",
			short = "Forest's Edge lies southwest of Stormwind, a tongue of woodland between Mirror Lake Orchard, the Nazferiti river, and a smaller stream toward Westfall.",
			full = "Forest's Edge lies southwest of Stormwind, a tongue of woodland between Mirror Lake Orchard, the Nazferiti river, and a smaller stream toward Westfall. Boars root through its underbrush, and copper veins run along the banks. The forest belongs to a band of gnolls, and among them stands one who is no mere pack beast. Hogger ranges the woods among the lesser gnolls, no common cur among them.",
			source = "https://warcraft.wiki.gg/wiki/Forest's_Edge",
		},
		["goldshire"] = {
			name = "Goldshire",
			short = "Goldshire sits in the heart of Elwynn Forest, its fields within sight of Northshire, its roads reaching toward Stormwind, Westfall, and Redridge.",
			full = "Goldshire sits in the heart of Elwynn Forest, its fields within sight of Northshire, its roads reaching toward Stormwind, Westfall, and Redridge. It grew up in the years after Stormwind's founding, when the kingdom's people spread from the capital into the surrounding country.\n\nThe town's worst hour came during the First War, when Warchief Blackhand turned the Horde against the lifeline running between Stormwind Keep and its people. Goldshire and Moonbrook were the last two towns standing between the orcs and the capital, and when they fell, the road to the Keep lay open. Goldshire did not rise again until after the Second War, when the Alliance of Lordaeron rebuilt it, Supreme Commander Turalyon himself seeing to the return of Stormwind's scattered citizens.\n\nWhat remains now is quieter: the Lion's Pride Inn stands at the center of town, its hearth and ale drawing travelers from every road that meets here. Marshal Dughan of the Stormwind Guard keeps watch over the town still, mindful of what it once cost to lose it.",
			source = "https://warcraft.wiki.gg/wiki/Goldshire",
		},
		["heroes vigil"] = {
			name = "Heroes' Vigil",
			short = "A ring of standing stones circles the small island in Stone Cairn Lake, centered on the Stone of Remembrance.",
			full = "A ring of standing stones circles the small island in Stone Cairn Lake, centered on the Stone of Remembrance. It honors the dead of the First War, when orcs sacked Goldshire and the surrounding lands and put them to fire.\n\nRogue wizards hold the island now. Among the stones lies the body of Henze Faulk, left where he fell.",
			source = "https://warcraft.wiki.gg/wiki/Heroes'_Vigil",
		},
		["jasperlode mine"] = {
			name = "Jasperlode Mine",
			short = "Jasperlode Mine once fed Stormwind's forges, one of the sites in Elwynn Forest that supplied the raw ore the city needed for its wars.",
			full = "Jasperlode Mine once fed Stormwind's forges, one of the sites in Elwynn Forest that supplied the raw ore the city needed for its wars. That work is done now. Kobolds have overrun the tunnels, and Stormwind's army, stretched thin by graver threats, has no men to spare to root them out.\n\nThe kobolds are not the only danger below. In the deepest recesses of the mine a colony of mine spiders has taken hold, and to them the kobolds are not invaders to fear but prey to hunt. Their queen, Mother Fang, broods in the dark and suffers no intrusion into her nest.",
			source = "https://warcraft.wiki.gg/wiki/Jasperlode_Mine",
		},
		["jerods landing"] = {
			name = "Jerod's Landing",
			short = "Jerod's Landing is a boat dock on the Elwynn Forest bank of the Nazferiti river.",
			full = "Jerod's Landing is a boat dock on the Elwynn Forest bank of the Nazferiti river. The Defias Brotherhood holds it, and the Dockmaster and his men use it to smuggle stolen goods from the Redridge Mountains to Klaven's Tower in Westfall.",
			source = "https://warcraft.wiki.gg/wiki/Jerod's_Landing",
		},
		["maclure vineyards"] = {
			name = "Maclure Vineyards",
			short = "The Maclure Vineyards lie in southern Elwynn Forest, tended by the Maclure family across long rows of vine and soil.",
			full = "The Maclure Vineyards lie in southern Elwynn Forest, tended by the Maclure family across long rows of vine and soil. The Maclures hold a bitter rivalry with the neighboring Stonefield family, trading dislike as freely as they trade nothing else. Yet a child of the Maclures and a child of the Stonefields have fallen for one another, in defiance of everything their families stand for, and some hope such a love might mend what generations of bad blood could not.",
			source = "https://warcraft.wiki.gg/wiki/Maclure_Vineyards",
		},
		["mirror lake"] = {
			name = "Mirror Lake",
			short = "Mirror Lake lies small and quiet in western Elwynn Forest, its waterfall spilling bright beside a nearby orchard, the kind of place that looks made for swimming or fishing.",
			full = "Mirror Lake lies small and quiet in western Elwynn Forest, its waterfall spilling bright beside a nearby orchard, the kind of place that looks made for swimming or fishing. It is not so simple anymore. Defias bandits have taken to the woods around it, and what should be a place of rest has become one to cross carefully.",
			source = "https://warcraft.wiki.gg/wiki/Mirror_Lake",
		},
		["mirror lake orchard"] = {
			name = "Mirror Lake Orchard",
			short = "Mirror Lake Orchard lies on the southern banks of Mirror Lake, its rows of trees and a lone cottage standing among the fields of western Elwynn Forest.",
			full = "Mirror Lake Orchard lies on the southern banks of Mirror Lake, its rows of trees and a lone cottage standing among the fields of western Elwynn Forest. Defias bandits once held the orchard and the cottage beside it, using the place as their own, and whether the orchard's true owners were driven off by them, no one can say for certain.",
			source = "https://warcraft.wiki.gg/wiki/Mirror_Lake_Orchard",
		},
		["northshire abbey"] = {
			name = "Northshire Abbey",
			short = "Northshire Abbey rests in the valley that bears its name, in the foothills of Elwynn Forest, its main hall, hall of arms, and library wing standing where clerics from the Church of the Holy Light first settled after venturing south from Lordaeron.",
			full = "Northshire Abbey rests in the valley that bears its name, in the foothills of Elwynn Forest, its main hall, hall of arms, and library wing standing where clerics from the Church of the Holy Light first settled after venturing south from Lordaeron. From here the Holy Order of Northshire Clerics gave Stormwind its comfort and its wisdom, and it was within these walls that Medivh, the Guardian of Tirisfal, was tended through the long years of his coma.\n\nThe abbey did not survive the First War unscathed. Its Abbot lent the Clerics of Northshire to Stormwind's defense, and not long after the half-orc Garona was brought here as a captive, the orcs overran Northshire and burned it to ruin. Refugees fled toward Lordaeron, but not before pulling sacred tomes from the wreckage, texts that would later teach the mages of Dalaran the art of invisibility.\n\nThe ruined grounds did not stay empty. Cho'gall's Twilight's Hammer clan made the site its headquarters during the Second War, until the Alliance retook Elwynn Forest and Archbishop Alonsus Faol rebuilt the abbey stone by stone, founding the Brotherhood of Northshire in its halls.",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Abbey",
		},
		["northshire valley"] = {
			name = "Northshire Valley",
			short = "Northshire Valley lies closed in on every side but one, its mountains impenetrable, its only pass to the south sealed behind thick stone walls and a watched gate.",
			full = "Northshire Valley lies closed in on every side but one, its mountains impenetrable, its only pass to the south sealed behind thick stone walls and a watched gate. A river cuts through the quiet of it, winding down toward Crystal Lake, past the abbey and the vineyard rows that give the place its air of peace.\n\nThat peace was not always so certain. During the Second War, Northshire Abbey stood as the headquarters of Cho'gall's Twilight's Hammer clan, sworn to Gul'dan's cause, and its walls sheltered orcish war-councils rather than novices and farmers.\n\nNow Marshal McBride commands the abbey's garrison and answers for the whole of Northshire's safety, though the valley is not wholly settled even under his watch. Wolves press in from Duskwood in numbers no one can account for, kobolds burrow through Echo Ridge Mine.",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Valley",
		},
		["northshire valley camelot"] = {
			pending = true,
			name = "Northshire Valley - Camelot",
			short = "",
			full = "",
			source = "",
		},
		["northshire vineyards"] = {
			name = "Northshire Vineyards",
			short = "The vineyards stretch out east of the abbey, once tended for their harvest before the Defias Brotherhood claimed the land.",
			full = "The vineyards stretch out east of the abbey, once tended for their harvest before the Defias Brotherhood claimed the land. Garrick Padfoot led the agents who held it, using the rows as a foothold for the Brotherhood's minions, who took the stolen property of Milly Osworth with them.",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Vineyards",
		},
		["ridgepoint tower"] = {
			name = "Ridgepoint Tower",
			short = "Ridgepoint Tower watches the border of Elwynn Forest, one of the Stormwind Guard's scout towers.",
			full = "Ridgepoint Tower watches the border of Elwynn Forest, one of the Stormwind Guard's scout towers. Its sentries turn their eyes toward Redridge, where gnolls and orcs gather, toward Duskwood, where the dead do not stay buried, and toward the nearby Defias camps. The garrison holds well defended against all three.",
			source = "https://warcraft.wiki.gg/wiki/Ridgepoint_Tower",
		},
		["stone cairn lake"] = {
			name = "Stone Cairn Lake",
			short = "Stone Cairn Lake takes its name from Heroes' Vigil, the cairn raised on the island at its heart to remember the dead of the First War against the orcs, when so many fell that no single grave could hold their memory.",
			full = "Stone Cairn Lake takes its name from Heroes' Vigil, the cairn raised on the island at its heart to remember the dead of the First War against the orcs, when so many fell that no single grave could hold their memory. It was once a place of quiet pilgrimage.\n\nThat peace is gone. Rogue Wizards have taken the island, and the cairn meant for mourning now stands behind them. Along the southern banks, a tribe of murlocs has raised its own crude dwellings, indifferent to the monument across the water.",
			source = "https://warcraft.wiki.gg/wiki/Stone_Cairn_Lake",
		},
		["stonefield farm"] = {
			name = "Stonefield Farm",
			short = "Stonefield Farm lies in southern Elwynn Forest, worked by the Stonefield family, who share a bitter rivalry with the nearby Maclures.",
			full = "Stonefield Farm lies in southern Elwynn Forest, worked by the Stonefield family, who share a bitter rivalry with the nearby Maclures. Yet a child of each house has fallen in love, defying the old grudge between their families. Some hope that romance might succeed where years of quarreling never could, and mend what the feud has broken.",
			source = "https://warcraft.wiki.gg/wiki/Stonefield_Farm",
		},
		["thunder falls"] = {
			name = "Thunder Falls",
			short = "The path up from Mirror Lake's waterfall climbs steep and narrow into the mountains before opening onto Thunder Falls, a ravine unlike others in Elwynn Forest for having falling water at both ends.",
			full = "The path up from Mirror Lake's waterfall climbs steep and narrow into the mountains before opening onto Thunder Falls, a ravine unlike others in Elwynn Forest for having falling water at both ends. A third waterfall tumbles down from the northern cliffs, feeding the ravine from above. Below the rise stands a small rural cottage, its anvil and fire kept lit, with a little pier and boat resting on the river beside the house. Bandits linger near the cottage. The river spills onward through a second waterfall near the edge of Westfall. The violet perch that swim in these waters are said to be found nowhere as readily as here.",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Falls",
		},
		["tower of azora"] = {
			name = "Tower of Azora",
			short = "The Tower of Azora rises amid the fields of central Elwynn Forest, home to a company of gnomish servants who answer to the Archmage Theocritus.",
			full = "The Tower of Azora rises amid the fields of central Elwynn Forest, home to a company of gnomish servants who answer to the Archmage Theocritus.\n\nFar off in the Redridge Mountains stands its rival, the Tower of Ilgalar, ruled by the sorcerer Morganth. The two towers have never made war outright, but they watch each other constantly through magical means, each waiting to catch the other in some misstep.\n\nThe tower's own magic spills into the fields around it, and anything that lingers too near is liable to be touched by it, turned into something stranger than it was. The servants tend their tower against this small, constant trouble, one eye always turned toward Redridge.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Azora",
		},
		["westbrook garrison"] = {
			name = "Westbrook Garrison",
			short = "Westbrook Garrison stands at the western edge of Elwynn Forest, where the trees give way to the poorer country of Westfall, and it has always been a lonely posting for the Stormwind Guard.",
			full = "Westbrook Garrison stands at the western edge of Elwynn Forest, where the trees give way to the poorer country of Westfall, and it has always been a lonely posting for the Stormwind Guard.\n\nIts hardest years came while Lady Katrana Prestor's corruption sat heavy over the kingdom and the bulk of the Stormwind Army was committed elsewhere. With too few soldiers to spare, gnolls and thieves out of Westfall pressed harder on the woods each season, and the garrison barely kept the roads safe.\n\nAmong the gnolls, the Riverpaw chieftain Hogger became a name of dread. He overpowered every attempt made to capture him, and wanted postings still hang at the garrison gate naming him, unfulfilled.",
			source = "https://warcraft.wiki.gg/wiki/Westbrook_Garrison",
		},
	},
	-- Deadwind Pass: 9 subzones
	[1430] = {
		["aridens camp"] = {
			name = "Ariden's Camp",
			short = "The camp lies abandoned north of the road through Deadwind Pass, a scatter of cold fire pits and empty bedrolls beneath the ever-dark trees.",
			full = "The camp lies abandoned north of the road through Deadwind Pass, a scatter of cold fire pits and empty bedrolls beneath the ever-dark trees. Ariden once led the Dark Riders from this ground, setting up camp here before he was cursed, and from it he tried to sell off fake artifacts he claimed had belonged to Medivh. Nothing remains now but the campsite itself.",
			source = "https://warcraft.wiki.gg/wiki/Ariden's_Camp",
		},
		["deadmans crossing"] = {
			name = "Deadman's Crossing",
			short = "A hangman's tree stands at the crossing, a pair of corpses still swinging from its branches. Beside it a signpost bears two warnings: \"Turn Back!\" and \"Abandon hope, all ye who enter here.\"",
			full = "A hangman's tree stands at the crossing, a pair of corpses still swinging from its branches. Beside it a signpost bears two warnings: \"Turn Back!\" and \"Abandon hope, all ye who enter here.\"\n\nHere the road west leads toward Duskwood, the road east toward the Swamp of Sorrows, and the road south into Deadwind Pass, where Karazhan stands. The gallows and the warning were raised for anyone tempted to stray from the crossing into the pass beyond.",
			source = "https://warcraft.wiki.gg/wiki/Deadman's_Crossing",
		},
		["deadwind ravine"] = {
			name = "Deadwind Ravine",
			short = "The ravine cuts a craggy cleft through the mountains, its western road running along the upper level toward Karazhan, the tower's silhouette waiting ominous at the far end.",
			full = "The ravine cuts a craggy cleft through the mountains, its western road running along the upper level toward Karazhan, the tower's silhouette waiting ominous at the far end. At the ravine's end lies the southern bridge, the last crossing before the tower itself.",
			source = "https://warcraft.wiki.gg/wiki/Deadwind_Ravine",
		},
		["groshgok compound"] = {
			name = "Grosh'gok Compound",
			short = "The Deadwind ogres claim the Grosh'gok Compound as their own, a mound of earth and stone raised in the Vice.",
			full = "The Deadwind ogres claim the Grosh'gok Compound as their own, a mound of earth and stone raised in the Vice. Of the caves that pit that stretch of land, this one lies furthest south, and none of the others match it for size.",
			source = "https://warcraft.wiki.gg/wiki/Grosh'gok_Compound",
		},
		["karazhan"] = {
			name = "Karazhan",
			short = "Karazhan stands abandoned in southern Deadwind Pass, built upon a nexus of ley lines. The tower is best known for its last occupant, Medivh, last Guardian of Tirisfal.",
			full = "Karazhan stands abandoned in southern Deadwind Pass, built upon a nexus of ley lines. The tower is best known for its last occupant, Medivh, last Guardian of Tirisfal. After Medivh was slain by Khadgar, Anduin Lothar, and Garona, the tower sealed itself off from the world. But recently Karazhan has stirred again -- an evil presence has taken it for its own, its halls crawling with spirits and demons, and the Shade of Medivh still lingers, his power so great that his magic echoes through the tower yet.\n\nIt is impossible to set eyes upon Karazhan without reflecting on the dark saga of its master. As befitting his title, the Last Guardian of Tirisfal had amassed a vast collection of writings and artifacts, dwarfing even that of the Kirin Tor. The tower is vast and dangerous, its halls thick with ghosts.",
			source = "https://warcraft.wiki.gg/wiki/Karazhan",
		},
		["masters cellar"] = {
			name = "Master's Cellar",
			short = "Beneath the ruined village south of Karazhan, where servants of the tower once kept their homes, the ground opens into cellars that no longer belong to the living.",
			full = "Beneath the ruined village south of Karazhan, where servants of the tower once kept their homes, the ground opens into cellars that no longer belong to the living. Two entrances lead down. One opens onto a vast wine cellar, its racks and barrels long abandoned to the dead. The other drops into a second cellar whose floor has given way entirely, collapsing into a cave system that runs deep underground.\n\nBoth are thick with the restless: unliving caretakers who still seem to tend a house with no master, damned souls, shades that will not settle, spectres whose wailing carries up through the broken stone. Whatever service bound them to Karazhan in life has curdled into something that will not let them leave in death.\n\nOnly the wine cellar holds anything singled out among the dead. The lower cave system, silent and drowned in dark, keeps nothing but more of the same restless dead, nothing named, nothing that anyone thought worth remembering.",
			source = "https://warcraft.wiki.gg/wiki/Master's_Cellar",
		},
		["morgans plot"] = {
			name = "Morgan's Plot",
			short = "A small, decrepit church stands behind Karazhan, its graveyard and crypt sunk into the gloom of Deadwind Pass.",
			full = "A small, decrepit church stands behind Karazhan, its graveyard and crypt sunk into the gloom of Deadwind Pass. The chapel has long housed things that do not rest easily, and something else still patrols the hill just below.\n\nThat a place meant for the dead should so often fail to keep them says something about what lies behind it.",
			source = "https://warcraft.wiki.gg/wiki/Morgan's_Plot",
		},
		["sleeping gorge"] = {
			name = "Sleeping Gorge",
			short = "The Sleeping Gorge cuts through the eastern reaches of Deadwind Pass, a small chasm that travelers on the southern approach to Karazhan must pass through before the path turns east into the Vice.",
			full = "The Sleeping Gorge cuts through the eastern reaches of Deadwind Pass, a small chasm that travelers on the southern approach to Karazhan must pass through before the path turns east into the Vice.",
			source = "https://warcraft.wiki.gg/wiki/Sleeping_Gorge",
		},
		["vice"] = {
			name = "Vice",
			short = "The Vice lies along the southern stretch of the road to Karazhan, where the Deadwind ogres have raised their mounds and camps among the crags.",
			full = "The Vice lies along the southern stretch of the road to Karazhan, where the Deadwind ogres have raised their mounds and camps among the crags. It is a desolate stretch of ground, home to little else but restless spirits and the vultures that circle over them. Why the ogres chose to root themselves here, in a place so empty and ill-favored, is not known to anyone who has looked upon it.",
			source = "https://warcraft.wiki.gg/wiki/Vice",
		},
	},
	-- Duskwood: 17 subzones
	[1431] = {
		["addles stead"] = {
			name = "Addle's Stead",
			short = "Addle's Stead lies abandoned among the fields of southwestern Duskwood, one of many farmsteads left to rot when darkness crept over the land.",
			full = "Addle's Stead lies abandoned among the fields of southwestern Duskwood, one of many farmsteads left to rot when darkness crept over the land. The barn stands empty, the farmhouse silent, and only Forlorn Spirits linger now, said to be the shades of dead Defias Brotherhood who once claimed the place.\n\nThe Defias took Addle's Stead entirely, creeping through the overgrown field, hiding in the barn, stalking the farmhouse rooms.",
			source = "https://warcraft.wiki.gg/wiki/Addle's_Stead",
		},
		["beggars haunt"] = {
			name = "Beggar's Haunt",
			short = "The tower called Beggar's Haunt stands abandoned above the road into Deadwind Pass, northeast of Manor Mistmantle.",
			full = "The tower called Beggar's Haunt stands abandoned above the road into Deadwind Pass, northeast of Manor Mistmantle. Raised as a scout post for the Stormwind Guard, it now serves the Forsaken, whose Deathstalker Zraedus and Apothecary Faustin work experiments within its walls.\n\nA path winds down to a small pool fed by a waterfall, where an unmarked grave rests beneath two great statues carved like those at the Dark Portal. Near the tower lies another small cemetery, holding the grave of an Unknown Soldier.",
			source = "https://warcraft.wiki.gg/wiki/Beggar's_Haunt",
		},
		["brightwood grove"] = {
			name = "Brightwood Grove",
			short = "Brightwood Grove lies just west of Darkshire, its few buildings long since fallen to ruin.",
			full = "Brightwood Grove lies just west of Darkshire, its few buildings long since fallen to ruin. What remains of the place belongs now to the Nightbane worgen, who prowl the dark fields in packs, raising crude camps among the wreckage and falling upon anyone who wanders too close.",
			source = "https://warcraft.wiki.gg/wiki/Brightwood_Grove",
		},
		["darkened bank"] = {
			name = "Darkened Bank",
			short = "The Darkened Bank runs along the northern shore of Duskwood, from the western edge of the land east to the bridge joining it to Redridge.",
			full = "The Darkened Bank runs along the northern shore of Duskwood, from the western edge of the land east to the bridge joining it to Redridge. At its western end stands a small camp where the refugees Sven Yorgen and Lars have taken shelter, driven to the water's edge by whatever has made the rest of Duskwood too dangerous to hold.",
			source = "https://warcraft.wiki.gg/wiki/Darkened_Bank",
		},
		["darkshire"] = {
			name = "Darkshire",
			short = "Darkshire was not always so named. It rose long ago as Grand Hamlet, a small woodland town built up as Stormwind's people spread into the nearby lands.",
			full = "Darkshire was not always so named. It rose long ago as Grand Hamlet, a small woodland town built up as Stormwind's people spread into the nearby lands. But the land itself never recovered from what happened at Karazhan. When the Guardian Medivh was slain in his tower there, the fel energy loosed by his death crept into the surrounding forest, twisting it into the thorned, lightless place it remains. Brightwood became Duskwood, and Grand Hamlet took the truer name of Darkshire.\n\nThe town's militia, the Night Watch, exists because Stormwind abandoned it. When Lady Katrana Prestor's schemes in Stormwind emptied the kingdom's garrisons from the forest, the townsfolk armed themselves rather than wait for soldiers who were never coming. Formed and trained entirely by the people of the forest, they have since held the roads against wolves, walking corpses, and worse, with no army left to call upon but themselves.",
			source = "https://warcraft.wiki.gg/wiki/Darkshire",
		},
		["dawning wood catacombs"] = {
			name = "Dawning Wood Catacombs",
			short = "Beneath Raven Hill Cemetery, the earth opens into the Dawning Wood Catacombs, a warren of tunnels twisting deep enough that few who enter alone come out again.",
			full = "Beneath Raven Hill Cemetery, the earth opens into the Dawning Wood Catacombs, a warren of tunnels twisting deep enough that few who enter alone come out again. Two ways lead down. The eastern passage opens into a den of ghouls, diseased and ferocious. The western passage opens into a hall of skeletons, standing sentinel over the tombs of the dead they once were.",
			source = "https://warcraft.wiki.gg/wiki/Dawning_Wood_Catacombs",
		},
		["forlorn rowe"] = {
			name = "Forlorn Rowe",
			short = "A hill on the northern edge of Raven Hill Cemetery, the Forlorn Rowe lies wrapped in a darkness that clings closer than the shadow of the surrounding trees.",
			full = "A hill on the northern edge of Raven Hill Cemetery, the Forlorn Rowe lies wrapped in a darkness that clings closer than the shadow of the surrounding trees. Here stands the home of Morbent Fel, a necromancer who bends the forest's undead to his will through evil arcane magic. Only a single weapon of great power could hope to still him.",
			source = "https://warcraft.wiki.gg/wiki/Forlorn_Rowe",
		},
		["hushed bank"] = {
			name = "Hushed Bank",
			short = "The Hushed Bank runs along the western river of Duskwood, from where Westfall, Elwynn Forest, and Duskwood meet, south toward Stranglethorn Vale.",
			full = "The Hushed Bank runs along the western river of Duskwood, from where Westfall, Elwynn Forest, and Duskwood meet, south toward Stranglethorn Vale. A covered bridge crosses the river here, joining Duskwood to Westfall.\n\nAt the northern corner of the bank, the brothers Lars and Sven Yorgen keep a camp.\n\nWolves and spiders range the bank among the trees.",
			source = "https://warcraft.wiki.gg/wiki/Hushed_Bank",
		},
		["manor mistmantle"] = {
			name = "Manor Mistmantle",
			short = "Manor Mistmantle stands in northeastern Duskwood, its grounds rotten, its gardens gone to ruin.",
			full = "Manor Mistmantle stands in northeastern Duskwood, its grounds rotten, its gardens gone to ruin. It was once the home of Stalvan Mistmantle, a schoolteacher and tutor who became an agent of the undead, leaving ghouls to shamble through the property in his place. Amid the corruption, one thing still grows: a single flower called the Tear of Tilloa, the only sign of life left in a garden otherwise given over to rot.",
			source = "https://warcraft.wiki.gg/wiki/Manor_Mistmantle",
		},
		["raven hill"] = {
			name = "Raven Hill",
			short = "The houses of Raven Hill stand empty in western Duskwood, given up to rot and dark. A few souls held on regardless: Jitters, and Bliztik, a goblin who kept out of sight on an upper floor.",
			full = "The houses of Raven Hill stand empty in western Duskwood, given up to rot and dark. A few souls held on regardless: Jitters, and Bliztik, a goblin who kept out of sight on an upper floor.\n\nThe town is haunted by the Unseen, unseen in more than name, moving through its empty rooms.",
			source = "https://warcraft.wiki.gg/wiki/Raven_Hill",
		},
		["raven hill cemetery"] = {
			name = "Raven Hill Cemetery",
			short = "Raven Hill Cemetery sprawls north of the town it takes its name from, grown far beyond its old bounds since the corruption of Duskwood took hold.",
			full = "Raven Hill Cemetery sprawls north of the town it takes its name from, grown far beyond its old bounds since the corruption of Duskwood took hold. Undead now walk among the stones, and massive spiders and gangs of grave robbers work over the graves undisturbed, driving off anyone who stumbles into their business.\n\nIn the cemetery's northwest corner stands Forlorn Rowe, home of the necromancer Morbent Fel, whose dark work stirs the dead of the cemetery.\n\nThat name, Ladimore, marks the cemetery's oldest grief. Morgan Ladimore returned from the Third War to find his wife and children already buried here. Grief broke him; he murdered three of the cemetery's attendants over their graves. Now the undead Mor'Ladim patrols the grounds, and death comes swiftly and unseen to anyone he finds unwary among the headstones.",
			source = "https://warcraft.wiki.gg/wiki/Raven_Hill_Cemetery",
		},
		["rolands doom"] = {
			name = "Roland's Doom",
			short = "Roland's Doom is a mine in southeastern Duskwood, east of the Rotting Orchard.",
			full = "Roland's Doom is a mine in southeastern Duskwood, east of the Rotting Orchard. The night elven priestess Velinde Starsong carried the Scythe of Elune into these hills before she vanished, and the relic was lost in the mine. The man Jitters found it there, and its finding drew more worgen down upon Duskwood and Darkshire.\n\nThe mine now belongs to Gutspill and Nefaru of the Nightbane pack, whose worgen range as far as the Rotting Orchard.",
			source = "https://warcraft.wiki.gg/wiki/Roland's_Doom",
		},
		["rotting orchard"] = {
			name = "Rotting Orchard",
			short = "The orchard lies in southern Duskwood, its trees gone black with rot, its buildings fallen to ruin between the Yorgen Farmstead and the Tranquil Gardens Cemetery.",
			full = "The orchard lies in southern Duskwood, its trees gone black with rot, its buildings fallen to ruin between the Yorgen Farmstead and the Tranquil Gardens Cemetery.\n\nThe worgen of the Nightbane pack have made it theirs. Shadow Weavers work their magic amid the ruined buildings while Stalkers wait unseen in the dark between the trees.\n\nTo stand here now is to stand in a place that has stopped being a farm and become a hunting ground.",
			source = "https://warcraft.wiki.gg/wiki/Rotting_Orchard",
		},
		["tranquil gardens cemetery"] = {
			name = "Tranquil Gardens Cemetery",
			short = "The Tranquil Gardens Cemetery lies southeast of Darkshire, its name now a bitter joke.",
			full = "The Tranquil Gardens Cemetery lies southeast of Darkshire, its name now a bitter joke. The dead here do not rest, though they are weaker than the undead found elsewhere in Duskwood, wandering among the headstones and the ruined church at the graveyard's heart. The Insane Ghoul haunts this ground, sometimes within the broken church, sometimes among the graves. Just north stands Blind Mary's house.",
			source = "https://warcraft.wiki.gg/wiki/Tranquil_Gardens_Cemetery",
		},
		["twilight grove"] = {
			name = "Twilight Grove",
			short = "A great tree stands unnamed at the heart of the Twilight Grove, deep in Duskwood, beside a moonwell and an old night elf gazebo.",
			full = "A great tree stands unnamed at the heart of the Twilight Grove, deep in Duskwood, beside a moonwell and an old night elf gazebo. Beneath its boughs lies one of only four portals into the Emerald Dream, sister to those hidden in Feralas, the Hinterlands, and Ashenvale.\n\nThe grove's portal did not go unguarded. Four great dragons, once proud lieutenants of Ysera, Aspect of Dreams, kept watch here as her chosen protectors of the Dream. But the Emerald Nightmare corrupted them in turn, twisting guardians into destroyers who wanted nothing but death, and it fell to Alliance and Horde alike to take up arms against the very dragons who had once stood sentinel over this place.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Grove",
		},
		["vulgol ogre mound"] = {
			name = "Vul'Gol Ogre Mound",
			short = "Southern Duskwood dips into a small basin where the road splits toward Stranglethorn Vale, and where farmhouses once stood before the ogres came.",
			full = "Southern Duskwood dips into a small basin where the road splits toward Stranglethorn Vale, and where farmhouses once stood before the ogres came. The Splinter Fist ogres hold it now, and it takes its name from their leader, Zzarc'Vul, who rules the mound from within it.\n\nThe ruined farmhouses are the only sign that people lived here before the ogres took the basin for their own. Whatever became of those families, the ogres left nothing behind but broken walls.\n\nThe Night Watch does not spare its own for this place, judging the threat here less urgent than others pressing on Duskwood, and so it has been left to outsiders to thin the ogres' numbers when needed. Among the ogres' plunder was a crate of tools and herbs stolen from the necromancer Abercrombie, carried off into the mound after they overran him. And Zzarc'Vul himself wears a monocle that a researcher once coveted for his own studies, a small vanity on a brutal creature.",
			source = "https://warcraft.wiki.gg/wiki/Vul'Gol_Ogre_Mound",
		},
		["yorgen farmstead"] = {
			name = "Yorgen Farmstead",
			short = "The Yorgen Farmstead lies abandoned in southern Duskwood, its fields gone to rot. Sven Yorgen once worked this land, but now keeps to a small camp on the Darkened Bank.",
			full = "The Yorgen Farmstead lies abandoned in southern Duskwood, its fields gone to rot. Sven Yorgen once worked this land, but now keeps to a small camp on the Darkened Bank. The farmstead itself has since fallen into the hands of the Defias Brotherhood, whose assassins move through the fields unseen, striking only when it is too late.",
			source = "https://warcraft.wiki.gg/wiki/Yorgen_Farmstead",
		},
	},
	-- Loch Modan: 16 subzones
	[1432] = {
		["algaz station"] = {
			name = "Algaz Station",
			short = "Algaz Station stands east of the North Gate Pass, taking its name from Dun Algaz to the north.",
			full = "Algaz Station stands east of the North Gate Pass, taking its name from Dun Algaz to the north. Here dwarven mountaineers keep their watch, with Mountaineer Stormpike among them, and the armorer Gothor Brumn tends to their gear.",
			source = "https://warcraft.wiki.gg/wiki/Algaz_Station",
		},
		["dun algaz"] = {
			name = "Dun Algaz",
			short = "The tunnel through Dun Algaz is older than the quarrel that split the dwarves. When the War of the Three Hammers drove the Wildhammers from Ironforge, it was through this pass that they made their retreat.",
			full = "The tunnel through Dun Algaz is older than the quarrel that split the dwarves. When the War of the Three Hammers drove the Wildhammers from Ironforge, it was through this pass that they made their retreat.\n\nIt carried the Horde's retreat as well. Beaten back from Dun Modr, the orcs fell south across the Thandol Valley and dug in at the outpost here, and Anduin Lothar, wanting them pushed clear out of Khaz Modan, sent his forces to tear the stronghold down. The assault failed. The orcs held on, and Dun Algaz became the last ground the Horde kept in the region, a foothold that would not be pried loose.\n\nThe dwarven mountaineers who watched this pass kept mostly to the hills above it, but the Dragonmaw clan overran their post and drove them back to the upper tunnel, where they hold on still. With the lower pass lost, the road between the dwarven homelands and Menethil Harbor has grown far more dangerous.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Algaz",
		},
		["farstrider lodge"] = {
			name = "Farstrider Lodge",
			short = "Farstrider Lodge stands in southeastern Loch Modan, its architecture unmistakably high elven, though only one of that race remains within its halls.",
			full = "Farstrider Lodge stands in southeastern Loch Modan, its architecture unmistakably high elven, though only one of that race remains within its halls. Humans and dwarves have since taken up residence there, hunters among them, living within walls raised by hands long since departed from this place.",
			source = "https://warcraft.wiki.gg/wiki/Farstrider_Lodge",
		},
		["grizzlepaw ridge"] = {
			name = "Grizzlepaw Ridge",
			short = "Grizzlepaw Ridge rises south of Thelsamar, thick with bears that have made the heights their own.",
			full = "Grizzlepaw Ridge rises south of Thelsamar, thick with bears that have made the heights their own. Chief among them is Ol' Sooty, a bear of fearsome size and temper, who wanders down from his lair to the base of the valley, quick to pounce upon anyone unfortunate enough to irritate him.\n\nGorick Guzzledraught keeps to the ridge as well.",
			source = "https://warcraft.wiki.gg/wiki/Grizzlepaw_Ridge",
		},
		["ironbands excavation site"] = {
			name = "Ironband's Excavation Site",
			short = "Ironband's Excavation Site, in southeastern Loch Modan, is a dwarven digsite opened by Prospector Ironband in search of what the ancients had buried.",
			full = "Ironband's Excavation Site, in southeastern Loch Modan, is a dwarven digsite opened by Prospector Ironband in search of what the ancients had buried. But the earth gave up more than relics: troggs, larger and more volatile than those found at the other dwarven digs, rose from below and overran the site, driving off the prospectors and miners who had opened it.",
			source = "https://warcraft.wiki.gg/wiki/Ironband's_Excavation_Site",
		},
		["loch"] = {
			name = "The Loch",
			short = "The Loch fills the heart of Loch Modan, the largest body of water on all of Khaz Modan, and third in size across the known world, behind only Lordamere and Darrowmere.",
			full = "The Loch fills the heart of Loch Modan, the largest body of water on all of Khaz Modan, and third in size across the known world, behind only Lordamere and Darrowmere.",
			source = "https://warcraft.wiki.gg/wiki/The_Loch",
		},
		["mogrosh stronghold"] = {
			name = "Mo'grosh Stronghold",
			short = "The caves of Mo'grosh Stronghold lie in northeastern Loch Modan, home to a tribe of ogres, their darkmaulers and earthbenders answering to no one but their own.",
			full = "The caves of Mo'grosh Stronghold lie in northeastern Loch Modan, home to a tribe of ogres, their darkmaulers and earthbenders answering to no one but their own.",
			source = "https://warcraft.wiki.gg/wiki/Mo'grosh_Stronghold",
		},
		["north gate pass"] = {
			name = "North Gate Pass",
			short = "The pass cuts through the high mountains, dropping from Dun Morogh down toward Loch Modan.",
			full = "The pass cuts through the high mountains, dropping from Dun Morogh down toward Loch Modan. It is the shortest road between the two, and travelers bound for the lands beyond the Loch pass through here more than any other way.\n\nThe North Gate Outpost stands guard here, holding the passage.",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Pass",
		},
		["silver stream mine"] = {
			name = "Silver Stream Mine",
			short = "The Silver Stream Mine once ran deep with silver, and for generations the dwarves of Ironforge drew wealth from its veins.",
			full = "The Silver Stream Mine once ran deep with silver, and for generations the dwarves of Ironforge drew wealth from its veins. When the ore ran dry, the Miners' League turned the tunnels into a storage depot rather than abandon them.\n\nThe mine still holds one thing worth taking: Charged Rift Gems, found nowhere else, prized for the making of mage robes.\n\nBut the dwarves no longer hold these tunnels. Tunnel Rat kobolds have overrun the mine, seeking its remaining resources for themselves.",
			source = "https://warcraft.wiki.gg/wiki/Silver_Stream_Mine",
		},
		["south gate pass"] = {
			name = "South Gate Pass",
			short = "South Gate Pass cuts through the mountains, joining the high snows of Dun Morogh to the lower valleys of Loch Modan. It is the shortest way down to Thelsamar, worn by travelers between the two lands.",
			full = "South Gate Pass cuts through the mountains, joining the high snows of Dun Morogh to the lower valleys of Loch Modan. It is the shortest way down to Thelsamar, worn by travelers between the two lands.\n\nHere stands South Gate Outpost, a guard station set to watch the pass.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Pass",
		},
		["stonesplinter valley"] = {
			name = "Stonesplinter Valley",
			short = "Stonesplinter Valley cuts among the mountains of southwestern Loch Modan. Once pristine, it now belongs to the Stonesplinter troggs, who have overrun its floor and slopes.",
			full = "Stonesplinter Valley cuts among the mountains of southwestern Loch Modan. Once pristine, it now belongs to the Stonesplinter troggs, who have overrun its floor and slopes. The dwarves of Loch Modan count them as vermin to be culled. Deepest in the valley dwells Grawmug, the leader the troggs rally behind.",
			source = "https://warcraft.wiki.gg/wiki/Stonesplinter_Valley",
		},
		["stonewrought dam"] = {
			name = "Stonewrought Dam",
			short = "The Stonewrought Dam rises east of Dun Algaz pass, along the northern edge of Loch Modan.",
			full = "The Stonewrought Dam rises east of Dun Algaz pass, along the northern edge of Loch Modan.\n\nIts builder was a Dark Iron dwarf. Franclorn Forgewright, architect of that clan, devised the stonewrought method by which the dam was raised, though few who cross it know a Dark Iron hand built it.\n\nThe dam holds back the Loch, swelling it to more than twice its former size, and the flooding it caused made the wetlands beyond it, ground once mostly underwater.\n\nThe Dark Iron clan struck at the dam, and Ironforge answered by tightening its watch. Chief Engineer Hinderweir VII now holds that charge.",
			source = "https://warcraft.wiki.gg/wiki/Stonewrought_Dam",
		},
		["stoutlager inn"] = {
			name = "Stoutlager Inn",
			short = "The Stoutlager Inn stands in Thelsamar, its hearth rarely cold. Dwarves and travelers alike gather here to drink and trade word of the Loch, and few places in the region draw so steady a crowd through the door.",
			full = "The Stoutlager Inn stands in Thelsamar, its hearth rarely cold. Dwarves and travelers alike gather here to drink and trade word of the Loch, and few places in the region draw so steady a crowd through the door.",
			source = "https://warcraft.wiki.gg/wiki/Stoutlager_Inn",
		},
		["thelsamar"] = {
			name = "Thelsamar",
			short = "Thelsamar sits on the western shore of Loch Modan, north of Grizzlepaw Ridge and northeast of Stonesplinter Valley. A road runs just west of town, climbing through the passes toward Dun Morogh and the Wetlands.",
			full = "Thelsamar sits on the western shore of Loch Modan, north of Grizzlepaw Ridge and northeast of Stonesplinter Valley. A road runs just west of town, climbing through the passes toward Dun Morogh and the Wetlands. Gryphons nest at its roost, and its inn shelters travelers crossing the high country.",
			source = "https://warcraft.wiki.gg/wiki/Thelsamar",
		},
		["valley of kings"] = {
			name = "Valley of Kings",
			short = "The Valley of Kings lies in the southwestern reach of Loch Modan, where the green land narrows toward the gate leading down into the blackened Searing Gorge.",
			full = "The Valley of Kings lies in the southwestern reach of Loch Modan, where the green land narrows toward the gate leading down into the blackened Searing Gorge. That gate stands locked and watched, held under the eye of Mountaineer Pebblebitty, who yields passage only to those who prove themselves worthy of it.\n\nWhat draws the eye here are the two great statues that rise over the pass: Madoran Bronzebeard and Khardros Wildhammer, carved in stone to stand watch over the road south. When the two kings died, it was their sons who raised the statues together, binding Bronzebeard and Wildhammer in stone as their fathers had been bound in life. The southlands beyond had been turned to fire and ash by Ragnaros, and the statues face that ruin directly: a warning to any who would move against the dwarven kingdoms, and a reminder of the price the Dark Irons paid for what they had done.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Kings",
		},
	},
	-- Redridge Mountains: 16 subzones
	[1433] = {
		["althers mill"] = {
			name = "Alther's Mill",
			short = "The mill northeast of Lakeshire stands empty, its wheel long stilled. It was little more than a waypoint on the road to Stonewatch Keep, its ruins home to spiders, buzzards, and the odd stray orc.",
			full = "The mill northeast of Lakeshire stands empty, its wheel long stilled. It was little more than a waypoint on the road to Stonewatch Keep, its ruins home to spiders, buzzards, and the odd stray orc.",
			source = "https://warcraft.wiki.gg/wiki/Alther's_Mill",
		},
		["galardell valley"] = {
			name = "Galardell Valley",
			short = "The Galardell Valley, in the northeastern Redridge Mountains, swarms with gnolls under Lieutenant Fangore, whose howl calls the packs down on any who face him unprepared.",
			full = "The Galardell Valley, in the northeastern Redridge Mountains, swarms with gnolls under Lieutenant Fangore, whose howl calls the packs down on any who face him unprepared.\n\nAbove the valley stands the Tower of Ilgalar, dwelling place of the evil Morganth, whose name alone marks the place as one to fear.",
			source = "https://warcraft.wiki.gg/wiki/Galardell_Valley",
		},
		["lake everstill"] = {
			name = "Lake Everstill",
			short = "Lake Everstill lies at the heart of the Redridge Mountains, its waters wide and blue enough to give the sleepy town of Lakeshire its whole reason for being.",
			full = "Lake Everstill lies at the heart of the Redridge Mountains, its waters wide and blue enough to give the sleepy town of Lakeshire its whole reason for being. The lake drains eastward, its river running on toward the dark stones of Stonewatch Keep.\n\nIt was once a fisherman's lake, calm and dependable, but that has changed. Tribes of murlocs have overrun the shallows and depths alike, and somewhere in the deep water a thresher still patrols, old and vast enough that even seasoned hunters of the murloc tribes give it a wide berth. The Everstill Bridge still carries travelers across the water, above the murloc camps and the thing that watches from below.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Everstill",
		},
		["lakeridge highway"] = {
			name = "Lakeridge Highway",
			short = "Lakeridge Highway once carried steady traffic along the southern shore of Lake Everstill, before orcs seized Stonewatch Keep and the road fell out of use.",
			full = "Lakeridge Highway once carried steady traffic along the southern shore of Lake Everstill, before orcs seized Stonewatch Keep and the road fell out of use. Gnolls now range along most of its length, and camouflaged Blackrock hunters lie in wait further down. Travel along it is not something anyone would advise.",
			source = "https://warcraft.wiki.gg/wiki/Lakeridge_Highway",
		},
		["lakeshire"] = {
			name = "Lakeshire",
			short = "Lake Everstill lies still and cold beneath the Redridge peaks, and the town on its shore has bled for that ground more than once.",
			full = "Lake Everstill lies still and cold beneath the Redridge peaks, and the town on its shore has bled for that ground more than once. When Warchief Blackhand first led orcs into these mountains, Sir Anduin Lothar and the Knights of Stormwind ambushed them on the slopes and nearly broke them, until two Shadow Council warlocks turned the battle and forced Lothar back. Blackhand returned weeks later with a greater host and took Lakeshire outright. Only after the Second War did the Alliance of Lordaeron reclaim it, Supreme Commander Turalyon overseeing the return of its scattered people.",
			source = "https://warcraft.wiki.gg/wiki/Lakeshire",
		},
		["redridge canyons"] = {
			name = "Redridge Canyons",
			short = "The canyons cut through the northwestern reaches of Redridge, their walls hiding the den of Yowler, who leads the gnolls that hold this ground.",
			full = "The canyons cut through the northwestern reaches of Redridge, their walls hiding the den of Yowler, who leads the gnolls that hold this ground.",
			source = "https://warcraft.wiki.gg/wiki/Redridge_Canyons",
		},
		["renders camp"] = {
			name = "Render's Camp",
			short = "The Blackrock orcs hold a camp in the northwestern Redridge Mountains, close by the way into the Burning Steppes.",
			full = "The Blackrock orcs hold a camp in the northwestern Redridge Mountains, close by the way into the Burning Steppes. From here they keep watch over the pass, a foothold of the Blackrock clan pressed against the mountains that lead to their master's domain.",
			source = "https://warcraft.wiki.gg/wiki/Render's_Camp",
		},
		["renders rock"] = {
			name = "Render's Rock",
			short = "Render's Rock is a wide cave in the northwestern Redridge Mountains, near the Burning Steppes. Blackrock orcs hold it in force.",
			full = "Render's Rock is a wide cave in the northwestern Redridge Mountains, near the Burning Steppes. Blackrock orcs hold it in force.\n\nHere Corporal Keeshan lies wounded, cut off, needing to reach Lakeshire alive.",
			source = "https://warcraft.wiki.gg/wiki/Render's_Rock",
		},
		["renders valley"] = {
			name = "Render's Valley",
			short = "Render's Valley lies in the southeastern Redridge Mountains, a Blackrock orc outpost grown into a stronghold, ringed with towers and held by elite warriors.",
			full = "Render's Valley lies in the southeastern Redridge Mountains, a Blackrock orc outpost grown into a stronghold, ringed with towers and held by elite warriors.",
			source = "https://warcraft.wiki.gg/wiki/Render's_Valley",
		},
		["rethban caverns"] = {
			name = "Rethban Caverns",
			short = "The Rethban Caverns cut deep into the northwestern Redridge Mountains. Gnolls hold the tunnels, led by the cunning Ardo Dirtpaw, hoarding Rethban ore wrested from the stone.",
			full = "The Rethban Caverns cut deep into the northwestern Redridge Mountains. Gnolls hold the tunnels, led by the cunning Ardo Dirtpaw, hoarding Rethban ore wrested from the stone. The caverns may take their name from a man called Bart Rethban, though little else is remembered of him.",
			source = "https://warcraft.wiki.gg/wiki/Rethban_Caverns",
		},
		["stonewatch"] = {
			name = "Stonewatch",
			short = "Stonewatch once belonged to the humans of Lakeshire, a stronghold set against the cliffs where the falls cascade down below the keep, watching over Redridge against the orcish menace of the Burning Steppes.",
			full = "Stonewatch once belonged to the humans of Lakeshire, a stronghold set against the cliffs where the falls cascade down below the keep, watching over Redridge against the orcish menace of the Burning Steppes.\n\nThat watch was broken by betrayal. The warlock Morganth struck an alliance with Gath'Ilzogg and his Blackrock orcs, and together their combined force fell upon Stonewatch Keep with a savagery that broke the garrison. The orcs took the keep, but their triumph was short-lived in trust, for Morganth turned on the allies who had won it for him. He raised the Tower of Ilgalar for himself and bent a warband of Shadowhide gnolls, under Lieutenant Fangore, to his own purposes. Since that turning, both orc and man who cross the gnolls' path have paid for it.\n\nAbandoned by the warlock who had used them, the Blackrock orcs held the keep on their own, Gath'Ilzogg ruling it with his lieutenant Tharil'zun at his side.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch",
		},
		["stonewatch falls"] = {
			name = "Stonewatch Falls",
			short = "Below Stonewatch, the eastern river of Lake Everstill drops in a long fall down the hillside, gathering into a deep lake in the nook of the Redridge Mountains.",
			full = "Below Stonewatch, the eastern river of Lake Everstill drops in a long fall down the hillside, gathering into a deep lake in the nook of the Redridge Mountains. A small tribe of murlocs has settled its banks, fishing the water and raising crude shelters beneath the falls.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Falls",
		},
		["stonewatch keep"] = {
			name = "Stonewatch Keep",
			short = "Stonewatch Keep once belonged to the humans of Lakeshire, set to watch over Redridge.",
			full = "Stonewatch Keep once belonged to the humans of Lakeshire, set to watch over Redridge. It fell when the warlock Morganth struck an alliance with the Blackrock orc warlord Gath'Ilzogg, and together their combined forces threw themselves at the keep with a savagery fed by Morganth's dark magic. The defenders broke, and the keep was taken.\n\nThe alliance did not last. No sooner had Stonewatch fallen than Morganth turned on the orcs who had bled for it beside him. He raised the Tower of Ilgalar nearby and filled it with Shadowhide gnolls under Lieutenant Fangore, creatures bent to his will alone. Orc and man alike have since fallen to the brutes he set loose.\n\nAbandoned by their warlock ally, the Blackrock orcs held the keep on their own, Gath'Ilzogg and his lieutenant Tharil'zun ruling what remained of it. During the battle they had taken Corporal Keeshan of the Stormwind Army prisoner and dragged him off north to their camps. Magistrate Solomon set a bounty on Gath'Ilzogg's head for it, and Marshal Marris of Lakeshire swore Tharil'zun would answer for his crimes as well.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Keep",
		},
		["stonewatch tower"] = {
			name = "Stonewatch Tower",
			short = "Stonewatch Tower once stood beside Stonewatch Keep, both held by the humans of Lakeshire, until the Blackrock clan seized the stronghold.",
			full = "Stonewatch Tower once stood beside Stonewatch Keep, both held by the humans of Lakeshire, until the Blackrock clan seized the stronghold. The tower serves as a scout post under Gath'Ilzogg's underlings, orcs of the Blackrock clan watching over the stronghold their kin took from Lakeshire's men.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Tower",
		},
		["three corners"] = {
			name = "Three Corners",
			short = "At Three Corners the road forks three ways: west to Goldshire in Elwynn Forest, east to Lakeshire, south to Darkshire in Duskwood.",
			full = "At Three Corners the road forks three ways: west to Goldshire in Elwynn Forest, east to Lakeshire, south to Darkshire in Duskwood. Standing here, a traveler stands at the seam of three lands, with only the crossroads to mark the passage between them. Gnolls press in from the hills nearby.",
			source = "https://warcraft.wiki.gg/wiki/Three_Corners",
		},
		["tower of ilgalar"] = {
			name = "Tower of Ilgalar",
			short = "The Tower of Ilgalar rises in the eastern Redridge Mountains.",
			full = "The Tower of Ilgalar rises in the eastern Redridge Mountains. Morganth rules it, a sorcerer exiled from Stormwind's Mage Quarter for his dark studies, who took the tower as refuge and bent the Shadowhide gnoll clan to his will.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Ilgalar",
		},
	},
	-- Stranglethorn Vale: 38 subzones
	[1434] = {
		["baliamah ruins"] = {
			name = "Balia'mah Ruins",
			short = "The stones of Balia'mah are old troll work, standing east of the river below Mosh'Ogg. The Skullsplitter trolls hold them now, having made a home of what their ancestors raised.",
			full = "The stones of Balia'mah are old troll work, standing east of the river below Mosh'Ogg. The Skullsplitter trolls hold them now, having made a home of what their ancestors raised.",
			source = "https://warcraft.wiki.gg/wiki/Balia'mah_Ruins",
		},
		["ballal ruins"] = {
			name = "Bal'lal Ruins",
			short = "Broken columns rise near the Vile Reef, north of Grom'gol Base Camp, all that remains of a settlement raised long ago by trolls. Little of what it once was still stands.",
			full = "Broken columns rise near the Vile Reef, north of Grom'gol Base Camp, all that remains of a settlement raised long ago by trolls. Little of what it once was still stands. Now Bloodscalp trolls hold the ruin, dwelling among the stones their ancestors left behind.",
			source = "https://warcraft.wiki.gg/wiki/Bal'lal_Ruins",
		},
		["bloodsail compound"] = {
			name = "Bloodsail Compound",
			short = "The Bloodsail Buccaneers keep a loose camp along the western coast of Stranglethorn Vale, tucked toward the middle stretch of the shore.",
			full = "The Bloodsail Buccaneers keep a loose camp along the western coast of Stranglethorn Vale, tucked toward the middle stretch of the shore. No banners of order fly here, no discipline of a proper port -- only the scattered gathering of pirates who call the place their own.",
			source = "https://warcraft.wiki.gg/wiki/Bloodsail_Compound",
		},
		["booty bay"] = {
			name = "Booty Bay",
			short = "Booty Bay sits in a blue lagoon at the southern tip of Stranglethorn Vale, entered on foot through the bleached jaws of a giant shark.",
			full = "Booty Bay sits in a blue lagoon at the southern tip of Stranglethorn Vale, entered on foot through the bleached jaws of a giant shark. Life is cheap here, and no one is to be trusted; it is a rogue's paradise, thick with informants and traders of every stripe.\n\nBefore it wore that name, the cove was called Blackwater Cove, a small human port until jungle trolls overran it. The goblins of the Steamwheedle Cartel drove the trolls back from the shore and claimed the cove for themselves, before the First War was ever fought, and built there their center of operations in the Eastern Kingdoms.\n\nThe Blackwater Raiders run the port now, in close company with the Cartel, and its doors stand open to any traveler regardless of banner. Baron Revilgaz rules from the top of the inn, alongside Fleet Master Seahorn of the Raiders, and he has spent freely to hire swords against the Bloodsail Buccaneers, pirates who have plotted, unsuccessfully, to seize the bay itself.",
			source = "https://warcraft.wiki.gg/wiki/Booty_Bay",
		},
		["cape of stranglethorn"] = {
			name = "Cape of Stranglethorn",
			short = "The southern reaches of Stranglethorn Vale lie thick with troll ruins, half-swallowed by jungle, and long stretches of sandy shore where the trees give way to sea.",
			full = "The southern reaches of Stranglethorn Vale lie thick with troll ruins, half-swallowed by jungle, and long stretches of sandy shore where the trees give way to sea.\n\nAlong the coast sits Booty Bay, a harbor city run by goblin pirates, its docks and market open to anyone with coin regardless of banner.\n\nThat neutrality is not peace. Booty Bay's goblins hold their harbor by trade and by force, and their rivals are the Bloodsail Buccaneers, pirates who have turned against them and taken to raiding the waters and shore the goblins call their own. The conflict between the two has only worsened, ship against ship and camp against camp, the goblins guarding what they built while the Bloodsails press to take it from them.\n\nBeyond the harbor and the ruins, the land is quiet: sand, old stone, and the sea beyond.",
			source = "https://warcraft.wiki.gg/wiki/Cape_of_Stranglethorn",
		},
		["crystal shore"] = {
			name = "Crystal Shore",
			short = "The Crystal Shore is a sandy coastline in southeast Stranglethorn, where the South Seas break against the mainland and the eastern beaches of Jaguero Isle.",
			full = "The Crystal Shore is a sandy coastline in southeast Stranglethorn, where the South Seas break against the mainland and the eastern beaches of Jaguero Isle. It runs from the Wild Shore to the cliffs where the land rises northward, cut off from the interior by a steep ridge crossed by only two paths, one climbing toward Mistvale Valley.\n\nThe Ruins of Aboraz sit at the north end of the shore.",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Shore",
		},
		["crystalvein mine"] = {
			name = "Crystalvein Mine",
			short = "Crank Fizzlebub called them Singing Crystals, unique to Stranglethorn and worth a fortune.",
			full = "Crank Fizzlebub called them Singing Crystals, unique to Stranglethorn and worth a fortune. They seam the rock of Crystalvein Mine near Zul'Mamwe, and the basilisks nesting there eat them raw, hardening their hides to stone. The Venture Company pushed in hoping to strip the mine, but the basilisks have beaten back every attempt. Outside the entrance, trolls and humans stand crystallized where they fell.",
			source = "https://warcraft.wiki.gg/wiki/Crystalvein_Mine",
		},
		["gromgol base camp"] = {
			name = "Grom'gol Base Camp",
			short = "Grom'gol Base Camp sits fortified on the southwestern coast of Stranglethorn, its palisades raised against the jungle trolls of the coast, against naga rising from the surf, and against the Alliance making their way in from Booty Bay and Duskwood.",
			full = "Grom'gol Base Camp sits fortified on the southwestern coast of Stranglethorn, its palisades raised against the jungle trolls of the coast, against naga rising from the surf, and against the Alliance making their way in from Booty Bay and Duskwood. Commander Aggro'gosh holds the camp, keeping it as the safe link in the chain of supply running to Stonard in the Swamp of Sorrows.",
			source = "https://warcraft.wiki.gg/wiki/Grom'gol_Base_Camp",
		},
		["gurubashi arena"] = {
			name = "Gurubashi Arena",
			short = "The Gurubashi Arena stands in the northwestern reach of Stranglethorn, a relic raised in the days when the Gurubashi Empire ruled vast tracts of the southern Eastern Kingdoms.",
			full = "The Gurubashi Arena stands in the northwestern reach of Stranglethorn, a relic raised in the days when the Gurubashi Empire ruled vast tracts of the southern Eastern Kingdoms.\n\nIn older times the fights held here were not sport but slaughter. The sand went muddy with troll blood as combatants fought to the death. Now Short John Mithril oversees matches of a gentler sort, offering fame and plunder rather than death. Old stories still warn that whoever finds a blood-red amulet at midnight will be devoured by a demon before daybreak.",
			source = "https://warcraft.wiki.gg/wiki/Gurubashi_Arena",
		},
		["jaguero isle"] = {
			name = "Jaguero Isle",
			short = "Off the coast of the Wild Shore lies Jaguero Isle, jungle held by panthers and gorillas that answer to no one.",
			full = "Off the coast of the Wild Shore lies Jaguero Isle, jungle held by panthers and gorillas that answer to no one. Chief among them is King Mukla, an enormous ape, who rules the isle and keeps a captive Princess Poobah, a tauren held against her will.\n\nHalf-buried along the shore are bottles washed up from the sea, one holding a folded note.",
			source = "https://warcraft.wiki.gg/wiki/Jaguero_Isle",
		},
		["janeiros point"] = {
			name = "Janeiro's Point",
			short = "Janeiro's Point is a small island off Booty Bay, marked by a great stone goblin with arms flung wide, raised as a beacon to welcome ships into harbor.",
			full = "Janeiro's Point is a small island off Booty Bay, marked by a great stone goblin with arms flung wide, raised as a beacon to welcome ships into harbor. No one now recalls whose likeness it bears. The sea giant Mok'rash the Cleaver has made the island his abode.",
			source = "https://warcraft.wiki.gg/wiki/Janeiro's_Point",
		},
		["kalai ruins"] = {
			name = "Kal'ai Ruins",
			short = "The Kal'ai Ruins lie half-swallowed by the sea in Stranglethorn Vale, ancient troll stonework worn by tide and age.",
			full = "The Kal'ai Ruins lie half-swallowed by the sea in Stranglethorn Vale, ancient troll stonework worn by tide and age. The Murkgill tribe of murlocs now nests among the fallen columns, having claimed the drowned halls for its own.",
			source = "https://warcraft.wiki.gg/wiki/Kal'ai_Ruins",
		},
		["kurzens compound"] = {
			name = "Kurzen's Compound",
			short = "Kurzen's Compound stands east of the Rebel Camp, seat of Kurzen's Expedition. Colonel Kurzen leads it, though madness has taken him.",
			full = "Kurzen's Compound stands east of the Rebel Camp, seat of Kurzen's Expedition. Colonel Kurzen leads it, though madness has taken him. What he became is not spoken of, only the result: the men under him split. Those who would not follow him further broke away and became the jungle fighters of the Rebel Camp, and the compound has been at war with them since, men once of one command now killing each other in the trees.\n\nKurzen himself is no longer often seen among his men, said to keep to the Stockpile at the back of the compound, where the fighters store their arms. Near the stables, panthers and Stranglethorn tigers are held in cages, broken and trained into war beasts for the expedition's use.",
			source = "https://warcraft.wiki.gg/wiki/Kurzen's_Compound",
		},
		["lake nazferiti"] = {
			name = "Lake Nazferiti",
			short = "Lake Nazferiti's waters run thick with frenzies and crocolisks, and a large Venture Company base crowds its shore.",
			full = "Lake Nazferiti's waters run thick with frenzies and crocolisks, and a large Venture Company base crowds its shore.\n\nThe lake is fed by the Nazferiti river, thought by some to be the longest in the southern Eastern Kingdoms, rising at a waterfall in the Redridge Mountains, perhaps further still in Deadwind Pass.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Nazferiti",
		},
		["mistvale valley"] = {
			name = "Mistvale Valley",
			short = "Fog settles low over Mistvale Valley, thick enough to blur the tree line in the southern reaches of Stranglethorn Vale.",
			full = "Fog settles low over Mistvale Valley, thick enough to blur the tree line in the southern reaches of Stranglethorn Vale. The great Mistvale gorillas make their home here, moving through the mist between the trees, undisturbed rulers of this quiet, damp hollow.",
			source = "https://warcraft.wiki.gg/wiki/Mistvale_Valley",
		},
		["mizjah ruins"] = {
			name = "Mizjah Ruins",
			short = "The Mizjah Ruins lie southeast of Grom'gol Base Camp, held by Mosh'Ogg Brutes and their Witch Doctors.",
			full = "The Mizjah Ruins lie southeast of Grom'gol Base Camp, held by Mosh'Ogg Brutes and their Witch Doctors. From these broken stones the ogres strike at the caravans bound for Stonard, ambushing the supply lines and vanishing back into the ruins before any answer can be made.",
			source = "https://warcraft.wiki.gg/wiki/Mizjah_Ruins",
		},
		["moshogg ogre mound"] = {
			name = "Mosh'Ogg Ogre Mound",
			short = "The Mosh'Ogg Ogre Mound lies south of Zul'Gurub, its dark hollows home to the Mosh'Ogg tribe of ogres.",
			full = "The Mosh'Ogg Ogre Mound lies south of Zul'Gurub, its dark hollows home to the Mosh'Ogg tribe of ogres. Deep within, their leader, the ogre mage Mai'Zoth, holds a powerful relic known as the Mind's Eye, and it is from these depths that he rules the mound today.",
			source = "https://warcraft.wiki.gg/wiki/Mosh'Ogg_Ogre_Mound",
		},
		["nekmani wellspring"] = {
			name = "Nek'mani Wellspring",
			short = "The Nek'mani Wellspring rises in the cliffs above the Southern Savage Coast, on the western edge of Stranglethorn.",
			full = "The Nek'mani Wellspring rises in the cliffs above the Southern Savage Coast, on the western edge of Stranglethorn.\n\nScholars of every race claim the waters were made sacred for their people alone, and none has ever settled it.",
			source = "https://warcraft.wiki.gg/wiki/Nek'mani_Wellspring",
		},
		["nesingwarys expedition"] = {
			name = "Nesingwary's Expedition",
			short = "Hemet Nesingwary, a dwarven master hunter, led an expedition into Stranglethorn, drawn by the wild game of the jungle.",
			full = "Hemet Nesingwary, a dwarven master hunter, led an expedition into Stranglethorn, drawn by the wild game of the jungle. He made his camp just below the river north of Lake Nazferiti, and it still stands, a hunter's foothold cut into the green sprawl of Stranglethorn.",
			source = "https://warcraft.wiki.gg/wiki/Nesingwary's_Expedition",
		},
		["rebel camp"] = {
			name = "Rebel Camp",
			short = "The Rebel Camp stands in the northern reaches of Stranglethorn Vale, west of the road running south from Duskwood, northwest of Kurzen's Compound.",
			full = "The Rebel Camp stands in the northern reaches of Stranglethorn Vale, west of the road running south from Duskwood, northwest of Kurzen's Compound.\n\nIts founders served under Colonel Kurzen's expedition until madness took him and his men, twisting their minds beyond recognition. A small band under Lieutenant Doren broke free before the madness claimed them, fleeing Kurzen's Compound westward through the jungle.\n\nThere they built the Rebel Camp, a foothold from which to undo what Kurzen had become. Krazek of Booty Bay keeps them supplied with land mines and other means of defense, enough to let the rebels hold out against the cursed garrison they once served beside.",
			source = "https://warcraft.wiki.gg/wiki/Rebel_Camp",
		},
		["ruins of aboraz"] = {
			name = "Ruins of Aboraz",
			short = "Aboraz was raised by ancient trolls, but it belongs to none now.",
			full = "Aboraz was raised by ancient trolls, but it belongs to none now. Zanzil the Outcast, exiled from his own kind, has claimed the ruins as his domain, filling them with ghouls, naga, and troll minions who answer to his witch doctor's craft.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Aboraz",
		},
		["ruins of jubuwal"] = {
			name = "Ruins of Jubuwal",
			short = "The Ruins of Jubuwal lie east of the Gurubashi Arena, an old troll settlement now held by ghouls, naga, and trolls serving Zanzil the Outcast.",
			full = "The Ruins of Jubuwal lie east of the Gurubashi Arena, an old troll settlement now held by ghouls, naga, and trolls serving Zanzil the Outcast. Among them hide Jon-Jon the Crow and Maury \"Club Foot\" Wilkins, men fled into that grim company to escape debts owed to the ruthless \"Sea Wolf\" MacKinley.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Jubuwal",
		},
		["ruins of zulkunda"] = {
			name = "Ruins of Zul'Kunda",
			short = "Zul'Kunda's stone terraces belong to the Bloodscalp trolls now, ruled by Nezzliok the Dire and Gan'zulah.",
			full = "Zul'Kunda's stone terraces belong to the Bloodscalp trolls now, ruled by Nezzliok the Dire and Gan'zulah. The path east from Zuuldaia Ruins leads straight into their territory, where old troll stonework stands claimed by the living.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Zul'Kunda",
		},
		["ruins of zulmamwe"] = {
			name = "Ruins of Zul'Mamwe",
			short = "The Ruins of Zul'Mamwe lie ringed by mountains on every side but the north, south of the Mosh'Ogg Ogre Mound.",
			full = "The Ruins of Zul'Mamwe lie ringed by mountains on every side but the north, south of the Mosh'Ogg Ogre Mound. They are the seat of the Skullsplitters, second of Stranglethorn Vale's troll tribes, ruled by their chieftain Ana'thek the Cruel.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Zul'Mamwe",
		},
		["savage coast"] = {
			name = "Savage Coast",
			short = "The Savage Coast runs along the northern shore of Stranglethorn Vale, from the Westfall border down past the Vile Reef to Grom'Gol.",
			full = "The Savage Coast runs along the northern shore of Stranglethorn Vale, from the Westfall border down past the Vile Reef to Grom'Gol.\n\nCrocolisks haunt its shallows and basilisks stalk its rocks, their gaze turning the unwary to stone. Several troll settlements watch over these waters.",
			source = "https://warcraft.wiki.gg/wiki/Savage_Coast",
		},
		["south seas"] = {
			name = "South Seas",
			short = "The South Seas fill the water between the known continents, a portion of the Great Sea. Zandalar rises from these waters, ancient home of the troll empire.",
			full = "The South Seas fill the water between the known continents, a portion of the Great Sea. Zandalar rises from these waters, ancient home of the troll empire. Kezan lies among them too, a volcanic island holding its own people apart from the mainland powers. Nearer Stranglethorn Vale, the sea grows treacherous with reefs and small islands, some no more than a sandbar, others holding ruins whose builders are gone. The South Seas run along the borders of Stranglethorn, Tanaris, and Uldum.",
			source = "https://warcraft.wiki.gg/wiki/South_Seas",
		},
		["southern savage coast"] = {
			name = "Southern Savage Coast",
			short = "The Southern Savage Coast lies where the South Seas break against open beaches and shallow water, running down to the waters near Booty Bay and Janeiro's Point, where the shore gives way to the Wild Shore beyond.",
			full = "The Southern Savage Coast lies where the South Seas break against open beaches and shallow water, running down to the waters near Booty Bay and Janeiro's Point, where the shore gives way to the Wild Shore beyond.\n\nThe Vile Reef marks the line between this coast and its northern counterpart, where the Great Sea gives way to the South Seas. Bays and inlets bring the coast into contact with the Gurubashi Arena and the Nek'mani Wellspring.",
			source = "https://warcraft.wiki.gg/wiki/Southern_Savage_Coast",
		},
		["spirit den"] = {
			name = "Spirit Den",
			short = "The Spirit Den lies hidden in a cave at the northern end of Mistvale Valley. There the witch doctor Unbagwa keeps to the shadows of the den, tending to whatever spirits linger in that quiet, unseen hollow.",
			full = "The Spirit Den lies hidden in a cave at the northern end of Mistvale Valley. There the witch doctor Unbagwa keeps to the shadows of the den, tending to whatever spirits linger in that quiet, unseen hollow.",
			source = "https://warcraft.wiki.gg/wiki/Spirit_Den",
		},
		["stockpile"] = {
			name = "Stockpile",
			short = "In a cave at the back of Kurzen's Compound, Colonel Kurzen keeps the equipment of his war.",
			full = "In a cave at the back of Kurzen's Compound, Colonel Kurzen keeps the equipment of his war.",
			source = "https://warcraft.wiki.gg/wiki/Stockpile",
		},
		["tkashi ruins"] = {
			name = "Tkashi Ruins",
			short = "The Tkashi Ruins lie in Stranglethorn Vale, old troll stonework reclaimed by jungle.",
			full = "The Tkashi Ruins lie in Stranglethorn Vale, old troll stonework reclaimed by jungle. The Bloodscalp tribe holds them now, its shamans working ancient rites among the broken walls, artifacts still scattered through the wreckage.",
			source = "https://warcraft.wiki.gg/wiki/Tkashi_Ruins",
		},
		["venture co base camp"] = {
			name = "Venture Co. Base Camp",
			short = "The Venture Company keeps a base camp here, given over to the search for Tumbled Crystals. Nearby stands their Operations Center, the two working in tandem toward the same find.",
			full = "The Venture Company keeps a base camp here, given over to the search for Tumbled Crystals. Nearby stands their Operations Center, the two working in tandem toward the same find.",
			source = "https://warcraft.wiki.gg/wiki/Venture_Co._Base_Camp",
		},
		["venture co operations center"] = {
			name = "Venture Co. Operations Center",
			short = "The Venture Company oil platform rises from a lake in the jungle, the operations center for their push into the wilds.",
			full = "The Venture Company oil platform rises from a lake in the jungle, the operations center for their push into the wilds. Mechanics, geologists, and other goblin crews crowd the rig, working the machinery of an outfit bent on stripping the land for profit.",
			source = "https://warcraft.wiki.gg/wiki/Venture_Co._Operations_Center",
		},
		["vile reef"] = {
			name = "Vile Reef",
			short = "Off the western coast of Stranglethorn Vale, near Grom'Gol, the sea breaks bright over coral.",
			full = "Off the western coast of Stranglethorn Vale, near Grom'Gol, the sea breaks bright over coral. Beneath it lie sunken troll ruins, and among that drowned stone the murlocs now make their home, thick shoals moving through halls that once belonged to someone else. The Altar of the Tides still stands there. Giant clams litter the reef floor, said to hold Blue Pearls, and wreckage from ships that never cleared the reef rolls in along the shore.",
			source = "https://warcraft.wiki.gg/wiki/Vile_Reef",
		},
		["wild shore"] = {
			name = "Wild Shore",
			short = "The Wild Shore is where the Eastern Kingdoms give way to the South Seas, its beaches held by the Bloodsail Buccaneers, whose fleet rides offshore and whose crews claim the sands as their own.",
			full = "The Wild Shore is where the Eastern Kingdoms give way to the South Seas, its beaches held by the Bloodsail Buccaneers, whose fleet rides offshore and whose crews claim the sands as their own. Somewhere along the shore wanders Gorlash, a lone giant, and between pirates and giant the coast answers to no crown.\n\nThe land narrows westward to a rocky point before turning toward Booty Bay. East across a shallow strait lies Jaguero Isle. Northward the sands blur into the Crystal Shore.",
			source = "https://warcraft.wiki.gg/wiki/Wild_Shore",
		},
		["yojamba isle"] = {
			name = "Yojamba Isle",
			short = "On these small islands off the northwestern coast of Stranglethorn, near the border with Westfall, the Zandalar Tribe made its stand against a god gone mad.",
			full = "On these small islands off the northwestern coast of Stranglethorn, near the border with Westfall, the Zandalar Tribe made its stand against a god gone mad.\n\nHakkar the Soulflayer had turned Zul'Gurub into a place of blood and madness, and the Zandalari knew they could not face him alone. So they came to Yojamba Isle and called on Alliance and Horde alike to set aside their war long enough to help destroy him. It was an old, proud tribe trusting outsiders with the fate of its god-touched city.",
			source = "https://warcraft.wiki.gg/wiki/Yojamba_Isle",
		},
		["ziatajai ruins"] = {
			name = "Ziata'jai Ruins",
			short = "The Ziata'jai Ruins are ancient stones raised long ago by trolls, now claimed by the Skullsplitter tribe, who hold the old walls as their own.",
			full = "The Ziata'jai Ruins are ancient stones raised long ago by trolls, now claimed by the Skullsplitter tribe, who hold the old walls as their own.",
			source = "https://warcraft.wiki.gg/wiki/Ziata'jai_Ruins",
		},
		["zulgurub"] = {
			name = "Zul'Gurub",
			short = "Zul'Gurub rises out of the jungle in northeastern Stranglethorn Vale, its terraces and idols overgrown but still standing, a temple city that was once the beating heart of an empire.",
			full = "Zul'Gurub rises out of the jungle in northeastern Stranglethorn Vale, its terraces and idols overgrown but still standing, a temple city that was once the beating heart of an empire. Thousands of years ago it was the capital of the Gurubashi Empire, seat of every jungle troll tribe bound to it. Now it belongs only to the Gurubashi tribe that remains, and the jungle around it does not feel empty.\n\nThe empire tore itself apart when a circle of priests called the Atal'ai summoned the avatar of an ancient blood god, Hakkar the Soulflayer, and were driven into exile for it. They learned that Hakkar could only take physical form in one place: the old Gurubashi capital itself. It is here that Jin'do the Hexxer has enslaved several high priests of the Gurubashi, bending them to the work of calling Hakkar into the world. Champions sent to stop him, each bound to a Primal God, have fallen under Hakkar's sway instead, their power now feeding the very thing they came to destroy.",
			source = "https://warcraft.wiki.gg/wiki/Zul'Gurub",
		},
		["zuuldaia ruins"] = {
			name = "Zuuldaia Ruins",
			short = "Weathered stone rises above the western coast of Stranglethorn Vale, ruins of a settlement long since fallen.",
			full = "Weathered stone rises above the western coast of Stranglethorn Vale, ruins of a settlement long since fallen. The Bloodscalp trolls now hold the broken walls, thick among the old foundations, claiming ground their ancestors never raised.",
			source = "https://warcraft.wiki.gg/wiki/Zuuldaia_Ruins",
		},
	},
	-- Swamp of Sorrows: 14 subzones
	[1435] = {
		["fallow sanctuary"] = {
			name = "Fallow Sanctuary",
			short = "In the Swamp of Sorrows stands the Fallow Sanctuary, home to a tribe of Lost Ones known simply as the Lost Ones.",
			full = "In the Swamp of Sorrows stands the Fallow Sanctuary, home to a tribe of Lost Ones known simply as the Lost Ones. Homesickness has taken every one of them, driving them fully feral, so that nothing of who they once were remains to greet anyone who comes near their village.",
			source = "https://warcraft.wiki.gg/wiki/Fallow_Sanctuary",
		},
		["harborage"] = {
			name = "Harborage",
			short = "In the northern reaches of the Swamp of Sorrows stands a refuge of those who crossed over from Draenor to Azeroth and, unlike so many of their kin, kept their minds whole.",
			full = "In the northern reaches of the Swamp of Sorrows stands a refuge of those who crossed over from Draenor to Azeroth and, unlike so many of their kin, kept their minds whole. Magtoor leads them here.",
			source = "https://warcraft.wiki.gg/wiki/Harborage",
		},
		["ithariuss cave"] = {
			name = "Itharius's Cave",
			short = "In the southwestern Swamp of Sorrows, a cave shelters the high elf Itharius. Outside, unruly green whelps scrap and stumble, too young to master wing or fire.",
			full = "In the southwestern Swamp of Sorrows, a cave shelters the high elf Itharius. Outside, unruly green whelps scrap and stumble, too young to master wing or fire. Itharius has taken it upon himself to watch over them as they grow.",
			source = "https://warcraft.wiki.gg/wiki/Itharius's_Cave",
		},
		["misty reed post"] = {
			name = "Misty Reed Post",
			short = "Misty Reed Post is a small outpost of Stonard, set between the Stagalbog and the southern Misty Reed Strand. Tok'Kar holds it, with Katar, a handful of Stonard hunters, and a Stonard shaman.",
			full = "Misty Reed Post is a small outpost of Stonard, set between the Stagalbog and the southern Misty Reed Strand. Tok'Kar holds it, with Katar, a handful of Stonard hunters, and a Stonard shaman. It is only a camp, no burrow or tower, though Tok'Kar dreams of one day raising one.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Reed_Post",
		},
		["misty reed strand"] = {
			name = "Misty Reed Strand",
			short = "The Misty Reed Strand runs along the Swamp of Sorrows, a gloomy stretch of beach where little grows but driftwood and rot. Crocolisks bask in its shallows, and crabs and murlocs keep to the shore beyond.",
			full = "The Misty Reed Strand runs along the Swamp of Sorrows, a gloomy stretch of beach where little grows but driftwood and rot. Crocolisks bask in its shallows, and crabs and murlocs keep to the shore beyond.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Reed_Strand",
		},
		["misty valley"] = {
			name = "Misty Valley",
			short = "Mist hangs low over this corner of the Swamp of Sorrows, thick enough to swallow sound. Deep in a cave at the valley's back dwelt the Mire Lord, an elemental force.",
			full = "Mist hangs low over this corner of the Swamp of Sorrows, thick enough to swallow sound. Deep in a cave at the valley's back dwelt the Mire Lord, an elemental force.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Valley",
		},
		["pool of tears"] = {
			name = "Pool of Tears",
			short = "The Pool of Tears lies broad and still on the eastern edge of the Swamp of Sorrows. Beneath its calm surface sits the Temple of Atal'Hakkar, sunk there by Ysera after the trolls raised it, hidden from the world.",
			full = "The Pool of Tears lies broad and still on the eastern edge of the Swamp of Sorrows. Beneath its calm surface sits the Temple of Atal'Hakkar, sunk there by Ysera after the trolls raised it, hidden from the world. The green dragonflight long kept watch over the drowned place, guarding against anything that might wake what slept below.\n\nBlood-thirsty frenzies move through the water now, and broken Atal'ai stonework litters the shore.",
			source = "https://warcraft.wiki.gg/wiki/Pool_of_Tears",
		},
		["shifting mire"] = {
			name = "Shifting Mire",
			short = "The silt of the Shifting Mire never lies still. It gathers along the ground in fine drifts and creeps across the swamp as though something unseen were dragging it, curling and pooling like a living thing.",
			full = "The silt of the Shifting Mire never lies still. It gathers along the ground in fine drifts and creeps across the swamp as though something unseen were dragging it, curling and pooling like a living thing.\n\nSome say the force behind that movement is not malevolent, but some positive energy stirring the silt without any will to harm.",
			source = "https://warcraft.wiki.gg/wiki/Shifting_Mire",
		},
		["sorrowmurk"] = {
			name = "Sorrowmurk",
			short = "The Sorrowmurk lies east of the Pool of Tears, near the Sunken Temple.",
			full = "The Sorrowmurk lies east of the Pool of Tears, near the Sunken Temple. It belongs to dragonkin, green dragonspawn crawling through its mire under the watch of a great green drake, which keeps all but the most reckless travelers away.",
			source = "https://warcraft.wiki.gg/wiki/Sorrowmurk",
		},
		["splinterspear junction"] = {
			name = "Splinterspear Junction",
			short = "Where the road into the Swamp of Sorrows forks, an old orcish watch tower still stands, and Horde patrols keep the crossing under their eyes.",
			full = "Where the road into the Swamp of Sorrows forks, an old orcish watch tower still stands, and Horde patrols keep the crossing under their eyes.\n\nThe tower is what remains of Kyross, an orcish outpost raised here during the First War. Kyross stood nearer to the human township of Grand Hamlet than any other Horde position in the swamp, and Stormwind could not let it be. War parties were sent to tear it down.\n\nThe tower still watches the fork in the road.",
			source = "https://warcraft.wiki.gg/wiki/Splinterspear_Junction",
		},
		["stagalbog"] = {
			name = "Stagalbog",
			short = "South of the Pool of Tears, where the Swamp of Sorrows rises into mountains, the marsh thickens into the Stagalbog. West of the wet wilderness, at the mountain's edge, a cave opens into the rock.",
			full = "South of the Pool of Tears, where the Swamp of Sorrows rises into mountains, the marsh thickens into the Stagalbog. West of the wet wilderness, at the mountain's edge, a cave opens into the rock.",
			source = "https://warcraft.wiki.gg/wiki/Stagalbog",
		},
		["stagalbog cave"] = {
			name = "Stagalbog Cave",
			short = "In the eastern Stagalbog of the Swamp of Sorrows, a cave opens into the mire.",
			full = "In the eastern Stagalbog of the Swamp of Sorrows, a cave opens into the mire.",
			source = "https://warcraft.wiki.gg/wiki/Stagalbog_Cave",
		},
		["stonard"] = {
			name = "Stonard",
			short = "Stonard rises out of the mire of the Swamp of Sorrows, its great hall still standing where so many other orcish halls have long since fallen.",
			full = "Stonard rises out of the mire of the Swamp of Sorrows, its great hall still standing where so many other orcish halls have long since fallen. Two burrows guard the approach, and orcish patrols move out to hold the small encampments nearby, each one another claim staked against the swamp.\n\nThe outpost is old, older than almost any other orcish foothold on this side of the world, sister to the fortress once known as Rockard. It was raised by the Old Horde in the Black Morass in the days after the Dark Portal first opened. When the Second War came and the Horde broke, Stonard fell quiet, likely abandoned or destroyed along with so much else the orcs had built.\n\nIt did not stay empty. With the rise of the new Horde and a renewed will to hold this ground, Stonard was rebuilt, its hall restored, its burrows re-dug. Rockard was not so fortunate -- the Dreadmaul ogres took the old fortress for their own and renamed it Dreadmaul Hold, leaving Stonard the lone Horde outpost in the swamp, the last hall of its kind still lit in these lowlands.",
			source = "https://warcraft.wiki.gg/wiki/Stonard",
		},
		["temple of atalhakkar"] = {
			name = "Temple of Atal'Hakkar",
			short = "More than a thousand years ago, the Gurubashi Empire tore itself apart in civil war. At its heart were the Atal'ai, troll priests who sought to bring the blood god Hakkar the Soulflayer back into the world.",
			full = "More than a thousand years ago, the Gurubashi Empire tore itself apart in civil war. At its heart were the Atal'ai, troll priests who sought to bring the blood god Hakkar the Soulflayer back into the world. Defeated and exiled, they fled north into the Swamp of Sorrows and raised a temple there to prepare for his return.\n\nThe dragon Aspect Ysera learned of their plan and sank the temple beneath the marsh, meaning to bury their work forever. It did not happen that way. Undisturbed in the drowned dark, shielded from any eye that might have stopped them, the Atal'ai carried on their rituals in peace. The green dragons Ysera set to guard the ruins have kept watch ever since, holding closed a door that was never truly sealed.\n\nStill the temple sits sunken and half-flooded, its altars to Hakkar unbroken, and those who enter risk worse than death. The Loa of Blood is owed souls as well as flesh, and every one it is given feeds the day it does not fail.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Atal'Hakkar",
		},
	},
	-- Westfall: 17 subzones
	[1436] = {
		["alexston farmstead"] = {
			name = "Alexston Farmstead",
			short = "The fields at Alexston Farmstead once fed families before the Defias Brotherhood took the land for their own.",
			full = "The fields at Alexston Farmstead once fed families before the Defias Brotherhood took the land for their own. Now only the mechanical Harvest Watchers move among the furrows, tireless and untended, guarding rows that no one plants anymore.\n\nBaros Alexston, who came to serve Stormwind City as an architect, was born to this soil. He labored here as a boy, among the same fields the Harvest Watchers now patrol, before the land that shaped him passed into other hands.",
			source = "https://warcraft.wiki.gg/wiki/Alexston_Farmstead",
		},
		["dagger hills"] = {
			name = "Dagger Hills",
			short = "The Dagger Hills rise as a ridge at the back of Moonbrook, in the south of Westfall. Little stirs there now.",
			full = "The Dagger Hills rise as a ridge at the back of Moonbrook, in the south of Westfall. Little stirs there now. Grimbooze Thunderbrew keeps himself among the hills, one of the only living souls to be found in that quiet stretch of ground, and the ghoul Leprithus is known to rise from the earth there as well.",
			source = "https://warcraft.wiki.gg/wiki/Dagger_Hills",
		},
		["dead acre"] = {
			name = "Dead Acre",
			short = "The Dead Acre was once a farm among the others in southeast Westfall, near the bridge into Duskwood. When the Defias Brotherhood seized the region, they took the farm that had stood there, along with its fields.",
			full = "The Dead Acre was once a farm among the others in southeast Westfall, near the bridge into Duskwood. When the Defias Brotherhood seized the region, they took the farm that had stood there, along with its fields.\n\nNo farmer walks it now. Mechanical Harvest Watchers stalk the ground instead, roaming where a harvest used to grow.",
			source = "https://warcraft.wiki.gg/wiki/Dead_Acre",
		},
		["deadmines"] = {
			name = "Deadmines",
			short = "Beneath Moonbrook the tunnels run deep, and once they ran with gold. Before the orcs ever crossed into human lands, the Deadmines fed Stormwind's treasury -- by some accounts a third of it came from this rock.",
			full = "Beneath Moonbrook the tunnels run deep, and once they ran with gold. Before the orcs ever crossed into human lands, the Deadmines fed Stormwind's treasury -- by some accounts a third of it came from this rock. The First War emptied the mines of miners, and afterward they were left for dead, thought haunted, and untouched for a long while.\n\nInto that silence came Edwin VanCleef, who gathered the Defias Brotherhood, former laborers turned brigands, and set them to building a juggernaught in the depths with goblin help.\n\nIn those depths VanCleef remains, guarded by his Brotherhood, while Gryan Stoutmantle gathers men at Sentinel Hill sworn to bring back his head.",
			source = "https://warcraft.wiki.gg/wiki/Deadmines",
		},
		["demonts place"] = {
			name = "Demont's Place",
			short = "Little remains of Demont's Place but broken timber and overgrown fields, west of Moonbrook. Once a working farmstead, it now lies occupied by Defias agents, who hold it as their own.",
			full = "Little remains of Demont's Place but broken timber and overgrown fields, west of Moonbrook. Once a working farmstead, it now lies occupied by Defias agents, who hold it as their own.",
			source = "https://warcraft.wiki.gg/wiki/Demont's_Place",
		},
		["dust plains"] = {
			name = "Dust Plains",
			short = "The Dust Plains lie across the southern reach of Westfall, dry ground given over to gnolls, who hold a scatter of camps there and threaten any who cross their territory.",
			full = "The Dust Plains lie across the southern reach of Westfall, dry ground given over to gnolls, who hold a scatter of camps there and threaten any who cross their territory.\n\nOn the eastern edge stands Mortwake's Tower, an old mage's tower whose original purpose has long since given way to newer masters.",
			source = "https://warcraft.wiki.gg/wiki/Dust_Plains",
		},
		["furlbrows pumpkin farm"] = {
			name = "Furlbrow's Pumpkin Farm",
			short = "Furlbrow's Pumpkin Patch was once tended by Farmer Furlbrow and his wife Verna, but when the Defias Brotherhood swept through Westfall with their mechanical harvest golems, the farm fell like so many others in that country.",
			full = "Furlbrow's Pumpkin Patch was once tended by Farmer Furlbrow and his wife Verna, but when the Defias Brotherhood swept through Westfall with their mechanical harvest golems, the farm fell like so many others in that country. Furlbrow and Verna fled, taking refuge on the road near the Jansen Stead to the north, leaving their pumpkins and their name behind them.",
			source = "https://warcraft.wiki.gg/wiki/Furlbrow's_Pumpkin_Farm",
		},
		["gold coast quarry"] = {
			name = "Gold Coast Quarry",
			short = "Gold Coast Quarry once yielded gold and ore for Stormwind, before Westfall fell into ruin. The Defias Brotherhood holds it now, working the pits under their own banner.",
			full = "Gold Coast Quarry once yielded gold and ore for Stormwind, before Westfall fell into ruin. The Defias Brotherhood holds it now, working the pits under their own banner. The People's Militia and its members have clashed with the Brotherhood here, ambushed by Defias among the stone they still patrol.",
			source = "https://warcraft.wiki.gg/wiki/Gold_Coast_Quarry",
		},
		["jangolode mine"] = {
			name = "Jangolode Mine",
			short = "The Jangolode Mine once ran ore to Stormwind, one of Westfall's steadier sources of mineral wealth.",
			full = "The Jangolode Mine once ran ore to Stormwind, one of Westfall's steadier sources of mineral wealth.\n\nThat steadiness broke when the Defias Brotherhood seized the mine. Kobolds have since crept into its shafts and claimed them for their own.",
			source = "https://warcraft.wiki.gg/wiki/Jangolode_Mine",
		},
		["jansen stead"] = {
			name = "Jansen Stead",
			short = "The Jansen Stead sits at the northern edge of Westfall, close by the bridge into Elwynn Forest. Like the other farms of the region, it was emptied of its rightful owners when the Defias Brotherhood drove them out.",
			full = "The Jansen Stead sits at the northern edge of Westfall, close by the bridge into Elwynn Forest. Like the other farms of the region, it was emptied of its rightful owners when the Defias Brotherhood drove them out.\n\nNearby stand Farmer Furlbrow and his wife, who fled their own home at Furlbrow's Pumpkin Patch and now shelter at the stead.",
			source = "https://warcraft.wiki.gg/wiki/Jansen_Stead",
		},
		["longshore"] = {
			name = "Longshore",
			short = "The coast of Westfall runs long and empty, one of the widest beaches in Azeroth.",
			full = "The coast of Westfall runs long and empty, one of the widest beaches in Azeroth. Murlocs move along it in numbers too great to hold back, and among them swims Old Murk-Eye, a creature the fishing-folk of the coast have learned to fear and name. Out past the breakers lie the bones of ships that never made it in, elven destroyers among them, given over to the tide.\n\nOn the far southwestern reach of the beach stands the farm of Daphne Stilwell. The Defias Brotherhood came for her more than once, meaning to burn her out as they burned so much else in Westfall. Word of her trouble reached Duthorian Rall, who sent aspiring Knights of the Silver Hand down to the coast to stand watch over her land, and they held it.",
			source = "https://warcraft.wiki.gg/wiki/Longshore",
		},
		["molsen farm"] = {
			name = "Molsen Farm",
			short = "Molsen Farm lies among the many farmsteads of Westfall held by the Defias Brotherhood.",
			full = "Molsen Farm lies among the many farmsteads of Westfall held by the Defias Brotherhood. Its rows stand given over to rust and machinery, and mechanical Harvest Watchers roam the fields, striking down anyone who wanders too close.",
			source = "https://warcraft.wiki.gg/wiki/Molsen_Farm",
		},
		["moonbrook"] = {
			name = "Moonbrook",
			short = "Beneath the fields of Moonbrook once ran a third of Stormwind's treasury, gold pulled from the tunnels later called the Deadmines.",
			full = "Beneath the fields of Moonbrook once ran a third of Stormwind's treasury, gold pulled from the tunnels later called the Deadmines. The town was the kingdom's breadbasket, until the disbanding of the Stonemasons Guild set off riots that killed Queen Tiffin Wrynn. King Varian's vengeance for her death fell hardest on the guild, and the Stonemasons fled into the farmlands of Westfall to escape him. Stoked from the shadows, their anger became the Defias Brotherhood. Under Edwin VanCleef they turned to banditry, drove the farmers from Moonbrook, and took the abandoned mine tunnels beneath the town as their headquarters, working there in secret to build a weapon meant to destroy Stormwind from the sea.\n\nFor years no army has come to answer them. The Brotherhood holds Moonbrook still, and only Gryan Stoutmantle's People's Militia stands against them, gathering strength at Sentinel Hill for a reckoning yet to come.",
			source = "https://warcraft.wiki.gg/wiki/Moonbrook",
		},
		["saldeans farm"] = {
			name = "Saldean's Farm",
			short = "Saldean's Farm alone in Westfall was never overrun by the Defias Brotherhood. Defias harvest golems roam its fields, yet Farmer Saldean and his wife Salma refused to leave.",
			full = "Saldean's Farm alone in Westfall was never overrun by the Defias Brotherhood. Defias harvest golems roam its fields, yet Farmer Saldean and his wife Salma refused to leave. Their farmhouse has served for years as a halfway house, the couple doing what they can to keep their guests alive.",
			source = "https://warcraft.wiki.gg/wiki/Saldean's_Farm",
		},
		["sentinel hill"] = {
			name = "Sentinel Hill",
			short = "Sentinel Hill stands on high ground above the farmlands of Westfall, its tower watching over cottages, forge, and mill built into the slope below.",
			full = "Sentinel Hill stands on high ground above the farmlands of Westfall, its tower watching over cottages, forge, and mill built into the slope below.\n\nBoth the Riverpaw gnolls and the Defias Brotherhood have struck at the hill and the lands it holds.",
			source = "https://warcraft.wiki.gg/wiki/Sentinel_Hill",
		},
		["stendels pond"] = {
			name = "Stendel's Pond",
			short = "A small pond lies southwest of Sentinel Hill, its water gone still beneath a ring of gnolls.",
			full = "A small pond lies southwest of Sentinel Hill, its water gone still beneath a ring of gnolls. Two graves rest at its edge, along with scattered old bones, and something in the water seems wrong, as if it were never meant for drinking again.\n\nFishermen who try their luck there mostly pull up common sagefish. But it is said something else swims beneath the surface, a fish called Stendel's Bane, rarely seen and rarer still caught.",
			source = "https://warcraft.wiki.gg/wiki/Stendel's_Pond",
		},
		["westfall lighthouse"] = {
			name = "Westfall Lighthouse",
			short = "The lighthouse stands at the far southern edge of Westfall, its beam still circling out over the water at night, though the hand that keeps it now belongs to a dead man.",
			full = "The lighthouse stands at the far southern edge of Westfall, its beam still circling out over the water at night, though the hand that keeps it now belongs to a dead man.\n\nA family once tended the flame, until the murloc Old Murk-Eye came out of the surf and drove them off in terror. They returned and relit the light, but Old Murk-Eye came back, and this time he brought the murlocs of the coast with him in a raid on the lighthouse. The family did not survive it. Grayson watched them die before him, unable to stop it, and it is his ghost that keeps the light now, standing sentinel outside the tower with no one left to relieve him.",
			source = "https://warcraft.wiki.gg/wiki/Westfall_Lighthouse",
		},
	},
	-- Wetlands: 26 subzones
	[1437] = {
		["angerfang encampment"] = {
			name = "Angerfang Encampment",
			short = "Angerfang Encampment sprawls across central Wetlands, the largest camp the Dragonmaw clan holds in the region, home to the Angerfang orcs.",
			full = "Angerfang Encampment sprawls across central Wetlands, the largest camp the Dragonmaw clan holds in the region, home to the Angerfang orcs.\n\nUnder Nek'rosh Skullcrusher, son of Nekros Skullcrusher, the camp has become a staging ground, massing catapults meant for an assault on Menethil Harbor. The threat is real enough that Captain Stoutfist has sworn to see Nek'rosh dead and the clan's war banners torn down before the catapults roll.",
			source = "https://warcraft.wiki.gg/wiki/Angerfang_Encampment",
		},
		["baradin bay"] = {
			name = "Baradin Bay",
			short = "The waters of Baradin Bay wash the coast where Khaz Modan meets Lordaeron, touching the shores of Menethil Harbor and Stromgarde Keep.",
			full = "The waters of Baradin Bay wash the coast where Khaz Modan meets Lordaeron, touching the shores of Menethil Harbor and Stromgarde Keep. Murlocs and crocolisks drift in its shallows, while sharks and crabs hold the deeper water.\n\nThe bay's true history lies broken along its bottom. During the Second War, the Kul Tiran armada patrolled these waters, holding the coast against the war spreading through the Eastern Kingdoms. But Kul Tiras paid dearly for that vigilance: the nation's Third Fleet was destroyed in the fighting. Some of its wrecks still lie shattered along the coast of the Wetlands, visible in the shallows where they broke apart, while others sank entirely, settling into the dark below where none have raised them since.",
			source = "https://warcraft.wiki.gg/wiki/Baradin_Bay",
		},
		["black channel marsh"] = {
			name = "Black Channel Marsh",
			short = "The road to Menethil Harbor skirts Black Channel Marsh in the southwestern Wetlands.",
			full = "The road to Menethil Harbor skirts Black Channel Marsh in the southwestern Wetlands. Raptors nest throughout the fen, and the hungrier ones wander close to the roadside, so travelers passing this stretch do well to keep watch.",
			source = "https://warcraft.wiki.gg/wiki/Black_Channel_Marsh",
		},
		["bluegill marsh"] = {
			name = "Bluegill Marsh",
			short = "The waters of Bluegill Marsh, in the western Wetlands, hold camps of Bluegill murlocs, who never travel alone but in twos and threes among the reeds.",
			full = "The waters of Bluegill Marsh, in the western Wetlands, hold camps of Bluegill murlocs, who never travel alone but in twos and threes among the reeds. At the head of them stands Gobbler, a murloc fiercer than the rest, whose presence makes the marsh a place best entered with caution.",
			source = "https://warcraft.wiki.gg/wiki/Bluegill_Marsh",
		},
		["deepwater tavern"] = {
			name = "Deepwater Tavern",
			short = "The Deepwater Tavern stands in Menethil Harbor, its common room thick with the talk of sailors passing through.",
			full = "The Deepwater Tavern stands in Menethil Harbor, its common room thick with the talk of sailors passing through. It is a rough place -- chairs get thrown as often as ale gets poured, brawls often started at the urging of Tapoke \"Slim\" Jahn.",
			source = "https://warcraft.wiki.gg/wiki/Deepwater_Tavern",
		},
		["direforge hill"] = {
			name = "Direforge Hill",
			short = "Direforge Hill once served as a major campsite of the Dark Iron dwarves, led by the warlock Balgaras the Foul.",
			full = "Direforge Hill once served as a major campsite of the Dark Iron dwarves, led by the warlock Balgaras the Foul.",
			source = "https://warcraft.wiki.gg/wiki/Direforge_Hill",
		},
		["dragonmaw gates"] = {
			name = "Dragonmaw Gates",
			short = "The Dragonmaw Gates are guarded by the red dragonflight under the drake Axtroz, who holds the way against those who seek to reach Grim Batol.",
			full = "The Dragonmaw Gates are guarded by the red dragonflight under the drake Axtroz, who holds the way against those who seek to reach Grim Batol.",
			source = "https://warcraft.wiki.gg/wiki/Dragonmaw_Gates",
		},
		["dragonmaw retreat"] = {
			pending = true,
			name = "Dragonmaw Retreat",
			short = "",
			full = "",
			source = "",
		},
		["drunken dwarf"] = {
			pending = true,
			name = "The Drunken Dwarf",
			short = "",
			full = "",
			source = "",
		},
		["dun algaz"] = {
			name = "Dun Algaz",
			short = "The tunnel through Dun Algaz is older than the quarrel that split the dwarves. When the War of the Three Hammers drove the Wildhammers from Ironforge, it was through this pass that they made their retreat.",
			full = "The tunnel through Dun Algaz is older than the quarrel that split the dwarves. When the War of the Three Hammers drove the Wildhammers from Ironforge, it was through this pass that they made their retreat.\n\nIt carried the Horde's retreat as well. Beaten back from Dun Modr, the orcs fell south across the Thandol Valley and dug in at the outpost here, and Anduin Lothar, wanting them pushed clear out of Khaz Modan, sent his forces to tear the stronghold down. The assault failed. The orcs held on, and Dun Algaz became the last ground the Horde kept in the region, a foothold that would not be pried loose.\n\nThe dwarven mountaineers who watched this pass kept mostly to the hills above it, but the Dragonmaw clan overran their post and drove them back to the upper tunnel, where they hold on still. With the lower pass lost, the road between the dwarven homelands and Menethil Harbor has grown far more dangerous.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Algaz",
		},
		["dun modr"] = {
			name = "Dun Modr",
			short = "Dun Modr stands south of Thandol Span, an old dwarven city long since fallen into ruin, its blacksmith and its brewery-inn still standing amid wreckage the Dark Iron dwarves now claim as their own.",
			full = "Dun Modr stands south of Thandol Span, an old dwarven city long since fallen into ruin, its blacksmith and its brewery-inn still standing amid wreckage the Dark Iron dwarves now claim as their own.\n\nDuring the Second War the orcish Horde seized the ruins and built an outpost there, using it to beat back Alliance troops and raid the farmlands round about, a vital staging ground for their armies. Stromgarde warriors struck out from the island citadel of Tol Barad to break that outpost, laying siege and driving the orcs south to their secondary hold at Dun Algaz. The Horde struck back, retook Dun Modr, and turned their strength even against Tol Barad itself. Only when the Horde broke at Capital City did Anduin Lothar drive them back through Thandol Span into Khaz Modan, and Dun Modr passed to the Alliance.\n\nThat peace did not last. With Ironforge's soldiers spent in wars fought far from home, the Dark Iron dwarves tore through Thandol Span, and Dun Modr fell soon after under the warlock Balgaras the Foul, who now holds the city his people have claimed as their own.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Modr",
		},
		["excavation site wetlands"] = {
			pending = true,
			name = "Excavation Site: Wetlands",
			short = "",
			full = "",
			source = "",
		},
		["green belt"] = {
			name = "Green Belt",
			short = "The Green Belt is thick with crocolisks, bog beasts, and oozes, and Rethiel the Greenwarden keeps watch here, angered by a land gone strange and unquiet.",
			full = "The Green Belt is thick with crocolisks, bog beasts, and oozes, and Rethiel the Greenwarden keeps watch here, angered by a land gone strange and unquiet.\n\nTo the west, mirebeasts have turned malicious. To the northeast, fire elementals rise unlooked-for out of Direforge Hill. Both are wounds to the land Rethiel wardens, and neither has abated.\n\nWithin the Belt lies a wrecked Dragonmaw clan caravan, red whelps now denning among its ruin, all that remains of an effort to steal young of the black dragonflight that met its end here, swallowed by the marsh.",
			source = "https://warcraft.wiki.gg/wiki/Green_Belt",
		},
		["grim batol"] = {
			name = "Grim Batol",
			short = "Grim Batol is a mountain fortress located in the eastern Wetlands. It has great walls and spires that reach toward a steel-gray sky, but the stronghold's bulk is underground.",
			full = "Grim Batol is a mountain fortress located in the eastern Wetlands. It has great walls and spires that reach toward a steel-gray sky, but the stronghold's bulk is underground. It was founded by the Wildhammer dwarves until it was cursed during the War of the Three Hammers. It was later seized by orcs to serve as a prison for the Dragon Aspect Alexstrasza until she was freed during the Battle of Grim Batol.",
			source = "https://warcraft.wiki.gg/wiki/Grim_Batol",
		},
		["ironbeards tomb"] = {
			name = "Ironbeard's Tomb",
			short = "Ironbeard's Tomb lies west of the road to Dun Modr, in the north-central Wetlands. A dwarven statue stands over the graveyard here, presumably carved in the likeness of Ironbeard himself.",
			full = "Ironbeard's Tomb lies west of the road to Dun Modr, in the north-central Wetlands. A dwarven statue stands over the graveyard here, presumably carved in the likeness of Ironbeard himself.\n\nThe dead no longer rest easy in it. Oozes in black, crimson, and monstrous shades have crept into the crypt and defiled it, spreading through the graveyard until no one who wishes to bury their kin will come near the place anymore.",
			source = "https://warcraft.wiki.gg/wiki/Ironbeard's_Tomb",
		},
		["lost fleet"] = {
			name = "Lost Fleet",
			short = "The wrecks of the Wave Mistress and the Intrepid lie on the seabed of Baradin Bay, off the coast of northern Bluegill Marsh.",
			full = "The wrecks of the Wave Mistress and the Intrepid lie on the seabed of Baradin Bay, off the coast of northern Bluegill Marsh.\n\nThey were part of the Kul Tiras Third Fleet, commanded by Derek Proudmoore, elder son of Lord Admiral Daelin Proudmoore, during the Second War. At the Battle of Crestfall, red dragons enslaved by the Dragonmaw clan fell out of the sky and set the fleet alight. Derek climbed to the crow's nest to warn his father of the danger. A dragon killed him there before the warning could matter, and his ship went down with the rest of the fleet soon after. Only one man survived, First Mate Fitzsimmons of the Wave Mistress.\n\nThe dead did not stay quiet. Deep in the Intrepid's hold, its commander, Captain Halyndor, had hidden away a blackened orb out of greed: the Cursed Eye of Paleth. Its curse reached into the sunken crew years later, binding them into undeath. Only First Mate Snellig kept his mind through it, and his ghost still walks the nearby shore.",
			source = "https://warcraft.wiki.gg/wiki/Lost_Fleet",
		},
		["menethil bay"] = {
			name = "Menethil Bay",
			short = "Menethil Bay lies between the harbor and the cliffs of Dun Morogh, folded into Baradin Bay's inlet.",
			full = "Menethil Bay lies between the harbor and the cliffs of Dun Morogh, folded into Baradin Bay's inlet.\n\nNear the bay's entrance rests the wreckage of the Flying Osprey, its broken hull settled into the water.",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Bay",
		},
		["menethil harbor"] = {
			name = "Menethil Harbor",
			short = "The wall is the first thing anyone notices, thick stone thrown up around a harbor town that sits half on rock, half on the sea.",
			full = "The wall is the first thing anyone notices, thick stone thrown up around a harbor town that sits half on rock, half on the sea. Four towers rise above it, watching the water and the road alike, and there is no way in but the bridge, the tide, or a hidden path running underground to the mainland.\n\nThe orcs raised the first shipyard here. After the First War, Warchief Orgrim Doomhammer chose this shore to build the fleet meant to carry the Horde past Lordaeron's ground defenses, stripping iron and timber from the dwarven mines of Khaz Modan to do it. When the Second War ended, the Alliance took the place and rebuilt it as its own, and Grand Admiral Daelin Proudmoore named it Menethil Harbor for Terenas Menethil II, King of Lordaeron.\n\nFor years afterward, raptors came out of the hills to strike at the town, never in great numbers, but often enough.",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Harbor",
		},
		["menethil keep"] = {
			name = "Menethil Keep",
			short = "Four towers rise above Menethil Harbor, watching the town below like stern guardians. This is Menethil Keep.",
			full = "Four towers rise above Menethil Harbor, watching the town below like stern guardians. This is Menethil Keep.",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Keep",
		},
		["mosshide fen"] = {
			name = "Mosshide Fen",
			short = "Mosshide Fen is a waterlogged stretch of the eastern Wetlands, its ground broken by the camps of the Mosshide gnolls. The tribe holds the fen, seizing and devouring any who wander too far into the marsh.",
			full = "Mosshide Fen is a waterlogged stretch of the eastern Wetlands, its ground broken by the camps of the Mosshide gnolls. The tribe holds the fen, seizing and devouring any who wander too far into the marsh.",
			source = "https://warcraft.wiki.gg/wiki/Mosshide_Fen",
		},
		["raptor ridge"] = {
			name = "Raptor Ridge",
			short = "Raptor Ridge rises in the eastern Wetlands, northwest of the Dragonmaw Gates, its slopes and cavern thick with raptors. Deep within, the Razormaw Matriarch broods over her clutch.",
			full = "Raptor Ridge rises in the eastern Wetlands, northwest of the Dragonmaw Gates, its slopes and cavern thick with raptors. Deep within, the Razormaw Matriarch broods over her clutch.",
			source = "https://warcraft.wiki.gg/wiki/Raptor_Ridge",
		},
		["saltspray glen"] = {
			name = "Saltspray Glen",
			short = "Saltspray Glen lies where the Wetlands meet Baradin Bay, between Bluegill Marsh and Ironbeard's Tomb.",
			full = "Saltspray Glen lies where the Wetlands meet Baradin Bay, between Bluegill Marsh and Ironbeard's Tomb. Its name comes from the wind: when it blows hard off the bay, the ocean throws its spray far inland here, further than anywhere along this shore, until the ground itself is left salt-slicked. Raptors nest thick throughout the glen, as they do across the marsh and ridge nearby.",
			source = "https://warcraft.wiki.gg/wiki/Saltspray_Glen",
		},
		["sundown marsh"] = {
			name = "Sundown Marsh",
			short = "Deep in the northwest of the Wetlands lies Sundown Marsh, thick with crocolisks, gnolls, raptors, bog beasts, and oozes that keep most travelers away.",
			full = "Deep in the northwest of the Wetlands lies Sundown Marsh, thick with crocolisks, gnolls, raptors, bog beasts, and oozes that keep most travelers away. At its heart stands Swiftgear Station, a small stone dwelling with a windmill, where Fradd Swiftgear and Wenna Silkbeard have made their home. The pair deal in what the swamp yields, strange items pulled from the muck, and recipes rarely found elsewhere.",
			source = "https://warcraft.wiki.gg/wiki/Sundown_Marsh",
		},
		["thandol span"] = {
			name = "Thandol Span",
			short = "Two great stone arches span the gap between the Wetlands and the Arathi Highlands, raised by dwarven hands and guarded for three generations by the Anvilmar line.",
			full = "Two great stone arches span the gap between the Wetlands and the Arathi Highlands, raised by dwarven hands and guarded for three generations by the Anvilmar line. They were built after the War of the Three Hammers, when Ironforge sought to keep faith with its Wildhammer kin in Aerie Peak, and the bridges became both road and symbol between the two dwarven kingdoms, carrying trade that enriched them both.\n\nThe bridges stand scarred now. Kam Deepfury and Balgaras the Foul led the Dark Iron dwarves against the Span, tearing down one of the two arches entirely and nearly taking the second. Dwarven forces fought fiercely to defend what remained and to retake the nearby town of Dun Modr, and many died in that fighting, among them Sully Balloo, Ebenezer Rustlocke, and the brother of Longbraid the Grim. The Dark Irons still hold the wreckage, and Balgaras the Foul yet lives among them.",
			source = "https://warcraft.wiki.gg/wiki/Thandol_Span",
		},
		["thelgen rock"] = {
			name = "Thelgen Rock",
			short = "Thelgen Rock rises in the southern Wetlands, its caverns running deep into the mountain and thick with poisonous spiders spinning silk through every crevice.",
			full = "Thelgen Rock rises in the southern Wetlands, its caverns running deep into the mountain and thick with poisonous spiders spinning silk through every crevice. Somewhere in the deeper tunnels lie veins of incendicite ore, guarded by the spiders' numbers.",
			source = "https://warcraft.wiki.gg/wiki/Thelgen_Rock",
		},
		["whelgars excavation site"] = {
			name = "Whelgar's Excavation Site",
			short = "The dig site east of Menethil Harbor was once quiet work for dwarves cutting into earth older than memory. Then mottled raptors overran it, pinning the diggers on a ridge above their own excavation.",
			full = "The dig site east of Menethil Harbor was once quiet work for dwarves cutting into earth older than memory. Then mottled raptors overran it, pinning the diggers on a ridge above their own excavation. They did not hold, abandoning the site for a camp of their own making off the main road, Whelgar's Retreat.\n\nWhat they left behind lies half-uncovered still. Living fossils and old elementals walk the pits now, unbothered by the picks left rusting there.",
			source = "https://warcraft.wiki.gg/wiki/Whelgar's_Excavation_Site",
		},
	},
	-- Teldrassil: 17 subzones
	[1438] = {
		["aldrassil"] = {
			name = "Aldrassil",
			short = "Aldrassil rises at the heart of Shadowglen, a tree grown vast enough to hold a village within its boughs.",
			full = "Aldrassil rises at the heart of Shadowglen, a tree grown vast enough to hold a village within its boughs. At its very top, above the reach of the settlement below, Tenaron Stormgrip has made his home, watching over the glen from the crown of the great tree.",
			source = "https://warcraft.wiki.gg/wiki/Aldrassil",
		},
		["banethil barrow den"] = {
			name = "Ban'ethil Barrow Den",
			short = "Ban'ethil Barrow Den was raised by the night elves as a sacred barrow to hold their sleeping Druids of the Talon in peaceful rest.",
			full = "Ban'ethil Barrow Den was raised by the night elves as a sacred barrow to hold their sleeping Druids of the Talon in peaceful rest.\n\nThat peace is broken now. The corrupted Gnarlpine furbolgs have overrun its Lower and Upper Den, and what was once sanctified ground is no place for a lone night elf to wander.",
			source = "https://warcraft.wiki.gg/wiki/Ban'ethil_Barrow_Den",
		},
		["banethil hollow"] = {
			name = "Ban'ethil Hollow",
			short = "A ravine cuts into the land south of the road between Dolanaar and Darnassus, its slopes held by hostile furbolgs who ambush travelers who stray too close.",
			full = "A ravine cuts into the land south of the road between Dolanaar and Darnassus, its slopes held by hostile furbolgs who ambush travelers who stray too close. At the back of the hollow lies the Ban'ethil Barrow Den, sunk into the earth. Caution is warranted on the road above.",
			source = "https://warcraft.wiki.gg/wiki/Ban'ethil_Hollow",
		},
		["cleft"] = {
			name = "Cleft",
			short = "The Cleft lies northwest of Dolanaar, a den of corrupted Gnarlpine furbolgs led by Ursal the Mauler. They ambush travelers on the road to Darnassus and hold a group of slumbering druids captive within.",
			full = "The Cleft lies northwest of Dolanaar, a den of corrupted Gnarlpine furbolgs led by Ursal the Mauler. They ambush travelers on the road to Darnassus and hold a group of slumbering druids captive within. Moon Priestess Amara and her bodyguards keep watch on the road near the entrance.",
			source = "https://warcraft.wiki.gg/wiki/Cleft",
		},
		["dolanaar"] = {
			name = "Dolanaar",
			short = "Dolanaar stands in the central-eastern reaches of Teldrassil, southwest of Shadowglen, its roots and rope-bridges woven into the great tree itself.",
			full = "Dolanaar stands in the central-eastern reaches of Teldrassil, southwest of Shadowglen, its roots and rope-bridges woven into the great tree itself. Its central place in the island's paths has long made it a hub of comings and goings, a village that felt the pulse of everything happening around it.",
			source = "https://warcraft.wiki.gg/wiki/Dolanaar",
		},
		["fel rock"] = {
			name = "Fel Rock",
			short = "North of Dolanaar lies a cave once beautiful, now corrupted. Grells infest its dark hollows, and within dwells the satyr Lord Melenas, whose presence has poisoned the place.",
			full = "North of Dolanaar lies a cave once beautiful, now corrupted. Grells infest its dark hollows, and within dwells the satyr Lord Melenas, whose presence has poisoned the place. The night elf druid Tallonkai Swiftroot watches this corruption with dread, for what was once fair ground is now foreboding.",
			source = "https://warcraft.wiki.gg/wiki/Fel_Rock",
		},
		["gnarlpine hold"] = {
			name = "Gnarlpine Hold",
			short = "In the far southwest corner of Teldrassil stands Gnarlpine Hold, home of the Gnarlpine furbolgs.",
			full = "In the far southwest corner of Teldrassil stands Gnarlpine Hold, home of the Gnarlpine furbolgs.",
			source = "https://warcraft.wiki.gg/wiki/Gnarlpine_Hold",
		},
		["lake alameth"] = {
			name = "Lake Al'Ameth",
			short = "Lake Al'Ameth spreads wide south of Dolanaar, one of the great waters of Teldrassil. Little marks its shores but a small jetty.",
			full = "Lake Al'Ameth spreads wide south of Dolanaar, one of the great waters of Teldrassil. Little marks its shores but a small jetty.\n\nLately its calm has soured: enraged timberlings haunt the shore, and the lake is no longer safe to walk alone.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Al'Ameth",
		},
		["oracle glade"] = {
			name = "Oracle Glade",
			short = "The Oracle Glade lies in Teldrassil's northwest, cradling the first and most powerful of the great tree's moonwells.",
			full = "The Oracle Glade lies in Teldrassil's northwest, cradling the first and most powerful of the great tree's moonwells. Here stands the Oracle Tree, its wide trunk rising into boughs shaped like an eagle perched atop a bear. Many whisper that no ordinary growth could take such a form, and that nature magic alone shaped it.\n\nThe tree has watched over Teldrassil's growth alongside the druids.\n\nBloodfeather harpies have nested nearby, threatening the tree, and a small company of Sentinels has been sent to hold them back.",
			source = "https://warcraft.wiki.gg/wiki/Oracle_Glade",
		},
		["pools of arlithrien"] = {
			name = "Pools of Arlithrien",
			short = "South of Darnassus, in western Teldrassil, the Pools of Arlithrien were once peaceful. A moonwell there was abandoned by the night elves when Gnarlpine furbolgs overran the area.",
			full = "South of Darnassus, in western Teldrassil, the Pools of Arlithrien were once peaceful. A moonwell there was abandoned by the night elves when Gnarlpine furbolgs overran the area. The well still stands untended among the pools, now home to hostile wildlife.",
			source = "https://warcraft.wiki.gg/wiki/Pools_of_Arlithrien",
		},
		["ruttheran village"] = {
			name = "Rut'theran Village",
			short = "Rut'theran Village lies at the roots of Teldrassil, where the World Tree meets the water, beneath Darnassus far above.",
			full = "Rut'theran Village lies at the roots of Teldrassil, where the World Tree meets the water, beneath Darnassus far above. Its buildings are humble beside the capital's, but kept exceedingly fresh, as though pride were taken in simplicity rather than size.\n\nHere the kaldorei tend the hippogryph roost, gathering and caring for the eggs and raising the young until they can fly. It is quiet work, done by folk who otherwise labor to keep the village running in support of the city above, asking little recognition for it.\n\nThe village is not only labor, though. When the Midsummer Fire Festival comes, its braziers are lit, and the same hands that tend hippogryph eggs and load boats turn instead to celebration.",
			source = "https://warcraft.wiki.gg/wiki/Rut'theran_Village",
		},
		["shadowglen"] = {
			name = "Shadowglen",
			short = "Beneath the boughs of Teldrassil, tucked into the island's northeastern reach, lies a glade that never quite sees full daylight. Shadowglen keeps a perpetual dusk about it, ringed by mountains on every side but one.",
			full = "Beneath the boughs of Teldrassil, tucked into the island's northeastern reach, lies a glade that never quite sees full daylight. Shadowglen keeps a perpetual dusk about it, ringed by mountains on every side but one. Only to the south does the stone break, letting a path slip through toward Dolanaar.\n\nAt the heart of the glade stands Aldrassil, a great tree whose presence dominates the clearing entirely, as though the whole glen were arranged around it. To the northwest, the ground opens into Shadowthread Cave, a dark seam cut into the hills that ring the glade.",
			source = "https://warcraft.wiki.gg/wiki/Shadowglen",
		},
		["shadowthread cave"] = {
			name = "Shadowthread Cave",
			short = "Shadowthread Cave lies in the northwest corner of Shadowglen, in the roots of Teldrassil. It has always belonged to the great spiders of the island, but of late they have grown restless and the cave more dangerous.",
			full = "Shadowthread Cave lies in the northwest corner of Shadowglen, in the roots of Teldrassil. It has always belonged to the great spiders of the island, but of late they have grown restless and the cave more dangerous.\n\nDeepest within dwells Githyiss the Vile, largest of the brood, the ruin of more than one young Kaldorei who wandered too far in.",
			source = "https://warcraft.wiki.gg/wiki/Shadowthread_Cave",
		},
		["starbreeze village"] = {
			name = "Starbreeze Village",
			short = "Starbreeze Village once belonged to the night elves, a cluster of small houses southeast of Shadowglen. It stands empty of them now, its houses claimed by the corrupted Gnarlpine furbolgs.",
			full = "Starbreeze Village once belonged to the night elves, a cluster of small houses southeast of Shadowglen. It stands empty of them now, its houses claimed by the corrupted Gnarlpine furbolgs. Uruson paces its paths, and at its edges lurks Ferocitas the Dream Eater, a beast whose presence alone marks how far the village has fallen from what it once was.",
			source = "https://warcraft.wiki.gg/wiki/Starbreeze_Village",
		},
		["wellspring lake"] = {
			name = "Wellspring Lake",
			short = "Wellspring Lake draws its water from a spring deep within Teldrassil itself, its overflow running off as the Wellspring River. Night elven fishermen once favored these quiet waters.",
			full = "Wellspring Lake draws its water from a spring deep within Teldrassil itself, its overflow running off as the Wellspring River. Night elven fishermen once favored these quiet waters. Now the timberlings that dwell here have turned corrupted, and nightsabers and spiders have crept into the surrounding land, making what was once a peaceful fishing spot a place of danger.",
			source = "https://warcraft.wiki.gg/wiki/Wellspring_Lake",
		},
		["wellspring river"] = {
			name = "Wellspring River",
			short = "The Wellspring River rises from a spring deep within Teldrassil, flowing from Wellspring Lake north to the tree's edge, where it falls in a great waterfall to the sea below.",
			full = "The Wellspring River rises from a spring deep within Teldrassil, flowing from Wellspring Lake north to the tree's edge, where it falls in a great waterfall to the sea below.\n\nCrazed timberlings now stalk its banks, attacking any who come near.",
			source = "https://warcraft.wiki.gg/wiki/Wellspring_River",
		},
	},
	-- Darkshore: 15 subzones
	[1439] = {
		["ametharan"] = {
			name = "Ameth'Aran",
			short = "The ruins of Ameth'Aran lie southeast of Auberdine in Darkshore, and something of the town still walks there.",
			full = "The ruins of Ameth'Aran lie southeast of Auberdine in Darkshore, and something of the town still walks there.\n\nQueen Azshara once raised Ameth'Aran as a twin to Bashal'Aran, seating her favored Highborne within its bazaars and its temples to Elune. Over it she placed Athrikus Narassin, a mage of great power who kept to his Tower of Althalaxx.\n\nWhen the Sundering came and the town was already crumbling, its people clung to the ground as if that alone might save them. Athrikus Narassin appeared among them and promised a spell that would spare them the destruction to come, granting them life eternal within soul gems he carried. As he spoke it, the elves around him died. What eternity he gave them was a prison, not a rescue, and it is their spirits, not their lives, that have lingered in Ameth'Aran ever since.\n\nTwo great stone tablets still stand among the ruins, carved with the story of the town's fall. A sentinel who came to read them was set upon by the restless Highborne before she could finish, and fled.",
			source = "https://warcraft.wiki.gg/wiki/Ameth'Aran",
		},
		["auberdine"] = {
			name = "Auberdine",
			short = "Auberdine stands where the Sundering broke the land, on a coast that swallowed the great cities of the old Kaldorei Empire. Every settlement attempted in Darkshore since has failed, save this one town on the Veiled Sea.",
			full = "Auberdine stands where the Sundering broke the land, on a coast that swallowed the great cities of the old Kaldorei Empire. Every settlement attempted in Darkshore since has failed, save this one town on the Veiled Sea.\n\nIt has grown unlike the rest of night elven society. Its port draws ships and traders from the Eastern Kingdoms, and its streets are filled with dwarves, gnomes, humans, even high elves, so that Auberdine is lit brighter than a night elf town has reason to be, its signposts written in two tongues for the sake of strangers. Darnassus looks down on it for this. Broll Bearmantle, who once visited the town, considers its people little better than outcasts and misfits, and the Sentinels garrisoned here keep apart from the folk they guard. Yet Shandris Feathermoon, who was once stationed here, remembers it as a place that rang with laughter.\n\nNear the lighthouse, the wreck of a ship once commanded by the elf Elura still marks the rocks, its cargo of elunite ore lost when it went down.",
			source = "https://warcraft.wiki.gg/wiki/Auberdine",
		},
		["bashalaran"] = {
			name = "Bashal'Aran",
			short = "Before the sea rose over the world and broke it, Queen Azshara raised twin towns in northern Darkshore for her favored Highborne: Ameth'Aran and Bashal'Aran.",
			full = "Before the sea rose over the world and broke it, Queen Azshara raised twin towns in northern Darkshore for her favored Highborne: Ameth'Aran and Bashal'Aran. She set Athrikus Narassin, an elf of great magical power, to govern them, and beneath him served Asterion, a mage as skilled in arcane craft as in arms, who lived among the people of Bashal'Aran and traveled often to Ameth'Aran to tend to its folk. In those days the twin cities held bazaars and temples to Elune, graced by the queen's own favor.\n\nWhen the first Well of Eternity was shattered, both cities fell to ruin. But at some point Athrikus Narassin turned his craft against his own second, binding Asterion within a moonstone seal and imprisoning him among the stones of Bashal'Aran. Why the master turned on his servant no one now living can say. Asterion endured the prison through a long and painful life, and when at last he died, he found that death had not freed him. His spirit remained bound as surely as his flesh had been.",
			source = "https://warcraft.wiki.gg/wiki/Bashal'Aran",
		},
		["blackwood den"] = {
			name = "Blackwood Den",
			short = "In the far south of Darkshore, near the border of Ashenvale, a scatter of furbolg camps and a small cave make up the place called Blackwood Den, sometimes named Blackwood Hold.",
			full = "In the far south of Darkshore, near the border of Ashenvale, a scatter of furbolg camps and a small cave make up the place called Blackwood Den, sometimes named Blackwood Hold. The furbolgs who hold it are corrupted, twisted from whatever they once were.\n\nWithin the cave sits a lone night elf named Volcor, held captive among the furbolgs.",
			source = "https://warcraft.wiki.gg/wiki/Blackwood_Den",
		},
		["cliffspring falls"] = {
			name = "Cliffspring Falls",
			short = "Cliffspring Falls is the source of the Cliffspring River, once its purest water and the drinking source for all of Darkshore. That water is no longer clean.",
			full = "Cliffspring Falls is the source of the Cliffspring River, once its purest water and the drinking source for all of Darkshore. That water is no longer clean. The cave from which the falls rise has turned foul, and the corruption spreads with the current down through the region it once sustained.\n\nNo one agrees why. Some blame Felwood, saying the taint simply seeps outward from that ruined forest. Others point to what has been found deep in the cave itself, where naga now crawl through the dark at the water's source.",
			source = "https://warcraft.wiki.gg/wiki/Cliffspring_Falls",
		},
		["cliffspring river"] = {
			name = "Cliffspring River",
			short = "The Cliffspring River runs from Cliffspring Falls to the sea in northern Darkshore. Its waters are tainted by the Stormscale naga, and wildlife that drinks from it often falls sick.",
			full = "The Cliffspring River runs from Cliffspring Falls to the sea in northern Darkshore. Its waters are tainted by the Stormscale naga, and wildlife that drinks from it often falls sick.",
			source = "https://warcraft.wiki.gg/wiki/Cliffspring_River",
		},
		["grove of the ancients"] = {
			name = "Grove of the Ancients",
			short = "The Grove of the Ancients is an old night elven temple, its stones settled around the surging Wildbend River in the mountains of Darkshore.",
			full = "The Grove of the Ancients is an old night elven temple, its stones settled around the surging Wildbend River in the mountains of Darkshore. Here Onu, an Ancient of Lore, dwells with a sleeping druid and a pair of merchants, and here the Circle of Ancients still gathers.",
			source = "https://warcraft.wiki.gg/wiki/Grove_of_the_Ancients",
		},
		["long wash"] = {
			name = "Long Wash",
			short = "The Long Wash runs south from Auberdine to the waters west of Ameth'Aran, the shortest stretch of coast in Darkshore despite its name.",
			full = "The Long Wash runs south from Auberdine to the waters west of Ameth'Aran, the shortest stretch of coast in Darkshore despite its name. Gray sand lies beneath an unbroken overcast sky. The tide leaves little but driftwood and the carcasses of dead sea creatures. Murlocs are seen along the shore.",
			source = "https://warcraft.wiki.gg/wiki/Long_Wash",
		},
		["masters glaive"] = {
			name = "Master's Glaive",
			short = "In the southwest of Darkshore lies a colossal skull, half-swallowed by earth, with an adamantine glaive still driven through the bone.",
			full = "In the southwest of Darkshore lies a colossal skull, half-swallowed by earth, with an adamantine glaive still driven through the bone. This was Soggoth the Slitherer, a herald of the Old Gods, and the blade is called the Master's Glaive.\n\nTablets uncovered at Remtravel's Excavation told what happened here. The titans had sent twenty stone giants against Soggoth, and the battle that followed was so terrible that only one of them lived to see its end: Kronn, the largest of the twenty. As Soggoth's tendrils closed around him, Kronn did not fight free of them. He let himself be dragged inward, closer and closer to the creature's skull, until he was near enough to strike. The blow that killed Soggoth was struck from within its own grasp, and the sword left buried in its skull took the name of that victory.\n\nThe Twilight's Hammer has since claimed the site, digging into Soggoth's remains, working to undo what Kronn's sword accomplished and call the Old God's herald back into the world.",
			source = "https://warcraft.wiki.gg/wiki/Master's_Glaive",
		},
		["mists edge"] = {
			name = "Mist's Edge",
			short = "The coast called Mist's Edge runs the length of Darkshore, the longest shoreline in the region.",
			full = "The coast called Mist's Edge runs the length of Darkshore, the longest shoreline in the region.\n\nIt is a gloomy stretch: gray beaches and grim bays, littered with the huge carcasses of dead sea animals and the wrecks of sunken ships.\n\nCrabs scuttle across the whole length of it, and murlocs lurk in the shallow bays, an ever-present threat to anyone walking the shore.",
			source = "https://warcraft.wiki.gg/wiki/Mist's_Edge",
		},
		["remtravels excavation"] = {
			name = "Remtravel's Excavation",
			short = "Prospector Remtravel gave his name to this dig site in Darkshore.",
			full = "Prospector Remtravel gave his name to this dig site in Darkshore. In his digging he found a fossil unlike any other, humming with mystic properties, but the absent-minded prospector has since lost track of where he put it.\n\nThe excavation itself has grown dangerous: Gravelflint troggs have claimed its tunnels, and huge golems, unearthed by the digging, now stir within it.",
			source = "https://warcraft.wiki.gg/wiki/Remtravel's_Excavation",
		},
		["ruins of mathystra"] = {
			name = "Ruins of Mathystra",
			short = "Past the Tower of Althalaxx, in the north of Darkshore, lie the ruins of Mathystra. Before the Great Sundering, it stood as a city of the night elves, raised in the age of the Highborne.",
			full = "Past the Tower of Althalaxx, in the north of Darkshore, lie the ruins of Mathystra. Before the Great Sundering, it stood as a city of the night elves, raised in the age of the Highborne. When the Well of Eternity tore itself apart and the world broke beneath it, Mathystra was ruined along with so much else, and the night elves who survived did not return to rebuild it. They withdrew instead to smaller villages along the coast further south, leaving the ruins behind.\n\nScattered relics of the old Highborne still lie among the fallen stones, and young night elves sometimes come searching through Mathystra for them, wary of the ghost sabers that prowl there among the ruins of what their people once built.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Mathystra",
		},
		["tower of althalaxx"] = {
			name = "Tower of Althalaxx",
			short = "In the age of the Great Sundering, when Queen Azshara raised the Highborne above all others, she set an elf named Athrikus Narassin to govern the twin towns of Ameth'Aran and Bashal'Aran.",
			full = "In the age of the Great Sundering, when Queen Azshara raised the Highborne above all others, she set an elf named Athrikus Narassin to govern the twin towns of Ameth'Aran and Bashal'Aran. Athrikus served her well enough at first, but the work bored him, and he took to spending his days away from the towns, in a tower of his own called Althalaxx.\n\nTen thousand years later, what had long been whispered of that tower proved true. A cult calling itself the Cult of the Dark Strand had gathered there, warlocks and a satyr among them, and at their head stood Athrikus Narassin himself. Their purpose was unclear until it came out that the cult answered to the Shadow Council, and that Althalaxx had become one more thread in that old conspiracy's web.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Althalaxx",
		},
		["twilight vale"] = {
			name = "Twilight Vale",
			short = "The forests south of Ameth'Aran, running to the border of Ashenvale, are called Twilight Vale.",
			full = "The forests south of Ameth'Aran, running to the border of Ashenvale, are called Twilight Vale. Corrupted furbolgs, feral nightsabers, and rabid bears haunt these woods, and travelers are counseled to keep to the roads rather than wander beneath the trees.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Vale",
		},
		["wildbend river"] = {
			name = "Wildbend River",
			short = "The Wildbend River carries its sickness down from the mountains, a continuation of the Bloodvenom River spilling out of Felwood into southern Darkshore, near the Grove of the Ancients.",
			full = "The Wildbend River carries its sickness down from the mountains, a continuation of the Bloodvenom River spilling out of Felwood into southern Darkshore, near the Grove of the Ancients. Its waters run tainted, the corruption of Felwood following the current down into these lower lands.",
			source = "https://warcraft.wiki.gg/wiki/Wildbend_River",
		},
	},
	-- Ashenvale: 41 subzones
	[1440] = {
		["astranaar"] = {
			name = "Astranaar",
			short = "Astranaar rises from an island in the heart of Ashenvale, the largest of the region's night elven settlements, reached only by a pair of bridges that carry the road across the water.",
			full = "Astranaar rises from an island in the heart of Ashenvale, the largest of the region's night elven settlements, reached only by a pair of bridges that carry the road across the water. The lake sets it apart from the forest around it, a quiet, defensible place at the center of a contested land.\n\nIts cemetery lies by the shore, holding the town's dead among the quiet rows of stone.\n\nBeyond the town, the Thistlefur furbolgs have gathered strength in the north, and there is fear in Astranaar that they might one day find the courage to turn their strength against the town itself.",
			source = "https://warcraft.wiki.gg/wiki/Astranaar",
		},
		["bathrans haunt"] = {
			name = "Bathran's Haunt",
			short = "The pillars of Bathran's Haunt once stood as part of a Kaldorei ruin, raised in an age when the night elves still walked this part of Ashenvale.",
			full = "The pillars of Bathran's Haunt once stood as part of a Kaldorei ruin, raised in an age when the night elves still walked this part of Ashenvale. That age passed, the elves withdrew, and the marble was left to crack and fall.\n\nIt is not empty now. Forsaken agents have taken up residence among the broken columns, herbalists and the thugs who guard them, and wherever they settle the land answers in kind: the grass has gone brown, the flowers have withered. Among the fallen stone they have raised a makeshift laboratory, working over the local herbs for purposes of their own.\n\nChief among what draws them here is a plant found nowhere else nearby: Bathran's Hair, a remedial herb rare enough to justify holding the site alone.",
			source = "https://warcraft.wiki.gg/wiki/Bathran's_Haunt",
		},
		["blackfathom deeps"] = {
			name = "Blackfathom Deeps",
			short = "Beneath the Zoram Strand, where the ancient city of Zoram sank into the sea, lie the drowned halls of Lathar'Lazal, once a temple to Elune.",
			full = "Beneath the Zoram Strand, where the ancient city of Zoram sank into the sea, lie the drowned halls of Lathar'Lazal, once a temple to Elune. The Sundering was thought to have destroyed it outright, and for millennia the ocean kept it.\n\nThen the Twilight's Hammer came, drawn by whispers and foul dreams into the watery caverns the temple had become. The cult sacrificed untold innocents in those depths, and was rewarded with a charge: to nurture and protect a cherished creature of the Old Gods -- the monstrous hydra Aku'mai the Devourer -- until the day it is loosed upon the world. The place is called Blackfathom now, and the name fits.",
			source = "https://warcraft.wiki.gg/wiki/Blackfathom_Deeps",
		},
		["bloodtooth camp"] = {
			name = "Bloodtooth Camp",
			short = "Bloodtooth Camp lies west of the Falfarren River, southwest of the southern moonwell of Ashenvale. It takes its name from Ran Bloodtooth, chieftain of the furbolg tribe that holds it.",
			full = "Bloodtooth Camp lies west of the Falfarren River, southwest of the southern moonwell of Ashenvale. It takes its name from Ran Bloodtooth, chieftain of the furbolg tribe that holds it.\n\nThese furbolgs were once like any other of their kind, but corruption has taken every one of them, and now the camp answers with hostility to any outsider who draws near.",
			source = "https://warcraft.wiki.gg/wiki/Bloodtooth_Camp",
		},
		["bough shadow"] = {
			name = "Bough Shadow",
			short = "Beyond Forest Song, where the trees of Ashenvale grow thick and old, Bough Shadow holds one of the portals to the Emerald Dream.",
			full = "Beyond Forest Song, where the trees of Ashenvale grow thick and old, Bough Shadow holds one of the portals to the Emerald Dream.\n\nThe green dragonflight keeps it. The drakes Phantim and Dreamstalker watch over the passage, and dragonspawn move through the surrounding woods in patrols of three, an Emeraldon Oracle flanked by Boughguards and Tree Warders, treading the same ground again and again in their long vigil.",
			source = "https://warcraft.wiki.gg/wiki/Bough_Shadow",
		},
		["demon fall canyon"] = {
			name = "Demon Fall Canyon",
			short = "Demon Fall Canyon carries the scar of the moment the orcs broke free of their old bondage.",
			full = "Demon Fall Canyon carries the scar of the moment the orcs broke free of their old bondage.\n\nHere Mannoroth the pit lord met Grommash Hellscream and Thrall in single struggle. The demon struck Thrall down, but could not turn aside quickly enough from Grom's axe, which drove into his chest. Mannoroth's death burst outward in fire and light, and that same fire tore the life from Grom as it claimed the demon. The orcs took the site of his sacrifice and gave it his name, for it was there the curse the Burning Legion had laid upon their people was broken.\n\nMany orcs journey here still to honor the warrior who paid for that freedom, and a monument stands in his memory. But the ground remains fel-touched, and lesser demons now haunt the canyon.",
			source = "https://warcraft.wiki.gg/wiki/Demon_Fall_Canyon",
		},
		["demon fall ridge"] = {
			name = "Demon Fall Ridge",
			short = "Above Demon Fall Canyon, the ridge rises broken, its slopes and the barrow den cut into its side overrun by lesser demons.",
			full = "Above Demon Fall Canyon, the ridge rises broken, its slopes and the barrow den cut into its side overrun by lesser demons. Deeper in, past the reach of daylight, waits Diathorus the Seeker, a dreadlord who rules the demonic conclave gathered in Ashenvale, holding court in the dark while lesser fiends guard the ridge above.",
			source = "https://warcraft.wiki.gg/wiki/Demon_Fall_Ridge",
		},
		["dordanil barrow den"] = {
			name = "Dor'Danil Barrow Den",
			short = "The Dor'Danil Barrow Den has long been a resting place for night elven druids, who sleep there in body while their spirits wander free.",
			full = "The Dor'Danil Barrow Den has long been a resting place for night elven druids, who sleep there in body while their spirits wander free. It was the Forsaken who turned their attention to the sleepers, severing the druids from their wandering spirits. The experiment did not kill them. It drove them insane.\n\nNow the barrow den holds no peaceful sleepers. Forsaken assassins move through it unseen, while the enraged souls of the severed druids rage through the mound with nowhere left to return to. Among them linger three spirits stronger than the rest -- Uthil Mooncall, Mavoris Cloudsbreak, and Taneel Darkwood.",
			source = "https://warcraft.wiki.gg/wiki/Dor'Danil_Barrow_Den",
		},
		["falfarren river"] = {
			name = "Falfarren River",
			short = "The Falfarren cuts Ashenvale nearly in half. To its west lie the night elves under Astranaar; to the east, the orcs hold Splintertree Post.",
			full = "The Falfarren cuts Ashenvale nearly in half. To its west lie the night elves under Astranaar; to the east, the orcs hold Splintertree Post. The river runs shallow enough to wade and narrow enough to cross without much trouble, save when rains swell it past its banks, but it marks a boundary all the same, one both peoples understand without needing to speak of it.\n\nIts waters rise on the slopes of Mount Hyjal, falling through cascades into the lake at Xavian before running on between Splintertree and Night Run, under the great bridge most travelers use to cross Ashenvale, and past Silverwing Outpost and the Moonwell of Cleansing, before slipping underground beneath the northern mountains toward the Barrens.\n\nNear Felfire Hill the river hides another danger. Bog beasts lurk beneath its surface there, striking at anything that lingers too long in the water.",
			source = "https://warcraft.wiki.gg/wiki/Falfarren_River",
		},
		["fallen sky lake"] = {
			name = "Fallen Sky Lake",
			short = "A small lake lies south of Silverwing Outpost in Ashenvale, its waters gathered around a lone island.",
			full = "A small lake lies south of Silverwing Outpost in Ashenvale, its waters gathered around a lone island. On that island dwells a Shadethicket Oracle, an elder among the shadethicket folk who ring the shore in lesser numbers, watching over the water from the reeds and thickets around it.",
			source = "https://warcraft.wiki.gg/wiki/Fallen_Sky_Lake",
		},
		["felfire hill"] = {
			name = "Felfire Hill",
			short = "Felfire Hill still bears the scars of the Third War, when infernals fell burning from the sky and struck the earth here. Demons have lingered since, foul things denning among the stone.",
			full = "Felfire Hill still bears the scars of the Third War, when infernals fell burning from the sky and struck the earth here. Demons have lingered since, foul things denning among the stone.\n\nThe Horde has fortified both bridges leading onto the hill, holding them to keep the demons from spilling toward nearby settlements.",
			source = "https://warcraft.wiki.gg/wiki/Felfire_Hill",
		},
		["fire scar shrine"] = {
			name = "Fire Scar Shrine",
			short = "Fire Scar Shrine stands in southwestern Ashenvale, corrupted by the demonic influence of the Shadow Council until it became a place of great evil.",
			full = "Fire Scar Shrine stands in southwestern Ashenvale, corrupted by the demonic influence of the Shadow Council until it became a place of great evil. The orcish warlock Ilkrud Magthrull once resided here, serving Athrikus Narassin, leader of the Cult of the Dark Strand.\n\nNow demons infest the shrine, drawn to the taint left in the stone. Among them, a doomguard named Akkrilus is known to appear in the area from time to time, a rare and dangerous sign of how deep the corruption runs.",
			source = "https://warcraft.wiki.gg/wiki/Fire_Scar_Shrine",
		},
		["forest song"] = {
			name = "Forest Song",
			short = "Forest Song is an old night elf ruin in the forests of Ashenvale, long left to moss and memory. For a time it held almost no one at all.",
			full = "Forest Song is an old night elf ruin in the forests of Ashenvale, long left to moss and memory. For a time it held almost no one at all.\n\nThen the druid Kayneth Stillwind made it his own, the ruin's lone inhabitant, directing the fight against the Forsaken in the region from its stones. A forgotten place became a sentinel's post, held not by numbers but by one druid's refusal to leave it.",
			source = "https://warcraft.wiki.gg/wiki/Forest_Song",
		},
		["greenpaw village"] = {
			name = "Greenpaw Village",
			short = "Greenpaw Village is home to the Foulweald tribe, furbolgs led by Chief Murgut and the shaman Oakpaw. The bearmen here are corrupted.",
			full = "Greenpaw Village is home to the Foulweald tribe, furbolgs led by Chief Murgut and the shaman Oakpaw. The bearmen here are corrupted.",
			source = "https://warcraft.wiki.gg/wiki/Greenpaw_Village",
		},
		["howling vale"] = {
			name = "Howling Vale",
			short = "A cave opens into the vale where the Shrine of Mel'Thandris stands, its stone carved with an ancient inscription praising Elune, and above it, in Darnassian: the truth is a guiding light.",
			full = "A cave opens into the vale where the Shrine of Mel'Thandris stands, its stone carved with an ancient inscription praising Elune, and above it, in Darnassian: the truth is a guiding light.\n\nThe shrine was raised by the mother of Velinde Starsong in honor of Mel'Thandris, who had been entrusted with the Scythe of Elune. When Mel'Thandris died, the scythe was laid to rest here, hidden within the shrine. It remained forgotten until Velinde, having found a book in Darnassus recounting the tale, came to the vale and uncovered it herself.\n\nIn time the shrine fell to ruin, and a tribe of worgen called the Terrowulf overran it, making the cave their den. Their howls, echoing through the stone, gave the vale the name it now carries.",
			source = "https://warcraft.wiki.gg/wiki/Howling_Vale",
		},
		["iris lake"] = {
			name = "Iris Lake",
			short = "Iris Lake lies in north-central Ashenvale, east of Astranaar and west of Shael'dryn's moonwell.",
			full = "Iris Lake lies in north-central Ashenvale, east of Astranaar and west of Shael'dryn's moonwell. Once part of the unbroken night elven forest, it fell to the corruption spreading from Felwood, its water turned a sickly yellowish green. Twisted bog beasts now haunt its shores, attacking any who come seeking Elune's Tears.",
			source = "https://warcraft.wiki.gg/wiki/Iris_Lake",
		},
		["kargathia keep"] = {
			name = "Kargathia Keep",
			short = "Kargathia Keep rises among spiked barricades in the Warsong Lumber Camp of eastern Ashenvale, near the Southfury River.",
			full = "Kargathia Keep rises among spiked barricades in the Warsong Lumber Camp of eastern Ashenvale, near the Southfury River. It serves as the seat of the Warsong Clan's officers, its position chosen so that reinforcements can be called down from Orgrimmar should the Alliance move against the camp in force.\n\nThe keep takes its name from Kargath Bladefist, the orcish hero also honored at Kargath in the Badlands and Bladefist Bay in Durotar. Overseer Gorthak commands the camp from within its walls, directing the felling of Ashenvale's timber.",
			source = "https://warcraft.wiki.gg/wiki/Kargathia_Keep",
		},
		["lake falathim"] = {
			name = "Lake Falathim",
			short = "Lake Falathim lies in western Ashenvale, where the goddess's moonlight always touches the water, day or night. Night elves once came here freely to swim and fish, until murlocs overran the lake and turned it savage.",
			full = "Lake Falathim lies in western Ashenvale, where the goddess's moonlight always touches the water, day or night. Night elves once came here freely to swim and fish, until murlocs overran the lake and turned it savage. The scholar Teronis was last seen near its shores and never returned.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Falathim",
		},
		["maestras post"] = {
			name = "Maestra's Post",
			short = "A tower and a single night elven hall stand quiet here, holding a handful of defenders and, strangest of all for Ashenvale, two humans among the elves: Feero Ironhand and Delgren the Purifier, the only ones of their kind at this post.",
			full = "A tower and a single night elven hall stand quiet here, holding a handful of defenders and, strangest of all for Ashenvale, two humans among the elves: Feero Ironhand and Delgren the Purifier, the only ones of their kind at this post.\n\nTheir numbers are few, for the corruption spreading through the nearby furbolgs draws off hands that might otherwise stand watch here, leaving the post's defenders stretched thin.",
			source = "https://warcraft.wiki.gg/wiki/Maestra's_Post",
		},
		["mystral lake"] = {
			name = "Mystral Lake",
			short = "The water of Mystral Lake was once kept by spirits loyal to the night elves, bound to the lake as its wardens.",
			full = "The water of Mystral Lake was once kept by spirits loyal to the night elves, bound to the lake as its wardens. Sarilus Foulborne turned them, corrupting the elementals until they answered to him instead of the elves they had once served. What waits in the lake now is not what it was.",
			source = "https://warcraft.wiki.gg/wiki/Mystral_Lake",
		},
		["night run"] = {
			name = "Night Run",
			short = "Night Run sits on a naze thrust out into the land, its cliffs too sheer to climb, so that a traveler must follow the Falfarren nearly to the waters of Xavian before turning west, or else find the narrow ledge north of Raynewood.",
			full = "Night Run sits on a naze thrust out into the land, its cliffs too sheer to climb, so that a traveler must follow the Falfarren nearly to the waters of Xavian before turning west, or else find the narrow ledge north of Raynewood. There is little to find once inside: only a scatter of broken pillars and ruined stonework, the smallest and poorest of the three satyr strongholds in Ashenvale, dwarfed by Xavian and Satyrnaar alike. The Felmusk satyr who shelter among these ruins have little need of walls when the land itself guards them. Among the rubble lies one of the soulgems of the Cult of the Dark Strand, with whom the Felmusk are allied.",
			source = "https://warcraft.wiki.gg/wiki/Night_Run",
		},
		["nightsong woods"] = {
			name = "Nightsong Woods",
			short = "The Falfarren River cuts the eastern woods in two, and the line it draws is the line of a war that never ends.",
			full = "The Falfarren River cuts the eastern woods in two, and the line it draws is the line of a war that never ends. West of its banks the Silverwing Sentinels hold ground for the Alliance; east of it, the Warsong Clan has driven its stakes into the earth, and here the fighting between the two peoples is heaviest and most constant.\n\nFarther east, a second, nameless river marks another boundary. On one side stands Splintertree Post, the heart of Horde strength in these woods; on the other, Silverwing Grove answers for the Alliance. Beyond that river lies ground that belongs to no one for long, claimed in pieces by the night elves of Forest Song, the satyrs of Satyrnaar and Xavian, the Warsong orcs, and the Burning Legion itself. No single banner has ever flown unchallenged there.\n\nSouth of the fighting, the forest has paid the price of the war. The Warsong Clan has stripped these reaches bare, felling the old trees for timber to raise its settlements, leaving open, wounded ground where ancient forest once stood unbroken.",
			source = "https://warcraft.wiki.gg/wiki/Nightsong_Woods",
		},
		["raynewood retreat"] = {
			name = "Raynewood Retreat",
			short = "High in the boughs of the Great Tree that gives this place its name hides Ordanus, a keeper of the grove and one of the eldest sons of Cenarius.",
			full = "High in the boughs of the Great Tree that gives this place its name hides Ordanus, a keeper of the grove and one of the eldest sons of Cenarius. He came here to conceal himself from the Shadow Council, whose agents had marked him for death. Chief among them was Braelyn Firehand, who made his death her singular purpose and sent killers against him. Ordanus survived the attempt, and remains hidden in the tree's high branches still.\n\nBelow him, Cenarion Protectors, Blink Dragons, and the Laughing Sisters keep watch from the outpost, guarding the northern path into the blighted reaches of Felwood.",
			source = "https://warcraft.wiki.gg/wiki/Raynewood_Retreat",
		},
		["ruins of ordilaran"] = {
			name = "Ruins of Ordil'Aran",
			short = "Little remains of Ordil'Aran now but broken stone. The Cult of the Dark Strand once made the ruins their own, ready to fall upon anyone who came too near.",
			full = "Little remains of Ordil'Aran now but broken stone. The Cult of the Dark Strand once made the ruins their own, ready to fall upon anyone who came too near. That ended in blood: the Thistlefur furbolgs drove them out and claimed the ruins for themselves, and the cultists' bodies still lie scattered where they fell.\n\nAmid the wreckage stands the Heartswood, rooted in what was once a city of some name and standing. Nothing else of it survives to say what that was.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Ordil'Aran",
		},
		["ruins of stardust"] = {
			name = "Ruins of Stardust",
			short = "The Ruins of Stardust lie on a lake island, sunk once in sanctity, now sunk in rot. The demonic taint seeping down from Felwood has crept into the water and stone alike, staining the island a sickly yellow-green.",
			full = "The Ruins of Stardust lie on a lake island, sunk once in sanctity, now sunk in rot. The demonic taint seeping down from Felwood has crept into the water and stone alike, staining the island a sickly yellow-green. Bog beasts, twisted by the poisoned lake, drag themselves through the wreckage now.\n\nYet the stardust shrubs still grow there, untouched by the corruption around them. Their leaves are said to hold a healing virtue, the one part of the ruins that still resembles what the place must have been before the rot came.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Stardust",
		},
		["satyrnaar"] = {
			name = "Satyrnaar",
			short = "Satyrnaar stands broken among the trees of northeastern Ashenvale, its buildings long fallen to ruin, though tents now cluster among the wreckage where the Bleakheart satyr have made their home.",
			full = "Satyrnaar stands broken among the trees of northeastern Ashenvale, its buildings long fallen to ruin, though tents now cluster among the wreckage where the Bleakheart satyr have made their home. Of the three satyr strongholds in the forest, Satyrnaar alone remains largely intact, and its place beside the road running from Splintertree toward Azshara has made it both the easiest to reach and the most fought-over of the three.\n\nThe Bleakheart hold more than shelter here. Within Satyrnaar rests one of the soulgems of the Cult of the Dark Strand, a token of the pact binding the satyr to that cult's dark purposes.",
			source = "https://warcraft.wiki.gg/wiki/Satyrnaar",
		},
		["shady nook"] = {
			name = "Shady Nook",
			short = "Shady Nook lies south of Raynewood Retreat and east of Greenpaw Village, a small valley folded quietly into Ashenvale.",
			full = "Shady Nook lies south of Raynewood Retreat and east of Greenpaw Village, a small valley folded quietly into Ashenvale. A cave opens into its hillside, home to a small family of bears who keep to themselves among the trees and shadow.",
			source = "https://warcraft.wiki.gg/wiki/Shady_Nook",
		},
		["shrine of aessina"] = {
			name = "Shrine of Aessina",
			short = "The Shrine of Aessina stands in southwestern Ashenvale, tucked between Maestra's Post and Astranaar.",
			full = "The Shrine of Aessina stands in southwestern Ashenvale, tucked between Maestra's Post and Astranaar.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_Aessina",
		},
		["silverwind refuge"] = {
			name = "Silverwind Refuge",
			short = "Silverwind Refuge belongs to the night elves, held under the watch of the Sentinels and the water elementals that serve alongside them.",
			full = "Silverwind Refuge belongs to the night elves, held under the watch of the Sentinels and the water elementals that serve alongside them. Together with Astranaar, it stands as one of the major outposts of Ashenvale, and its name is well earned: a welcoming place, its inn counted among the more comfortable to be found in the region.",
			source = "https://warcraft.wiki.gg/wiki/Silverwind_Refuge",
		},
		["silverwing grove"] = {
			name = "Silverwing Grove",
			short = "Silverwing Grove stands in south-central Ashenvale, a stand of trees held by the Silverwing Sentinels, southwest of their outpost and west of Fallen Sky Lake.",
			full = "Silverwing Grove stands in south-central Ashenvale, a stand of trees held by the Silverwing Sentinels, southwest of their outpost and west of Fallen Sky Lake. Sentinel Farsong keeps watch here among those sworn to the grove's defense.",
			source = "https://warcraft.wiki.gg/wiki/Silverwing_Grove",
		},
		["silverwing outpost"] = {
			name = "Silverwing Outpost",
			short = "Silverwing Outpost stands on the wrong side of the Falfarren River, deep in country the orcs of Splintertree Post mean to clear.",
			full = "Silverwing Outpost stands on the wrong side of the Falfarren River, deep in country the orcs of Splintertree Post mean to clear. Duriel Moonfire commands it, and command here means constant war -- the orcs do not raid for plunder, but to erase the outpost and drive every sentinel from these woods for good.",
			source = "https://warcraft.wiki.gg/wiki/Silverwing_Outpost",
		},
		["southfury river"] = {
			name = "Southfury River",
			short = "The Southfury rises high on Mount Hyjal, spilling from a mountain lake in a fall that drops thunderously into the lowlands.",
			full = "The Southfury rises high on Mount Hyjal, spilling from a mountain lake in a fall that drops thunderously into the lowlands. From there it runs wide and swift, cutting the land in two: it marks where Ashenvale gives way to Azshara, and further south where the Barrens ends and Durotar begins. At its mouth the river throws itself over a last cascade into the Great Sea, just northeast of the goblin port of Ratchet.\n\nBridges cross its length, one linking Azshara to Ashenvale, another joining Durotar to the Barrens. Just north of the westernmost of these, a single stretch of water touches all four lands at once, the only place where Ashenvale, Azshara, Durotar, and the Barrens meet.\n\nThe river still feeds the fields along its banks, still turns the soil green where it runs. But it can no longer be drunk.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["splintertree post"] = {
			name = "Splintertree Post",
			short = "The timbers of Splintertree Post still bear the marks of the axes that raised it, for it was Grommash Hellscream and his Warsong clan who built this outpost when the orcs first pushed into Ashenvale during the Third War, felling the ancient trees for their road and their camps.",
			full = "The timbers of Splintertree Post still bear the marks of the axes that raised it, for it was Grommash Hellscream and his Warsong clan who built this outpost when the orcs first pushed into Ashenvale during the Third War, felling the ancient trees for their road and their camps.\n\nThe night elves have never made peace with what the Warsong did to their forests, and the old wounds sit uneasily under the strained truce between Horde and Alliance. So Splintertree draws retaliation more than most outposts in these woods, with raids on nearby Astranaar frequent on both sides.\n\nWhat remains now is a garrison, not a settlement: orcs and tauren standing scout and guard, watching the tree line for the raiders they have learned to expect.",
			source = "https://warcraft.wiki.gg/wiki/Splintertree_Post",
		},
		["talondeep path"] = {
			name = "Talondeep Path",
			short = "The Talondeep Path is a winding tunnel joining Ashenvale to the Stonetalon Mountains, its passage uneven with small dead ends and strange hollows worn into the rock.",
			full = "The Talondeep Path is a winding tunnel joining Ashenvale to the Stonetalon Mountains, its passage uneven with small dead ends and strange hollows worn into the rock. It opens west of Mystral Lake on one end, and in the northwestern reach of Windshear Crag on the other. Nothing dwells there; it is simply a way through the mountains.",
			source = "https://warcraft.wiki.gg/wiki/Talondeep_Path",
		},
		["thistlefur village"] = {
			name = "Thistlefur Village",
			short = "Thistlefur Village lies in westcentral Ashenvale, north of Astranaar. It is home to the Thistlefur tribe, furbolgs turned corrupt and hostile, attacking any who wander near.",
			full = "Thistlefur Village lies in westcentral Ashenvale, north of Astranaar. It is home to the Thistlefur tribe, furbolgs turned corrupt and hostile, attacking any who wander near. Two ferocious warriors, Dal Bloodclaw and Rorgish Jowl, lead the tribe and hold the village against all who approach.",
			source = "https://warcraft.wiki.gg/wiki/Thistlefur_Village",
		},
		["warsong labor camp"] = {
			name = "Warsong Labor Camp",
			short = "In southeastern Ashenvale, east of Fallen Sky Lake, the Warsong clan keeps a labor camp where loggers and harvesters work under orcish guard, cutting timber for the clan's holdings.",
			full = "In southeastern Ashenvale, east of Fallen Sky Lake, the Warsong clan keeps a labor camp where loggers and harvesters work under orcish guard, cutting timber for the clan's holdings.\n\nThe camp stands apart from the Warsong's main strength, its guards left isolated and beyond hope of reinforcement.",
			source = "https://warcraft.wiki.gg/wiki/Warsong_Labor_Camp",
		},
		["warsong lumber camp"] = {
			name = "Warsong Lumber Camp",
			short = "The forests of Ashenvale ring with axes at Warsong Lumber Camp, where the Warsong clan strips the ancient trees for timber.",
			full = "The forests of Ashenvale ring with axes at Warsong Lumber Camp, where the Warsong clan strips the ancient trees for timber. The camp is anchored by a kennel of war beasts and by Kargathia Keep, a stronghold raised to guard the cutting.\n\nThe clan's hunger for wood has not gone unanswered. Illiyana and her sisters have taken to the woods here, turning nature magic against the shredders that gnaw through the trunks, and the ground between the stacked logs has become a battlefield between Alliance and Horde.\n\nEven so, the camp still serves its purpose: a steady train of timber moves from here to Splintertree Post, whose walls and people depend on what Warsong Lumber Camp sends them.",
			source = "https://warcraft.wiki.gg/wiki/Warsong_Lumber_Camp",
		},
		["xavian"] = {
			name = "Xavian",
			short = "Xavian rises where a temple of the night elves once stood, its stones now given over to satyrs.",
			full = "Xavian rises where a temple of the night elves once stood, its stones now given over to satyrs. Among the three satyr strongholds of Ashenvale, it is here that power gathers: Prince Raze and Geltharis both make their seat within these ruins, and it is here that the satyrs have turned to the stolen Warsong Oil for their rituals.\n\nThe place takes its name from Xavius, who long ago helped open the way for the Burning Legion through a portal drawn from the Well of Eternity in Zin-Azshari. Sargeras, displeased with how slowly that working went, twisted Xavius into the very first of the satyrs. Xavian lies near enough to Azshara that the name seems no accident.\n\nDryads have come against Xavian - one of them, Anilia, was found here mortally wounded after searching out a branch of Cenarius the satyrs had taken for themselves, left lying on the ground amid the ruins she could not clear.",
			source = "https://warcraft.wiki.gg/wiki/Xavian",
		},
		["zoram strand"] = {
			name = "Zoram Strand",
			short = "The waves along Zoram Strand break over what was once a city.",
			full = "The waves along Zoram Strand break over what was once a city. Before the world was torn apart in the Great Sundering, Zoram stood here as a night elven town, and when the sea rose to claim its share of the shattered world, Zoram went under with it. Nothing remains above the water now but the name.\n\nWhat walks the strand today are not elves but naga. They have taken the shore for their own, and the wreckage scattered along the sand, broken ships, the bodies of beached sea creatures, marks how thoroughly the coast has passed into their hands. Among the rocks and drowned hollows nearby lies Blackfathom Deeps, sunk into the earth as Zoram once sank into the sea.\n\nThe Horde holds a small foothold here at Zoram'gar Outpost, driven to it more than by choice, and has spent itself fighting the Wrathtail naga who contest every foot of the strand. Those same naga fell upon Talen, leaving the outpost with enemies pressing from more than one direction. It is a hard, wet, contested stretch of coast, claimed by an empire that drowned, and held now by creatures born of the sea that swallowed it.",
			source = "https://warcraft.wiki.gg/wiki/Zoram_Strand",
		},
		["zoramgar outpost"] = {
			name = "Zoram'gar Outpost",
			short = "The Zoram'gar Outpost stands as a Horde port along the Zoram Strand of Ashenvale, its docks reaching out into the waters below.",
			full = "The Zoram'gar Outpost stands as a Horde port along the Zoram Strand of Ashenvale, its docks reaching out into the waters below.",
			source = "https://warcraft.wiki.gg/wiki/Zoram'gar_Outpost",
		},
	},
	-- Thousand Needles: 21 subzones
	[1441] = {
		["camp ethok"] = {
			name = "Camp E'thok",
			short = "Camp E'thok is a Galak centaur camp in northwestern Thousand Needles.",
			full = "Camp E'thok is a Galak centaur camp in northwestern Thousand Needles. Its centaurs raided a caravan carrying the goblin Wizlo Bearingshiner, but could not steal the gadget he prized most, kept safe around the neck of his ferocious pet panther.",
			source = "https://warcraft.wiki.gg/wiki/Camp_E'thok",
		},
		["darkcloud pinnacle"] = {
			name = "Darkcloud Pinnacle",
			short = "Darkcloud Pinnacle rises on three small mesas east of the Great Lift, their tops laced together with rope bridges strung over open air.",
			full = "Darkcloud Pinnacle rises on three small mesas east of the Great Lift, their tops laced together with rope bridges strung over open air. Only two paths lead up, each well guarded: a natural slope across a fourth mesa, or a bridge reaching over from Razorfen Downs.\n\nThe Grimtotem tauren hold these heights, led by Arnak Grimtotem and Harb Foulmountain. Behind the guarded bridges, the two leaders carry on a secret correspondence with some dark power whose identity is not known. What passes between them is not spoken of openly, but the care taken to seal off the mesas shows how closely that secret is kept.",
			source = "https://warcraft.wiki.gg/wiki/Darkcloud_Pinnacle",
		},
		["freewind post"] = {
			name = "Freewind Post",
			short = "Freewind Post sits high on a mesa in Thousand Needles, raised out of the reach of the centaur that roam below.",
			full = "Freewind Post sits high on a mesa in Thousand Needles, raised out of the reach of the centaur that roam below. Wooden lifts carry its people up from the canyon floor, and rope bridges string between the neighboring pinnacles, climbing pinnacle by pinnacle until they reach the village. Below, the Galak centaur press their warbands, and harpies wheel and shriek over the flats, but the height itself is the post's real defense.\n\nThe deeper trouble came from the northwest, from Darkcloud Pinnacle, where the Grimtotem tribe held their own high ground. Freewind Post grew wary of them long before open war came: tauren went missing, agents of unknown and dark origin were seen visiting the pinnacle, and murder was laid at the Grimtotems' door. Chieftain Arnak Grimtotem bore the worst of the blame. When Lakota Windsong of Freewind Post refused his advances, he had her taken by force, and when her brother came to defend her, the Grimtotem killed him.",
			source = "https://warcraft.wiki.gg/wiki/Freewind_Post",
		},
		["great lift"] = {
			name = "Great Lift",
			short = "The Great Lift is a tauren-built elevator carrying travelers between the Barrens and Thousand Needles below. Grish Longrunner and Brave Moonhorn keep watch over it for the Horde.",
			full = "The Great Lift is a tauren-built elevator carrying travelers between the Barrens and Thousand Needles below. Grish Longrunner and Brave Moonhorn keep watch over it for the Horde.",
			source = "https://warcraft.wiki.gg/wiki/Great_Lift",
		},
		["highperch"] = {
			name = "Highperch",
			short = "Highperch rises above the Thousand Needles, home to wyverns and their nests. Among the crags the tauren Pao'ka Swiftmountain lies stranded, hoping to slip past the wyverns and make it home.",
			full = "Highperch rises above the Thousand Needles, home to wyverns and their nests. Among the crags the tauren Pao'ka Swiftmountain lies stranded, hoping to slip past the wyverns and make it home.",
			source = "https://warcraft.wiki.gg/wiki/Highperch",
		},
		["ironstone camp"] = {
			name = "Ironstone Camp",
			short = "Ironstone Camp sits at the edge of the Shimmering Flats.",
			full = "Ironstone Camp sits at the edge of the Shimmering Flats.",
			source = "https://warcraft.wiki.gg/wiki/Ironstone_Camp",
		},
		["mirage raceway"] = {
			name = "Mirage Raceway",
			short = "A goblin named Pozzik and a gnome named Fizzle Brassbolts each believed their own people the cleverer engineers, and neither would yield the point.",
			full = "A goblin named Pozzik and a gnome named Fizzle Brassbolts each believed their own people the cleverer engineers, and neither would yield the point. So they settled it as tinkerers do: they built a track, and they built rocket cars to run on it.\n\nThe rivalry draws crowds far beyond the two of them. Horde and Alliance alike come to cheer their favorites as gnome and goblin drag cars race daily, each team scrambling afterward to rebuild their engines with some new edge. The real contest is always the same one: which race builds the better machine, and it is never settled.",
			source = "https://warcraft.wiki.gg/wiki/Mirage_Raceway",
		},
		["razorfen downs"] = {
			name = "Razorfen Downs",
			short = "Deep within the brambles of the Thousand Needles lies a maze of thorn and bone, its entrance said to be shaped from Agamaggan's own maw, an arched gap in the outer dome so hidden that only those who already know its shape can find it.",
			full = "Deep within the brambles of the Thousand Needles lies a maze of thorn and bone, its entrance said to be shaped from Agamaggan's own maw, an arched gap in the outer dome so hidden that only those who already know its shape can find it. This is Razorfen Downs, the ancestral burial ground and traditional capital of the quilboar, crafted from the same mighty vines as Razorfen Kraul. Charlga Razorflank shaped most of the great thorn dome that covers it.\n\nFor generations the Downs stood as a place of quilboar dead, tended by the high priests of the Death's Head tribe. But after the Third War, the lich Amnennar the Coldbringer turned his agents against the quilboar and seized their holy city, binding it into a bastion of the Scourge. The quilboar fought bitterly to win back what was theirs before Amnennar's plague could spread further into the Barrens, and in that struggle the living were dragged down and caged within the thorns alongside the dead.\n\nAmnennar remains within the labyrinth still, ruling over the quilboar he has bent to his will, his hold on the Downs unbroken.",
			source = "https://warcraft.wiki.gg/wiki/Razorfen_Downs",
		},
		["roguefeather den"] = {
			name = "Roguefeather Den",
			short = "In a small cavern in south central Thousand Needles, the harpies of Roguefeather Den have made their nest.",
			full = "In a small cavern in south central Thousand Needles, the harpies of Roguefeather Den have made their nest. They screech at any who draw near, and in the back of the den they hoard their gathered foodstuffs, guarding the stores as fiercely as they guard their young.",
			source = "https://warcraft.wiki.gg/wiki/Roguefeather_Den",
		},
		["rustmaul dig site"] = {
			name = "Rustmaul Dig Site",
			short = "The Rustmaul Dig Site lies in the Shimmering Flats, its trenches left mid-work. The Explorers' League had come here to uncover old ruins, working the ground in the shadow of a cave that held a nest of silithid.",
			full = "The Rustmaul Dig Site lies in the Shimmering Flats, its trenches left mid-work. The Explorers' League had come here to uncover old ruins, working the ground in the shadow of a cave that held a nest of silithid.\n\nThe digging stopped before it was finished. The trenches stand open and empty, the tools of the dwarves abandoned where they were left, and the cave beneath the site remains home to the silithid that dwell there still.",
			source = "https://warcraft.wiki.gg/wiki/Rustmaul_Dig_Site",
		},
		["scalding ridge"] = {
			pending = true,
			name = "Scalding Ridge",
			short = "",
			full = "",
			source = "",
		},
		["screeching canyon"] = {
			name = "Screeching Canyon",
			short = "The Screeching Canyon cuts through southern Thousand Needles, its walls echoing with the cries of the Screeching harpies that infest it.",
			full = "The Screeching Canyon cuts through southern Thousand Needles, its walls echoing with the cries of the Screeching harpies that infest it. At the canyon's back lies the Roguefeather Den, the harpies' stronghold.",
			source = "https://warcraft.wiki.gg/wiki/Screeching_Canyon",
		},
		["shimmering flats"] = {
			name = "Shimmering Flats",
			short = "The Shimmering Flats lie at the southeastern edge of Thousand Needles, where the land runs flat and bare to the border with Tanaris.",
			full = "The Shimmering Flats lie at the southeastern edge of Thousand Needles, where the land runs flat and bare to the border with Tanaris. Nothing grows here. The ground is hard-baked salt, home only to basilisks, scorpids, turtles, and vultures. Once this was the bottom of a lake -- the wrecked hull of a sailing vessel still sits half-buried in the northern flats, a ship stranded far from any water, proof of what this place used to be before it dried to salt and cracked earth.\n\nThat flatness drew goblins and gnomes from opposite sides of their long rivalry. They raised the Mirage Raceway here and raced to build machines faster than one another's. The contraptions rarely held together. Craters pock the flats where engines went wrong, and the wreckage of failed racers lies scattered across the salt, left to bake where it fell.",
			source = "https://warcraft.wiki.gg/wiki/Shimmering_Flats",
		},
		["splithoof crag"] = {
			name = "Splithoof Crag",
			short = "Splithoof Crag stands against the northern wall of Thousand Needles, east of Darkcloud Pinnacle, home to the Galak centaur.",
			full = "Splithoof Crag stands against the northern wall of Thousand Needles, east of Darkcloud Pinnacle, home to the Galak centaur. At its center lies Splithoof Hold, a cavern in the mountainside where the Galak keep the Cloven Hoof, an ancient artifact guarded by the Ancient Brazier and its Sacred Flame.",
			source = "https://warcraft.wiki.gg/wiki/Splithoof_Crag",
		},
		["splithoof hold"] = {
			name = "Splithoof Hold",
			short = "The Galak centaur made Splithoof Hold their stronghold in the caves of Splithoof Crag. Within it burns the Sacred Flame upon the Ancient Brazier, a fire said to endure even underwater.",
			full = "The Galak centaur made Splithoof Hold their stronghold in the caves of Splithoof Crag. Within it burns the Sacred Flame upon the Ancient Brazier, a fire said to endure even underwater.",
			source = "https://warcraft.wiki.gg/wiki/Splithoof_Hold",
		},
		["tahonda ruins"] = {
			name = "Tahonda Ruins",
			short = "A tauren village once stood where the Shimmering Flats now lie, long fallen to ruin and swallowed by sand. Saltstone basilisks nest among the stones now, and some say it was they who drove the tauren out.",
			full = "A tauren village once stood where the Shimmering Flats now lie, long fallen to ruin and swallowed by sand. Saltstone basilisks nest among the stones now, and some say it was they who drove the tauren out.\n\nOne clue remains: on the leather wall of a building, two sets of three parallel tears, the mark of claws, not wind or time. Something came for that village with purpose.\n\nNo names survive. Only the ruins remain, near the mountain path to Tanaris.",
			source = "https://warcraft.wiki.gg/wiki/Tahonda_Ruins",
		},
		["weathered nook"] = {
			name = "Weathered Nook",
			short = "The northern wall of Thousand Needles hides a small cave known as the Weathered Nook, easy to pass by unless one knows to look for it.",
			full = "The northern wall of Thousand Needles hides a small cave known as the Weathered Nook, easy to pass by unless one knows to look for it. Here Dorn Plainstalker and Prate Cloudseer made their home, tucked away from the winds and dust of the canyon below.",
			source = "https://warcraft.wiki.gg/wiki/Weathered_Nook",
		},
		["weazels crater"] = {
			name = "Weazel's Crater",
			short = "A great scar opens in the northern Shimmering Flats, deep enough to swallow the light by midday. No one knows how it came to be, though its name hints at some figure called Weazel, whether finder or maker.",
			full = "A great scar opens in the northern Shimmering Flats, deep enough to swallow the light by midday. No one knows how it came to be, though its name hints at some figure called Weazel, whether finder or maker. Scattered rubble and lesser craters nearby suggest goblin or gnome tinkering gone wrong, some invention pushed too far.\n\nSaltstone basilisks have since claimed the pit as their own.",
			source = "https://warcraft.wiki.gg/wiki/Weazel's_Crater",
		},
		["whitereach post"] = {
			name = "Whitereach Post",
			short = "Whitereach Post is a small Horde camp along the road near Camp E'thok in Thousand Needles.",
			full = "Whitereach Post is a small Horde camp along the road near Camp E'thok in Thousand Needles.",
			source = "https://warcraft.wiki.gg/wiki/Whitereach_Post",
		},
		["windbreak canyon"] = {
			name = "Windbreak Canyon",
			short = "Windbreak Canyon lies between Freewind Post and the Shimmering Flats, its walls riddled with nests. Wind serpents claim the place as their own, rising on the currents that give the canyon its name.",
			full = "Windbreak Canyon lies between Freewind Post and the Shimmering Flats, its walls riddled with nests. Wind serpents claim the place as their own, rising on the currents that give the canyon its name. A path here leads on to the Weathered Nook.",
			source = "https://warcraft.wiki.gg/wiki/Windbreak_Canyon",
		},
	},
	-- Stonetalon Mountains: 18 subzones
	[1442] = {
		["blackwolf river"] = {
			name = "Blackwolf River",
			short = "The Blackwolf River flows from Cragpool Lake through Windshear Crag in the Stonetalon Mountains. Its waters run foul, poisoned by the Venture Company's deforestation of the valley.",
			full = "The Blackwolf River flows from Cragpool Lake through Windshear Crag in the Stonetalon Mountains. Its waters run foul, poisoned by the Venture Company's deforestation of the valley.",
			source = "https://warcraft.wiki.gg/wiki/Blackwolf_River",
		},
		["boulderslide cavern"] = {
			name = "Boulderslide Cavern",
			short = "At the end of Boulderslide Ravine, Boulderslide Cavern holds the nest of the Boulderslide kobolds. They mine a rare purple crystal called Resonite, touched with earthen magic, and guard every vein of it with their lives.",
			full = "At the end of Boulderslide Ravine, Boulderslide Cavern holds the nest of the Boulderslide kobolds. They mine a rare purple crystal called Resonite, touched with earthen magic, and guard every vein of it with their lives.",
			source = "https://warcraft.wiki.gg/wiki/Boulderslide_Cavern",
		},
		["boulderslide ravine"] = {
			name = "Boulderslide Ravine",
			short = "Boulderslide Ravine lies quiet along Webwinder Path, untouched by the wars troubling the lands around it. Rams pick their way along its slopes, and cliff stormers wheel overhead.",
			full = "Boulderslide Ravine lies quiet along Webwinder Path, untouched by the wars troubling the lands around it. Rams pick their way along its slopes, and cliff stormers wheel overhead.\n\nOpposite the ravine's cavern stands an abandoned cave, its barrels still stacked, its crude torches still standing though no one remains to light them. On its walls, tribal art endures, marked in a style that looks to be tauren work.",
			source = "https://warcraft.wiki.gg/wiki/Boulderslide_Ravine",
		},
		["camp aparaje"] = {
			name = "Camp Aparaje",
			short = "Camp Aparaje was a tauren village in the eastern Stonetalon Mountains, attacked by Grimtotem forces from Grimtotem Post under Grundig Darkcloud.",
			full = "Camp Aparaje was a tauren village in the eastern Stonetalon Mountains, attacked by Grimtotem forces from Grimtotem Post under Grundig Darkcloud. Makaba Flathoof had lived there with his daughter Kaya before the attack.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Aparaje",
		},
		["charred vale"] = {
			name = "Charred Vale",
			short = "The Charred Vale was once green, a valley in the southwest of Stonetalon where Bloodfury harpies made their nests and treants walked the forest as its guardians.",
			full = "The Charred Vale was once green, a valley in the southwest of Stonetalon where Bloodfury harpies made their nests and treants walked the forest as its guardians.\n\nThen the goblins of the Venture Company came to strip the vale for its wood and ore. The treants rose against them and drove the machines back, but the vale's spirits would not be calmed. The digging had woken something beneath the earth, and fire and elementals poured up through the broken ground where the forest had stood. The treants who turned the goblins away did not come back whole; whatever the goblins' weapons touched them with, it stayed, and they are counted among the vale's dangers now rather than its guardians.\n\nWhat remains is a valley of flame and lava, black trees standing in ash where green ones stood before. The druids of Sun Rock Retreat have taken up the work the treants once did, coaxing new growth from the burned ground in the hope that the vale will be a forest again rather than a wound in the mountains.",
			source = "https://warcraft.wiki.gg/wiki/Charred_Vale",
		},
		["cragpool lake"] = {
			name = "Cragpool Lake",
			short = "Cragpool Lake sits beneath the great wooden structure the Venture Company raised over Windshear Crag. Gerenzo Wrenchwhistle watches over the operation from this spot.",
			full = "Cragpool Lake sits beneath the great wooden structure the Venture Company raised over Windshear Crag. Gerenzo Wrenchwhistle watches over the operation from this spot.\n\nThe lake itself is off limits, claimed by Cragjaw, a fish grown monstrous in its still water.",
			source = "https://warcraft.wiki.gg/wiki/Cragpool_Lake",
		},
		["greatwood vale"] = {
			name = "Greatwood Vale",
			short = "The Greatwood Vale lies wooded in the foothills of the Stonetalon Mountains, reached by the Webwinder Path, with Malaka'jin to its south.",
			full = "The Greatwood Vale lies wooded in the foothills of the Stonetalon Mountains, reached by the Webwinder Path, with Malaka'jin to its south.\n\nThe vale's quiet broke when the Grimtotem tribe, under Grundig Darkcloud, fell upon Camp Aparaje and slaughtered nearly everyone there. Makaba Flathoof survived, and called for the Grimtotem in the vale to be hunted down in answer.",
			source = "https://warcraft.wiki.gg/wiki/Greatwood_Vale",
		},
		["grimtotem post"] = {
			name = "Grimtotem Post",
			short = "Grimtotem Post is the tribe's foothold in Stonetalon Mountains, its brutes, ruffians, sorcerers, and mercenaries patrolling the slopes around it.",
			full = "Grimtotem Post is the tribe's foothold in Stonetalon Mountains, its brutes, ruffians, sorcerers, and mercenaries patrolling the slopes around it. Grundig Darkcloud commands them here, holding the post for the Grimtotem's own purposes.",
			source = "https://warcraft.wiki.gg/wiki/Grimtotem_Post",
		},
		["malakajin"] = {
			name = "Malaka'jin",
			short = "Malaka'jin sits in the Stonetalon Mountains, south of the Grimtotem Post.",
			full = "Malaka'jin sits in the Stonetalon Mountains, south of the Grimtotem Post. It is a modest village, home to troll hunters who make their living selling their catches to those of the Horde who pass through, a foothold within sight of Grimtotem ground.",
			source = "https://warcraft.wiki.gg/wiki/Malaka'jin",
		},
		["mirkfallon lake"] = {
			name = "Mirkfallon Lake",
			short = "Mirkfallon Lake sits at the heart of Stonetalon Mountains, a wild basin thick with wyverns, slimes, and thunder lizards moving through its waters and shores.",
			full = "Mirkfallon Lake sits at the heart of Stonetalon Mountains, a wild basin thick with wyverns, slimes, and thunder lizards moving through its waters and shores. A hill rises from the lake's center, and above it, at Windshear Heights, the area's remaining wyverns still nest.",
			source = "https://warcraft.wiki.gg/wiki/Mirkfallon_Lake",
		},
		["sishir canyon"] = {
			name = "Sishir Canyon",
			short = "The canyon leads from the main road in the Stonetalon Mountains toward the Ruins of Eldre'thar, but no one passes through it easily.",
			full = "The canyon leads from the main road in the Stonetalon Mountains toward the Ruins of Eldre'thar, but no one passes through it easily. Sishir Canyon is given over entirely to the Deepmoss spiders, a monstrous brood whose eggs and webbing choke every ledge and hollow of the stone. Deep within, the greatest of them, Besseleth, waits among her kin.",
			source = "https://warcraft.wiki.gg/wiki/Sishir_Canyon",
		},
		["stonetalon peak"] = {
			name = "Stonetalon Peak",
			short = "Stonetalon Peak lies in a green valley at the far northwestern reach of the mountains that share its name, tended by the druids of nearby Talon Den.",
			full = "Stonetalon Peak lies in a green valley at the far northwestern reach of the mountains that share its name, tended by the druids of nearby Talon Den. The mountain is held sacred, and magic runs thick through its stone.\n\nDuring the Third War, Jaina Proudmoore and her expedition came here and set a base near the entrance to the caverns beneath the peak. Thrall and his Horde followed after, seeking the Oracle.\n\nIt has since become a hub for the night elves and the Alliance, its druids keeping watch over the valley.",
			source = "https://warcraft.wiki.gg/wiki/Stonetalon_Peak",
		},
		["sun rock retreat"] = {
			name = "Sun Rock Retreat",
			short = "Sun Rock Retreat sits hidden among the peaks south of Mirkfallon Lake in the Stonetalon Mountains, a place where the spirit world presses close against the living one.",
			full = "Sun Rock Retreat sits hidden among the peaks south of Mirkfallon Lake in the Stonetalon Mountains, a place where the spirit world presses close against the living one. Long before the Horde raised its banners here, tauren made pilgrimage to this stone to perform their rites of crossing into the spirit realm. It is said that An'she, the sun, once kissed the mountain where the retreat now stands.\n\nNow orcs and tauren hold Sun Rock Retreat together, the busiest gathering of Horde strength in these mountains, a hub of trade and labor, mending what the Venture Company and other malignant forces have torn from the land.",
			source = "https://warcraft.wiki.gg/wiki/Sun_Rock_Retreat",
		},
		["talon den"] = {
			name = "Talon Den",
			short = "High on Stonetalon Peak, the earth opens into the Talon Den, a barrow home to the Mirkfallon dryads and the keepers who share their name, watched over by night elf Cenarion Caretakers.",
			full = "High on Stonetalon Peak, the earth opens into the Talon Den, a barrow home to the Mirkfallon dryads and the keepers who share their name, watched over by night elf Cenarion Caretakers.",
			source = "https://warcraft.wiki.gg/wiki/Talon_Den",
		},
		["talondeep path"] = {
			name = "Talondeep Path",
			short = "The Talondeep Path is a winding tunnel joining Ashenvale to the Stonetalon Mountains, its passage uneven with small dead ends and strange hollows worn into the rock.",
			full = "The Talondeep Path is a winding tunnel joining Ashenvale to the Stonetalon Mountains, its passage uneven with small dead ends and strange hollows worn into the rock. It opens west of Mystral Lake on one end, and in the northwestern reach of Windshear Crag on the other. Nothing dwells there; it is simply a way through the mountains.",
			source = "https://warcraft.wiki.gg/wiki/Talondeep_Path",
		},
		["webwinder path"] = {
			name = "Webwinder Path",
			short = "The Webwinder Path runs between Malaka'jin and Mirkfallon Lake, through land that has sunk low on either side.",
			full = "The Webwinder Path runs between Malaka'jin and Mirkfallon Lake, through land that has sunk low on either side. West of Malaka'jin, the Horde built a barricade across the road to hold the Alliance from pressing further east.",
			source = "https://warcraft.wiki.gg/wiki/Webwinder_Path",
		},
		["windshear crag"] = {
			name = "Windshear Crag",
			short = "Windshear Crag was once old-growth forest, thick and green in its valley among the Stonetalon Mountains. It is not that now. What stands here is stumps, fouled water, and machinery that never quite stops creaking.",
			full = "Windshear Crag was once old-growth forest, thick and green in its valley among the Stonetalon Mountains. It is not that now. What stands here is stumps, fouled water, and machinery that never quite stops creaking.\n\nThe ruin has a name behind it: Gerenzo Wrenchwhistle, a leper gnome given the whole logging expedition to run under the Venture Company's banner. He built the Super Reaper 6000, a machine that can reduce the crag's oldest trees to sawdust, and he watches his work from a platform raised above Cragpool Lake, lord of everything the machine has cleared. His mastery of the place has made him expendable to those above him: Director Riddlevox, of the Undermine's Tinkers' Union, wants him dead, and the goblin Ziz Fizziks lurks in the crag, waiting to see the order carried out.\n\nIn the southeast corner of the crag, Windshear kobolds have taken the Windshear Mine for their own, tunneling after smoky iron ore.",
			source = "https://warcraft.wiki.gg/wiki/Windshear_Crag",
		},
		["windshear mine"] = {
			name = "Windshear Mine",
			short = "Windshear Mine lies at the end of Blackwolf River, within Windshear Crag. The Venture Company once worked its tin seams here, setting kobolds to the digging.",
			full = "Windshear Mine lies at the end of Blackwolf River, within Windshear Crag. The Venture Company once worked its tin seams here, setting kobolds to the digging.",
			source = "https://warcraft.wiki.gg/wiki/Windshear_Mine",
		},
	},
	-- Desolace: 20 subzones
	[1443] = {
		["bolgans hole"] = {
			name = "Bolgan's Hole",
			short = "In Gelkis Village, the cave called Bolgan's Hole shelters the clan's most prominent members, its khan Shaka among them.",
			full = "In Gelkis Village, the cave called Bolgan's Hole shelters the clan's most prominent members, its khan Shaka among them.\n\nDeep within grow blue crystals, the tears of Theradras, hoarded by the Gelkis shaman, who believe the stones carry the princess's protection.",
			source = "https://warcraft.wiki.gg/wiki/Bolgan's_Hole",
		},
		["ethel rethor"] = {
			name = "Ethel Rethor",
			short = "Off the northwest coast of Desolace, the sea has swallowed most of Ethel Rethor. Only a lone tower breaks the surface, joined to shore by a narrow bridge to a doorway that stays shut.",
			full = "Off the northwest coast of Desolace, the sea has swallowed most of Ethel Rethor. Only a lone tower breaks the surface, joined to shore by a narrow bridge to a doorway that stays shut. Naga have taken the drowned ruin for their own.",
			source = "https://warcraft.wiki.gg/wiki/Ethel_Rethor",
		},
		["gelkis village"] = {
			name = "Gelkis Village",
			short = "Gelkis Village sits ringed around a wide ravine in southwestern Desolace, seat of the Gelkis clan.",
			full = "Gelkis Village sits ringed around a wide ravine in southwestern Desolace, seat of the Gelkis clan. Bridges strung between the cliffs and bluffs of the ravine lead down to Bolgan's Hole, a cave cut into the southern mountain face, where the Gelkis Khan makes his residence.\n\nThe village lies hard against Desolace's main north-south road, so close that the road itself has become a danger to those who travel it. The Gelkis have pushed new huts out to the east side of the road leading toward Feralas, along the lake, spreading beyond the ravine that first sheltered them.",
			source = "https://warcraft.wiki.gg/wiki/Gelkis_Village",
		},
		["ghost walker post"] = {
			name = "Ghost Walker Post",
			short = "Ghost Walker Post stands beside the Kodo Graveyard in central Desolace, and the dead there shape everything about the place.",
			full = "Ghost Walker Post stands beside the Kodo Graveyard in central Desolace, and the dead there shape everything about the place. Tauren shamans keep watch over the bones, easing the spirits of fallen kodo into their next lives and, when the need arises, speaking with those who have already passed. Gurda Wildmane leads them, holding this exposed post with little more than the bare necessities to sustain it.\n\nUnlike Shadowprey Village, secure elsewhere in the region, Ghost Walker Post has no such safety. It is a forward camp built for war, not comfort, with no inn and nowhere to rest. It exists for one purpose: to carry the Horde's fight against the Burning Blade cultists and the centaur tribes ranging across Desolace.",
			source = "https://warcraft.wiki.gg/wiki/Ghost_Walker_Post",
		},
		["kodo graveyard"] = {
			name = "Kodo Graveyard",
			short = "The kodo of Desolace come here to die, their bones piled and bleached across the cracked earth. Disturb them and the dead do not stay quiet: apparitions of kodo rise from the ground to guard what remains of their kind.",
			full = "The kodo of Desolace come here to die, their bones piled and bleached across the cracked earth. Disturb them and the dead do not stay quiet: apparitions of kodo rise from the ground to guard what remains of their kind.",
			source = "https://warcraft.wiki.gg/wiki/Kodo_Graveyard",
		},
		["kolkar village"] = {
			name = "Kolkar Village",
			short = "The village on the eastern margin of Desolace is the seat of the Kolkar clan, the most prolific of the centaur clans across Kalimdor, with outposts as far off as the Barrens and Durotar.",
			full = "The village on the eastern margin of Desolace is the seat of the Kolkar clan, the most prolific of the centaur clans across Kalimdor, with outposts as far off as the Barrens and Durotar. The rival Magram press them constantly, for the feud between the clans never rests.",
			source = "https://warcraft.wiki.gg/wiki/Kolkar_Village",
		},
		["kormeks hut"] = {
			name = "Kormek's Hut",
			short = "The hut stands weathered in north-central Desolace. Inside dwells Willow, a member of the Twilight's Hammer, tending the place with unlikely warmth for one of that cult.",
			full = "The hut stands weathered in north-central Desolace. Inside dwells Willow, a member of the Twilight's Hammer, tending the place with unlikely warmth for one of that cult. Outside, in a pen scattered with kodo bones, Bibbly F'utzbuckle dances among the remains, delighted at the profit such bones might fetch.",
			source = "https://warcraft.wiki.gg/wiki/Kormek's_Hut",
		},
		["magram village"] = {
			name = "Magram Village",
			short = "Magram Village rises from a scatter of islands amid polluted yellow pools in southeastern Desolace, its huts linked by crude bridges thrown across the water.",
			full = "Magram Village rises from a scatter of islands amid polluted yellow pools in southeastern Desolace, its huts linked by crude bridges thrown across the water. Here the Magram clan makes its home, one of the centaur peoples locked in war with the Gelkis clan for dominance of these barren lands.",
			source = "https://warcraft.wiki.gg/wiki/Magram_Village",
		},
		["mannoroc coven"] = {
			name = "Mannoroc Coven",
			short = "Among the ruins of the night elves that lie broken across Desolace, one place bears a name no traveler speaks lightly.",
			full = "Among the ruins of the night elves that lie broken across Desolace, one place bears a name no traveler speaks lightly. Mannoroc Coven takes its name from Mannoroth, the dreaded Pit Lord, and the ground here remembers him. The earth was dead long before the demons came, but fel magic has blasted it further still, until the very air hangs thick with corruption and a deadly pall settles over anyone who crosses into it.\n\nThe Burning Blade cultists opened the way, tearing a number of portals into the world to summon through them the servants of the Burning Legion: infernals, succubi, felhounds and felguards that now prowl the ruins. Lord Azrethoc commands these demons, while the orc warlock Jugkar Grim'rod stands among them as the Burning Blade's own voice in the coven. Together they have built the largest gathering of demons anywhere in central Kalimdor, proof that the cultists' scheme has succeeded far beyond a warning.",
			source = "https://warcraft.wiki.gg/wiki/Mannoroc_Coven",
		},
		["nijels point"] = {
			name = "Nijel's Point",
			short = "Nijel's Point stands watch in the northern mountains of Desolace, an outpost held by the Alliance and the Cenarion Circle.",
			full = "Nijel's Point stands watch in the northern mountains of Desolace, an outpost held by the Alliance and the Cenarion Circle.\n\nKeeper Marandis came here with his dryad sisters, using the outpost as their base while they pursued Princess Theradras. Their purpose was to retrieve the body of Zaetar from the depths of Maraudon and carry it home to Stonetalon Mountains.\n\nAt the same time, the Stormwind Army stationed the Nijel's Point Guard here under Captain Pentigast, set against the threat of the centaur clans that held the region. Pentigast watched the rivalry between the Gelkis and Magram with a soldier's wariness, certain that whichever clan won out would grow bold enough to turn on the Alliance holdings nearby, and so sought to learn how the centaurs might be beaten by weighing one clan against the other.",
			source = "https://warcraft.wiki.gg/wiki/Nijel's_Point",
		},
		["ranazjar isle"] = {
			name = "Ranazjar Isle",
			short = "Ranazjar Isle is a small, rocky island off the northwest coast of Desolace, home to the serpentine naga.",
			full = "Ranazjar Isle is a small, rocky island off the northwest coast of Desolace, home to the serpentine naga. Among the stones stand night elven ruins, part of the same ancient city as Ethel Rethor, now silent above the naga that dwell there.",
			source = "https://warcraft.wiki.gg/wiki/Ranazjar_Isle",
		},
		["sargeron"] = {
			name = "Sargeron",
			short = "The city that stood here once bore a night elven name, lost since the War of the Ancients tore the world apart.",
			full = "The city that stood here once bore a night elven name, lost since the War of the Ancients tore the world apart. What remains is ruin, now called Sargeron by the Hatefury satyr who dwell there, in honor of their demon master Sargeras.\n\nThe ruins once held three holy sites of Elune: her cathedral, her temple, her sanctuary. Relics of that older faith still lie among the stones: Elune's Brazier, her Handmaiden, her Cup, and the Ancient Vortex Runestone.",
			source = "https://warcraft.wiki.gg/wiki/Sargeron",
		},
		["sartheris strand"] = {
			name = "Sar'theris Strand",
			short = "The coast where Desolace meets the sea is unlike the land behind it. While the interior lies grey and desolate, Sar'theris Strand is sunny, its grasses green.",
			full = "The coast where Desolace meets the sea is unlike the land behind it. While the interior lies grey and desolate, Sar'theris Strand is sunny, its grasses green. Sea giants wade its shallows, naga coil through its waters, and makrura scuttle along its sands.\n\nBelow Ethel Rethor, a small boat lies smashed on the beach, its wood splintered, whatever crew it carried gone.",
			source = "https://warcraft.wiki.gg/wiki/Sar'theris_Strand",
		},
		["scrabblescrews camp"] = {
			name = "Scrabblescrew's Camp",
			short = "Near the Kodo Graveyard in Desolace stands a small goblin camp.",
			full = "Near the Kodo Graveyard in Desolace stands a small goblin camp. It belongs to Smeed Scrabblescrew, an enterprising goblin who maintains a kodo caravan, driving the great beasts across the wastes for whatever profit the land allows.",
			source = "https://warcraft.wiki.gg/wiki/Scrabblescrew's_Camp",
		},
		["shadowbreak ravine"] = {
			name = "Shadowbreak Ravine",
			short = "Shadowbreak Ravine lies hidden in the mountains southeast of Shok'Thokar, a fold of Desolace few would stumble upon by chance.",
			full = "Shadowbreak Ravine lies hidden in the mountains southeast of Shok'Thokar, a fold of Desolace few would stumble upon by chance. Giant mushrooms rise among its rocks, and at its heart sits a summoning circle bound in massive chains, built by the Burning Blade cultists who made the ravine their haven.",
			source = "https://warcraft.wiki.gg/wiki/Shadowbreak_Ravine",
		},
		["shadowprey village"] = {
			name = "Shadowprey Village",
			short = "Shadowprey Village sits where the Sar'theris Strand meets the southern coast of Desolace, a fishing settlement of the trolls.",
			full = "Shadowprey Village sits where the Sar'theris Strand meets the southern coast of Desolace, a fishing settlement of the trolls. Its people make their living from the sea, and their catches are what keep the Ghost Walker Post fed further inland.",
			source = "https://warcraft.wiki.gg/wiki/Shadowprey_Village",
		},
		["tethris aran"] = {
			name = "Tethris Aran",
			short = "Night elven ruins lie scattered in northern Desolace, north of Thunder Axe Fortress, the remains of a settlement thought destroyed in the Great Sundering.",
			full = "Night elven ruins lie scattered in northern Desolace, north of Thunder Axe Fortress, the remains of a settlement thought destroyed in the Great Sundering. Nothing has been rebuilt. Only Desolace's wild creatures now move among the broken stones.",
			source = "https://warcraft.wiki.gg/wiki/Tethris_Aran",
		},
		["thunder axe fortress"] = {
			name = "Thunder Axe Fortress",
			short = "Thunder Axe Fortress stands in northwestern Desolace, given over to the Burning Blade cult.",
			full = "Thunder Axe Fortress stands in northwestern Desolace, given over to the Burning Blade cult. Behind its walls of stronghold, barracks, cave, and watch towers, the cultists under Kohor work toward summoning the demon Nazargen in his full strength, wary of calling him too soon, when he would be weak enough to be destroyed.\n\nThe fortress once held the Sceptre of Light, an artifact of terrible potency stolen by the Burning Blade from the naga. Azore Aldamort, serving the Argent Dawn, set himself to recovering it, and with aid succeeded in wresting it back from the cult's keeping.\n\nWithin these walls also dwelt Tyranis Malem, a name spoken with contempt among his own people, for he turned traitor to them and gave himself to the study of demonic magic, making Thunder Axe Fortress his refuge for such dark pursuits.",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Axe_Fortress",
		},
		["valley of bones"] = {
			name = "Valley of Bones",
			short = "The Valley of Bones is a crag on Desolace's southern edge, haunted by skeletons, centaur necromancers, and the ghosts of the slain Magram clan.",
			full = "The Valley of Bones is a crag on Desolace's southern edge, haunted by skeletons, centaur necromancers, and the ghosts of the slain Magram clan. Against the cliff walls rest a pair of massive skeletons, the Dead Goliaths, their origin unknown.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Bones",
		},
		["valley of spears"] = {
			name = "Valley of Spears",
			short = "The Valley of Spears, in western Desolace, is home to the Maraudine clan of centaur, reachable on foot only through narrow mountain passes to the south and east.",
			full = "The Valley of Spears, in western Desolace, is home to the Maraudine clan of centaur, reachable on foot only through narrow mountain passes to the south and east. At its southwestern end lies the entrance to Maraudon. Among the centaur, held captive, is Melizza Brimbuzzle.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Spears",
		},
	},
	-- Feralas: 28 subzones
	[1444] = {
		["camp mojache"] = {
			name = "Camp Mojache",
			short = "Camp Mojache sits where a swift stream feeds into Wildwind Lake.",
			full = "Camp Mojache sits where a swift stream feeds into Wildwind Lake. The tauren who hold this ground are known for the thickness of their hides and the courage of their braves, who guard travelers against the dangers of Feralas.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Mojache",
		},
		["dire maul"] = {
			name = "Dire Maul",
			short = "Twelve thousand years ago, a covert sect of night elf sorcerers raised Eldre'Thalas to guard Queen Azshara's most prized arcane secrets.",
			full = "Twelve thousand years ago, a covert sect of night elf sorcerers raised Eldre'Thalas to guard Queen Azshara's most prized arcane secrets. Among its Highborne, the arcanists known as the Shen'dralar lived in quiet splendor, and one of them, Millicent Serene, wrought the Fruit of Fertility, a vine whose aura of growth and protection let the whole city flourish.\n\nCut off from the Well of Eternity after the Great Sundering, the Highborne bound a demon, Immol'thar, and drew their power from his imprisonment. It sustained them for thousands of years, until the cost of holding him grew greater than what he gave. Their leader, Prince Tortheldrin, answered this by turning on his own people, slaughtering many of them to free enough power to keep the rest alive. The survivors retreated deeper into the ruins they once ruled, abandoning the rest of the city to whatever would come to dwell there.\n\nThe stone of Eldre'Thalas still stands, arcane energy bound within it by a craft none now remember, holding the shape of a city that fed itself on its own people to survive.",
			source = "https://warcraft.wiki.gg/wiki/Dire_Maul",
		},
		["dream bough"] = {
			name = "Dream Bough",
			short = "A great tree rises from a small island in the middle of Jademir Lake, its roots and branches holding one of the portals into the Emerald Dream.",
			full = "A great tree rises from a small island in the middle of Jademir Lake, its roots and branches holding one of the portals into the Emerald Dream. The Green dragonflight keeps watch over it, guarding the threshold against any who would tamper with the dream below.",
			source = "https://warcraft.wiki.gg/wiki/Dream_Bough",
		},
		["feathermoon stronghold"] = {
			name = "Feathermoon Stronghold",
			short = "Off the western coast of Feralas, on Sardor Isle, stands a fortress raised in the sea by General Shandris Feathermoon, who for ten thousand years has stood at Tyrande Whisperwind's side as her right hand among the Sentinels.",
			full = "Off the western coast of Feralas, on Sardor Isle, stands a fortress raised in the sea by General Shandris Feathermoon, who for ten thousand years has stood at Tyrande Whisperwind's side as her right hand among the Sentinels. She gave the stronghold her name, and it holds this stretch of Kalimdor's coast for the night elves still.\n\nOnly the sea joins it to the mainland, a boat crossing from the Forgotten Coast to the island dock.",
			source = "https://warcraft.wiki.gg/wiki/Feathermoon_Stronghold_(Classic)",
		},
		["feral scar vale"] = {
			name = "Feral Scar Vale",
			short = "In the High Wilderness of western Feralas lies Feral Scar Vale, claimed by the Feral Scar yeti who give it their name.",
			full = "In the High Wilderness of western Feralas lies Feral Scar Vale, claimed by the Feral Scar yeti who give it their name.",
			source = "https://warcraft.wiki.gg/wiki/Feral_Scar_Vale",
		},
		["forgotten coast"] = {
			name = "Forgotten Coast",
			short = "The Forgotten Coast runs the whole western edge of Feralas, where the land meets the Veiled Sea. Water elementals rise from the surf here, and sea giants stalk the shoreline.",
			full = "The Forgotten Coast runs the whole western edge of Feralas, where the land meets the Veiled Sea. Water elementals rise from the surf here, and sea giants stalk the shoreline.\n\nA murloc fishing village clings to this shore. Birds have been known to swoop in and carry off tadpoles, and the village has suffered raids by humans and gnolls in turn. Worst of all are the Gordunni ogres, who have preyed upon it for years, dragging murlocs off into captivity within the ruins of Dire Maul. A dozen or more have been taken this way, among them two named Murrl and Murrgly.",
			source = "https://warcraft.wiki.gg/wiki/Forgotten_Coast",
		},
		["frayfeather highlands"] = {
			name = "Frayfeather Highlands",
			short = "The Frayfeather Highlands belong to the Frayfeather hippogryphs, who nest in the high places there and give the land their name.",
			full = "The Frayfeather Highlands belong to the Frayfeather hippogryphs, who nest in the high places there and give the land their name. Among the crags their eggs lie hidden in scattered nests, guarded by the wheeling flocks that call the highlands home.",
			source = "https://warcraft.wiki.gg/wiki/Frayfeather_Highlands",
		},
		["gordunni outpost"] = {
			name = "Gordunni Outpost",
			short = "In the mountains north of Lariss Pavilion, the ground bears the mark of the Gordunni. Where Feralas is elsewhere green, the outpost lies withered and brown under the ogres' presence.",
			full = "In the mountains north of Lariss Pavilion, the ground bears the mark of the Gordunni. Where Feralas is elsewhere green, the outpost lies withered and brown under the ogres' presence.\n\nTwo caves mark the hills, a small one near the entrance and a great mound at the back, both held by the Gordunni who claim this blighted ground.",
			source = "https://warcraft.wiki.gg/wiki/Gordunni_Outpost",
		},
		["grimtotem compound"] = {
			name = "Grimtotem Compound",
			short = "The Grimtotem Compound, east of Dire Maul, is a home the Grimtotem tauren have made for themselves. In its southern section stands a large cage, holding captive sprite darters.",
			full = "The Grimtotem Compound, east of Dire Maul, is a home the Grimtotem tauren have made for themselves. In its southern section stands a large cage, holding captive sprite darters. East of the northern section, gnolls have made their own camps.",
			source = "https://warcraft.wiki.gg/wiki/Grimtotem_Compound",
		},
		["high wilderness"] = {
			name = "High Wilderness",
			short = "The High Wilderness spreads across western Feralas, from the Forgotten Coast to the Verdantis River.",
			full = "The High Wilderness spreads across western Feralas, from the Forgotten Coast to the Verdantis River. Bears, wolves, and hippogryphs roam its ancient trees, treants stand among the deeper groves, and yetis and ogres claim the wilder reaches beyond.",
			source = "https://warcraft.wiki.gg/wiki/High_Wilderness",
		},
		["isle of dread"] = {
			name = "Isle of Dread",
			short = "The Isle of Dread lies off the coast of Feralas, south of Sardor Isle, its central valley walled in on every side by unyielding cliffs save for a single approach in the southeast.",
			full = "The Isle of Dread lies off the coast of Feralas, south of Sardor Isle, its central valley walled in on every side by unyielding cliffs save for a single approach in the southeast. Within that hidden basin the chimaerok make their home, arcane-touched beasts and devourers alike, ruled over by Lord Lakmaeran. His flesh has been sought for stranger purposes than survival: rendered down and reshaped, it became a monstrous five-hundred-pound fowl devoured whole by the gnome wizard Narain Soothfancy.\n\nAt the northern end of the isle, a cave sinks into the rock unlike anything else known there, deep and strange in its making. A secret passage beneath the water leads through to an inner chamber that serves no purpose anyone has found beyond sheltering Lady Szallah in its depths. The cave and its naga are commanded by Lord Shalzaru, whose presence drew the attention of Feathermoon Stronghold, wary of the naga so close to their own shores.",
			source = "https://warcraft.wiki.gg/wiki/Isle_of_Dread",
		},
		["jademir lake"] = {
			name = "Jademir Lake",
			short = "Jademir Lake in northern Feralas holds a small island, Dream Bough, at its center. A portal into the Emerald Dream stands there, guarded by Lethlas and a number of green dragonspawn.",
			full = "Jademir Lake in northern Feralas holds a small island, Dream Bough, at its center. A portal into the Emerald Dream stands there, guarded by Lethlas and a number of green dragonspawn. Infected green whelps linger along the lake's northwestern shore.",
			source = "https://warcraft.wiki.gg/wiki/Jademir_Lake",
		},
		["lariss pavilion"] = {
			name = "Lariss Pavilion",
			short = "The Lariss Pavilion, night elf in its stonework, stands north of Camp Mojache in Feralas. Its dryads were once peaceful, but the Emerald Nightmare has corrupted them, and now they attack any who draw near.",
			full = "The Lariss Pavilion, night elf in its stonework, stands north of Camp Mojache in Feralas. Its dryads were once peaceful, but the Emerald Nightmare has corrupted them, and now they attack any who draw near.\n\nBeneath the Pavilion lies a hidden way down, known to Azj'Tordin, a Highborne who broke with Prince Tortheldrin and fled Dire Maul through it. He escaped with little, for an imp named Pusillin stole his book of incantations before he could vanish below, and he has kept to that passage ever since.",
			source = "https://warcraft.wiki.gg/wiki/Lariss_Pavilion",
		},
		["lower wilds"] = {
			name = "Lower Wilds",
			short = "The Lower Wilds fills the eastern reach of Feralas, where treants move among the trees and corrupted dryads walk, their gifts turned strange.",
			full = "The Lower Wilds fills the eastern reach of Feralas, where treants move among the trees and corrupted dryads walk, their gifts turned strange.",
			source = "https://warcraft.wiki.gg/wiki/Lower_Wilds",
		},
		["oneiros"] = {
			name = "Oneiros",
			short = "South of Jademir Lake in northern Feralas lie the ruins of Oneiros.",
			full = "South of Jademir Lake in northern Feralas lie the ruins of Oneiros.",
			source = "https://warcraft.wiki.gg/wiki/Oneiros",
		},
		["rage scar hold"] = {
			name = "Rage Scar Hold",
			short = "Rage Scar Hold is a dug-in cave in Feralas, holding the fiercest yetis in the area.",
			full = "Rage Scar Hold is a dug-in cave in Feralas, holding the fiercest yetis in the area. Scattered within are books and strange symbols, hinting at arcane study, or perhaps the remains of some unfortunate magus who met his end there.",
			source = "https://warcraft.wiki.gg/wiki/Rage_Scar_Hold",
		},
		["ruins of isildien"] = {
			name = "Ruins of Isildien",
			short = "The Ruins of Isildien are what remains of a great night elven city, broken ten thousand years ago. Gordunni ogres now nest among its fallen colonnades, ruling over stones raised by hands far older than their own.",
			full = "The Ruins of Isildien are what remains of a great night elven city, broken ten thousand years ago. Gordunni ogres now nest among its fallen colonnades, ruling over stones raised by hands far older than their own.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Isildien",
		},
		["ruins of ravenwind"] = {
			name = "Ruins of Ravenwind",
			short = "Northern Feralas holds the broken stones of Ravenwind, raised long ago by the Highborne of the kaldorei, much as Dire Maul was raised elsewhere.",
			full = "Northern Feralas holds the broken stones of Ravenwind, raised long ago by the Highborne of the kaldorei, much as Dire Maul was raised elsewhere. Little of that glory remains standing now. Northspring harpies have taken the ruins for their own, nesting among the fallen columns and empty halls.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Ravenwind",
		},
		["ruins of solarsal"] = {
			name = "Ruins of Solarsal",
			short = "Southwest of Feathermoon Stronghold, on Sardor Isle, the old stones of Solarsal still stand among the trees, night elven work long since abandoned to the wild.",
			full = "Southwest of Feathermoon Stronghold, on Sardor Isle, the old stones of Solarsal still stand among the trees, night elven work long since abandoned to the wild. The Hatecrest naga hold the ruins now, coiling through the broken columns where the elves once walked.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Solarsal",
		},
		["sardor isle"] = {
			name = "Sardor Isle",
			short = "Sardor Isle rises off the coast of Feralas, a small refuge held by the night elves under Shandris Feathermoon.",
			full = "Sardor Isle rises off the coast of Feralas, a small refuge held by the night elves under Shandris Feathermoon. Naga have crept onto its shores, and wolves range through what wild places remain, so the stronghold's watch is never idle.",
			source = "https://warcraft.wiki.gg/wiki/Sardor_Isle",
		},
		["shalzarus lair"] = {
			name = "Shalzaru's Lair",
			short = "South of Feathermoon Stronghold's island, at the northern end of the Isle of Dread, a twisting cave holds two chambers joined by a waterway.",
			full = "South of Feathermoon Stronghold's island, at the northern end of the Isle of Dread, a twisting cave holds two chambers joined by a waterway. Hatecrest sorceresses and serpent guards fill its length. Deep within dwells Shalzaru, master of the Hatecrest.",
			source = "https://warcraft.wiki.gg/wiki/Shalzaru's_Lair",
		},
		["thalanaar"] = {
			name = "Thalanaar",
			short = "Thalanaar stands quiet, a small outpost with little to draw travelers beyond its purpose.",
			full = "Thalanaar stands quiet, a small outpost with little to draw travelers beyond its purpose. Caryssia Moonhunter keeps her craft here, working hides and leather in the old tribal way, one of the few reasons anyone has cause to linger.",
			source = "https://warcraft.wiki.gg/wiki/Thalanaar",
		},
		["twin colossals"] = {
			name = "Twin Colossals",
			short = "The Twin Colossals rise on the western edge of Feralas, two vertical mountains so high they are the tallest point in the region, with the road to Desolace threading the gap between them.",
			full = "The Twin Colossals rise on the western edge of Feralas, two vertical mountains so high they are the tallest point in the region, with the road to Desolace threading the gap between them.\n\nAt the top of the eastern peak lies a small, deep pond, its water calm enough to fish, where Gregan Brewspewer can be found. From the summit the whole region opens out below.",
			source = "https://warcraft.wiki.gg/wiki/Twin_Colossals",
		},
		["verdantis river"] = {
			name = "Verdantis River",
			short = "The Verdantis River winds through central Feralas, southeast of the ruins of Dire Maul, cutting a quiet green thread through the tangled forest.",
			full = "The Verdantis River winds through central Feralas, southeast of the ruins of Dire Maul, cutting a quiet green thread through the tangled forest. Its waters hold Feralas ahi, found nowhere else in the world.",
			source = "https://warcraft.wiki.gg/wiki/Verdantis_River",
		},
		["wildwind lake"] = {
			name = "Wildwind Lake",
			short = "Wildwind Lake lies near Camp Mojache in Feralas, its waters quiet beneath the surrounding wilds, home to nothing more remarkable than what swims beneath its surface and the stillness that hangs over the camp nearby.",
			full = "Wildwind Lake lies near Camp Mojache in Feralas, its waters quiet beneath the surrounding wilds, home to nothing more remarkable than what swims beneath its surface and the stillness that hangs over the camp nearby.",
			source = "https://warcraft.wiki.gg/wiki/Wildwind_Lake",
		},
		["woodpaw den"] = {
			name = "Woodpaw Den",
			short = "In the heart of Feralas lies Woodpaw Den, warren to the Woodpaw gnolls. Here the Woodpaw Alphas hold sway over their kin, thick upon the ground in numbers few outsiders care to test.",
			full = "In the heart of Feralas lies Woodpaw Den, warren to the Woodpaw gnolls. Here the Woodpaw Alphas hold sway over their kin, thick upon the ground in numbers few outsiders care to test. South of the den stand the Darkmist Ruins, silent neighbors to the gnolls' clamor.",
			source = "https://warcraft.wiki.gg/wiki/Woodpaw_Den",
		},
		["woodpaw hills"] = {
			name = "Woodpaw Hills",
			short = "The Woodpaw Hills lie thick with forest, home to the gnolls of the Woodpaw clan.",
			full = "The Woodpaw Hills lie thick with forest, home to the gnolls of the Woodpaw clan. Their hold on the land is slipping, for in the southeasternmost reaches the ground has split open into what is now called the Writhing Deep, and the swarming things that burst up from beneath the earth have been driving the gnolls from their own territory. Where Woodpaw Alphas once led their tribe from the camps, they now hold only in the Woodpaw Den.",
			source = "https://warcraft.wiki.gg/wiki/Woodpaw_Hills",
		},
		["writhing deep"] = {
			name = "Writhing Deep",
			short = "The Writhing Deep, in southeastern Feralas, is given over to Hive Zukk'ash. The silithid there have poisoned the ground around them, driving nearby gnolls to frenzy and north against Camp Mojache.",
			full = "The Writhing Deep, in southeastern Feralas, is given over to Hive Zukk'ash. The silithid there have poisoned the ground around them, driving nearby gnolls to frenzy and north against Camp Mojache.\n\nWarriors from the camp cut down the silithid on the surface, but the hive's heart beneath the earth, packed with eggs, was never touched. Rexxar warns it is only a matter of time before the next generation hatches.",
			source = "https://warcraft.wiki.gg/wiki/Writhing_Deep",
		},
	},
	-- Dustwallow Marsh: 24 subzones
	[1445] = {
		["alcaz island"] = {
			name = "Alcaz Island",
			short = "Alcaz Island rises out of the sea off Dustwallow Marsh, thick with a tropical green that has no business growing so close to the marsh's grey mud, as though some older, warmer power once claimed this ground and never let go.",
			full = "Alcaz Island rises out of the sea off Dustwallow Marsh, thick with a tropical green that has no business growing so close to the marsh's grey mud, as though some older, warmer power once claimed this ground and never let go. The naga of the Strashaz hold it, myrmidons and sirens thick along its shores.\n\nYet during the war against Ahn'Qiraj, Doctor Weavil came to the island by flying machine and settled its hilltop with his minions, turning a stretch of the shore into a workshop of technological invention.",
			source = "https://warcraft.wiki.gg/wiki/Alcaz_Island",
		},
		["beezils wreck"] = {
			name = "Beezil's Wreck",
			short = "A goblin zeppelin bound south with supplies went down in the deepest reaches of Dustwallow Marsh, east of Tabetha's Farm.",
			full = "A goblin zeppelin bound south with supplies went down in the deepest reaches of Dustwallow Marsh, east of Tabetha's Farm. Its hull lies broken in the mud, cargo scattered among the wreckage, Seaforium Boosters still lying where they fell.",
			source = "https://warcraft.wiki.gg/wiki/Beezil's_Wreck",
		},
		["bloodfen burrow"] = {
			name = "Bloodfen Burrow",
			short = "A cave in south-western Dustwallow Marsh shelters an unusual number of Bloodfen raptors. Outside the entrance lie the remains of some settlement, torn apart by the creatures, its people now lost to the marsh mud.",
			full = "A cave in south-western Dustwallow Marsh shelters an unusual number of Bloodfen raptors. Outside the entrance lie the remains of some settlement, torn apart by the creatures, its people now lost to the marsh mud. Somewhere within, one part of Cortello's Riddle waits among the wreckage.",
			source = "https://warcraft.wiki.gg/wiki/Bloodfen_Burrow",
		},
		["bluefen"] = {
			name = "Bluefen",
			short = "Bluefen lies in northern Dustwallow Marsh, its low ground thick with reeds and standing water.",
			full = "Bluefen lies in northern Dustwallow Marsh, its low ground thick with reeds and standing water. Spiders, crocolisks, raptors, and marsh birds move through the fen unchecked, and Theramore infiltrators pass through it unseen among the reeds.",
			source = "https://warcraft.wiki.gg/wiki/Bluefen",
		},
		["brackenwall village"] = {
			name = "Brackenwall Village",
			short = "Brackenwall Village stands among huts and ogre mounds in northwest Dustwallow Marsh, home to the Stonemaul ogres and sworn to the Horde.",
			full = "Brackenwall Village stands among huts and ogre mounds in northwest Dustwallow Marsh, home to the Stonemaul ogres and sworn to the Horde. It was not always their home. The Stonemaul once held a village to the south, until the black dragonflight fell upon it and burned it to ruin. Overlord Mok'Morokk, who had taken up leadership after Rexxar, led the survivors north and raised Brackenwall in its place.\n\nMok'Morokk built his rule on staying put. When the ogre Draz'Zilb learned the attackers had been Onyxia's brood and brought the truth to him, Mok'Morokk would not act. Brackenwall was safe, no black dragons dwelt here, and that was enough for him. Draz'Zilb will not let the matter rest, and quietly weighs what it would take to see the Overlord fall and the Stonemaul led back to what they have lost.",
			source = "https://warcraft.wiki.gg/wiki/Brackenwall_Village",
		},
		["darkmist cavern"] = {
			name = "Darkmist Cavern",
			short = "A small mine sits in the northwest of Dustwallow Marsh, long since given over to spiders grown terrifyingly large in the dark.",
			full = "A small mine sits in the northwest of Dustwallow Marsh, long since given over to spiders grown terrifyingly large in the dark. The marsh folk call them the Darkmist Spiders, and the cavern Darkmist in turn, though none can say which name came first, the place or the creatures that claimed it.\n\nOutside the mine's mouth stand the ruins of small houses, half-sunk in the wet ground, all that remains of some settlement long forgotten.",
			source = "https://warcraft.wiki.gg/wiki/Darkmist_Cavern",
		},
		["den of flame"] = {
			name = "Den of Flame",
			short = "The Den of Flame was raised by the Stonemaul ogres as their mound, its stonework still bearing their craft. It lies west of the Stonemaul ruins, in marshland claimed by Onyxia.",
			full = "The Den of Flame was raised by the Stonemaul ogres as their mound, its stonework still bearing their craft. It lies west of the Stonemaul ruins, in marshland claimed by Onyxia.\n\nThe ogres are gone from it now. Black dragonkin have overrun the den, holding it as a nest of the black dragonflight. Only the old stonework and the Stonemaul banner, left standing within, recall its first builders.",
			source = "https://warcraft.wiki.gg/wiki/Den_of_Flame",
		},
		["dragonmurk"] = {
			name = "Dragonmurk",
			short = "In the southern reaches of Dustwallow Marsh lies a stretch of fetid ground called the Dragonmurk, thick with the whelps and spawn of the black dragonflight.",
			full = "In the southern reaches of Dustwallow Marsh lies a stretch of fetid ground called the Dragonmurk, thick with the whelps and spawn of the black dragonflight. Nearby stand the Den of Flame and the Stonemaul Ruins, both likewise overrun with black dragonspawn.",
			source = "https://warcraft.wiki.gg/wiki/Dragonmurk",
		},
		["dreadmurk shore"] = {
			name = "Dreadmurk Shore",
			short = "The shore between Theramore Isle and Northwatch Hold lies thick with the Mirefin murloc tribe, who claim the coastline and its scattered islands as their own.",
			full = "The shore between Theramore Isle and Northwatch Hold lies thick with the Mirefin murloc tribe, who claim the coastline and its scattered islands as their own. Sea turtles and other creatures share the waters around them.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmurk_Shore",
		},
		["dustwallow bay"] = {
			name = "Dustwallow Bay",
			short = "Dustwallow Bay is part of the Great Sea, reaching into the eastern coast of Dustwallow Marsh west of Theramore Isle.",
			full = "Dustwallow Bay is part of the Great Sea, reaching into the eastern coast of Dustwallow Marsh west of Theramore Isle. On a small island off the bay, in Tidefury Cove, the fisherman Nat Pagle keeps his solitary watch over the water.",
			source = "https://warcraft.wiki.gg/wiki/Dustwallow_Bay",
		},
		["emberstrifes den"] = {
			name = "Emberstrife's Den",
			short = "A wide cave opens into the reeking Wyrmbog, home to the black drake Emberstrife.",
			full = "A wide cave opens into the reeking Wyrmbog, home to the black drake Emberstrife. Here he tests young black dragonlings through trials of endurance and cruelty, for only those who prove worthy may go on to enter Onyxia's Lair.",
			source = "https://warcraft.wiki.gg/wiki/Emberstrife's_Den",
		},
		["foothold citadel"] = {
			name = "Foothold Citadel",
			short = "Foothold Citadel stands at the heart of Theramore Isle, headquarters of the Theramore Guard.",
			full = "Foothold Citadel stands at the heart of Theramore Isle, headquarters of the Theramore Guard.\n\nIt was here that Daelin Proudmoore met his end, when Thrall's forces stormed Theramore, led into the keep by Rexxar and his companions. The admiral who defied his daughter Jaina's peace with the orcs fell within these walls.",
			source = "https://warcraft.wiki.gg/wiki/Foothold_Citadel",
		},
		["lost point"] = {
			name = "Lost Point",
			short = "Lost Point, a decrepit scout tower once raised by Theramore in western Dustwallow Marsh, no longer serves its builders.",
			full = "Lost Point, a decrepit scout tower once raised by Theramore in western Dustwallow Marsh, no longer serves its builders. Theramore deserters hold it now, led by Balos Jacken, who knows of Private Hendel's hand in the kidnapping of a person of great importance.",
			source = "https://warcraft.wiki.gg/wiki/Lost_Point",
		},
		["north point tower"] = {
			name = "North Point Tower",
			short = "North Point Tower watches over northern Dustwallow Marsh beside a well-traveled road, held by a sizable contingent of Theramore guards.",
			full = "North Point Tower watches over northern Dustwallow Marsh beside a well-traveled road, held by a sizable contingent of Theramore guards. Since deserters seized Lost Point, this tower stands as Theramore's farthest outpost.",
			source = "https://warcraft.wiki.gg/wiki/North_Point_Tower",
		},
		["onyxias lair"] = {
			name = "Onyxia's Lair",
			short = "The passage into Onyxia's lair is shaped like the broodmother's own gaping jaw. Beyond it the path is lined with magma, the ground cracked and glowing with fire from below.",
			full = "The passage into Onyxia's lair is shaped like the broodmother's own gaping jaw. Beyond it the path is lined with magma, the ground cracked and glowing with fire from below. The stone ceiling above groans and shifts, loosing constant falls of rock, and the walls themselves weep lava where the heat cannot be held back. Onyxia carved this place herself, deep beneath the Dragonmurk, the dismal swamp within Dustwallow Marsh.\n\nShe is not like her kin. Where her father rules through brute force and her brother shapes twisted abominations to do his bidding, Onyxia works through whispers and charm, delighting in the tangled politics of mortals and bending them quietly to her own purposes. For a time she wore a stolen name, calling herself Katrana Prestor, and in that guise wound herself into the heart of Stormwind's court, working to unravel it from within. It was Marshal Windsor who saw through the mask and named her for what she was. Exposed, she fled the city and returned to her fiery hall beneath the marsh, where she remains, guarded still by her own kin, the black dragonflight.",
			source = "https://warcraft.wiki.gg/wiki/Onyxia's_Lair",
		},
		["quagmire"] = {
			name = "Quagmire",
			short = "The Quagmire is the sodden heart of Dustwallow Marsh, running between Lost Point and Dustwallow Bay, hemmed by Brackenwall Village to the north and the Dragonmurk to the south.",
			full = "The Quagmire is the sodden heart of Dustwallow Marsh, running between Lost Point and Dustwallow Bay, hemmed by Brackenwall Village to the north and the Dragonmurk to the south.\n\nCrocolisks lurk in its black water, oozes and spiders crawl its reeds, and Grimtotem tauren hold ground here, far from any kin who would claim them. It is better crossed than lingered in.",
			source = "https://warcraft.wiki.gg/wiki/Quagmire",
		},
		["sentry point"] = {
			name = "Sentry Point",
			short = "Sentry Point rises just across the bridge from Theramore, a scout tower built by the citadel to watch the road below. It stands unbroken, keeping its silent vigil over all who pass toward the city.",
			full = "Sentry Point rises just across the bridge from Theramore, a scout tower built by the citadel to watch the road below. It stands unbroken, keeping its silent vigil over all who pass toward the city.",
			source = "https://warcraft.wiki.gg/wiki/Sentry_Point",
		},
		["shady rest inn"] = {
			name = "Shady Rest Inn",
			short = "The Shady Rest Inn once stood near the border between Dustwallow Marsh and the Southern Barrens, a human-built waystop.",
			full = "The Shady Rest Inn once stood near the border between Dustwallow Marsh and the Southern Barrens, a human-built waystop.\n\nIt burned to the ground without warning. Two men might have named the culprits, Paval Reethe and Lieutenant Caldwell, but both were killed before either could speak the truth, and the burning remained unsolved.",
			source = "https://warcraft.wiki.gg/wiki/Shady_Rest_Inn",
		},
		["stonemaul ruins"] = {
			name = "Stonemaul Ruins",
			short = "Stonemaul Village once stood in Dustwallow Marsh, home to the ogres of the Stonemaul clan, until the warlord Kor'gall, having seized the ancient orcish axe Serathil, took the clan and ruled it through brutality.",
			full = "Stonemaul Village once stood in Dustwallow Marsh, home to the ogres of the Stonemaul clan, until the warlord Kor'gall, having seized the ancient orcish axe Serathil, took the clan and ruled it through brutality. It was here that Rexxar came and was refused entry, fighting his way in. Kor'gall offered him a place among the clan if he could survive the Gauntlet, a valley thick with deadly beasts. Rexxar endured it and returned, and was made Stonemaul. When Kor'gall refused to lend the clan to the Horde's war against Kul Tiras, Rexxar challenged him for leadership and killed him, then led the Stonemaul to war himself. Afterward he named Mok'Morokk to rule in his place and departed.\n\nMok'Morokk did not rule as Rexxar had. He took from his people rather than serving them, and when Onyxia's brood descended on the village and claimed it, he led the survivors away to safety and was content to remain there, far from the dragons, rather than fight to take the old home back.\n\nThe ruins stand now within Dragonmurk, infested with Firemane dragonspawn.",
			source = "https://warcraft.wiki.gg/wiki/Stonemaul_Ruins",
		},
		["swamplight manor"] = {
			name = "Swamplight Manor",
			short = "Swamplight Manor is a modest house on Witch Hill in Dustwallow Marsh, home to the cook \"Swamp Eye\" Jarl.",
			full = "Swamplight Manor is a modest house on Witch Hill in Dustwallow Marsh, home to the cook \"Swamp Eye\" Jarl.\n\nIn the garden outside, a pile of turned dirt hides something Jarl's cooking never explains: a report buried by an orcish spy, left beneath the soil to keep its secret from prying eyes.",
			source = "https://warcraft.wiki.gg/wiki/Swamplight_Manor",
		},
		["theramore isle"] = {
			name = "Theramore Isle",
			short = "After the Third War, Jaina Proudmoore led the survivors of Lordaeron across the sea to Kalimdor.",
			full = "After the Third War, Jaina Proudmoore led the survivors of Lordaeron across the sea to Kalimdor. On a rocky island off Dustwallow Marsh, they raised Theramore, a walled city meant to shelter what remained of the Alliance in a strange land.\n\nThe city stands ringed by a rectangular wall studded with cannon towers, broken only at the harbor, which two scout towers guard instead. At its heart rises Jaina's Tower, the Citadel, tallest building in Theramore, its many wooden-floored stories linked by winding stairs and warded against attack, holding Jaina's private quarters, her library, and the city's small throne room. Near it stands the Foothold Citadel, the guard quarters, where soldiers drill against practice dummies and recruits spar under the watch of priests ready to call on the Light the moment someone is hurt.\n\nThe marsh gives poor soil and poor timber, and Theramore's sailors grumble that the oaks the orcs cut above Orgrimmar are far better than anything Dustwallow offers. Even so, humans and orcs trade fish for surplus Durotarian crops, and for now the city's crime is low and its people, for the most part, at peace.",
			source = "https://warcraft.wiki.gg/wiki/Theramore_Isle",
		},
		["tidefury cove"] = {
			name = "Tidefury Cove",
			short = "Tidefury Cove lies at the end of Dustwallow Bay, south of Theramore Isle, its waters dotted with small islands and hidden reefs. It is treacherous water to sail.",
			full = "Tidefury Cove lies at the end of Dustwallow Bay, south of Theramore Isle, its waters dotted with small islands and hidden reefs. It is treacherous water to sail. Two ships lie broken upon its shallows, given over now to roaming makrura.\n\nAmong its islets sits Nat's Landing, home to the fisherman Nat Pagle.",
			source = "https://warcraft.wiki.gg/wiki/Tidefury_Cove",
		},
		["witch hill"] = {
			name = "Witch Hill",
			short = "Swamplight Manor stands at the center of Witch Hill, home to \"Swamp Eye\" Jarl. The Mirefin murlocs keep their camps nearby in the mire.",
			full = "Swamplight Manor stands at the center of Witch Hill, home to \"Swamp Eye\" Jarl. The Mirefin murlocs keep their camps nearby in the mire.",
			source = "https://warcraft.wiki.gg/wiki/Witch_Hill",
		},
		["wyrmbog"] = {
			name = "Wyrmbog",
			short = "South of the Dragonmurk in Dustwallow Marsh, the mire thickens into the Wyrmbog.",
			full = "South of the Dragonmurk in Dustwallow Marsh, the mire thickens into the Wyrmbog. Black dragons make their home here, and the earth opens into two hidden places: the entrance to Emberstrife's Den, and the lair of Onyxia herself.",
			source = "https://warcraft.wiki.gg/wiki/Wyrmbog",
		},
	},
	-- Tanaris: 23 subzones
	[1446] = {
		["abyssal sands"] = {
			name = "Abyssal Sands",
			short = "The sands here lie within Tanaris, a desert reaching in every direction.",
			full = "The sands here lie within Tanaris, a desert reaching in every direction.",
			source = "https://warcraft.wiki.gg/wiki/Abyssal_Sands",
		},
		["broken pillar"] = {
			name = "Broken Pillar",
			short = "South of Gadgetzan, near the Abyssal Sands, stands a small huddle of troll ruins known as the Broken Pillar.",
			full = "South of Gadgetzan, near the Abyssal Sands, stands a small huddle of troll ruins known as the Broken Pillar. There the goblin scientist Marvon Rivetseeker has made his camp, searching among the fallen stones for answers of his own.",
			source = "https://warcraft.wiki.gg/wiki/Broken_Pillar",
		},
		["caverns of time"] = {
			name = "Caverns of Time",
			short = "The Caverns of Time lie beneath the eastern sands of Tanaris, a winding labyrinth sealed against the world above. Here the bronze dragonflight keeps watch over the branching paths of time itself.",
			full = "The Caverns of Time lie beneath the eastern sands of Tanaris, a winding labyrinth sealed against the world above. Here the bronze dragonflight keeps watch over the branching paths of time itself. Since the world was young, this has been their sacred charge, laid upon them by the titans: to guard the caverns against mortal intrusion, for the meddling of lesser hands could unravel the flow of history. At the heart of the caverns stands a great hourglass.\n\nNozdormu, the Aspect of Time, dwells here among his flight, tending to a private hobby of collecting rare artifacts. In the aftermath of the Second War, the mage Krasus made his way into Nozdormu's lair by means of an Eon Rose, a device that let him step across the distance in an instant. Nozdormu was displeased at the intrusion, for it disturbed him in the midst of his collecting, and he made his displeasure known.",
			source = "https://warcraft.wiki.gg/wiki/Caverns_of_Time",
		},
		["dunemaul compound"] = {
			name = "Dunemaul Compound",
			short = "Dunemaul Compound is the mound of the Dunemaul ogres, sprawled across the sands of Tanaris, where the clan gathers in its earthen shelters beneath the sun.",
			full = "Dunemaul Compound is the mound of the Dunemaul ogres, sprawled across the sands of Tanaris, where the clan gathers in its earthen shelters beneath the sun.",
			source = "https://warcraft.wiki.gg/wiki/Dunemaul_Compound",
		},
		["eastmoon ruins"] = {
			name = "Eastmoon Ruins",
			short = "Stone terraces and cracked pillars mark Eastmoon Ruins, west of the Gaping Chasm in Tanaris, all that remains of a troll settlement long abandoned.",
			full = "Stone terraces and cracked pillars mark Eastmoon Ruins, west of the Gaping Chasm in Tanaris, all that remains of a troll settlement long abandoned. Dunemaul ogres claimed the crumbling stonework after the trolls, and hold it still.",
			source = "https://warcraft.wiki.gg/wiki/Eastmoon_Ruins",
		},
		["gadgetzan"] = {
			name = "Gadgetzan",
			short = "Gadgetzan rises out of the northern Tanaris desert under a permanent blanket of black fumes, the capital of the Steamwheedle Cartel, greatest of the goblin cartels.",
			full = "Gadgetzan rises out of the northern Tanaris desert under a permanent blanket of black fumes, the capital of the Steamwheedle Cartel, greatest of the goblin cartels. Here the goblins' creed governs everything: profit above loyalty. Both Horde and Alliance officially recognize the city as neutral ground, and goblin bruisers patrol its streets, ready to pound to a pulp anyone foolish enough to bring war into a place built on trade. Wallets, not banners, decide who is welcome.\n\nThat neutrality has never sat easy with everyone. The Wastewander bandits took the Noonshade Ruins and the Waterspring Field to the northeast. The goblins cared nothing for the old ruins, but the Waterspring Field was another matter: the water towers raised and maintained there by the Gadgetzan Water Company, under the desert's blazing sun, were the liquid gold that kept the city alive. The goblins were not about to surrender towers they had sweated for, and so mercenaries from far corners of the world were drawn into defending Gadgetzan's water against the bandits who would see it fall.",
			source = "https://warcraft.wiki.gg/wiki/Gadgetzan",
		},
		["gaping chasm"] = {
			name = "Gaping Chasm",
			short = "The Gaping Chasm lies swarming with Hazzali silithid, its hive complexes riddled through the rock in southeastern Tanaris.",
			full = "The Gaping Chasm lies swarming with Hazzali silithid, its hive complexes riddled through the rock in southeastern Tanaris.\n\nSenior Surveyor Fizzledowser once sent his junior, Scrimshank, down into the chasm to survey it. Scrimshank never came back out. He died among the hives, and only his gear was later recovered and carried back to Fizzledowser, who had sent him to his death without ever knowing it.",
			source = "https://warcraft.wiki.gg/wiki/Gaping_Chasm",
		},
		["lands end beach"] = {
			name = "Land's End Beach",
			short = "Land's End Beach lies at the southernmost point of Tanaris, where Kalimdor's southeastern corner meets the sea. The shore is quiet, marked mostly by the creatures that roam it.",
			full = "Land's End Beach lies at the southernmost point of Tanaris, where Kalimdor's southeastern corner meets the sea. The shore is quiet, marked mostly by the creatures that roam it. Surf gliders and duneshore crabs pick their way along the eastern stretch of sand, undisturbed.",
			source = "https://warcraft.wiki.gg/wiki/Land's_End_Beach",
		},
		["lost rigger cove"] = {
			name = "Lost Rigger Cove",
			short = "Tucked behind mountains on three sides, Lost Rigger Cove hides the Southsea Pirates' port on the Tanaris coast, its shipyard busy with a new vessel under construction.",
			full = "Tucked behind mountains on three sides, Lost Rigger Cove hides the Southsea Pirates' port on the Tanaris coast, its shipyard busy with a new vessel under construction.",
			source = "https://warcraft.wiki.gg/wiki/Lost_Rigger_Cove",
		},
		["noonshade ruins"] = {
			name = "Noonshade Ruins",
			short = "The Noonshade Ruins lie east of Gadgetzan, worn stone left behind by trolls long since gone. What purpose the ruins once served, or what became of those who raised them, the desert sands no longer say.",
			full = "The Noonshade Ruins lie east of Gadgetzan, worn stone left behind by trolls long since gone. What purpose the ruins once served, or what became of those who raised them, the desert sands no longer say.",
			source = "https://warcraft.wiki.gg/wiki/Noonshade_Ruins",
		},
		["noxious lair"] = {
			name = "Noxious Lair",
			short = "Southwestern Tanaris holds a wound in the sand where water once stood. Something broad and shallow, a river or a lake, lay across this ground before the silithid came, and what the Centipaar swarm found there it emptied.",
			full = "Southwestern Tanaris holds a wound in the sand where water once stood. Something broad and shallow, a river or a lake, lay across this ground before the silithid came, and what the Centipaar swarm found there it emptied. Western Tanaris was left dry for it.\n\nThe surface still shows the shape of what was lost. The land dips, sunken and hollowed, looking out over Un'Goro Crater as if it remembers being a shoreline. Here and there great claws stand erect out of the sand, twitching, as though buried creatures had frozen mid-strike. Around each claw the soil is black and wet with silithid goo, the only moisture left in a place that used to hold a lake.\n\nBelow the surface the Noxious Lair is a hive like any other the Centipaar have carved into Tanaris: humid, warm, eerie in its stillness, its tunnels coated in silithid acid.",
			source = "https://warcraft.wiki.gg/wiki/Noxious_Lair",
		},
		["sandsorrow watch"] = {
			name = "Sandsorrow Watch",
			short = "Sandsorrow Watch spreads west of Gadgetzan across the dry basin of Tanaris, held by the Farraki trolls and the zombies they have raised among their own dead.",
			full = "Sandsorrow Watch spreads west of Gadgetzan across the dry basin of Tanaris, held by the Farraki trolls and the zombies they have raised among their own dead.",
			source = "https://warcraft.wiki.gg/wiki/Sandsorrow_Watch",
		},
		["south seas"] = {
			name = "South Seas",
			short = "The waters south of the known continents open into a wide stretch of the Great Sea, carrying currents past islands whose names are known mostly to sailors.",
			full = "The waters south of the known continents open into a wide stretch of the Great Sea, carrying currents past islands whose names are known mostly to sailors. Zandalar rises from these waters, ancient home of the troll empire. Kezan lies among them too, a volcanic island holding its own people apart from the mainland powers.\n\nCloser to Stranglethorn Vale, the sea grows treacherous with reefs and hidden coves, the sort of waters where a captain either knows every rock by name or loses the ship. Small islands dot this stretch, some no more than a sandbar, others holding ruins whose builders have long vanished beneath the waves.\n\nWhat makes this sea worth naming is less any single battle fought upon it than the things it has swallowed and half-revealed again: sunken temples, drowned coasts, ruins glimpsed through clear water at low tide. It is a sea of edges and in-between places, running along the borders of Stranglethorn, Tanaris, and Uldum, carrying whatever the tides choose to bring to the shores it divides.",
			source = "https://warcraft.wiki.gg/wiki/South_Seas",
		},
		["southbreak shore"] = {
			name = "Southbreak Shore",
			short = "Southbreak Shore lies quiet along the southern edge of Tanaris, a flat stretch of beach mostly empty of life. Turtles and sea giants roam the surf.",
			full = "Southbreak Shore lies quiet along the southern edge of Tanaris, a flat stretch of beach mostly empty of life. Turtles and sea giants roam the surf.",
			source = "https://warcraft.wiki.gg/wiki/Southbreak_Shore",
		},
		["southmoon ruins"] = {
			name = "Southmoon Ruins",
			short = "The Southmoon Ruins are the remains of an old troll settlement in southern Tanaris, their stones weathered and half-buried in the desert sand.",
			full = "The Southmoon Ruins are the remains of an old troll settlement in southern Tanaris, their stones weathered and half-buried in the desert sand.",
			source = "https://warcraft.wiki.gg/wiki/Southmoon_Ruins",
		},
		["steamwheedle port"] = {
			name = "Steamwheedle Port",
			short = "Steamwheedle Port sits on Tanaris's eastern coast, a road running west to its mother city of Gadgetzan and a dock reaching toward Kezan.",
			full = "Steamwheedle Port sits on Tanaris's eastern coast, a road running west to its mother city of Gadgetzan and a dock reaching toward Kezan. It belongs to the Steamwheedle Cartel, goblins who deal with all comers so long as the gold is good.\n\nAmong the port's residents is Yeh'kinya, whose dealings stirred the return of Hakkar the Soulflayer.",
			source = "https://warcraft.wiki.gg/wiki/Steamwheedle_Port",
		},
		["thistleshrub valley"] = {
			name = "Thistleshrub Valley",
			short = "Thistleshrub Valley lies thick with giant cacti, strange for such barren desert to sustain living growth.",
			full = "Thistleshrub Valley lies thick with giant cacti, strange for such barren desert to sustain living growth. The thistleshrubs that once grew thick here have thinned in recent times, and desert blooms can now be found among them, though only sparsely.",
			source = "https://warcraft.wiki.gg/wiki/Thistleshrub_Valley",
		},
		["uldum"] = {
			name = "Uldum",
			short = "Uldum lies on the southern coast of Kalimdor, walled in by the Un'Goro Crater to the north, Tanaris to the east, and Silithus to the northwest.",
			full = "Uldum lies on the southern coast of Kalimdor, walled in by the Un'Goro Crater to the north, Tanaris to the east, and Silithus to the northwest. It is a place rich with the lore of the titans, its mountain passes shrouded so that no mortal eye may find the way in.",
			source = "https://warcraft.wiki.gg/wiki/Uldum",
		},
		["valley of the watchers"] = {
			name = "Valley of the Watchers",
			short = "The Valley of the Watchers guards southern Tanaris, where a great gate stands impenetrable against Uldum. Mountain giants, the Dune Smashers, roam here as its watchers.",
			full = "The Valley of the Watchers guards southern Tanaris, where a great gate stands impenetrable against Uldum. Mountain giants, the Dune Smashers, roam here as its watchers.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_the_Watchers",
		},
		["waterspring field"] = {
			name = "Waterspring Field",
			short = "Waterspring Field takes its name from the water towers that rise across it, drawing water up from reserves deep underground.",
			full = "Waterspring Field takes its name from the water towers that rise across it, drawing water up from reserves deep underground. The goblins of Gadgetzan built them, meaning to secure water for their desert operations in Tanaris.\n\nThat plan did not survive the Wastewanders. The nomadic bandits swept into the field and simply took it, seizing the towers for themselves without a thought for the goblins who raised them. They squat there still, glad enough of this ground after whatever they fled before -- they do not care to speak of the ogre camp that came before it, only that this is better.",
			source = "https://warcraft.wiki.gg/wiki/Waterspring_Field",
		},
		["wavestrider beach"] = {
			name = "Wavestrider Beach",
			short = "Wavestrider Beach runs along the eastern shore of Tanaris, the stretch of sand between Steamwheedle Port and Lost Rigger Cove.",
			full = "Wavestrider Beach runs along the eastern shore of Tanaris, the stretch of sand between Steamwheedle Port and Lost Rigger Cove. Desert Crawlers scuttle across the beach here, alongside the Steeljaw Snappers that share the same shoreline.",
			source = "https://warcraft.wiki.gg/wiki/Wavestrider_Beach",
		},
		["zalashjis den"] = {
			name = "Zalashji's Den",
			short = "Zalashji's Den still bears the name of whoever once denned here. Nothing in the tales that survive says who Zalashji was, or what became of the place after.",
			full = "Zalashji's Den still bears the name of whoever once denned here. Nothing in the tales that survive says who Zalashji was, or what became of the place after. Whether Zalashji still lives, or died here, or elsewhere, no one can say for certain.",
			source = "https://warcraft.wiki.gg/wiki/Zalashji's_Den",
		},
		["zulfarrak"] = {
			name = "Zul'Farrak",
			short = "Zul'Farrak was once a city of jungle, when Tanaris was still forest under the Gurubashi Empire.",
			full = "Zul'Farrak was once a city of jungle, when Tanaris was still forest under the Gurubashi Empire. When the Great Sundering tore the ancient world apart, the jungle burned away into desert, and the Farraki trolls who had built their city here found themselves stranded amid the sand. They endured, hardening into the Sandfury, a tribe known even among trolls for its ruthlessness and its dark mysticism.\n\nWithin the sun-blasted walls, troll legend speaks of Sul'thraze the Lasher, a blade said to instill fear and weakness in any foe it touched. Long ago the sword was broken in two, and it is whispered that both halves still lie somewhere inside the city, lost among its courts and temples.\n\nAt the heart of Zul'Farrak lies a sacred pool, and beneath its still water the Sandfury are said to keep something far older than themselves sleeping - a demigod whose waking would bring ruin down upon the city and all within it.",
			source = "https://warcraft.wiki.gg/wiki/Zul'Farrak",
		},
	},
	-- Azshara: 30 subzones
	[1447] = {
		["bay of storms"] = {
			name = "Bay of Storms",
			short = "The Bay of Storms lies off the eastern coast of Azshara, its waters known to travelers for the storms that gather there. Along its shore stand Scalebeard's Cave, Hetaera's Clutch, and the Temple of Arkkoran.",
			full = "The Bay of Storms lies off the eastern coast of Azshara, its waters known to travelers for the storms that gather there. Along its shore stand Scalebeard's Cave, Hetaera's Clutch, and the Temple of Arkkoran.",
			source = "https://warcraft.wiki.gg/wiki/Bay_of_Storms",
		},
		["bears head"] = {
			name = "Bear's Head",
			short = "Bear's Head takes its name from the furbolg villages scattered across the land, small outposts that watch the approaches to Timbermaw Hold and Ursolan farther north.",
			full = "Bear's Head takes its name from the furbolg villages scattered across the land, small outposts that watch the approaches to Timbermaw Hold and Ursolan farther north.\n\nOn a cliff above the villages stands Xylem's Tower, home to Archmage Xylem, who keeps company with several apprentices and associates who study and work within its walls.",
			source = "https://warcraft.wiki.gg/wiki/Bear's_Head",
		},
		["bitter reaches"] = {
			name = "Bitter Reaches",
			short = "The Bitter Reaches lie in northeastern Azshara, thick with hippogryphs, oozes, and chimaerae. Along the northern edge, mountain giants have driven off the lesser wildlife and claimed the ground for themselves.",
			full = "The Bitter Reaches lie in northeastern Azshara, thick with hippogryphs, oozes, and chimaerae. Along the northern edge, mountain giants have driven off the lesser wildlife and claimed the ground for themselves.",
			source = "https://warcraft.wiki.gg/wiki/Bitter_Reaches",
		},
		["blackmaw hold"] = {
			pending = true,
			name = "Blackmaw Hold",
			short = "",
			full = "",
			source = "",
		},
		["forlorn ridge"] = {
			name = "Forlorn Ridge",
			short = "Forlorn Ridge rises over western Azshara, dominating the land for miles around.",
			full = "Forlorn Ridge rises over western Azshara, dominating the land for miles around. Fortifications stand on its slopes in matching pairs, Alliance and Horde works raised within sight of each other -- built for a battle that has never come, and standing empty.",
			source = "https://warcraft.wiki.gg/wiki/Forlorn_Ridge",
		},
		["haldarr encampment"] = {
			name = "Haldarr Encampment",
			short = "The Haldarr Encampment lies thick with satyr in western Azshara, a corrupted host of goat-legged fiends, their fires burning northeast of Shadowsong Shrine and southwest of old Valormok.",
			full = "The Haldarr Encampment lies thick with satyr in western Azshara, a corrupted host of goat-legged fiends, their fires burning northeast of Shadowsong Shrine and southwest of old Valormok.",
			source = "https://warcraft.wiki.gg/wiki/Haldarr_Encampment",
		},
		["hetaeras clutch"] = {
			name = "Hetaera's Clutch",
			short = "Beneath the Bay of Storms off Azshara lies Hetaera's Clutch, a temple, home now to hydras.",
			full = "Beneath the Bay of Storms off Azshara lies Hetaera's Clutch, a temple, home now to hydras.",
			source = "https://warcraft.wiki.gg/wiki/Hetaera's_Clutch",
		},
		["jagged reef"] = {
			name = "Jagged Reef",
			short = "The Jagged Reef is the northern coast of Azshara, sandy beach broken again and again by jets of stone and small inlets of the sea. Rocks and shallows hide beneath the surface, making the shore hazardous to travel.",
			full = "The Jagged Reef is the northern coast of Azshara, sandy beach broken again and again by jets of stone and small inlets of the sea. Rocks and shallows hide beneath the surface, making the shore hazardous to travel. Murlocs, hydras, and makrura hold this coast, swimming the shallows or plodding the sand for food.",
			source = "https://warcraft.wiki.gg/wiki/Jagged_Reef",
		},
		["lake mennar"] = {
			name = "Lake Mennar",
			short = "The waters of Lake Mennar lie still at their center, though the ground on every side belongs to the dragonspawn.",
			full = "The waters of Lake Mennar lie still at their center, though the ground on every side belongs to the dragonspawn. Anyone who crosses that perimeter finds the lake itself free of danger, a place of quiet and refreshment amid the guarded shores.\n\nThis is one of the few places in the world, outside Northrend, where the blue dragonflight has made itself known. Only Mazthoril in Winterspring compares. Young azure whelplings are a common sight near these waters.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Mennar",
		},
		["legash encampment"] = {
			name = "Legash Encampment",
			short = "The Legashi satyr hold their encampment in northern Azshara, east of Ursolan.",
			full = "The Legashi satyr hold their encampment in northern Azshara, east of Ursolan.\n\nHere Archmage Xylem once found a grimoire, a discovery that drew notice to this otherwise unremarkable camp of fel-touched creatures.",
			source = "https://warcraft.wiki.gg/wiki/Legash_Encampment",
		},
		["legashi encampment"] = {
			pending = true,
			name = "Legashi Encampment",
			short = "",
			full = "",
			source = "",
		},
		["legashi stronghold"] = {
			pending = true,
			name = "Legashi Stronghold",
			short = "",
			full = "",
			source = "",
		},
		["ravencrest monument"] = {
			name = "Ravencrest Monument",
			short = "The cliffs at Azshara's southern tip bear the remains of a colossus, though little now remains to justify the word.",
			full = "The cliffs at Azshara's southern tip bear the remains of a colossus, though little now remains to justify the word. Only the broken legs still stand, planted above the sea, while the rest of the great figure lies scattered across the stone around them, or has slipped beneath the waves below.\n\nThe Spitelash naga hold the ruins now. The place cannot be reached from the water; anyone seeking it must come overland and cross the bridge that leads out past the Ruins of Eldarath, to stand beneath the toppled legs of something that was once, undoubtedly, impressive to behold.",
			source = "https://warcraft.wiki.gg/wiki/Ravencrest_Monument",
		},
		["rethress sanctum"] = {
			name = "Rethress Sanctum",
			short = "Rethress Sanctum stands broken among the Ruined Reaches, southwest of the Ravencrest Monument. No one keeps it now. Murlocs and makrura wander through its fallen stones, the only ones who come here at all.",
			full = "Rethress Sanctum stands broken among the Ruined Reaches, southwest of the Ravencrest Monument. No one keeps it now. Murlocs and makrura wander through its fallen stones, the only ones who come here at all.",
			source = "https://warcraft.wiki.gg/wiki/Rethress_Sanctum",
		},
		["ruined reaches"] = {
			name = "Ruined Reaches",
			short = "The southern coast of Azshara wears its ruin plainly. Cliffs and beaches break into inlets, and the water hides shallows that have caught more hulls than any sailor cares to count.",
			full = "The southern coast of Azshara wears its ruin plainly. Cliffs and beaches break into inlets, and the water hides shallows that have caught more hulls than any sailor cares to count. Wrecked ships lie half-buried in sand alongside older, stranger ruins whose builders are gone. Murlocs, hydras, and makrura haunt the shoreline, and even those who know the coast tread carefully along it.\n\nOn the western shores, above the beach, a gnomish building stands on a hill, reached only by a steep path from inland. Blimo and Jubie Gadgetspring have made their home and trade here. Upstairs, in their private quarters, sits a third bed. No one knows who it belongs to, or whether anyone sleeps in it at all.",
			source = "https://warcraft.wiki.gg/wiki/Ruined_Reaches",
		},
		["ruins of eldarath"] = {
			name = "Ruins of Eldarath",
			short = "Before the world was broken, Eldarath rose as one of the great strongholds of the Highborne, a city of arcane learning where the most powerful mages carved runes and tablets into stone and left them standing in public places, so that any who passed might ponder their insights into the arcane.",
			full = "Before the world was broken, Eldarath rose as one of the great strongholds of the Highborne, a city of arcane learning where the most powerful mages carved runes and tablets into stone and left them standing in public places, so that any who passed might ponder their insights into the arcane.\n\nThe city did not fall quietly. During the War of the Ancients, the Kaldorei Resistance made a stand here against the Burning Legion. When the Great Sundering tore the world apart, Eldarath could not endure it -- most of the city crumbled away and sank into the waters of the Bay of Storms below.\n\nWhat remains clings to the eastern cliffs, a broken cluster of towers long shunned by the night elves who once called it home. Naga have claimed the ruins now, and the warlord Krellian rules what is left from the Temple of Zin-Malor. Among the wreckage, the runic tablets of the old Highborne still stand, their arcane wisdom untouched by the ages since.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Eldarath",
		},
		["scalebeards cave"] = {
			name = "Scalebeard's Cave",
			short = "A cave on a tiny island in the Bay of Storms bears the name of Scalebeard, a rare old turtle. It is his home, though seldom his resting place, for he prefers to hunt far off in the Great Sea, leaving the den empty.",
			full = "A cave on a tiny island in the Bay of Storms bears the name of Scalebeard, a rare old turtle. It is his home, though seldom his resting place, for he prefers to hunt far off in the Great Sea, leaving the den empty.",
			source = "https://warcraft.wiki.gg/wiki/Scalebeard's_Cave",
		},
		["shadowsong shrine"] = {
			name = "Shadowsong Shrine",
			short = "A ruin-covered hill in western Azshara, the Shadowsong Shrine keeps no clear record of why it bears that name.",
			full = "A ruin-covered hill in western Azshara, the Shadowsong Shrine keeps no clear record of why it bears that name. It shares its name with Jarod Shadowsong, who led the resistance in the War of the Ancients, and his sister Maiev, the warden remembered for holding Illidan Stormrage captive after his betrayal at Mount Hyjal. What either has to do with this hill, no one can say.\n\nWhat can be said is what walks there. Ghosts of the highborne linger among the stones, hungry for any living thing that draws near.",
			source = "https://warcraft.wiki.gg/wiki/Shadowsong_Shrine",
		},
		["shattered strand"] = {
			name = "Shattered Strand",
			short = "The Shattered Strand runs along the north side of the Bay of Storms in Azshara, thick with hydras, sea giants, makrura, and murlocs, each holding their own stretch of sand.",
			full = "The Shattered Strand runs along the north side of the Bay of Storms in Azshara, thick with hydras, sea giants, makrura, and murlocs, each holding their own stretch of sand. The Temple of Arkkoran and the Tower of Eldara rise from the shore despite the crowding of claws and tentacles.\n\nGoblins, too, have staked claims along this coast, speculating on the beachfront property amid all the teeth and tide.",
			source = "https://warcraft.wiki.gg/wiki/Shattered_Strand",
		},
		["southfury river"] = {
			name = "Southfury River",
			short = "The Southfury rises high on Mount Hyjal, spilling from a mountain lake in a fall that drops thunderously into the lowlands.",
			full = "The Southfury rises high on Mount Hyjal, spilling from a mountain lake in a fall that drops thunderously into the lowlands. From there it runs wide and swift, cutting the land in two: it marks where Ashenvale gives way to Azshara, and further south where the Barrens ends and Durotar begins. At its mouth the river throws itself over a last cascade into the Great Sea, just northeast of the goblin port of Ratchet.\n\nBridges cross its length, one linking Azshara to Ashenvale, another joining Durotar to the Barrens.\n\nThe river still feeds the fields along its banks, still turns the soil green where it runs.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["southridge beach"] = {
			name = "Southridge Beach",
			short = "Southridge Beach lines the southern edge of the Bay of Storms, its sands strewn with ruins of the once-great city of Eldarath.",
			full = "Southridge Beach lines the southern edge of the Bay of Storms, its sands strewn with ruins of the once-great city of Eldarath. Naga now hold the shore, sharing it with makrura, hydras, murlocs, and the occasional sea giant risen from deeper water.",
			source = "https://warcraft.wiki.gg/wiki/Southridge_Beach",
		},
		["storm cliffs"] = {
			name = "Storm Cliffs",
			short = "The Storm Cliffs rise in Azshara, claimed by the Spitelash naga who dwell among the rock. At the cliffs' far eastern edge stands the Ravencrest Monument, a lone marker overlooking the naga-held stone.",
			full = "The Storm Cliffs rise in Azshara, claimed by the Spitelash naga who dwell among the rock. At the cliffs' far eastern edge stands the Ravencrest Monument, a lone marker overlooking the naga-held stone.",
			source = "https://warcraft.wiki.gg/wiki/Storm_Cliffs",
		},
		["talrendis point"] = {
			name = "Talrendis Point",
			short = "Talrendis Point stands in southwestern Azshara, its two guard towers watching the border with Ashenvale, and a moonwell still waters the southern ground.",
			full = "Talrendis Point stands in southwestern Azshara, its two guard towers watching the border with Ashenvale, and a moonwell still waters the southern ground.\n\nThe Point began as nothing more than a small night elven encampment, a watch kept at the forest's edge.",
			source = "https://warcraft.wiki.gg/wiki/Talrendis_Point",
		},
		["temple of arkkoran"] = {
			name = "Temple of Arkkoran",
			short = "The Temple of Arkkoran once belonged to the worship of Elune, its stones raised on the northeastern shores of Azshara. That sanctity is long gone.",
			full = "The Temple of Arkkoran once belonged to the worship of Elune, its stones raised on the northeastern shores of Azshara. That sanctity is long gone. The sea giant Arkkoroc now dwells at its summit, guarded by murlocs and makrura that fall upon anyone who draws near. The surrounding shoreline, the Shattered Strand, offers no safer passage, watched over by hydras and sea giants as aggressive as Arkkoroc himself.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Arkkoran",
		},
		["temple of zin malor"] = {
			name = "Temple of Zin-Malor",
			short = "The Temple of Zin-Malor stands among the Ruins of Eldarath, its stones shaped in the likeness of the nearby Temple of Arkkoran, and of the Temple of the Moon later raised in Darnassus.",
			full = "The Temple of Zin-Malor stands among the Ruins of Eldarath, its stones shaped in the likeness of the nearby Temple of Arkkoran, and of the Temple of the Moon later raised in Darnassus. It was built in devotion to Elune, in the days before the night elves turned to arcane magic.\n\nWithin it once rested the Crystal of Zin-Malor, a gift meant to carry the Highborne a message: that they had no true need of arcane magic at all. The crystal is gone now, carried off long ago.\n\nThe temple has since fallen to the Spitelash tribe of naga. Warlord Krellian rules there now, taking for himself the place of honor once reserved for the worship of the goddess.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Zin-Malor",
		},
		["thalassian base camp"] = {
			name = "Thalassian Base Camp",
			short = "The hill above the Legash camps belongs to blood elves, its slopes broken into small fortified stations under Magus Rimtori.",
			full = "The hill above the Legash camps belongs to blood elves, its slopes broken into small fortified stations under Magus Rimtori. She struck a bargain with the Horde, promising a share of whatever her expedition unearthed in exchange for gold and steel to protect it. The bargain did not hold. Rimtori took the funding and gave nothing back, and word of the betrayal has spread until vengeance is said to be owed her and her followers in kind.\n\nRimtori herself is rarely at the camp, given over to exploring Azshara under a guard of her own choosing, leaving Magister Hawkhelm to hold the hill in her absence. What the two of them are truly after is not gold. On one of the camp's ridges lies a Kaldorei Tome of Summoning, a thing capable of calling demons into the world, and its presence there marks the expedition for what it is: not a hunt for treasure, but something darker dressed as one.",
			source = "https://warcraft.wiki.gg/wiki/Thalassian_Base_Camp",
		},
		["thalassian vanguard camp"] = {
			pending = true,
			name = "Thalassian Vanguard Camp",
			short = "",
			full = "",
			source = "",
		},
		["tower of eldara"] = {
			name = "Tower of Eldara",
			short = "The Tower of Eldara stands on the far northeastern tip of land above the Bay of Storms, its sandy shore patrolled by murlocs, makrura, and hydras.",
			full = "The Tower of Eldara stands on the far northeastern tip of land above the Bay of Storms, its sandy shore patrolled by murlocs, makrura, and hydras. It once belonged to the night elven civilization that spread across this coast, but the tower stands closed and abandoned now.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Eldara",
		},
		["ursolan"] = {
			name = "Ursolan",
			short = "Ursolan takes its name from Ursol, the bear demigod revered by the furbolg race. It is now the site of an extensive Timbermaw furbolg settlement, stretching south through the Hold to Bear's Head.",
			full = "Ursolan takes its name from Ursol, the bear demigod revered by the furbolg race. It is now the site of an extensive Timbermaw furbolg settlement, stretching south through the Hold to Bear's Head.",
			source = "https://warcraft.wiki.gg/wiki/Ursolan",
		},
		["valormok"] = {
			name = "Valormok",
			short = "Valormok is a Horde outpost in Azshara, found in the northwest, north of the Haldarr Encampment. The warriors stationed there endure hard times but hold to their hope.",
			full = "Valormok is a Horde outpost in Azshara, found in the northwest, north of the Haldarr Encampment. The warriors stationed there endure hard times but hold to their hope.\n\nThat hope was betrayed from within. Belgrom Rockmaul had sent Magus Rimtori, a blood elf, out with a company of orc warriors to find riches and powerful artifacts in the region. Rimtori found what she sought, and rather than share the discovery she turned on the warriors who had escorted her, killing them and claiming the spoils for herself. Ag'tor Bloodfist, who leads the camp, will not let the slaughter go unanswered. He seeks warriors to avenge his fallen and Rockmaul's wounded pride, and to see Magus Rimtori dead in her camp nearby.",
			source = "https://warcraft.wiki.gg/wiki/Valormok",
		},
	},
	-- Felwood: 18 subzones
	[1448] = {
		["bloodvenom falls"] = {
			name = "Bloodvenom Falls",
			short = "Bloodvenom Falls tumbles down from the high places of Felwood, its waters fouled at the source.",
			full = "Bloodvenom Falls tumbles down from the high places of Felwood, its waters fouled at the source. From here the Bloodvenom River is born, carrying the taint downward until it spills into Darkshore as the sickened Wildbend River.",
			source = "https://warcraft.wiki.gg/wiki/Bloodvenom_Falls",
		},
		["bloodvenom post"] = {
			name = "Bloodvenom Post",
			short = "Bloodvenom Post stands on the high cliffs above Darkshore, where the Bloodvenom River cuts through Felwood.",
			full = "Bloodvenom Post stands on the high cliffs above Darkshore, where the Bloodvenom River cuts through Felwood. Its architecture and the tauren who guard it mark it as a tauren founding, a small Horde toehold watching over the coast below.\n\nIt is reached by a dark trail that follows the river's south bank westward from the stone path running through Felwood, curling around the hillside to the post itself.",
			source = "https://warcraft.wiki.gg/wiki/Bloodvenom_Post",
		},
		["bloodvenom river"] = {
			name = "Bloodvenom River",
			short = "The Bloodvenom River runs black through Felwood, its corruption spreading beyond the zone until it surfaces again as the Wildbend River in Darkshore.",
			full = "The Bloodvenom River runs black through Felwood, its corruption spreading beyond the zone until it surfaces again as the Wildbend River in Darkshore. Noxious oozes crawl its banks, and the wildlife nearby has turned venomous. No one drinks from it, and no one swims in it.",
			source = "https://warcraft.wiki.gg/wiki/Bloodvenom_River",
		},
		["deadwood village"] = {
			name = "Deadwood Village",
			short = "The Deadwood furbolgs built their village in southern Felwood behind walls of heavy timber, sturdier structures raised within.",
			full = "The Deadwood furbolgs built their village in southern Felwood behind walls of heavy timber, sturdier structures raised within. Like their kin across the corrupted forest, they succumbed to Felwood's taint, turning hostile and twisted.",
			source = "https://warcraft.wiki.gg/wiki/Deadwood_Village",
		},
		["emerald sanctuary"] = {
			name = "Emerald Sanctuary",
			short = "The Emerald Sanctuary stands in southeastern Felwood, a camp of the Emerald Circle druids. From here they watch Jaedenar, working to snuff out the demonic corruption spreading from it before it consumes more of the land.",
			full = "The Emerald Sanctuary stands in southeastern Felwood, a camp of the Emerald Circle druids. From here they watch Jaedenar, working to snuff out the demonic corruption spreading from it before it consumes more of the land.",
			source = "https://warcraft.wiki.gg/wiki/Emerald_Sanctuary",
		},
		["felpaw village"] = {
			name = "Felpaw Village",
			short = "Felpaw Village stands at the northern edge of Felwood, near the entrance to Timbermaw Hold.",
			full = "Felpaw Village stands at the northern edge of Felwood, near the entrance to Timbermaw Hold. It belongs to the Deadwood, furbolgs whose corruption has turned them from their kin, and their taint still marks the ground they hold.",
			source = "https://warcraft.wiki.gg/wiki/Felpaw_Village",
		},
		["irontree cavern"] = {
			name = "Irontree Cavern",
			short = "Deep within the cave, the twisted wood of the Warpwoods has taken root, giving rise to Shredders and Moss Flayers that stalk the dark in place of any living guardian.",
			full = "Deep within the cave, the twisted wood of the Warpwoods has taken root, giving rise to Shredders and Moss Flayers that stalk the dark in place of any living guardian.",
			source = "https://warcraft.wiki.gg/wiki/Irontree_Cavern",
		},
		["irontree woods"] = {
			name = "Irontree Woods",
			short = "The Irontree Woods once stood as a peaceful glade in northern Felwood, before the corruption of the Burning Legion twisted it into something else.",
			full = "The Irontree Woods once stood as a peaceful glade in northern Felwood, before the corruption of the Burning Legion twisted it into something else. Three great Ancients of the night elves lived here, living trees named Hastat, Stoma and Vartrus. The corruption did not spare them: all three were petrified where they stood and remain entombed in the woods still, dead among the blight that killed them.\n\nYet something has refused to stay dead. Moonwell water poured into the heart of the woods gave rise to a seedling. Tended and grown, it blossomed, then returned to the ground where it was born, rooted among the petrified dead, waiting to stand as an Ancient in their place.",
			source = "https://warcraft.wiki.gg/wiki/Irontree_Woods",
		},
		["jadefire glen"] = {
			name = "Jadefire Glen",
			short = "In the corrupted woods of southern Felwood, Jadefire Glen shelters a camp of satyr, demonic creatures who have made the tainted hollow their own, thriving amid its rot and spreading the corruption further through the trees around them.",
			full = "In the corrupted woods of southern Felwood, Jadefire Glen shelters a camp of satyr, demonic creatures who have made the tainted hollow their own, thriving amid its rot and spreading the corruption further through the trees around them.",
			source = "https://warcraft.wiki.gg/wiki/Jadefire_Glen",
		},
		["jadefire run"] = {
			name = "Jadefire Run",
			short = "In northern Felwood lies Jadefire Run, home to the most powerful satyrs in the region. Caution is warranted for any who venture near.",
			full = "In northern Felwood lies Jadefire Run, home to the most powerful satyrs in the region. Caution is warranted for any who venture near. Its structures follow demonic rather than mortal design.",
			source = "https://warcraft.wiki.gg/wiki/Jadefire_Run",
		},
		["jaedenar"] = {
			name = "Jaedenar",
			short = "Jaedenar rises out of ground that once belonged to the night elves, its stones older than the corruption that now claims them.",
			full = "Jaedenar rises out of ground that once belonged to the night elves, its stones older than the corruption that now claims them. Beneath its ruins lie two druidic barrow dens, sacred once, and it is on this desecrated foundation that the Shadow Council built its dominion, naming the place itself in worship of Kil'jaeden the Deceiver.\n\nAfter the Third War, the ruins passed into the hands of Lord Banehollow and the Shadow Council he led. Orcish and Forsaken warlocks filled its halls, and they did not come alone: succubi, felhunters, felguards, and satyrs moved among them. At its heart stands the Shadow Hold, the Council's seat of power on Azeroth, and beside it the Shrine of the Deceiver, raised in Kil'jaeden's name.",
			source = "https://warcraft.wiki.gg/wiki/Jaedenar",
		},
		["morlosaran"] = {
			name = "Morlos'Aran",
			short = "Morlos'Aran once stood as a great night elf settlement, raised before the Great Sundering tore the world apart.",
			full = "Morlos'Aran once stood as a great night elf settlement, raised before the Great Sundering tore the world apart. Now it lies in ruin at the southern edge of Felwood, one among several such places, like Ameth'Aran, Bashal'Aran, Ordil'Aran, and Tethris'Aran, all once thriving cities, all now only stone and memory of a golden age long lost.",
			source = "https://warcraft.wiki.gg/wiki/Morlos'Aran",
		},
		["ruins of constellas"] = {
			name = "Ruins of Constellas",
			short = "The broken columns here once belonged to a night elven settlement near Mount Hyjal. A moonwell still rests at its heart, but it no longer holds clean light.",
			full = "The broken columns here once belonged to a night elven settlement near Mount Hyjal. A moonwell still rests at its heart, but it no longer holds clean light. Fel corruption has soaked into its waters, and the satyr Xavathras now tends it on behalf of Xavaric, cultivating the corruption like a garden meant to poison. Deeper in the ruins, a wall of fire bars the way to him.\n\nDruidic kin have not left the demons unchallenged, striking at them in an effort to tear the place back from the fel that has taken root in it.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Constellas",
		},
		["shadow hold"] = {
			name = "Shadow Hold",
			short = "Beneath Jaedenar, in western Felwood, lies a labyrinth that was once a night elf barrow den. The Shadow Council claimed it long ago, and now warlocks and their demonic familiars roam its tunnels.",
			full = "Beneath Jaedenar, in western Felwood, lies a labyrinth that was once a night elf barrow den. The Shadow Council claimed it long ago, and now warlocks and their demonic familiars roam its tunnels. The satyr Prince Xavalis and the dreadlord Lord Banehollow both dwell within.\n\nThe paladin Trey Lightforge and the night elf Arko'narin Starshade ventured into Felwood hunting signs of the Shadow Council's work. The cultists took them both and caged them within Shadow Hold. Trey was tortured to death there, his spirit twisted and corrupted by his captors. Arko'narin remains caged in the depths, watched by her tormentors, waiting for a rescue that has not yet come.",
			source = "https://warcraft.wiki.gg/wiki/Shadow_Hold",
		},
		["shatter scar vale"] = {
			name = "Shatter Scar Vale",
			short = "Shatter Scar Vale is where the infernals fell when the Burning Legion tore through Felwood during the Third War. The craters they left still smolder, scarring the earth, and demons yet wander among them.",
			full = "Shatter Scar Vale is where the infernals fell when the Burning Legion tore through Felwood during the Third War. The craters they left still smolder, scarring the earth, and demons yet wander among them.",
			source = "https://warcraft.wiki.gg/wiki/Shatter_Scar_Vale",
		},
		["shrine of the deceiver"] = {
			name = "Shrine of the Deceiver",
			short = "The Shrine of the Deceiver, a corrupted barrow den at Jaedenar in Felwood, takes its name from Kil'jaeden, the Deceiver, lord of the Burning Legion.",
			full = "The Shrine of the Deceiver, a corrupted barrow den at Jaedenar in Felwood, takes its name from Kil'jaeden, the Deceiver, lord of the Burning Legion. Warlocks of the Shadow Council fill its depths, making it a dangerous place for the unprepared.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_the_Deceiver",
		},
		["talonbranch glade"] = {
			name = "Talonbranch Glade",
			short = "Talonbranch Glade stands in the northern reaches of Felwood, south of Timbermaw Hold, along the path that leads on to Moonglade and Winterspring.",
			full = "Talonbranch Glade stands in the northern reaches of Felwood, south of Timbermaw Hold, along the path that leads on to Moonglade and Winterspring.",
			source = "https://warcraft.wiki.gg/wiki/Talonbranch_Glade",
		},
		["timbermaw hold"] = {
			name = "Timbermaw Hold",
			short = "Timbermaw Hold, in northeast Felwood, is the capital of the Timbermaw tribe of furbolgs. Its tunnels open a passage through to Moonglade and Winterspring.",
			full = "Timbermaw Hold, in northeast Felwood, is the capital of the Timbermaw tribe of furbolgs. Its tunnels open a passage through to Moonglade and Winterspring.\n\nWhen the corruption of the Burning Legion crept into the sacred forests of Kalimdor, the furbolgs fell under its influence and were twisted into madness. The Timbermaw tribe alone escaped that darkness, sheltering within their hold while the forest they loved was turned into a festering perversion of itself. Even long after the demons' leader was struck down, the taint on the woods remained.\n\nThe furbolgs of Timbermaw Hold are wary of all strangers, fearing they may be mistaken for their corrupted kin and attacked on sight. Yet they know they cannot endure alone, and those they come to trust find that the Timbermaw value friendship above all else. Above all, they wish only to end the suffering of their corrupted brethren and find some cure for the wound Felwood has become.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
	},
	-- Un'Goro Crater: 12 subzones
	[1449] = {
		["fire plume ridge"] = {
			name = "Fire Plume Ridge",
			short = "Fire Plume Ridge rises at the heart of Un'Goro Crater, a mountain of scorched rock where lava creeps down the slopes and fire elementals stir in the heat.",
			full = "Fire Plume Ridge rises at the heart of Un'Goro Crater, a mountain of scorched rock where lava creeps down the slopes and fire elementals stir in the heat. Shallow veins of magma run beneath the crater floor, feeding the steam pools and geysers that hiss throughout Un'Goro, so that the whole basin seems to breathe from the mountain's fire.\n\nWithin a cave at the peak dwells Blazerunner, the strongest of the fire elementals that haunt the ridge, master of the mountain's burning heart. The spirits of fire that flicker and dance here speak of centuries spent burning, dying down to embers, and reigniting again, over and over, without end.\n\nNot all who come to the ridge master it. A wanderer named Ringo came to explore its slopes and lost his way, and heat exhaustion overtook him. He can still be found in the southern cave, having never made it back out.",
			source = "https://warcraft.wiki.gg/wiki/Fire_Plume_Ridge",
		},
		["fungal rock"] = {
			name = "Fungal Rock",
			short = "Fungal Rock opens in the northeastern wall of Un'Goro Crater, a cavern where gorillas live among the ghost mushrooms growing in its dark.",
			full = "Fungal Rock opens in the northeastern wall of Un'Goro Crater, a cavern where gorillas live among the ghost mushrooms growing in its dark. Outside, a small pool gathers beneath a waterfall, and there stands Karna Remtravel's mechanical ape, A-Me 01.",
			source = "https://warcraft.wiki.gg/wiki/Fungal_Rock",
		},
		["golakka hot springs"] = {
			name = "Golakka Hot Springs",
			short = "Steam rises constantly from Golakka Hot Springs, where the volcanic heart of Un'Goro Crater bleeds heat into pools and geysers in the crater's west.",
			full = "Steam rises constantly from Golakka Hot Springs, where the volcanic heart of Un'Goro Crater bleeds heat into pools and geysers in the crater's west. Fury elementals born of that steam and fire pace the shores, drawn from the earth by the same forces that keep the springs boiling.\n\nKrakle once came here to trace what bound the hot springs to the fires of nearby Fire Plume Ridge, before his search carried him elsewhere.",
			source = "https://warcraft.wiki.gg/wiki/Golakka_Hot_Springs",
		},
		["ironstone plateau"] = {
			name = "Ironstone Plateau",
			short = "Bare rock breaks through the green of Un'Goro along its northeastern wall. Ironstone Plateau lies quiet compared to the rest of the crater, largely empty of predators.",
			full = "Bare rock breaks through the green of Un'Goro along its northeastern wall. Ironstone Plateau lies quiet compared to the rest of the crater, largely empty of predators. Fledgling pterrordax nest here, and the plateau's stillness sets it apart from Un'Goro's restless growth.",
			source = "https://warcraft.wiki.gg/wiki/Ironstone_Plateau",
		},
		["lakkari tar pits"] = {
			name = "Lakkari Tar Pits",
			short = "The black lakes north of Marshal's Refuge sit thick and foul-smelling amid Un'Goro's green. Bones jut from the surface in their hundreds, remains of beasts that stepped in expecting solid ground and found none.",
			full = "The black lakes north of Marshal's Refuge sit thick and foul-smelling amid Un'Goro's green. Bones jut from the surface in their hundreds, remains of beasts that stepped in expecting solid ground and found none. Scavengers linger at the edges, waiting for the tar to finish what it started, while tar beasts have risen from the pits themselves.",
			source = "https://warcraft.wiki.gg/wiki/Lakkari_Tar_Pits",
		},
		["marshals refuge"] = {
			name = "Marshal's Refuge",
			short = "Marshal's Refuge sits at the northern edge of Un'Goro Crater, raised by Marshal Expeditions under Williden and Hol'anyee Marshal.",
			full = "Marshal's Refuge sits at the northern edge of Un'Goro Crater, raised by Marshal Expeditions under Williden and Hol'anyee Marshal. Their venture into the crater was not ready for what it found; Un'Goro's beasts proved too savage, and the expedition's base camps were overrun one by one. What remained of the troupe fled to higher ground, making their escape here, at the crater's edge.\n\nThe refuge is what came of that retreat, a foothold barely kept rather than won.",
			source = "https://warcraft.wiki.gg/wiki/Marshal's_Refuge",
		},
		["marshlands"] = {
			name = "Marshlands",
			short = "The marsh spreads across the southeastern reach of Un'Goro Crater, a low sprawl of standing water and rank growth that greets most who first descend into the crater from Tanaris, since any other approach is treacherous.",
			full = "The marsh spreads across the southeastern reach of Un'Goro Crater, a low sprawl of standing water and rank growth that greets most who first descend into the crater from Tanaris, since any other approach is treacherous. Raptors move through the reeds in great numbers, some carrying poison in their bite.\n\nBlue power crystals can be found here, and their presence has worked into the marsh itself, seeping into the raptors that hunt through the wet ground and leaving its mark on them.\n\nOn a mound rising from the water, Torwa Pathfinder keeps watch, having come to the spot by canoe from elsewhere in the crater.",
			source = "https://warcraft.wiki.gg/wiki/Marshlands",
		},
		["pillar of assimilation"] = {
			pending = true,
			name = "Pillar of Assimilation",
			short = "",
			full = "",
			source = "",
		},
		["shapers terrace"] = {
			pending = true,
			name = "The Shaper's Terrace",
			short = "",
			full = "",
			source = "",
		},
		["slithering scar"] = {
			name = "Slithering Scar",
			short = "The Slithering Scar spreads across the southern reach of Un'Goro Crater, a hive of the Gorishi sect.",
			full = "The Slithering Scar spreads across the southern reach of Un'Goro Crater, a hive of the Gorishi sect.\n\nThe hive once had a queen, summoned by disturbing the Gorishi Silithid Crystal within.",
			source = "https://warcraft.wiki.gg/wiki/Slithering_Scar",
		},
		["stomping grounds"] = {
			pending = true,
			name = "Stomping Grounds",
			short = "",
			full = "",
			source = "",
		},
		["terror run"] = {
			name = "Terror Run",
			short = "In Terror Run, west of the Slithering Scar, red crystals grow up from the ground unlike anywhere else in Un'Goro Crater. The beasts of the run have drunk in their power, and it shows in them.",
			full = "In Terror Run, west of the Slithering Scar, red crystals grow up from the ground unlike anywhere else in Un'Goro Crater. The beasts of the run have drunk in their power, and it shows in them.",
			source = "https://warcraft.wiki.gg/wiki/Terror_Run",
		},
