	-- Moonglade: 5 subzones
	[1450] = {
		["lake eluneara"] = {
			name = "Lake Elune'ara",
			short = "Crystal water fills the heart of Moonglade, still as glass beneath the trees. Beneath its surface lies Omen, the mad demigod, defeated long centuries past and never truly gone from these depths.",
			full = "Crystal water fills the heart of Moonglade, still as glass beneath the trees. Beneath its surface lies Omen, the mad demigod, defeated long centuries past and never truly gone from these depths. The lake keeps him still, a quiet weight beneath calm water.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Elune'ara",
		},
		["nighthaven"] = {
			name = "Nighthaven",
			short = "On the shores of Lake Elune'ara stands Nighthaven, a village of night elven stonework and moonwells, home to the druids of the Cenarion Circle.",
			full = "On the shores of Lake Elune'ara stands Nighthaven, a village of night elven stonework and moonwells, home to the druids of the Cenarion Circle. It is a quiet, sequestered place, closed to most outsiders, its people given over to druidism and the tending of the wild.\n\nOnly once a year does Nighthaven open its gates, when the Lunar Festival is celebrated and fireworks are lit over the lake in tribute to Elune's power, welcoming strangers who would otherwise never find welcome here.\n\nBut the village has seen darker nights than any festival. It was here that the Keeper Remulos faced the Nightmare dragon Eranikus, corrupted and turned against the village. Nightmare creatures fell upon Nighthaven, threatening to unmake it entirely, until Tyrande Whisperwind came at last and called down the light of Elune to cleanse the dragon of the corruption that had claimed him. The moonwells still burn with that same light.",
			source = "https://warcraft.wiki.gg/wiki/Nighthaven",
		},
		["shrine of remulos"] = {
			name = "Shrine of Remulos",
			short = "In western Moonglade stands the Shrine of Remulos, raised in honor of the Keeper who watches over that place. Within it dwells the night elf Tajarri, who guides young druids seeking to learn the aquatic form.",
			full = "In western Moonglade stands the Shrine of Remulos, raised in honor of the Keeper who watches over that place. Within it dwells the night elf Tajarri, who guides young druids seeking to learn the aquatic form.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_Remulos",
		},
		["stormrage barrow dens"] = {
			name = "Stormrage Barrow Dens",
			short = "Beneath the quiet turf of Moonglade lie the barrow dens, sunk into earth that many nightelven druids never truly leave, their bodies resting while their spirits wander the Emerald Dream.",
			full = "Beneath the quiet turf of Moonglade lie the barrow dens, sunk into earth that many nightelven druids never truly leave, their bodies resting while their spirits wander the Emerald Dream.\n\nIt was here that Malfurion Stormrage once slept, and the dens bear his name for it. When Tichondrius and his Dreadlords came in the Third War, they struck at Malfurion where he lay, nearly tearing his den apart. It was Tyrande Whisperwind who woke him, calling him back to the world to stand against Archimonde and the Burning Legion.\n\nAfterward, when the Cenarion Circle spoke of raising a second World Tree, Malfurion returned to the barrow dens to meditate. Tyrande later came seeking him and found his body fallen still, as though asleep, with no waking it. The Circle judged it wiser not to move him: if his spirit still wandered the Dream searching for its way home, it would need to find the body where it had left it. So he remained there, watched over by the Cenarion Circle and the Sisterhood of Elune, his body lying still in the den that carries his name.",
			source = "https://warcraft.wiki.gg/wiki/Stormrage_Barrow_Dens",
		},
		["timbermaw hold"] = {
			name = "Timbermaw Hold",
			short = "Timbermaw Hold stands in northeast Felwood, where a tunnel bores through to Moonglade and Winterspring. It is the capital of the Timbermaw tribe of furbolgs.",
			full = "Timbermaw Hold stands in northeast Felwood, where a tunnel bores through to Moonglade and Winterspring. It is the capital of the Timbermaw tribe of furbolgs.\n\nWhen the corruption of the Burning Legion crept into the sacred forests of Kalimdor, the furbolgs fell under its influence. The Timbermaw tribe alone escaped that darkness, sheltering within their hold while they watched, helpless, as the forest they loved was twisted into a festering perversion of itself. Even after the source of that corruption was destroyed, the taint on the woods remained.\n\nThe Timbermaw are wary of all strangers now, fearing they might be mistaken for their corrupted kin and attacked on sight. Yet they know they cannot endure alone, and those who earn their trust find that the Timbermaw value friendship above all else. Their shamanistic tradition endures, rich in the crafting of armor from hide and in old knowledge of healing. Above all, the tribe longs to end the suffering of their corrupted kin, so that the ancient forest might one day ring again with the chants and laughter it has lost.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
	},
	-- Silithus: 19 subzones
	[1451] = {
		["bones of grakkarond"] = {
			name = "Bones of Grakkarond",
			short = "In central Silithus lie the huge bones of the dragon Grakkarond, who fell there in the War of the Shifting Sands.",
			full = "In central Silithus lie the huge bones of the dragon Grakkarond, who fell there in the War of the Shifting Sands.",
			source = "https://warcraft.wiki.gg/wiki/Bones_of_Grakkarond",
		},
		["bronzebeard encampment"] = {
			name = "Bronzebeard Encampment",
			short = "The Bronzebeard Encampment stands in southern Silithus, east of the Scarab Wall.",
			full = "The Bronzebeard Encampment stands in southern Silithus, east of the Scarab Wall.",
			source = "https://warcraft.wiki.gg/wiki/Bronzebeard_Encampment",
		},
		["cenarion hold"] = {
			name = "Cenarion Hold",
			short = "Cenarion Hold rose in Silithus after the War of the Shifting Sands, built by the Cenarion Circle atop an ancient night elven settlement.",
			full = "Cenarion Hold rose in Silithus after the War of the Shifting Sands, built by the Cenarion Circle atop an ancient night elven settlement. It stands as one of the great druid strongholds of Kalimdor, rivaled in size only by Moonglade itself, and its purpose is singular: to hold the line against the silithid swarms and stand watch over the buried thing beneath the sands, the imprisoned Old God C'Thun, lest its armies rise again.\n\nIt is a hard, embattled place to live. The silithid press constantly against its walls, and the region around it grows ever more hostile. Even so, the merchants of the Hold keep their stalls open, trading with whoever makes the long climb up from Un'Goro Crater, for trade is scarce that far from anywhere else, and every coin matters.\n\nThe path to it winds northwest out of Un'Goro, past the Mossy Pile, climbing a steep cliff face that switches back on itself before opening onto the burning wastes of Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Cenarion_Hold",
		},
		["crystal vale"] = {
			name = "Crystal Vale",
			short = "In the far northwestern corner of Silithus lies the Crystal Vale, a valley given over to earth and air elementals.",
			full = "In the far northwestern corner of Silithus lies the Crystal Vale, a valley given over to earth and air elementals. Thorium runs thick beneath its stone, but the ground belongs first to the spirits that stir there, restless and old. Highlord Demitrian holds a camp within the vale.\n\nIt is here that Thunderaan, the Windseeker, can be called forth and bound anew into the blade that bears his fury, a working of storm and will that few dare attempt and fewer still complete.",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Vale",
		},
		["hiveashi"] = {
			name = "Hive'Ashi",
			short = "Hive'Ashi lies in northern Silithus, its silithid brood spreading out to infest the Swarming Pillar beyond its borders.",
			full = "Hive'Ashi lies in northern Silithus, its silithid brood spreading out to infest the Swarming Pillar beyond its borders.",
			source = "https://warcraft.wiki.gg/wiki/Hive'Ashi",
		},
		["hiveregal"] = {
			name = "Hive'Regal",
			short = "In southern Silithus, the mounds of Hive'Regal rise from the sand, home to the silithid, tunnels and chitin thick amid the dust.",
			full = "In southern Silithus, the mounds of Hive'Regal rise from the sand, home to the silithid, tunnels and chitin thick amid the dust.",
			source = "https://warcraft.wiki.gg/wiki/Hive'Regal",
		},
		["hivezora"] = {
			name = "Hive'Zora",
			short = "Hive'Zora is a silithid nest burrowed into the sands of western Silithus.",
			full = "Hive'Zora is a silithid nest burrowed into the sands of western Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Hive'Zora",
		},
		["ortells hideout"] = {
			name = "Ortell's Hideout",
			short = "In southeastern Silithus, a small cave opens onto the slopes, home to a hermit named Ortell.",
			full = "In southeastern Silithus, a small cave opens onto the slopes, home to a hermit named Ortell.",
			source = "https://warcraft.wiki.gg/wiki/Ortell's_Hideout",
		},
		["ravaged twilight camp"] = {
			name = "Ravaged Twilight Camp",
			short = "In the Crystal Vale, northwestern Silithus, stands a Twilight's Hammer camp, claimed by Highlord Demitrian.",
			full = "In the Crystal Vale, northwestern Silithus, stands a Twilight's Hammer camp, claimed by Highlord Demitrian.\n\nHere Demitrian remains, holding this ground for the cult.",
			source = "https://warcraft.wiki.gg/wiki/Ravaged_Twilight_Camp",
		},
		["scarab dais"] = {
			name = "Scarab Dais",
			short = "The Scarab Gong stands at the Scarab Dais, northwest of the Scarab Wall outside Ahn'Qiraj, in southern Silithus.",
			full = "The Scarab Gong stands at the Scarab Dais, northwest of the Scarab Wall outside Ahn'Qiraj, in southern Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Scarab_Dais",
		},
		["scarab wall"] = {
			name = "Scarab Wall",
			short = "The Scarab Wall runs along the southern edge of Silithus, sealing off the desert from the ruined city of Ahn'Qiraj beyond it.",
			full = "The Scarab Wall runs along the southern edge of Silithus, sealing off the desert from the ruined city of Ahn'Qiraj beyond it. It was raised from the sand itself at the end of the War of the Shifting Sands, its sandstone bulk climbing at least a hundred feet into the sky. Above that height, where stone could rise no further, the bronze dragonflight wove their magic into a barrier many times taller still.\n\nThose who made it, night elves and bronze dragons together, named it Irana'ethil, Shield against the Shadow. The name says plainly what it was for: C'Thun and its silithid broods lay sealed within Ahn'Qiraj, and the wall stood between that horror and the rest of the world.",
			source = "https://warcraft.wiki.gg/wiki/Scarab_Wall",
		},
		["southwind village"] = {
			name = "Southwind Village",
			short = "Southwind Village once stood as a night elven outpost in Silithus. It did not survive the War of the Shifting Sands.",
			full = "Southwind Village once stood as a night elven outpost in Silithus. It did not survive the War of the Shifting Sands.\n\nWhen the qiraji rose in their swarming multitudes, Valstann Staghelm, son of Fandral Staghelm, led a detachment of the night elven army to hold the village. His troops were slaughtered where they stood, and Valstann himself was taken alive by General Rajaxx while the village he had been sent to defend was torn apart behind him.\n\nWhat the qiraji left behind has not stayed empty. The spirits of druids and Sentinels who fell in the slaughter linger among the wreckage, wandering without purpose, bound to the place of their deaths, following the Shade of Ambermoon. Southwind Village stands on not as quiet ruin but as haunted ground, its dead still unfinished with it.",
			source = "https://warcraft.wiki.gg/wiki/Southwind_Village",
		},
		["staghelm point"] = {
			name = "Staghelm Point",
			short = "A night elven tower once crowned a peak in northeastern Silithus. Here Ralo'shan the Eternal Watcher keeps her post, a bronze drake of Nozdormu's brood wheeling in the sky above her.",
			full = "A night elven tower once crowned a peak in northeastern Silithus. Here Ralo'shan the Eternal Watcher keeps her post, a bronze drake of Nozdormu's brood wheeling in the sky above her. Down the road from the tower lies Twilight's Run, a cave sheltering Twilight cultists, with a small camp at its mouth, a threat the watcher must contend with.",
			source = "https://warcraft.wiki.gg/wiki/Staghelm_Point",
		},
		["swarming pillar"] = {
			name = "Swarming Pillar",
			short = "The Swarming Pillar rises south of Cenarion Hold, a peak riddled through with silithid tunnels, its slopes never still.",
			full = "The Swarming Pillar rises south of Cenarion Hold, a peak riddled through with silithid tunnels, its slopes never still. A haze of small silithid circles the stone at all hours, a living cloud that gave the pillar its name, and beneath the sand at its foot lies one of the hive's chambers, the largest of the many such nests honeycombing the ground of Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Swarming_Pillar",
		},
		["twilight base camp"] = {
			name = "Twilight Base Camp",
			short = "Twilight Base Camp stands as one of four camps the Twilight's Hammer cult has raised across the wastes of Silithus, a foothold for those who serve the coming of the Old Gods amid the dust and ruin of that scoured land.",
			full = "Twilight Base Camp stands as one of four camps the Twilight's Hammer cult has raised across the wastes of Silithus, a foothold for those who serve the coming of the Old Gods amid the dust and ruin of that scoured land.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Base_Camp",
		},
		["twilight outpost"] = {
			name = "Twilight Outpost",
			short = "The Twilight Outpost stands in the far southwestern corner of Silithus, near the Scarab Wall, west of the Bronzebeard Encampment. It is held by the Twilight's Hammer cult.",
			full = "The Twilight Outpost stands in the far southwestern corner of Silithus, near the Scarab Wall, west of the Bronzebeard Encampment. It is held by the Twilight's Hammer cult.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Outpost",
		},
		["twilight post"] = {
			name = "Twilight Post",
			short = "Twilight Post stands in the northwest reaches of Silithus, west of Cenarion Hold and northwest of Twilight Base Camp, a foothold claimed by the Twilight's Hammer in that scoured, silt-blown land.",
			full = "Twilight Post stands in the northwest reaches of Silithus, west of Cenarion Hold and northwest of Twilight Base Camp, a foothold claimed by the Twilight's Hammer in that scoured, silt-blown land.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Post",
		},
		["twilights run"] = {
			name = "Twilight's Run",
			short = "Twilight's Run lies hidden in the rock at the base of Staghelm Point, in northern Silithus.",
			full = "Twilight's Run lies hidden in the rock at the base of Staghelm Point, in northern Silithus. Its cave mouth gives no hint of what fills the dark beyond: chamber after chamber given over to the Twilight's Hammer Cult, who have made this hollow in the mountain their own, deep and unseen, while the desert wind scours the stone above them.",
			source = "https://warcraft.wiki.gg/wiki/Twilight's_Run",
		},
		["valors rest"] = {
			name = "Valor's Rest",
			short = "Valor's Rest is a small camp at the edge of Silithus, reached by the path climbing from the northwest corner of Un'Goro Crater -- the first ground a traveler crosses coming up into the sands.",
			full = "Valor's Rest is a small camp at the edge of Silithus, reached by the path climbing from the northwest corner of Un'Goro Crater -- the first ground a traveler crosses coming up into the sands.\n\nThe camp is tended by members of the Cenarion Circle, who share the ground with an insect infestation that feels unsettlingly familiar. Alliance and Horde alike shelter here in passing, and graves stand quiet at its edge.",
			source = "https://warcraft.wiki.gg/wiki/Valor's_Rest",
		},
	},
	-- Winterspring: 18 subzones
	[1452] = {
		["banthallow barrow den"] = {
			name = "Ban'Thallow Barrow Den",
			short = "Behind Starfall Village in Winterspring lies the Ban'Thallow Barrow Den, a warren of tunnels holding blessed relics treasured by the village.",
			full = "Behind Starfall Village in Winterspring lies the Ban'Thallow Barrow Den, a warren of tunnels holding blessed relics treasured by the village.",
			source = "https://warcraft.wiki.gg/wiki/Ban'Thallow_Barrow_Den",
		},
		["darkwhisper gorge"] = {
			name = "Darkwhisper Gorge",
			short = "Darkwhisper Gorge lies in the southern reaches of Winterspring.",
			full = "Darkwhisper Gorge lies in the southern reaches of Winterspring.\n\nWhen the Burning Legion's army broke upon Mount Hyjal in the Third War and Archimonde fell, the demons that survived did not vanish from the world. They fled into Darkwhisper Gorge and took refuge there, remnants of a host that had nearly unmade the world left to fester in the dark.",
			source = "https://warcraft.wiki.gg/wiki/Darkwhisper_Gorge",
		},
		["dun mandarr"] = {
			name = "Dun Mandarr",
			short = "Dun Mandarr sits near an icy cavern in south-eastern Winterspring, its name betraying dwarven hands. Ferocious moonkin overrun the camp now, and little else remains of whoever raised it.",
			full = "Dun Mandarr sits near an icy cavern in south-eastern Winterspring, its name betraying dwarven hands. Ferocious moonkin overrun the camp now, and little else remains of whoever raised it.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Mandarr",
		},
		["everlook"] = {
			name = "Everlook",
			short = "Everlook stands where Winterspring's trade routes cross, a goblin post of the Steamwheedle Cartel, its laboratory tucked among the buildings.",
			full = "Everlook stands where Winterspring's trade routes cross, a goblin post of the Steamwheedle Cartel, its laboratory tucked among the buildings.\n\nThe Argent Dawn sent Gregor Greystone here, to speak for their interests before the Cartel's local governance.",
			source = "https://warcraft.wiki.gg/wiki/Everlook",
		},
		["frostfire hot springs"] = {
			name = "Frostfire Hot Springs",
			short = "Steam rises from a chain of pools at the far western edge of Winterspring, water too warm for the frozen land around it. No one has explained why the springs burn hot beneath the snow and ice.",
			full = "Steam rises from a chain of pools at the far western edge of Winterspring, water too warm for the frozen land around it. No one has explained why the springs burn hot beneath the snow and ice. Donova Snowden, camped nearby, wonders if some demonic taint seeping north from Darkwhisper Gorge might have found its way here to warm the stone.\n\nThe pool nearest Timbermaw Hold has never come free of the Winterfall tribe's grip. They hold it still, and the furbolgs are not inclined to share the warmth they've claimed.",
			source = "https://warcraft.wiki.gg/wiki/Frostfire_Hot_Springs",
		},
		["frostsaber rock"] = {
			name = "Frostsaber Rock",
			short = "At the top of Frostsaber Rock stands Rivern Frostwind, keeper of the bond between the frostsabers and those who would ride them.",
			full = "At the top of Frostsaber Rock stands Rivern Frostwind, keeper of the bond between the frostsabers and those who would ride them. He teaches friends of the Alliance who earn it how to tame and ride the great white cats that prowl the icy stone below.",
			source = "https://warcraft.wiki.gg/wiki/Frostsaber_Rock",
		},
		["frostwhisper gorge"] = {
			name = "Frostwhisper Gorge",
			short = "Frostwhisper Gorge cuts through southern Winterspring, its floor and ridges broken with night elven ruins. Among these old stones the Frostmaul giants and their towering Preservers dwell.",
			full = "Frostwhisper Gorge cuts through southern Winterspring, its floor and ridges broken with night elven ruins. Among these old stones the Frostmaul giants and their towering Preservers dwell.",
			source = "https://warcraft.wiki.gg/wiki/Frostwhisper_Gorge",
		},
		["hidden grove"] = {
			name = "Hidden Grove",
			short = "The Hidden Grove lies sunk within a crater in Winterspring, walled in on every side by sheer cliffs.",
			full = "The Hidden Grove lies sunk within a crater in Winterspring, walled in on every side by sheer cliffs. Only a single cave, cut into the southeastern ridge, offers a way through, and dropping from the heights above is a path few would dare.\n\nOnce this hollow held nothing more fearsome than white hares, thriving undisturbed in its shelter. That has since changed. The grove is now claimed by moonkin, hostile to any who enter, and their presence has sealed the place as surely as its cliffs ever did.",
			source = "https://warcraft.wiki.gg/wiki/Hidden_Grove",
		},
		["ice thistle hills"] = {
			name = "Ice Thistle Hills",
			short = "The Ice Thistle Hills rise southeast of Everlook, home to the Ice Thistle yeti, who den in a cave climbing up the hillside and range through the slopes around it.",
			full = "The Ice Thistle Hills rise southeast of Everlook, home to the Ice Thistle yeti, who den in a cave climbing up the hillside and range through the slopes around it. Their thick fur and pale horns are prized by those who brave the cold to take them.\n\nIcecaps grow across the open slopes, and inside the cave veins of thorium run through the rock. Rarest of all, at the very lip of the cave, a black lotus is sometimes said to bloom, fragile and strange amid the yeti's ground.",
			source = "https://warcraft.wiki.gg/wiki/Ice_Thistle_Hills",
		},
		["lake keltheril"] = {
			name = "Lake Kel'Theril",
			short = "The frozen waters of Lake Kel'Theril lie still at the heart of Winterspring, ringed by the ruins that share its name.",
			full = "The frozen waters of Lake Kel'Theril lie still at the heart of Winterspring, ringed by the ruins that share its name. The ruins are old Highborne work, and those who once dwelled there did not leave when their halls fell. Their spirits linger still, tormented, drifting across the ice and broken stone.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Kel'Theril",
		},
		["mazthoril"] = {
			name = "Mazthoril",
			short = "Deep in the ice of Winterspring, near Lake Kel'Theril, the cavern of Mazthoril opens beneath the earth, cold and vast and thick with magic.",
			full = "Deep in the ice of Winterspring, near Lake Kel'Theril, the cavern of Mazthoril opens beneath the earth, cold and vast and thick with magic. Here dwells a brood of blue dragons, sworn to Malygos, and here their matriarch keeps her solitary watch.\n\nHaleh rarely takes any form the world would call true, showing herself only as a high elf standing at the cavern's uppermost reach, reached through a rune of passage set into the floor far below. Few who are not of her own kind ever see her face.\n\nAround her she has set a guard worthy of her reclusiveness. Four powerful drakes answer to her alone. Spellmaw walks a slow, unbroken circuit through a third of Winterspring's lower reaches, while Manaclaw and Scryer stand over the runes at the cavern's rear like sentries over a locked door.",
			source = "https://warcraft.wiki.gg/wiki/Mazthoril",
		},
		["moon horror den"] = {
			name = "Moon Horror Den",
			short = "A short walk northeast of Everlook's gates, the ground rises toward a small cave known as the Moon Horror Den, home to fierce Raging Owlbeasts.",
			full = "A short walk northeast of Everlook's gates, the ground rises toward a small cave known as the Moon Horror Den, home to fierce Raging Owlbeasts. A mountain stands between the den and Winterfall Village to the south, close as the two places seem, so that no direct path connects them, only a long ride around the high ground.",
			source = "https://warcraft.wiki.gg/wiki/Moon_Horror_Den",
		},
		["owl wing thicket"] = {
			name = "Owl Wing Thicket",
			short = "The caves of Owl Wing Thicket cut through the southern reaches of Winterspring, home to owlbeasts gone berserk, moontouched, and crazed.",
			full = "The caves of Owl Wing Thicket cut through the southern reaches of Winterspring, home to owlbeasts gone berserk, moontouched, and crazed. It is said the ancient Guardians of Elune tell here how the moonkin first came into the world, their tale kept by Ranshalla.",
			source = "https://warcraft.wiki.gg/wiki/Owl_Wing_Thicket",
		},
		["ruins of keltheril"] = {
			name = "Ruins of Kel'Theril",
			short = "The Ruins of Kel'Theril lie broken on the edges of the lake that bears its name, all that remains of a great night elven city.",
			full = "The Ruins of Kel'Theril lie broken on the edges of the lake that bears its name, all that remains of a great night elven city. It fell during the Great Sundering, when the world itself was torn apart, and it has never risen again.\n\nWhat lingers there now is grief made restless. The Highborne who died when Kel'Theril fell did not pass on; their spirits remain among the fallen columns of the northern ruins, tormented, unable to let go of what they lost. High elven ghosts haunt the eastern section, among them betrayed rangers and an archmage.\n\nA crystal called Zin-Malor is bound up with the fall of this place, tied to a destruction that swallowed generation after generation of elves here. That story belongs to Kel'Theril itself, to the fallen stone and the ghosts who still walk among it.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Kel'Theril",
		},
		["starfall village"] = {
			name = "Starfall Village",
			short = "Starfall Village stands along the road through Winterspring, the only place in that cold country where the Alliance keeps a foothold.",
			full = "Starfall Village stands along the road through Winterspring, the only place in that cold country where the Alliance keeps a foothold. A night elven lodge and a smaller house make up the settlement, and nearby lies the Ban'Thallow Barrow Den, sunk into the earth like the burial mounds it takes its name from.",
			source = "https://warcraft.wiki.gg/wiki/Starfall_Village",
		},
		["timbermaw hold"] = {
			name = "Timbermaw Hold",
			short = "Timbermaw Hold lies in the tunnels of northern Felwood, the passage that opens onto Moonglade and Winterspring, and it is the last stronghold of the Timbermaw tribe of furbolgs.",
			full = "Timbermaw Hold lies in the tunnels of northern Felwood, the passage that opens onto Moonglade and Winterspring, and it is the last stronghold of the Timbermaw tribe of furbolgs.\n\nWhen the corruption of the Burning Legion crept into the sacred forests of Kalimdor, the furbolgs of that land fell beneath it, twisted into something feral and cruel. The Timbermaw tribe alone escaped that fate, holding to their tunnels while the forest they loved was turned into a festering perversion of itself around them. Even after the source of the corruption was destroyed, the taint on the woods did not lift.\n\nThe Timbermaw remain wary of all strangers, fearing they will be mistaken for their corrupted kin and cut down before they can prove otherwise. Yet they know they cannot endure alone, and to those who earn their trust they are generous: they hold to the old shamanistic ways and share freely what healing knowledge they keep. What they want most is an end to their corrupted brethren's suffering, and a cure for the wounds Felwood has taken.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
		["timbermaw post"] = {
			name = "Timbermaw Post",
			short = "Timbermaw Post keeps a name that no longer fits.",
			full = "Timbermaw Post keeps a name that no longer fits. The camp once belonged to the Timbermaw tribe, but it now answers to the corrupted Winterfall furbolgs, who hold it completely, southeast of the Frostfire Hot Springs and west of Lake Kel'Theril.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Post",
		},
		["winterfall village"] = {
			name = "Winterfall Village",
			short = "Winterfall Village climbs the eastern slopes of Winterspring, near Everlook, its furbolgs long corrupted. At its summit sits a small cave, the seat of High Chief Winterfall, who rules the settlement from there.",
			full = "Winterfall Village climbs the eastern slopes of Winterspring, near Everlook, its furbolgs long corrupted. At its summit sits a small cave, the seat of High Chief Winterfall, who rules the settlement from there.",
			source = "https://warcraft.wiki.gg/wiki/Winterfall_Village",
		},
	},
	-- Stormwind City: 4 subzones
	[1453] = {
		["champions hall"] = {
			name = "Champions' Hall",
			short = "In the south of Old Town in Stormwind City stands the Champions' Hall, where the officers of the Alliance are quartered, set apart within the old city as befits their rank.",
			full = "In the south of Old Town in Stormwind City stands the Champions' Hall, where the officers of the Alliance are quartered, set apart within the old city as befits their rank.",
			source = "https://warcraft.wiki.gg/wiki/Champions'_Hall",
		},
		["deeprun tram"] = {
			name = "Deeprun Tram",
			short = "King Magni Bronzebeard did not build the Deeprun Tram out of comfort.",
			full = "King Magni Bronzebeard did not build the Deeprun Tram out of comfort. In the years after the Second War, as Stormwind labored to rebuild itself from ruin, Magni grew impatient with how slowly Ironforge's aid reached his human allies, and uneasy at how slowly dwarven soldiers could reach them should war come again. He turned to High Tinker Gelbin Mekkatorque, Azeroth's most esteemed engineer, and set him to the problem. Mekkatorque's answer was a railway driven beneath the earth itself, linking the two capitals directly.\n\nThe builders met a subterranean lake beneath the tunnel's path, and did not divert around it. The tram runs through it still, its enclosed tracks passing beneath the water rather than beside it.\n\nGnomes tend the tram daily, keeping its two sets of triple wagons running fast and smooth between Ironforge and Stormwind, free to all who cross the underground platforms.",
			source = "https://warcraft.wiki.gg/wiki/Deeprun_Tram",
		},
		["stormwind harbor"] = {
			pending = true,
			name = "Stormwind Harbor",
			short = "",
			full = "",
			source = "",
		},
		["valley of heroes"] = {
			name = "Valley of Heroes",
			short = "A bridge of pale stone carries every traveler over the moat before Stormwind's southern gate, into a green valley lined with statues raised for grief as much as glory.",
			full = "A bridge of pale stone carries every traveler over the moat before Stormwind's southern gate, into a green valley lined with statues raised for grief as much as glory.\n\nAfter the Second War, when Stormwind was rebuilt from ruin, the city honored those who led the Alliance Expedition through the Dark Portal to seal it from the far side. Kurdran Wildhammer and the Archmage Khadgar stand to the left of the road; Force Commander Danath Trollbane and Ranger-Captain Alleria Windrunner to the right; and at the road's end, where it forks to enter the city proper, stands General Turalyon, who led them all. None of the five ever returned.\n\nYears later, Alleria and Turalyon's son Arator was brought to a ceremony in the valley, carried on the shoulders of a Knight of the Silver Hand. He looked up at the stone likeness of his mother, a face he had no memory of. Something of her reached him there, for the boy smiled and reached out toward the statue. He would come back again and again as he grew, to stand before her face and know, without remembering her, that she had loved him.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Heroes",
		},
	},
	-- Orgrimmar: 2 subzones
	[1454] = {
		["hall of legends"] = {
			name = "Hall of Legends",
			short = "The Hall of Legends stands in the Valley of Strength in Orgrimmar, the barracks where the Horde's officers keep their counsel.",
			full = "The Hall of Legends stands in the Valley of Strength in Orgrimmar, the barracks where the Horde's officers keep their counsel.\n\nAt its center a table is spread with maps of Azeroth.",
			source = "https://warcraft.wiki.gg/wiki/Hall_of_Legends",
		},
		["ragefire chasm"] = {
			name = "Ragefire Chasm",
			short = "Beneath Orgrimmar the earth opens into a fiery chasm, its tunnels choked with lava and smoke. Troggs have begun climbing up out of the depths here, a clan the Horde came to call the Ragefire troggs.",
			full = "Beneath Orgrimmar the earth opens into a fiery chasm, its tunnels choked with lava and smoke. Troggs have begun climbing up out of the depths here, a clan the Horde came to call the Ragefire troggs. Magatha the Seer, of the tauren, attempted to make peace with them, hoping they might be turned from the city above. She was met only with hostility. It became plain that these creatures had no interest in diplomacy, and that if left unchecked they could overwhelm the Horde entirely.\n\nWorse, the plot reached into Orgrimmar itself. Neeru Fireblade, who kept his true loyalties hidden as leader of the Burning Blade, lured Thrall's own loyal followers down into the chasm, feeding them to a sect of dark cultists sheltering there, both to be rid of them and to test whether the cultists could be trusted. Thrall knows more of the betrayal than he lets on, but the cultist leaders still hold the caverns they have claimed as their own.",
			source = "https://warcraft.wiki.gg/wiki/Ragefire_Chasm",
		},
	},
	-- Ironforge: 2 subzones
	[1455] = {
		["deeprun tram"] = {
			name = "Deeprun Tram",
			short = "King Magni Bronzebeard did not build the Deeprun Tram out of comfort.",
			full = "King Magni Bronzebeard did not build the Deeprun Tram out of comfort. In the years after the Second War, as Stormwind labored to rebuild itself from ruin, Magni grew impatient with how slowly Ironforge's aid reached his human allies, and uneasy at how slowly dwarven soldiers could reach them should war come again. He turned to High Tinker Gelbin Mekkatorque, Azeroth's most esteemed engineer, and set him to the problem. Mekkatorque's answer was a railway driven beneath the earth itself, linking the two capitals directly.\n\nThe builders met a subterranean lake beneath the tunnel's path, and did not divert around it. The tram runs through it still, its enclosed tracks passing beneath the water rather than beside it.\n\nGnomes tend the tram daily, keeping its two sets of triple wagons running fast and smooth between Ironforge and Stormwind, free to all who cross the underground platforms.",
			source = "https://warcraft.wiki.gg/wiki/Deeprun_Tram",
		},
		["gates of ironforge"] = {
			name = "Gates of Ironforge",
			short = "The Gates of Ironforge rise where the great ramp of Dun Morogh climbs to meet the mountain, visible for miles across the snows before a traveler ever reaches them.",
			full = "The Gates of Ironforge rise where the great ramp of Dun Morogh climbs to meet the mountain, visible for miles across the snows before a traveler ever reaches them. They stand as the threshold between the open dwarven lands and Ironforge proper.\n\nPassing through, one comes under the gaze of a huge statue raised to High King Modimus Anvilmar, set to keep watch just inside the entrance, so that none enter the city without passing beneath his eyes first.",
			source = "https://warcraft.wiki.gg/wiki/Gates_of_Ironforge",
		},
	},
	-- Thunder Bluff: 4 subzones
	[1456] = {
		["elder rise"] = {
			name = "Elder Rise",
			short = "Elder Rise stands east of the central bluff, reached by rope bridges to the high rise and middle rise.",
			full = "Elder Rise stands east of the central bluff, reached by rope bridges to the high rise and middle rise. Here the Cenarion Circle keeps its home, where tauren druids and priests gather, and the Arch Druid Hamuul Runetotem resides. The Council of Elders also holds its governance here.\n\nBetween the two bridges stands a hut claimed by Magatha Grimtotem, leader of the Grimtotem tribe.",
			source = "https://warcraft.wiki.gg/wiki/Elder_Rise",
		},
		["hunter rise"] = {
			name = "Hunter Rise",
			short = "The southern rise of Thunder Bluff belongs to those who fight and those who hunt.",
			full = "The southern rise of Thunder Bluff belongs to those who fight and those who hunt. Here stands the Hunter's Hall, where the tauren train their warriors and hunters, and where trappers, trackers, and tanners keep to their crafts. Rope bridges carry the rise to the paths above and below, binding it into the rest of the bluff.",
			source = "https://warcraft.wiki.gg/wiki/Hunter_Rise",
		},
		["pools of vision"] = {
			name = "Pools of Vision",
			short = "Below the cap of Spirit Rise, a tunnel opens onto still, dark water known as the Pools of Vision.",
			full = "Below the cap of Spirit Rise, a tunnel opens onto still, dark water known as the Pools of Vision. The Forsaken keep a foothold here, deep in Tauren country, a center for their mages and priests, with an emissary of the Forsaken Defilers seeking recruits for battle among the pools.",
			source = "https://warcraft.wiki.gg/wiki/Pools_of_Vision",
		},
		["spirit rise"] = {
			name = "Spirit Rise",
			short = "Spirit Rise stands to the northwest of the central bluff, given over to shamanistic study among the Tauren. The Skychaser tribe holds sway here.",
			full = "Spirit Rise stands to the northwest of the central bluff, given over to shamanistic study among the Tauren. The Skychaser tribe holds sway here. Beneath the mesa's surface lie the Pools of Vision, their waters warmed by hidden steam. Rope bridges reach down to the lower and middle rises, binding the heights together.",
			source = "https://warcraft.wiki.gg/wiki/Spirit_Rise",
		},
	},
	-- Darnassus: 5 subzones
	[1457] = {
		["cenarion enclave"] = {
			name = "Cenarion Enclave",
			short = "The Cenarion Enclave lies in the northwest of Darnassus, a circular grove where oaks and ashes stand taller than the halls of stone elsewhere in the city.",
			full = "The Cenarion Enclave lies in the northwest of Darnassus, a circular grove where oaks and ashes stand taller than the halls of stone elsewhere in the city. Every tree here bears runes shaped not carved but grown from the living bark, and the gathering-places of the grove are themselves formed from wood and stone worked together, as though raised rather than built.\n\nThis has always been the seat of the city's druids, just as the Temple of the Moon is the seat of its priests. Archdruid Fandral Staghelm leads them from the boughs of the Enclave, and the largest of its living structures, standing at the heart of the grove, is his own residence.\n\nThe grove still serves the order that gathers beneath it: druids come here to be taught the old ways, hunters train in its easternmost tree, and at the foot of the great Enclave tree one may learn to ride the nightsabers that carry Darnassus's riders through the wilds. Below the ground, hidden within the westernmost bough, a secretive guild of rogues keeps its quarters, known only to those who already know where to look.",
			source = "https://warcraft.wiki.gg/wiki/Cenarion_Enclave",
		},
		["craftsmens terrace"] = {
			name = "Craftsmen's Terrace",
			short = "The Craftsmen's Terrace lies in the north of Darnassus, given over to trade rather than war or worship. Here the city's artisans keep their shops, and weary travelers may shelter in one of Darnassus's inns.",
			full = "The Craftsmen's Terrace lies in the north of Darnassus, given over to trade rather than war or worship. Here the city's artisans keep their shops, and weary travelers may shelter in one of Darnassus's inns. An embassy of the Argent Dawn also stands here, a foreign presence granted a place within the elven city.\n\nThe terrace borders the Warrior's Terrace to the south, and the Cenarion Enclave to the west.",
			source = "https://warcraft.wiki.gg/wiki/Craftsmen's_Terrace",
		},
		["temple gardens"] = {
			name = "Temple Gardens",
			short = "At the heart of Darnassus lie the Temple Gardens, a wide expanse of water, walkways, and small islands taking their name from the great Temple of the Moon that rises just to the south.",
			full = "At the heart of Darnassus lie the Temple Gardens, a wide expanse of water, walkways, and small islands taking their name from the great Temple of the Moon that rises just to the south. Bridges span outward in every direction, joining the Cenarion Enclave to the north, the Craftsmen's, Warrior's, and Tradesmen's Terraces to the east, and the Temple of the Moon to the south, so that all roads through the city seem to gather here.\n\nThe largest island holds the city's bank, and a portal at the western edge of the gardens offers passage down to Rut'theran Village at the base of the World Tree, making this quiet center of water and stone also the threshold between Darnassus and the world beyond.",
			source = "https://warcraft.wiki.gg/wiki/Temple_Gardens",
		},
		["tradesmens terrace"] = {
			name = "Tradesmen's Terrace",
			short = "The Tradesmen's Terrace sits in the southern reaches of Darnassus, where shopkeepers keep their stalls and traders gather to bargain, making it the heart of commerce for the whole city.",
			full = "The Tradesmen's Terrace sits in the southern reaches of Darnassus, where shopkeepers keep their stalls and traders gather to bargain, making it the heart of commerce for the whole city. From the north it opens onto the Warrior's Terrace, and to the west the paths lead toward the Temple of the Moon and the Temple Gardens.\n\nIts buildings are grown of wood, in the manner of the night elves, light and graceful things.",
			source = "https://warcraft.wiki.gg/wiki/Tradesmen's_Terrace",
		},
		["warriors terrace"] = {
			name = "Warrior's Terrace",
			short = "The Warrior's Terrace holds the eastern gate of Darnassus, where the city opens onto the wilds of Teldrassil.",
			full = "The Warrior's Terrace holds the eastern gate of Darnassus, where the city opens onto the wilds of Teldrassil. Here the Sentinels keep their ground, and any night elf who would take up arms in service of the city comes to this terrace to do it, working the target ranges and dueling grounds until their skill is fit for war.\n\nRiders on nightsabers keep watch along the gates, and the terrace stands as the city's shield against whatever violence might come up the road from the forest.\n\nIt is bordered by the Craftsmen's Terrace to the north, the Tradesmen's Terrace to the south, and the Temple Gardens to the west, so that a warrior training here stands within call of the city's artisans, its merchants, and its priests alike.",
			source = "https://warcraft.wiki.gg/wiki/Warrior's_Terrace",
		},
	},
	-- Undercity: 1 subzones
	[1458] = {
		["ruins of lordaeron"] = {
			name = "Ruins of Lordaeron",
			short = "Above the buried city, the palace of Lordaeron still stands, its halls open to the sky, its gardens gone to ruin. Here the great kingdom of the Alliance died, and here its ghosts have never quite left.",
			full = "Above the buried city, the palace of Lordaeron still stands, its halls open to the sky, its gardens gone to ruin. Here the great kingdom of the Alliance died, and here its ghosts have never quite left.\n\nIt was Arthas Menethil who ended it. The prince returned home at the head of an army raised against his own people, welcomed through these gates by bells and cheering before anyone understood what he had become. He found his father, King Terenas, waiting in the throne room, and killed him there. Standing over the body, he spoke words that still echo in that room to any who linger: that the kingdom would fall, and from its ashes a new order would rise to shake the world. It was no idle boast. Within days the city and its people were slaughtered, and Lordaeron belonged to the Scourge.\n\nWalk the courtyard still and, it is said, one can hear what the stone remembers: hushed voices, the clang of welcoming bells, a murmur from the throne room that never quite fades. Those who can see beyond the veil say the citizens of Lordaeron still walk there, unaware that their kingdom is gone.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Lordaeron",
		},
	},
